package com.golemsdontdie;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a developer-mode client with this plugin loaded, for testing in game.
 *
 * <p>Not a test despite the name and the location — {@code Launch-Plugin.ps1} derives
 * this class by appending "Test" to the plugin class from
 * {@code runelite-plugin.properties}, and runs its {@code main}. It lives in the test
 * source set so it is compiled but never shipped in the plugin jar.
 */
public class GolemsDontDiePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GolemsDontDiePlugin.class);
		RuneLite.main(args);
	}
}

package com.golemsdontdie.telemetry;

import java.io.BufferedReader;
import java.io.StringReader;
import org.junit.Assert;
import org.junit.Test;

/**
 * The obstacle data file on its own, with nothing from the rest of the plugin: what a line holds,
 * how repeats are counted, and that it reads back as it was written.
 */
public class ObstacleDataFileTest
{
	/** The file's contents, or null before it is first written: the plugin's folder, in memory. */
	private String contents;

	private ObstacleDataFile.Store store()
	{
		return new ObstacleDataFile.Store()
		{
			@Override
			public boolean exists()
			{
				return contents != null;
			}

			@Override
			public BufferedReader reader()
			{
				return new BufferedReader(new StringReader(contents));
			}

			@Override
			public void write(String text)
			{
				contents = text;
			}
		};
	}

	@Test
	public void keepsOneLinePerPlayerCrossingAndCountsRepeats() throws Exception
	{
		ObstacleDataFile data = new ObstacleDataFile(store(), "test");
		data.load();
		data.add(stile(3300, 3300, 3300, 3302));
		data.add(stile(3300, 3300, 3300, 3302));
		data.add(stile(3400, 3400, 3400, 3402));
		Assert.assertEquals("the same crossing twice is one line", 2, data.playerLines());
		data.save();

		String[] line = line("P\t12345");
		Assert.assertEquals("the name, with the tab taken out", "Stile here", value("P", line, "name"));
		Assert.assertEquals("seen twice", "2", value("P", line, "seen"));
		Assert.assertEquals("the path, as cycle:along:side", "0:0:0,2:64:0,4:256:0", value("P", line, "path"));

		ObstacleDataFile reloaded = new ObstacleDataFile(store(), "test");
		reloaded.load();
		Assert.assertEquals("both lines survive a restart", 2, reloaded.playerLines());
		reloaded.add(stile(3300, 3300, 3300, 3302));
		reloaded.save();
		Assert.assertEquals("and counting carries on", "3", value("P", line("P\t12345\tStile here\tClimb-over Stile\t839,839\t3\t33\t12\t3300\t3300"), "seen"));
	}

	@Test
	public void measuresHowFarAGolemStrayedFromItsRoute() throws Exception
	{
		ObstacleDataFile data = new ObstacleDataFile(store(), "test");
		data.load();

		// A route two tiles north. From the middle of the start tile the golem drifts half a tile to
		// the east (its right), then lands a quarter of a tile short of the middle of the end tile.
		int x = 3300 * 128 + 64;
		int y = 3300 * 128 + 64;
		int[][] drifted = {{0, x, y}, {10, x + 64, y + 128}, {20, x, y + 224}};
		data.add(new GolemCrossing(12345, 3300, 3300, 0, 3300, 3302, 0, drifted, false));
		int[][] straight = {{0, x, y}, {20, x, y + 256}};
		data.add(new GolemCrossing(12345, 3300, 3300, 0, 3300, 3302, 0, straight, true));
		Assert.assertEquals("one route, one line", 1, data.golemLines());
		data.save();

		String[] line = line("G\t12345");
		Assert.assertEquals("attempts", "2", value("G", line, "attempts"));
		Assert.assertEquals("worst distance off the line: half a tile", "64", value("G", line, "worstSide"));
		Assert.assertEquals("worst landing: a quarter of a tile short", "32", value("G", line, "worstLanding"));
		Assert.assertEquals("started on the start tile", "0", value("G", line, "worstStart"));
		Assert.assertEquals("one attempt hopped over a stone", "1", value("G", line, "overStone"));
		Assert.assertEquals("the latest path, measured along the route", "0:0:0,20:256:0", value("G", line, "path"));
	}

	@Test
	public void sideIsNegativeToTheLeft()
	{
		// Facing north, east is to the right and west to the left.
		Assert.assertArrayEquals(new int[]{0, 64}, ObstacleDataFile.alongAndSide(64, 0, 0, 256));
		Assert.assertArrayEquals(new int[]{0, -64}, ObstacleDataFile.alongAndSide(-64, 0, 0, 256));
		Assert.assertArrayEquals(new int[]{128, 0}, ObstacleDataFile.alongAndSide(0, 128, 0, 256));
	}

	@Test
	public void aFileFromAnotherSchemaIsReplacedNotMisread() throws Exception
	{
		contents = "#schema\t1\nP\t1\t2\t3\n";
		ObstacleDataFile data = new ObstacleDataFile(store(), "test");
		data.load();
		Assert.assertEquals(0, data.playerLines());
	}

	/** A column of a line, by the name the file's own header gives it. */
	private String value(String kind, String[] line, String name) throws Exception
	{
		String[] names = line("#" + kind + "\t");
		for (int i = 0; i < names.length; i++)
		{
			if (names[i].equals(name))
			{
				return line[i];
			}
		}
		throw new AssertionError("no column " + name);
	}

	private String[] line(String startingWith) throws Exception
	{
		for (String line : contents.split("\n"))
		{
			if (line.startsWith(startingWith))
			{
				return line.trim().split("\t", -1);
			}
		}
		throw new AssertionError("no line starting " + startingWith);
	}

	private static PlayerCrossing stile(int fromX, int fromY, int toX, int toY)
	{
		return new PlayerCrossing(12345, "Stile\there", "Climb-over Stile", new int[]{839, 839}, 3, 33, 12,
			fromX, fromY, 0, toX, toY, 0, 0, 2, false,
			new int[][]{{0, 0, 0}, {2, 64, 0}, {4, 256, 0}}, new int[][]{{0, 839}}, 0);
	}
}

package com.golemsdontdie;

import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * How many golems are in each part of the world, so that they spread out rather than gather.
 *
 * <p>Each golem's choice among nearby shortcuts is purely local, so golems settle where the map's
 * shape sends them: a simulated year put a third of every golem in Meiyerditch, a walled maze with
 * a dozen ladders and no way out on foot. This count is all golems know of each other.
 *
 * <p>Counted by map region and floor — 64 tiles square, about one leg of a walk — and recounted
 * every few ticks: it need only be roughly right, and a golem's move must stay one write.
 */
@Slf4j
@Singleton
class GolemCensus
{
	/** Golems in one region and floor that nobody minds. */
	static final int ROOMY = 5;

	/** Region ids are 16 bits and floors two, so everywhere has a slot. */
	private final int[] counts = new int[1 << 18];

	void recount(Iterable<Golem> golems)
	{
		begin();
		for (Golem golem : golems)
		{
			add(golem.getFineX() / Golem.TILE, golem.getFineY() / Golem.TILE, golem.getPlane());
		}
	}

	/** Starts a count, filled with {@link #add}. */
	void begin()
	{
		java.util.Arrays.fill(counts, 0);
	}

	void add(int x, int y, int plane)
	{
		counts[key(x, y, plane)]++;
	}

	void clear()
	{
		java.util.Arrays.fill(counts, 0);
	}

	/** Golems in the region and floor this tile is in. */
	int at(int x, int y, int plane)
	{
		return counts[key(x, y, plane)];
	}

	/**
	 * How willing a golem should be to go here: 1 where there is room, towards 0 where packed. A
	 * multiplier, never a bar — a golem with one way on takes it.
	 */
	float roominess(int x, int y, int plane)
	{
		int crowd = counts[key(x, y, plane)] - ROOMY;
		return crowd <= 0 ? 1f : 1f / (1f + crowd);
	}

	private static int key(int x, int y, int plane)
	{
		return ((x >> 6) << 10) | ((y >> 6) << 2) | (plane & 3);
	}
}

package com.golemsdontdie;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.NPC;

/**
 * Decides what counts as a golem, and when one is dying.
 *
 * <p>Both are hardcoded in {@link GolemContent}, not discovered at runtime: a name match
 * would sweep up the sixty-odd unrelated golems in the game, and learning the death
 * animation from the first death costs a visible crumble whenever the roster is empty.
 * Both stay overridable, as a content update can move them.
 */
@Singleton
class GolemDetector
{
	/** Live golems watched, by NPC index, with their latest snapshot. */
	private final Map<Integer, GolemSnapshot> tracked = new HashMap<>();

	/** Golems already replaced by a copy, so a despawn does not replace them twice. */
	private final Set<Integer> replaced = new HashSet<>();

	/**
	 * Golems seen playing the plinth animation. The copy takes over as it ends, the one
	 * moment a golem is reliably standing still.
	 */
	private final Set<Integer> leftPlinth = new HashSet<>();

	// ---- identity ----

	boolean isGolem(NPC npc)
	{
		return npc != null && GolemContent.isGolem(npc.getId());
	}

	/** True if this animation is the crumble. */
	boolean isDeathAnimation(int animationId)
	{
		return animationId != -1 && animationId == GolemContent.GOLEM_DEATH_ANIMATION;
	}

	// ---- tracking ----

	void track(NPC npc)
	{
		GolemSnapshot snapshot = GolemSnapshot.of(npc);
		if (snapshot != null)
		{
			tracked.put(npc.getIndex(), snapshot);
		}
	}

	/** Last snapshot of a golem, or null if never tracked. */
	GolemSnapshot snapshotOf(NPC npc)
	{
		return tracked.get(npc.getIndex());
	}

	void noteLeftPlinth(NPC npc)
	{
		leftPlinth.add(npc.getIndex());
	}

	boolean hasLeftPlinth(NPC npc)
	{
		return leftPlinth.contains(npc.getIndex());
	}

	/** Marks a golem as already replaced, so its despawn is ignored. */
	void markReplaced(NPC npc)
	{
		replaced.add(npc.getIndex());
	}

	boolean wasReplaced(NPC npc)
	{
		return replaced.contains(npc.getIndex());
	}

	/** Drops all state for an NPC that has left the scene. */
	void forget(NPC npc)
	{
		tracked.remove(npc.getIndex());
		replaced.remove(npc.getIndex());
		leftPlinth.remove(npc.getIndex());
	}

	/** Drops everything; on logout and plugin stop. */
	void reset()
	{
		tracked.clear();
		replaced.clear();
		leftPlinth.clear();
	}
}

package com.golemsdontdie;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * What a golem is allowed to do — the player's account, minus an inventory.
 *
 * <p>A golem made by a player who has done Plague City can use the Ardougne shortcuts that
 * quest opens: a door locked to a golem that the player walks through freely would read as
 * a bug. Three deliberate departures:
 *
 * <ul>
 *   <li><b>Real levels, never boosted.</b> A golem cannot drink a potion, and a shortcut
 *       open only while the player was boosted would strand golems an hour later.</li>
 *   <li><b>No inventory, but a fixed purse.</b> Coins up to 500,000 and a dramen staff,
 *       never tracked. The dearest fare is 10,000, so the check always passes; it says a
 *       golem may take a ferry but not chop a canoe.</li>
 *   <li><b>No timers.</b> Conditions of the countdown form are never satisfied.</li>
 * </ul>
 *
 * <p>Read live each time: the lookups are cheap, and a cached answer would go stale
 * whenever the player levels up or flips a lever — §12 of the plan calls that the likeliest
 * way to strand a golem mid-journey.
 */
@Slf4j
@Singleton
class GolemAbilities
{
	@Inject
	private Client client;

	@Inject
	private ObstacleKnowledge knowledge;

	private static final Skill[] SKILLS = Skill.values();
	private static final Quest[] QUESTS = Quest.values();

	/**
	 * True if a golem may use this transport right now. Cheapest test first: most of the
	 * network is unconditional, so the common case returns early.
	 */
	boolean canUse(GolemTransport transport)
	{
		// Not whether the golem is permitted through, but whether the plugin knows what
		// using it looks like. The shipped animation for most obstacles is a guess from
		// menu text that measuring has overturned every time, so a golem routes around
		// anything unproven.
		if (!knowledge.isUnlocked(transport))
		{
			return false;
		}

		if (transport.isUnconditional())
		{
			return true;
		}
		return hasSkills(transport.skills())
			&& hasQuests(transport.quests())
			&& conditionsMet(transport.varbits(), true)
			&& conditionsMet(transport.varps(), false);
	}

	private boolean hasSkills(int[] requirements)
	{
		for (int i = 0; i + 1 < requirements.length; i += 2)
		{
			int level = requirements[i];
			int ordinal = requirements[i + 1];
			if (ordinal < 0 || ordinal >= SKILLS.length)
			{
				continue;
			}
			if (client.getRealSkillLevel(SKILLS[ordinal]) < level)
			{
				return false;
			}
		}
		return true;
	}

	private boolean hasQuests(int[] requirements)
	{
		for (int ordinal : requirements)
		{
			if (ordinal < 0 || ordinal >= QUESTS.length)
			{
				continue;
			}
			if (!questFinished(ordinal))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * How long a quest's state is trusted before it is asked again, as SailingDocks does.
	 * Asking runs a client script, once per candidate transport per tile a golem entered.
	 * A quest opening its shortcut a few minutes late goes unnoticed.
	 */
	private static final long QUEST_RECHECK_MILLIS = 5 * 60 * 1000L;

	/** Per quest ordinal: when it was last asked, and whether it was finished. */
	private final long[] questAskedAt = new long[QUESTS.length];
	private final boolean[] questDone = new boolean[QUESTS.length];

	private boolean questFinished(int ordinal)
	{
		long now = System.currentTimeMillis();
		if (questAskedAt[ordinal] == 0 || now - questAskedAt[ordinal] >= QUEST_RECHECK_MILLIS)
		{
			questDone[ordinal] = QUESTS[ordinal].getState(client) == QuestState.FINISHED;
			questAskedAt[ordinal] = now;
		}
		return questDone[ordinal];
	}

	/** Forgets every quest state, for a login that may be another account. */
	void forgetQuests()
	{
		java.util.Arrays.fill(questAskedAt, 0);
	}

	/**
	 * Evaluates varbit or varp conditions, stored as triples of (id, operator, value).
	 *
	 * @param varbit true to read varbits, false for varplayers
	 */
	private boolean conditionsMet(int[] conditions, boolean varbit)
	{
		for (int i = 0; i + 2 < conditions.length; i += 3)
		{
			int id = conditions[i];
			int op = conditions[i + 1];
			int wanted = conditions[i + 2];

			if (op == TransportNetwork.OP_AT)
			{
				// A wall-clock countdown, a home teleport cooling down say: a golem is
				// never waiting for one, so it never passes.
				return false;
			}

			int actual = varbit ? client.getVarbitValue(id) : client.getVarpValue(id);
			switch (op)
			{
				case TransportNetwork.OP_EQ:
					if (actual != wanted)
					{
						return false;
					}
					break;
				case TransportNetwork.OP_GT:
					if (actual <= wanted)
					{
						return false;
					}
					break;
				case TransportNetwork.OP_AND:
					if ((actual & wanted) == 0)
					{
						return false;
					}
					break;
				default:
					return false;
			}
		}
		return true;
	}
}

package com.golemsdontdie;

import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

/**
 * One way of getting from one tile to another that is not walking: a door, a ladder, a stile,
 * a ferry.
 *
 * <p>From Shortest Path's tables, reduced offline to the rows a golem could use, which is most of them. Immutable and shared: ~13,000 rows, one set
 * for every golem, built once at startup. Requirements are parsed arrays, not strings, because a
 * golem tests them on every tile it enters near a transport.
 */
final class GolemTransport
{
	// Archetypes. Written into the shipped table; the numbering is a file format, so append only —
	// changing a value silently remaps every row in the shipped resource.
	static final int ARCHETYPE_NONE = 0;
	static final int ARCHETYPE_DOOR = 1;
	static final int ARCHETYPE_LADDER = 2;
	static final int ARCHETYPE_CLIMB = 3;
	static final int ARCHETYPE_DITCH = 4;
	static final int ARCHETYPE_JUMP = 5;
	static final int ARCHETYPE_GANGPLANK = 6;
	static final int ARCHETYPE_CLIMB_OVER = 7;
	static final int ARCHETYPE_SQUEEZE = 8;
	static final int ARCHETYPE_BALANCE = 9;
	static final int ARCHETYPE_STILE = 10;
	static final int ARCHETYPE_TIGHTROPE = 11;

	@Getter
	private final int fromX;
	@Getter
	private final int fromY;
	@Getter
	private final int fromPlane;
	@Getter
	private final int toX;
	@Getter
	private final int toY;
	@Getter
	private final int toPlane;

	/** Travel time in game ticks, as authored for a player. */
	@Getter
	private final int duration;

	/** Which animation set to play, decided offline from the menu text. */
	@Getter
	private final int archetype;

	/**
	 * The scene object this transport is, or -1, read from the menu column offline ("Cross
	 * Gangplank 12164"). It finds the object's model and animation, which
	 * {@code ObjectComposition} does not expose at runtime.
	 */
	@Getter
	private final int objectId;

	/** Pairs of (level, skill ordinal). Empty if ungated. */
	private final int[] skillRequirements;

	/** Quest ordinals that must be finished. Empty if ungated. */
	private final int[] questRequirements;

	/** Triples of (id, operator, value). See {@link GolemAbilities}. */
	private final int[] varbitRequirements;
	private final int[] varpRequirements;

	/**
	 * Index of the row that undoes this one, or -1. Resolved once when the network is built,
	 * because searching per decision would scan 13,000 rows per golem per tile.
	 */
	@Getter
	private int reverse = -1;

	/**
	 * This row's own index in the network, carried rather than looked up: cooldowns are keyed by
	 * index and tested for every candidate on every tile a golem enters, so a lookup would scan
	 * the whole table on the hottest path here.
	 */
	@Getter
	private int index = -1;

	GolemTransport(int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane,
		int duration, int archetype, int objectId, int[] skills, int[] quests, int[] varbits,
		int[] varps)
	{
		this.objectId = objectId;
		this.fromX = fromX;
		this.fromY = fromY;
		this.fromPlane = fromPlane;
		this.toX = toX;
		this.toY = toY;
		this.toPlane = toPlane;
		this.duration = duration;
		this.archetype = archetype;
		this.skillRequirements = skills;
		this.questRequirements = quests;
		this.varbitRequirements = varbits;
		this.varpRequirements = varps;
	}

	/** A learned route that goes into an instance, or comes out of one. See {@link InstanceMap}. */
	static final int INTO_INSTANCE = 1;
	static final int OUT_OF_INSTANCE = 2;

	/**
	 * {@link #INTO_INSTANCE}, {@link #OUT_OF_INSTANCE}, or neither. A golem through the pew is
	 * where nobody outside can see it, and one in the instance's copy of the island is not in
	 * the instance at all — identical in coordinates, since an instance is its template's.
	 */
	@Getter
	private int instanceFlags;

	void setInstanceFlags(int flags)
	{
		this.instanceFlags = flags;
	}

	boolean entersInstance()
	{
		return (instanceFlags & INTO_INSTANCE) != 0;
	}

	boolean leavesInstance()
	{
		return (instanceFlags & OUT_OF_INSTANCE) != 0;
	}

	/**
	 * The same journey the other way, for a golem somewhere it knows no other way out of. Not a
	 * row in the network; only {@link RoamPlanner#wayHome} produces it. The player may have
	 * entered a cave and teleported out, so nothing leaving it was ever learned and golems that
	 * followed gathered underground for good. Not what the game does, but it beats never coming
	 * out.
	 */
	GolemTransport backThrough()
	{
		GolemTransport back = new GolemTransport(toX, toY, toPlane, fromX, fromY, fromPlane, duration, archetype,
			objectId, new int[0], new int[0], new int[0], new int[0]);
		back.instanceFlags = (entersInstance() ? OUT_OF_INSTANCE : 0) | (leavesInstance() ? INTO_INSTANCE : 0);
		return back;
	}

	void setReverse(int index)
	{
		this.reverse = index;
	}

	void setIndex(int index)
	{
		this.index = index;
	}

	/** Both ends of this journey as one number. Rows with the same key go the same way. */
	long endpointKey()
	{
		return TransportNetwork.endpoints(getFromX(), getFromY(), getFromPlane(),
			getToX(), getToY(), getToPlane());
	}

	/** The key of the journey that undoes this one. */
	long reverseKey()
	{
		return TransportNetwork.endpoints(getToX(), getToY(), getToPlane(),
			getFromX(), getFromY(), getFromPlane());
	}

	WorldPoint destination()
	{
		return new WorldPoint(toX, toY, toPlane);
	}

	int[] skills()
	{
		return skillRequirements;
	}

	int[] quests()
	{
		return questRequirements;
	}

	int[] varbits()
	{
		return varbitRequirements;
	}

	int[] varps()
	{
		return varpRequirements;
	}

	/** True if this transport has no requirements at all — most of the network. */
	boolean isUnconditional()
	{
		return skillRequirements.length == 0 && questRequirements.length == 0
			&& varbitRequirements.length == 0 && varpRequirements.length == 0;
	}

	/**
	 * How far the golem is carried, in tiles, or -1 where the question is meaningless:
	 * underground maps sit ~6,400 tiles north of the surface above them, so a ladder down
	 * measures as a continent-wide journey.
	 */
	int travelDistance()
	{
		int d = Math.abs(fromX - toX) + Math.abs(fromY - toY);
		return d > 64 ? -1 : d;
	}

	/**
	 * The animation that plays while the golem uses this, or -1 for none. Doors are deliberately
	 * silent: the door animates, not the player. Teleport-like transports are -1 too.
	 */
	int animation()
	{
		int[] clips = animations();
		return clips.length == 0 ? -1 : clips[0];
	}

	/**
	 * The clips to play, in order, while the golem uses this. OSRS builds obstacle animations in
	 * threes — mount, loop, dismount — and using only the middle one left nine of twenty
	 * catalogued clips unused. The set comes from the plane change and the distance carried;
	 * clips are shared, so three cost as one.
	 */
	int[] animations()
	{
		// A shortcut somebody has watched beats a guess from menu text: the archetype below
		// was wrong for three of the first four obstacles tried.
		int measured = MeasuredShortcuts.animationFor(objectId);
		if (measured != -1)
		{
			return new int[]{measured};
		}

		switch (archetype)
		{
			case ARCHETYPE_LADDER:
				// Reaching up for a ladder and reaching down off the top are different
				// clips; the plane change says which.
				return new int[]{toPlane > fromPlane
					? GolemContent.ANIM_LADDER_GRAB
					: GolemContent.ANIM_LADDER_GRAB_TOP};

			case ARCHETYPE_CLIMB:
				if (toPlane < fromPlane)
				{
					// Going down is its own clip, not the ascent reversed. Measured on
					// Wyrmscraig: the west approach (62265) plays 740, HUMAN_CLIMBING_DOWN,
					// the east (62267) the climbing loop; three server reimplementations
					// use 740 for a descent too. Only the plane says which way a climb
					// goes, so a cliff on flat ground gets the ascent both ways unless
					// measured — the better failure, as an ascent played descending reads
					// as effortful.
					return new int[]{GolemContent.ANIM_CLIMB_DOWN};
				}
				// Take hold, haul up, step off.
				return new int[]{
					GolemContent.ANIM_CLIMB_READY,
					GolemContent.ANIM_CLIMB_LOOP,
					GolemContent.ANIM_CLIMB_MERGE,
				};

			case ARCHETYPE_DITCH:
				return new int[]{GolemContent.ANIM_DITCH_VAULT};

			case ARCHETYPE_JUMP:
			{
				// A hop between stones and a running leap across a chasm are different
				// movements, and distance is the only thing here that separates them. The
				// thresholds are unverified: only the shortest rung is measured —
				// Wyrmscraig's basalt stones, two tiles, play 741 — and the longer clips
				// come from the catalogue by name. A 2019 server reimplementation plays 741
				// for every stepping stone regardless of span, so the split may not exist.
				int span = travelDistance();
				if (span < 0 || span <= 2)
				{
					// The short hop, measured on Wyrmscraig's basalt stones.
					return new int[]{GolemContent.ANIM_JUMP_STEPPINGSTONE};
				}
				if (span <= 4)
				{
					return new int[]{GolemContent.ANIM_JUMP_GAP};
				}
				return new int[]{span <= 8
					? GolemContent.ANIM_JUMP_STONES
					: GolemContent.ANIM_JUMP_LONG};
			}

			case ARCHETYPE_CLIMB_OVER:
				return new int[]{GolemContent.ANIM_WALL_JUMP};

			case ARCHETYPE_STILE:
				// Stepped over one leg at a time, where a broken wall is vaulted; told
				// apart offline from the menu text.
				return new int[]{GolemContent.ANIM_STILE};

			case ARCHETYPE_TIGHTROPE:
				return new int[]{
					GolemContent.ANIM_BALANCE_WALK,
					GolemContent.ANIM_TIGHTROPE,
					GolemContent.ANIM_BALANCE_WALK,
				};

			case ARCHETYPE_SQUEEZE:
				// Turn sideways, shuffle through, straighten up.
				return new int[]{
					GolemContent.ANIM_SQUEEZE_READY,
					GolemContent.ANIM_SQUEEZE_LOOP,
					GolemContent.ANIM_SQUEEZE_END,
				};

			case ARCHETYPE_BALANCE:
				// Step on, cross, step off.
				return new int[]{
					GolemContent.ANIM_BALANCE_WALK,
					GolemContent.ANIM_BALANCE_WALK_LOOP,
					GolemContent.ANIM_BALANCE_WALK,
				};

			case ARCHETYPE_GANGPLANK:
				// Walking the plank is walking: the golem keeps its gait and the boarding
				// reads from the geometry.
				return new int[]{GolemContent.GOLEM_WALK_ANIMATION};

			default:
				return new int[0];
		}
	}

	/**
	 * True if this transport is worth drawing an animated copy of the object for. The object's
	 * animation comes from {@link PropFactory} at runtime, so nothing here names clips. Doors
	 * are excluded despite animating: the real object swings when a player opens it, and a
	 * second copy on top of a closed one is a ghost door.
	 */
	boolean wantsPropAnimation()
	{
		return objectId > 0 && archetype != ARCHETYPE_NONE && archetype != ARCHETYPE_DOOR;
	}

	@Override
	public String toString()
	{
		return "(" + fromX + "," + fromY + "," + fromPlane + ") -> ("
			+ toX + "," + toY + "," + toPlane + ") arch=" + archetype;
	}
}

package com.golemsdontdie;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws a named golem's name above its head, the way NPC highlighting names an NPC.
 *
 * <p>Only golems actually being drawn, so inside an instance the name follows where the golem
 * is drawn rather than where it is simulated. The name rises with the golem mid-hop.
 */
class GolemNameplateOverlay extends Overlay
{
	/** Space between the top of the golem and the bottom of its name, in height units. */
	private static final int NAME_GAP = 40;

	private final Client client;
	private final GolemsDontDiePlugin plugin;
	private final GolemsDontDieConfig config;

	@Inject
	GolemNameplateOverlay(Client client, GolemsDontDiePlugin plugin, GolemsDontDieConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showNameplates())
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}

		// Read once for the frame, not through the config proxy for every named golem.
		java.awt.Color colour = config.nameplateColour();
		for (Golem golem : plugin.drawnGolems())
		{
			String name = golem.getNickname();
			FakeGolem drawn = golem.getRenderer();
			if (name == null || name.trim().isEmpty() || drawn == null || golem.getDrawPlane() != wv.getPlane())
			{
				continue;
			}

			int localX = golem.getDrawFineX() - wv.getBaseX() * Golem.TILE;
			int localY = golem.getDrawFineY() - wv.getBaseY() * Golem.TILE;
			if (!Golem.isInScene(wv, localX, localY))
			{
				continue;
			}

			Point at = Perspective.getCanvasTextLocation(client, graphics, new LocalPoint(localX, localY, wv), name,
				drawn.getModelHeight() + NAME_GAP + golem.jumpArc() + golem.deckLift());
			if (at != null)
			{
				OverlayUtil.renderTextLocation(graphics, at, name, colour);
			}
		}
		return null;
	}
}

package com.golemsdontdie;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

/**
 * Rebuilds a golem's model from the cache, unposed.
 *
 * <p>{@link net.runelite.api.Renderable#getModel()} on the live NPC returns a model already
 * posed for the current frame, in a client-owned buffer. This copy outlives the golem and
 * animates on its own, so it needs the <i>rest</i> pose the animation frames are defined
 * against; posing a posed model compounds the two transforms and folds the golem through itself.
 */
@Slf4j
@Singleton
class GolemModelFactory
{
	/**
	 * The client's base lighting for actors; an NPC's own ambient and contrast add to these. Bare
	 * defaults look flatter and the wrong brightness beside the real thing.
	 */
	private static final int BASE_AMBIENT = 64;
	private static final int BASE_CONTRAST = 850;
	private static final int LIGHT_X = -30;
	private static final int LIGHT_Y = -50;
	private static final int LIGHT_Z = -30;

	/** Composition scales are in 128ths; 128 means "as authored". */
	private static final int UNSCALED = 128;

	@Inject
	private Client client;

	/**
	 * One built model per NPC ID, shared by every golem wearing it. Every golem is the same NPC,
	 * so building one each meant a cache load, merge, vertex clone and lighting pass per golem —
	 * seconds of stall as a few hundred arrive with the scene. Safe because
	 * {@link Client#applyTransformations} clones its source's vertices rather than writing to it.
	 */
	private final Map<Integer, Model> cache = new HashMap<>();

	/** The lit rest-pose model for a snapshot, built once and shared; null if a part is missing. */
	Model modelFor(GolemSnapshot snapshot)
	{
		Model cached = cache.get(snapshot.getNpcId());
		if (cached != null)
		{
			return cached;
		}

		Model built = build(snapshot);
		if (built != null)
		{
			cache.put(snapshot.getNpcId(), built);
		}
		return built;
	}

	/**
	 * Animation definitions, shared the same way the models are: there are exactly two across the
	 * whole population, and an {@link Animation} is immutable frame data — mutable playback state
	 * lives in each golem's own controller — so one copy of each serves every golem.
	 */
	private final Map<Integer, Animation> animations = new HashMap<>();

	/** The animation for an ID, loaded once. Null for -1, or if the cache lacks it. */
	Animation animationFor(int animationId)
	{
		if (animationId == -1)
		{
			return null;
		}
		// computeIfAbsent is avoided: loadAnimation can return null, which would mean
		// re-asking for a missing animation on every switch.
		if (animations.containsKey(animationId))
		{
			return animations.get(animationId);
		}
		Animation loaded = client.loadAnimation(animationId);
		animations.put(animationId, loaded);
		return loaded;
	}

	/**
	 * How long a clip runs for, in client cycles, or 0 if unknown: the sum of its frame lengths,
	 * asked of the client so it stays right if Jagex retimes one. Paces a golem through a
	 * shortcut; guessing had golems scaling a cliff in two thirds of a second.
	 */
	/**
	 * True if this animation is built to repeat.
	 *
	 * <p>{@code frameStep} is how many frames the client winds back at a clip's end: positive
	 * loops, -1 runs once. It cannot be guessed from the name — {@code human_climbing} (737) does
	 * not loop, {@code human_climbing_loop} (4435) does. Only a loop may be stretched to fill a
	 * duration; a stretched one-shot restarts partway and drifts.
	 */
	boolean loops(int animationId)
	{
		Animation animation = animationFor(animationId);
		return animation != null && animation.getFrameStep() > 0;
	}

	int animationCycles(int animationId)
	{
		Animation animation = animationFor(animationId);
		if (animation == null)
		{
			return 0;
		}

		// Frame lengths, summed, not getDuration(): that is a frame *count*, and reading it as
		// cycles made every clip four or five times shorter — a hop came out at 8 cycles against
		// its real 38. Frame lengths are in client cycles.
		int[] frames = animation.getFrameLengths();
		if (frames == null || frames.length == 0)
		{
			return 0;
		}

		int total = 0;
		for (int length : frames)
		{
			total += length;
		}
		return Math.min(total, MAX_CLIP_CYCLES);
	}

	/**
	 * The longest a clip is allowed to claim to be, in client cycles.
	 *
	 * <p>Some sequences end on a frame held absurdly long, meaning "stay like this until told
	 * otherwise": {@code agilityarena_handholds_middle} reports 20,056 cycles and
	 * {@code agilty_shortcut_enter_hole} 2,060, which taken at face value freeze a golem in the
	 * obstacle for minutes. Twenty ticks is longer than any real traversal.
	 */
	private static final int MAX_CLIP_CYCLES = 600;

	/**
	 * Drops the shared models and animations when the plugin stops, so a disable/enable cycle
	 * does not hand out resources built against a client that has moved on.
	 */
	void clear()
	{
		cache.clear();
		animations.clear();
	}

	/** Builds the rest-pose model a snapshot describes; null if the cache lacks a part. */
	private Model build(GolemSnapshot snapshot)
	{
		try
		{
			int[] ids = snapshot.getModelIds();
			ModelData[] parts = new ModelData[ids.length];
			int found = 0;

			for (int id : ids)
			{
				ModelData part = client.loadModelData(id);
				if (part == null)
				{
					// A missing part would leave a golem with no head; better to fail the
					// whole build and let the real death play out.
					log.debug("Golem model part {} not in cache for npc {}", id, snapshot.getNpcId());
					return null;
				}
				parts[found++] = part;
			}

			if (found == 0)
			{
				return null;
			}

			ModelData merged = client.mergeModels(parts, found);
			if (merged == null)
			{
				return null;
			}

			// Recolour and resize write into the vertex and colour arrays, shared with the
			// cache's copy until cloned. Skipping this repaints every other model in the
			// game that shares the source.
			merged.cloneColors().cloneVertices();

			short[] from = snapshot.getRecolourFrom();
			short[] to = snapshot.getRecolourTo();
			for (int i = 0; i < Math.min(from.length, to.length); i++)
			{
				merged.recolor(from[i], to[i]);
			}

			int width = snapshot.getWidthScale() <= 0 ? UNSCALED : snapshot.getWidthScale();
			int height = snapshot.getHeightScale() <= 0 ? UNSCALED : snapshot.getHeightScale();
			if (width != UNSCALED || height != UNSCALED)
			{
				// Y is the vertical axis, and it is the one the height scale drives.
				merged.scale(width, height, width);
			}

			Model model = merged.light(
				BASE_AMBIENT + GolemContent.GOLEM_AMBIENT,
				BASE_CONTRAST + GolemContent.GOLEM_CONTRAST,
				LIGHT_X, LIGHT_Y, LIGHT_Z);
			if (model == null)
			{
				return null;
			}
			model.calculateBoundsCylinder();
			return model;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not build golem model for npc {}", snapshot.getNpcId(), e);
			return null;
		}
	}
}

package com.golemsdontdie;

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * Every transport a golem could use, indexed by the tile you use it from.
 *
 * <p>Loaded once from {@code /transports.gz}, generated offline from Shortest Path's tables;
 * shipping it means golems can use a ladder the player
 * has never stood next to, as with the island map. Indexed by origin tile, the only question
 * asked of it.
 */
@Slf4j
@Singleton
class TransportNetwork
{
	private static final String RESOURCE = "/transports.gz";

	/** Operators in a varbit or varp condition, as encoded by the builder. */
	static final int OP_EQ = 0;
	static final int OP_GT = 1;
	static final int OP_AND = 2;
	static final int OP_AT = 3;

	private static final int[] NONE = new int[0];

	private final List<GolemTransport> transports = new ArrayList<>();

	/** Origin tile (x, y packed) to the transports starting there. Immutable once built. */
	private final Map<Long, List<GolemTransport>> byOrigin = new HashMap<>();

	/** Archetype per object id, built once with the rest of the index. */
	private final Map<Integer, Integer> archetypeByObject = new HashMap<>();

	/** Quest display name to enum, built once — the tables name quests as players do. */
	private static Map<String, Quest> questsByName;

	/**
	 * Reads the bundled table. A missing or corrupt resource is deliberately not fatal: golems
	 * fall back to walking rather than the plugin refusing to load.
	 */
	void load()
	{
		if (!transports.isEmpty())
		{
			return;
		}

		try (InputStream raw = TransportNetwork.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.warn("Bundled transport table missing from the jar");
				return;
			}

			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					transports.add(new GolemTransport(
						data.readShort() & 0xFFFF, data.readShort() & 0xFFFF, data.readByte(),
						data.readShort() & 0xFFFF, data.readShort() & 0xFFFF, data.readByte(),
						data.readShort() & 0xFFFF, data.readByte(), data.readInt(),
						parseSkills(data.readUTF()),
						parseQuests(data.readUTF()),
						parseConditions(data.readUTF()),
						parseConditions(data.readUTF())));
				}
			}

			index();
			shippedCount = transports.size();
			for (GolemTransport t : transports)
			{
				shippedByEndpoints.putIfAbsent(t.endpointKey(), t);
				if (t.getObjectId() > 0)
				{
					shippedObjects.add(t.getObjectId());
				}
			}
			link();
			log.debug("Loaded {} transports across {} origin tiles",
				transports.size(), byOrigin.size());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled transport table unreadable", e);
			transports.clear();
			byOrigin.clear();
		}
	}

	/**
	 * Transports usable from exactly this tile. Never null, never a copy: golems scan the tiles
	 * around them on every step, which near a town would be hundreds of lists a second. The lists
	 * are immutable and shared.
	 */
	List<GolemTransport> from(int x, int y)
	{
		List<GolemTransport> found = byOrigin.get(pack(x, y));
		return found == null ? Collections.emptyList() : found;
	}

	/**
	 * Adds routes the player has demonstrated, replacing any added before; they are kept apart
	 * only so re-learning replaces rather than accumulates. Archetype is {@code NONE} on purpose:
	 * what the golem plays comes from {@link ObstacleKnowledge} by object id.
	 */
	void setLearnedRoutes(java.util.List<int[]> routes)
	{
		if (!learned.isEmpty())
		{
			// Learned rows are always the tail, numbered from shippedCount. removeAll searched the
			// learned list for each of thirteen thousand rows, on every obstacle the player used.
			transports.subList(shippedCount, transports.size()).clear();
			learned.clear();
		}

		suppressed.clear();
		// One row per journey. Two saved routes can drift onto the same ends as they are merged.
		java.util.Set<Long> journeys = new java.util.HashSet<>();
		for (int[] r : routes)
		{
			if (!journeys.add(endpoints(r[1], r[2], r[3], r[4], r[5], r[6])))
			{
				continue;
			}
			// A learned route going exactly where a shipped row goes replaces it: two rows for one
			// journey can carry different object ids, as on the rockslide. What was watched is the
			// better authority on the object, the table on the journey's requirements.
			GolemTransport twin = shippedByEndpoints.get(
				endpoints(r[1], r[2], r[3], r[4], r[5], r[6]));
			GolemTransport route;
			if (twin == null)
			{
				// The observed duration, not a placeholder: a learned row claiming one tick
				// undercut the shipped row it was meant to improve on.
				route = new GolemTransport(r[1], r[2], r[3], r[4], r[5], r[6],
					r.length > 7 ? r[7] : 1, GolemTransport.ARCHETYPE_NONE, r[0],
					NO_REQUIREMENT, NO_REQUIREMENT, NO_REQUIREMENT, NO_REQUIREMENT);
			}
			else
			{
				route = new GolemTransport(r[1], r[2], r[3], r[4], r[5], r[6],
					r.length > 7 ? r[7] : 1,
					twin.getObjectId() == r[0] ? twin.getArchetype() : GolemTransport.ARCHETYPE_NONE,
					r[0], twin.skills(), twin.quests(), twin.varbits(), twin.varps());
				suppressed.add(twin);
			}
			route.setInstanceFlags(r.length > 8 ? r[8] : 0);
			learned.add(route);
		}
		transports.addAll(learned);

		// Indices are assigned once and never move: an index is the key a cooldown is stored
		// under, so re-indexing on every sighting voided every cooldown and golems ping-ponged
		// between the two cathedral doors. Learned rows are numbered above the shipped ones.
		for (int i = 0; i < learned.size(); i++)
		{
			learned.get(i).setIndex(shippedCount + i);
		}

		byOrigin.clear();
		archetypeByObject.clear();
		for (GolemTransport t : transports)
		{
			if (suppressed.contains(t))
			{
				continue;
			}
			byOrigin.computeIfAbsent(pack(t.getFromX(), t.getFromY()),
				k -> new ArrayList<>()).add(t);
			if (t.getObjectId() > 0)
			{
				archetypeByObject.merge(t.getObjectId(), t.getArchetype(), Math::max);
			}
		}
		byOrigin.replaceAll((k, v) -> Collections.unmodifiableList(v));
		indexChunks();

		// Learned rows need their reverse resolved like any other, or a golem has nothing to
		// put on cooldown coming back.
		link();

		log.debug("Transport network: {} rows including {} learned", transports.size(),
			learned.size());
	}

	/** How many rows shipped, fixed at load: the boundary between fixed and movable indices. */
	private int shippedCount;

	private final List<GolemTransport> learned = new ArrayList<>();

	/** The first shipped row for each pair of endpoints, for spotting a learned duplicate. */
	private final Map<Long, GolemTransport> shippedByEndpoints = new HashMap<>();

	/** Shipped rows a learned route has replaced. Kept in the table, never offered. */
	private final java.util.Set<GolemTransport> suppressed =
		Collections.newSetFromMap(new java.util.IdentityHashMap<>());

	private static final int[] NO_REQUIREMENT = new int[0];

	/**
	 * The archetype this object is given wherever it appears, or -1. Keyed by object rather than
	 * tile because the highlight overlay works from the obstacle index, which knows where
	 * obstacles stand but not where they lead.
	 */
	/**
	 * True if the shipped tables have a row for this object. Shipped rows only:
	 * {@link #archetypeFor} counts learned rows too, so a tree that slipped through once passed
	 * the obstacle test for good.
	 */
	boolean isShippedObstacle(int objectId)
	{
		return shippedObjects.contains(objectId);
	}

	private final java.util.Set<Integer> shippedObjects = new java.util.HashSet<>();

	int archetypeFor(int objectId)
	{
		Integer found = archetypeByObject.get(objectId);
		return found == null ? -1 : found;
	}

	/**
	 * Every transport, for callers that sweep the whole table. Immutable and shared, like
	 * {@link #from}: sweeping thirteen thousand rows beats the tile-by-tile lookup, which costs
	 * the square of the radius, from about sixty tiles out.
	 */
	List<GolemTransport> all()
	{
		return Collections.unmodifiableList(transports);
	}

	/** True unless a learned route has replaced this row; suppressed rows stay in {@link #all}. */
	boolean isOffered(GolemTransport transport)
	{
		return !suppressed.contains(transport);
	}

	/** How far a hop from a stepping stone can go, in tiles. */
	private static final int STONE_HOP = 4;

	/**
	 * True if a short hop on the same floor starts on this tile: a stepping stone or the like,
	 * which a golem leaves by the next hop rather than by stepping off.
	 */
	boolean isStone(int x, int y, int plane)
	{
		for (GolemTransport t : from(x, y))
		{
			if (t.getFromPlane() == plane && t.getToPlane() == plane
				&& Math.max(Math.abs(t.getToX() - x), Math.abs(t.getToY() - y)) <= STONE_HOP)
			{
				return true;
			}
		}
		return false;
	}

	/** True if any transport starts on this tile — the cheap test, and the common one. */
	boolean hasOrigin(int x, int y)
	{
		return byOrigin.containsKey(pack(x, y));
	}

	GolemTransport get(int index)
	{
		return index < 0 || index >= transports.size() ? null : transports.get(index);
	}

	int size()
	{
		return transports.size();
	}

	/** Goes up whenever the table changes, so anything built from it knows to build again. */
	private int revision;

	int revision()
	{
		return revision;
	}

	// ------------------------------------------------------------------ indexing

	private void index()
	{
		for (int i = 0; i < transports.size(); i++)
		{
			GolemTransport t = transports.get(i);
			t.setIndex(i);
			byOrigin.computeIfAbsent(pack(t.getFromX(), t.getFromY()),
				k -> new ArrayList<>()).add(t);

			// Highest archetype wins where an object appears under several: they normally agree, and
			// the classified one is more informative, ARCHETYPE_NONE being zero.
			if (t.getObjectId() > 0)
			{
				archetypeByObject.merge(t.getObjectId(), t.getArchetype(), Math::max);
			}
		}

		// Made immutable once built: these lists are handed straight out to every golem that
		// walks past.
		byOrigin.replaceAll((k, v) -> Collections.unmodifiableList(v));
		indexChunks();
	}

	/**
	 * Wyrmscraig and everywhere its own transports lead: the regions a golem stays in when its
	 * ambition is restricted.
	 *
	 * <p>The island's regions, then — repeatedly, until nothing new turns up — the region every
	 * transport starting in the area lands in, which picks up caves and the floors above ladders
	 * without a list. The region either side of each landing is allowed too, a floor rarely
	 * fitting one region, but does not seed further transports, which leaks along coasts.
	 */
	java.util.Set<Integer> homeRegions()
	{
		java.util.Set<Integer> seeds = new java.util.HashSet<>();
		for (int region : GolemContent.ISLAND_REGIONS)
		{
			seeds.add(region);
		}
		boolean grew = true;
		while (grew)
		{
			grew = false;
			for (GolemTransport t : transports)
			{
				if (!suppressed.contains(t) && t.getToX() < 6400
					&& seeds.contains(regionOf(t.getFromX(), t.getFromY()))
					&& seeds.add(regionOf(t.getToX(), t.getToY())))
				{
					grew = true;
				}
			}
		}
		// Not around the island itself: its nine regions cover it, and a margin reached the next
		// island's dock.
		java.util.Set<Integer> home = new java.util.HashSet<>(seeds);
		for (int region : seeds)
		{
			if (java.util.Arrays.stream(GolemContent.ISLAND_REGIONS).anyMatch(r -> r == region))
			{
				continue;
			}
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					home.add((((region >> 8) + dx) << 8) | ((region & 0xFF) + dy));
				}
			}
		}
		return home;
	}

	/** Hops a chain of transports is followed looking for somewhere to stand. */
	static final int CHAIN_HOPS = 6;

	/** Where a golem may stand, as whoever is asking judges it. */
	interface Ground
	{
		boolean walkable(int x, int y, int plane);
	}

	/**
	 * True if a golem on this tile, having arrived from {@code came}, can reach walkable ground by
	 * transports without going straight back. Followed for several hops, because a crossing is a
	 * chain: looking one hop ahead passed on every stone of a crossing where none led to a bank.
	 */
	boolean leadsToGround(int x, int y, int plane, int cameX, int cameY, int camePlane, int hops,
		java.util.function.Predicate<GolemTransport> usable, Ground ground)
	{
		if (ground.walkable(x, y, plane))
		{
			return true;
		}
		if (hops <= 0)
		{
			return false;
		}
		for (GolemTransport onward : from(x, y))
		{
			if (onward.getFromPlane() != plane || !usable.test(onward)
				|| (onward.getToX() == cameX && onward.getToY() == cameY && onward.getToPlane() == camePlane))
			{
				continue;
			}
			if (leadsToGround(onward.getToX(), onward.getToY(), onward.getToPlane(), x, y, plane, hops - 1,
				usable, ground))
			{
				return true;
			}
		}
		return false;
	}

	/** Chunks are 16 tiles square: a 48-tile search is a seven-by-seven block of them. */
	private static final int CHUNK_SHIFT = 4;

	/** Origin chunk to the offered transports starting in it. */
	private final Map<Long, List<GolemTransport>> byChunk = new HashMap<>();

	private void indexChunks()
	{
		byChunk.clear();
		for (List<GolemTransport> here : byOrigin.values())
		{
			for (GolemTransport t : here)
			{
				byChunk.computeIfAbsent(pack(t.getFromX() >> CHUNK_SHIFT, t.getFromY() >> CHUNK_SHIFT),
					k -> new ArrayList<>()).add(t);
			}
		}
	}

	/**
	 * Adds every offered transport starting within {@code radius} tiles of a tile, on any plane.
	 * The planner used to probe random tiles for an origin: two dozen probes in nine thousand
	 * tiles find a town's cluster but almost never the one ladder at the end of a corridor.
	 */
	void near(int x, int y, int radius, List<GolemTransport> out)
	{
		for (int cx = (x - radius) >> CHUNK_SHIFT; cx <= (x + radius) >> CHUNK_SHIFT; cx++)
		{
			for (int cy = (y - radius) >> CHUNK_SHIFT; cy <= (y + radius) >> CHUNK_SHIFT; cy++)
			{
				List<GolemTransport> chunk = byChunk.get(pack(cx, cy));
				if (chunk == null)
				{
					continue;
				}
				for (GolemTransport t : chunk)
				{
					if (Math.abs(t.getFromX() - x) <= radius && Math.abs(t.getFromY() - y) <= radius)
					{
						out.add(t);
					}
				}
			}
		}
	}

	/**
	 * Pairs each transport with the one that undoes it: two-way connections are authored as two
	 * rows, so a row's reverse is the one with its endpoints swapped. Turns §11's
	 * no-immediate-reversal rule into an integer comparison.
	 */
	private void link()
	{
		revision++;
		rebuildReachedRegions();

		Map<Long, Integer> byEndpoints = new HashMap<>();
		for (GolemTransport t : transports)
		{
			if (!suppressed.contains(t))
			{
				byEndpoints.put(t.endpointKey(), t.getIndex());
			}
		}

		int linked = 0;
		for (GolemTransport t : transports)
		{
			Integer other = byEndpoints.get(endpoints(t.getToX(), t.getToY(), t.getToPlane(),
				t.getFromX(), t.getFromY(), t.getFromPlane()));
			if (other != null)
			{
				t.setReverse(other);
				linked++;
			}
		}
		log.debug("{} of {} transports have a reverse", linked, transports.size());
	}

	// ----------------------------------------------------------------- parsing

	/** {@code "25 Magic;30 Agility"} to pairs of (level, skill ordinal). */
	private static int[] parseSkills(String spec)
	{
		if (spec.isEmpty())
		{
			return NONE;
		}
		List<Integer> out = new ArrayList<>();
		for (String clause : spec.split(";"))
		{
			String[] parts = clause.trim().split("\\s+", 2);
			if (parts.length != 2)
			{
				continue;
			}
			try
			{
				int level = Integer.parseInt(parts[0]);
				Skill skill = Skill.valueOf(parts[1].trim().toUpperCase());
				out.add(level);
				out.add(skill.ordinal());
			}
			catch (IllegalArgumentException e)
			{
				// A skill this client does not know. Dropping the clause makes the transport easier,
				// never harder, the safe direction here.
				log.debug("Unknown skill requirement: {}", clause);
			}
		}
		return toArray(out);
	}

	/** {@code "Plague City;Song of the Elves"} to quest ordinals. */
	private static int[] parseQuests(String spec)
	{
		if (spec.isEmpty())
		{
			return NONE;
		}
		if (questsByName == null)
		{
			questsByName = new HashMap<>();
			for (Quest quest : Quest.values())
			{
				questsByName.put(quest.getName().toLowerCase(), quest);
			}
		}

		List<Integer> out = new ArrayList<>();
		for (String name : spec.split(";"))
		{
			Quest quest = questsByName.get(name.trim().toLowerCase());
			if (quest == null)
			{
				log.debug("Unknown quest requirement: {}", name);
				continue;
			}
			out.add(quest.ordinal());
		}
		return toArray(out);
	}

	/**
	 * {@code "4070=0;10032>0;4560&2"} to triples of (id, operator, value). The {@code @} form is a
	 * real-time countdown in wall-clock minutes; a golem has nothing to count down, so those
	 * clauses are kept and never satisfied — see {@link GolemAbilities}.
	 */
	private static int[] parseConditions(String spec)
	{
		if (spec.isEmpty())
		{
			return NONE;
		}
		List<Integer> out = new ArrayList<>();
		for (String clause : spec.split(";"))
		{
			String c = clause.trim();
			if (c.isEmpty())
			{
				continue;
			}
			int op;
			int at = -1;
			if ((at = c.indexOf('>')) >= 0)
			{
				op = OP_GT;
			}
			else if ((at = c.indexOf('&')) >= 0)
			{
				op = OP_AND;
			}
			else if ((at = c.indexOf('@')) >= 0)
			{
				op = OP_AT;
			}
			else if ((at = c.indexOf('=')) >= 0)
			{
				op = OP_EQ;
			}
			else
			{
				continue;
			}

			try
			{
				out.add(Integer.parseInt(c.substring(0, at).trim()));
				out.add(op);
				out.add(Integer.parseInt(c.substring(at + 1).trim()));
			}
			catch (NumberFormatException e)
			{
				log.debug("Unparseable condition: {}", clause);
			}
		}
		return toArray(out);
	}

	private static int[] toArray(List<Integer> values)
	{
		if (values.isEmpty())
		{
			return NONE;
		}
		int[] out = new int[values.size()];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = values.get(i);
		}
		return out;
	}

	/** Regions the island's transports and learned routes lead into, with the regions around
	 * each, since an arrival rarely stays in the region it lands in. */
	private final java.util.Set<Integer> reachedRegions = new java.util.HashSet<>();

	/** True if golems can get into this region by transport, so its ground is worth mapping. */
	boolean leadsToRegion(int regionId)
	{
		return reachedRegions.contains(regionId);
	}

	private void rebuildReachedRegions()
	{
		reachedRegions.clear();
		java.util.Set<Integer> island = new java.util.HashSet<>();
		for (int region : GolemContent.ISLAND_REGIONS)
		{
			island.add(region);
		}
		for (GolemTransport t : transports)
		{
			if (suppressed.contains(t))
			{
				continue;
			}
			if (!island.contains(regionOf(t.getFromX(), t.getFromY())) && t.getIndex() < shippedCount)
			{
				continue;
			}
			int rx = t.getToX() >> 6;
			int ry = t.getToY() >> 6;
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					reachedRegions.add((rx + dx) << 8 | (ry + dy));
				}
			}
		}
	}

	private static int regionOf(int x, int y)
	{
		return (x >> 6) << 8 | (y >> 6);
	}

	private static long pack(int x, int y)
	{
		return ((long) x << 32) | (y & 0xFFFFFFFFL);
	}

	static long endpoints(int fx, int fy, int fz, int tx, int ty, int tz)
	{
		// 15 bits per coordinate and 2 per plane fits a world tile pair in a long.
		return ((long) (fx & 0x7FFF) << 49) | ((long) (fy & 0x7FFF) << 34)
			| ((long) (fz & 3) << 32) | ((long) (tx & 0x7FFF) << 17)
			| ((long) (ty & 0x7FFF) << 2) | (tz & 3);
	}
}

package com.golemsdontdie;

import lombok.Getter;
import lombok.Setter;

/**
 * What one golem has used recently, so it does not pace back and forth through a door.
 *
 * <p>Per golem, not global — two golems meeting at the same ladder should both be able to take
 * it. Transport cooldowns are not saved: they stop a golem visibly oscillating over the next
 * minute or two, and after a logout there is none left to interrupt. Shore leave is the exception
 * on both counts, saved and in real time, because a golem restored at a port it has just landed
 * at should not sail straight back out.
 *
 * <p>Endpoints, not row numbers: two rows can go the same way — the rockslide had a shipped row
 * and a learned route with identical ends under different object ids — and learned rows are
 * renumbered whenever what was learned changes. Going back the way it came is about tiles.
 */
final class TransportMemory
{
	/** How many recent journeys to remember. Small: this stops shuffling in a doorway, no more. */
	private static final int HISTORY = 8;

	/** Ticks a used transport, and its reverse, stay barred. Roughly two minutes. */
	static final int COOLDOWN_TICKS = 200;

	/** Least time ashore before a golem may sail again: three minutes, saved with the golem. */
	private static final long SHORE_LEAVE_MILLIS = 3 * 60_000L;

	/** Up to this much more, at random, so a boatload of golems landing together does not all leave together. */
	private static final long SHORE_LEAVE_SPREAD_MILLIS = 2 * 60_000L;

	private static final long MILLIS_PER_TICK = 600;

	/** The clock shore leave is measured on: real time, because it is saved with the golem. */
	static java.util.function.LongSupplier clock = System::currentTimeMillis;

	/** Ring of recently travelled endpoint pairs, and when each expires. */
	private final long[] recent = new long[HISTORY];
	private final int[] expiry = new int[HISTORY];
	private int next;

	/**
	 * Ring of recently used obstacles: {objectId, fromX, fromY, toX, toY, plane}, with expiry.
	 * Endpoints alone were not enough: over a broken cart one way was 2879,2950 to 2876,2952 and
	 * back was 2876,2952 to 2880,2952, so the way back was never barred.
	 */
	private final int[][] usedObstacles = new int[HISTORY][];
	private final int[] usedObstacleExpiry = new int[HISTORY];
	private int nextObstacle;

	/** How near a used obstacle's ends another use of the same object has to start to count as it. */
	private static final int SAME_OBSTACLE_TILES = 2;

	/**
	 * The longest move, in tiles, that counts as crossing one obstacle, and so barred by object and
	 * place. A glider or fairy ring is one object id with a dozen destinations from one spot, and
	 * barring the object stranded golems at a glider platform a thousand times.
	 */
	private static final int OBSTACLE_REACH = 8;

	private static boolean isCrossing(int fromX, int fromY, int toX, int toY)
	{
		return Math.max(Math.abs(toX - fromX), Math.abs(toY - fromY)) <= OBSTACLE_REACH;
	}

	/** The port this golem last sailed from, or -1: reachable again from the next, so it tours. */
	@Getter
	@Setter
	private int blockedPort = -1;

	/**
	 * The port this golem has decided to sail to and is waiting at a dock for, or -1. The distance
	 * field for a port not sailed to lately is built in the background, and deciding afresh each
	 * time meant golems walked to the end of the dock and away again.
	 */
	@Getter
	private int pendingPort = -1;

	/** The dock the golem is waiting at for {@link #pendingPort}, or -1. */
	@Getter
	private int pendingFrom = -1;

	/** The last tick it waits there. */
	@Getter
	private int pendingUntil;

	/** How long a golem waits at a dock for a crossing being worked out: about twenty seconds. */
	static final int PENDING_WAIT_TICKS = 32;

	/** Waits at this dock for a crossing to that port, from now if it was not already. */
	void holdPending(int fromDock, int port, int tick)
	{
		if (pendingPort != port || pendingFrom != fromDock)
		{
			pendingPort = port;
			pendingFrom = fromDock;
			pendingUntil = tick + PENDING_WAIT_TICKS;
		}
	}

	void clearPending()
	{
		pendingPort = -1;
		pendingFrom = -1;
	}

	/** When this golem may next sail, on {@link #clock}; 0 if it may now. Saved with the golem. */
	@Getter
	@Setter
	private long shoreLeaveUntil;

	/** Records a use, barring both this journey and the one that undoes it, which is the same. */
	void used(GolemTransport transport, int tick)
	{
		used(transport, tick, COOLDOWN_TICKS);
	}

	/**
	 * As {@link #used(GolemTransport, int)}, barred for a given number of ticks. Shorter where the
	 * far side is small: two minutes is sensible before a town, very long in a sheep pen.
	 */
	/**
	 * How long a golem walks after using a shortcut before it looks for another. Three minutes.
	 *
	 * <p>Not a cooldown on the shortcut but on the habit: Meiyerditch gave a golem a shortcut in
	 * reach on every decision, and a year of roaming left a third of all golems there. Stepping off
	 * somewhere it cannot walk is exempt.
	 */
	static final int TRANSPORT_REST_TICKS = 300;

	private int restUntil = Integer.MIN_VALUE;

	/** True if the golem has used a shortcut lately and is walking for a while. */
	boolean restingFromTransports(int tick)
	{
		return tick < restUntil;
	}

	void used(GolemTransport transport, int tick, int cooldownTicks)
	{
		restUntil = tick + TRANSPORT_REST_TICKS;
		remember(transport.endpointKey(), tick, cooldownTicks);
		remember(transport.reverseKey(), tick, cooldownTicks);
		journeys[nextJourney] = new int[]{transport.getFromX(), transport.getFromY(), transport.getFromPlane(),
			transport.getToX(), transport.getToY(), transport.getToPlane()};
		journeyExpiry[nextJourney] = tick + cooldownTicks;
		nextJourney = (nextJourney + 1) % HISTORY;
		if (transport.getFromPlane() == transport.getToPlane()
			&& isCrossing(transport.getFromX(), transport.getFromY(), transport.getToX(), transport.getToY()))
		{
			usedObstacles[nextObstacle] = new int[]{transport.getObjectId(), transport.getFromX(), transport.getFromY(),
				transport.getToX(), transport.getToY(), transport.getFromPlane()};
			usedObstacleExpiry[nextObstacle] = tick + cooldownTicks;
			nextObstacle = (nextObstacle + 1) % HISTORY;
		}
	}

	/**
	 * Recent journeys by their ends, {fromX, fromY, fromPlane, toX, toY, toPlane}, to recognise a way
	 * back that is not the exact reverse: down into a cave and back up are often two objects whose
	 * ends are a tile apart, and golems went down and up every few seconds.
	 */
	private final int[][] journeys = new int[HISTORY][];
	private final int[] journeyExpiry = new int[HISTORY];
	private int nextJourney;

	/** True if this transport undoes a recent journey: starts where it ended and ends where it started. */
	private boolean undoesRecentJourney(GolemTransport transport, int tick)
	{
		for (int i = 0; i < HISTORY; i++)
		{
			int[] j = journeys[i];
			if (j != null && journeyExpiry[i] > tick
				&& transport.getFromPlane() == j[5] && transport.getToPlane() == j[2]
				&& near(transport.getFromX(), transport.getFromY(), j[3], j[4])
				&& near(transport.getToX(), transport.getToY(), j[0], j[1]))
			{
				return true;
			}
		}
		return false;
	}

	private void remember(long key, int tick, int cooldownTicks)
	{
		recent[next] = key;
		expiry[next] = tick + cooldownTicks;
		next = (next + 1) % HISTORY;
	}

	boolean onCooldown(GolemTransport transport, int tick)
	{
		long key = transport.endpointKey();
		for (int i = 0; i < HISTORY; i++)
		{
			// An empty slot has expiry 0, which has always passed.
			if (recent[i] == key && expiry[i] > tick)
			{
				return true;
			}
		}
		// A way back that is not the exact reverse. Short hops on one floor go to the rule below.
		if ((transport.getFromPlane() != transport.getToPlane()
			|| !isCrossing(transport.getFromX(), transport.getFromY(), transport.getToX(), transport.getToY()))
			&& undoesRecentJourney(transport, tick))
		{
			return true;
		}

		// The same obstacle, at or beside either end of a recent use: over the cart and back again.
		for (int i = 0; i < HISTORY; i++)
		{
			int[] used = usedObstacles[i];
			if (used == null || usedObstacleExpiry[i] <= tick || used[0] != transport.getObjectId()
				|| used[5] != transport.getFromPlane() || transport.getToPlane() != transport.getFromPlane()
				|| !isCrossing(transport.getFromX(), transport.getFromY(), transport.getToX(), transport.getToY()))
			{
				continue;
			}
			if (near(transport.getFromX(), transport.getFromY(), used[1], used[2])
				|| near(transport.getFromX(), transport.getFromY(), used[3], used[4]))
			{
				// Not the next stone of a crossing: a hop carrying on the same way is the same obstacle.
				int lastX = used[3] - used[1];
				int lastY = used[4] - used[2];
				int nextX = transport.getToX() - transport.getFromX();
				int nextY = transport.getToY() - transport.getFromY();
				if (lastX * nextX + lastY * nextY > 0)
				{
					continue;
				}
				return true;
			}
		}
		return false;
	}

	private static boolean near(int x, int y, int otherX, int otherY)
	{
		return Math.max(Math.abs(x - otherX), Math.abs(y - otherY)) <= SAME_OBSTACLE_TILES;
	}

	/**
	 * Bars sea travel for a while after the golem steps off a boat. Takes the tick the golem
	 * <em>arrives</em>, not the tick it sets out: a crossing is planned up front, so shore leave
	 * would otherwise be spent at sea.
	 */
	void beginShoreLeaveOnArrival(int arrivalTick, int nowTick, java.util.Random random)
	{
		long arrival = clock.getAsLong() + Math.max(0, arrivalTick - nowTick) * MILLIS_PER_TICK;
		long spread = random == null ? 0 : (long) (random.nextDouble() * SHORE_LEAVE_SPREAD_MILLIS);
		shoreLeaveUntil = arrival + SHORE_LEAVE_MILLIS + spread;
	}

	boolean onShoreLeave()
	{
		return clock.getAsLong() < shoreLeaveUntil;
	}
}

package com.golemsdontdie;

import java.util.Arrays;

/**
 * Packed tiles mapped to packed tiles, without boxing, remembering insertion order.
 *
 * <p>The searches ask constantly whether a tile has been reached and from where; as a
 * {@code HashMap<Long, Long>} each question boxed a key and each tile reached made a key, a
 * value and an entry.
 *
 * <p>Insertion order is kept because the flood's order is part of its answer: the far half of
 * what it reached is where a golem is sent, drawn by index.
 */
final class TileMap
{
	/** Marks an empty slot; a real key equal to it is held apart, so any long is valid. */
	private static final long EMPTY = Long.MIN_VALUE;

	private long[] keys;
	private long[] values;
	private int mask;

	/** Keys in the order added, which is also a search's queue. */
	private long[] order;
	private int size;

	private boolean hasEmptyKey;
	private long emptyKeyValue;

	TileMap(int expected)
	{
		int capacity = Integer.highestOneBit(Math.max(4, expected) * 2 - 1) * 2;
		keys = new long[capacity];
		values = new long[capacity];
		Arrays.fill(keys, EMPTY);
		mask = capacity - 1;
		order = new long[Math.max(4, expected)];
	}

	int size()
	{
		return size;
	}

	/** The key added {@code index}th, counting from zero. */
	long keyAt(int index)
	{
		return order[index];
	}

	boolean containsKey(long key)
	{
		if (key == EMPTY)
		{
			return hasEmptyKey;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return true;
			}
			if (at == EMPTY)
			{
				return false;
			}
		}
	}

	/** The value for a key, or {@code missing} if absent. */
	long getOrDefault(long key, long missing)
	{
		if (key == EMPTY)
		{
			return hasEmptyKey ? emptyKeyValue : missing;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot];
			}
			if (at == EMPTY)
			{
				return missing;
			}
		}
	}

	/** The value for a key the map holds; throws if it does not. */
	long get(long key)
	{
		if (key == EMPTY)
		{
			if (!hasEmptyKey)
			{
				throw new IllegalStateException("no such tile");
			}
			return emptyKeyValue;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot];
			}
			if (at == EMPTY)
			{
				throw new IllegalStateException("no such tile");
			}
		}
	}

	/** Adds a key the map does not hold yet; the searches only ever add a tile once. */
	void add(long key, long value)
	{
		if (size == order.length)
		{
			order = Arrays.copyOf(order, size * 2);
		}
		order[size++] = key;
		if (key == EMPTY)
		{
			hasEmptyKey = true;
			emptyKeyValue = value;
			return;
		}
		if (size * 2 > keys.length)
		{
			grow();
		}
		insert(key, value);
	}

	/**
	 * Adds to a key's value, from zero for a key the map does not hold yet.
	 *
	 * @return the value after adding
	 */
	long addTo(long key, long delta)
	{
		if (key == EMPTY)
		{
			if (!hasEmptyKey)
			{
				add(key, delta);
				return delta;
			}
			return emptyKeyValue += delta;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot] += delta;
			}
			if (at == EMPTY)
			{
				add(key, delta);
				return delta;
			}
		}
	}

	/** Empties the map, keeping its capacity. */
	void clear()
	{
		if (size == 0)
		{
			return;
		}
		Arrays.fill(keys, EMPTY);
		size = 0;
		hasEmptyKey = false;
	}

	private void insert(long key, long value)
	{
		int slot = slot(key);
		while (keys[slot] != EMPTY)
		{
			slot = (slot + 1) & mask;
		}
		keys[slot] = key;
		values[slot] = value;
	}

	private void grow()
	{
		long[] oldKeys = keys;
		long[] oldValues = values;
		keys = new long[oldKeys.length * 2];
		values = new long[oldKeys.length * 2];
		Arrays.fill(keys, EMPTY);
		mask = keys.length - 1;
		for (int i = 0; i < oldKeys.length; i++)
		{
			if (oldKeys[i] != EMPTY)
			{
				insert(oldKeys[i], oldValues[i]);
			}
		}
	}

	private int slot(long key)
	{
		long h = key * 0x9E3779B97F4A7C15L;
		return (int) (h ^ (h >>> 32)) & mask;
	}
}

package com.golemsdontdie;

/**
 * Shortcuts whose real animation was watched in game, keyed by the object.
 *
 * <p>Which clip an obstacle plays is decided server-side and appears in no file — object
 * definitions carry the object's own animation, not the person's — so every entry below was
 * measured in game. Measurements beat the archetype mapping in {@link GolemTransport}, which
 * guesses from the menu text: it put the basalt stones on the 68-cycle
 * {@code HUMAN_STEPPINGSTONEJUMP} rather than the 38-cycle 741, doubling every hop. The
 * archetype still answers for the thirteen thousand nobody has measured.
 */
final class MeasuredShortcuts
{
	private MeasuredShortcuts()
	{
	}

	/**
	 * {objectId, animationId, ticks}. Ticks of zero mean the clip's own length is used, usually
	 * right: the cathedral door measured one tick against a 30-cycle clip, the cave three
	 * against 96.
	 */
	private static final int[][] MEASURED = {
		// Wyrmscraig basalt stepping stones; hops two ticks apart, the 38-cycle clip plus a breath.
		{62260, 741, 0},
		{62261, 741, 0},
		{62262, 741, 0},

		// Wyrmscraig's rock climb: two co-located objects, one per approach, east being the top.
		// West (2550, 2209) uses 62267, the 4435 climbing loop; east (2554, 2209) uses 62265,
		// HUMAN_CLIMBING_DOWN 740. Climbs are directional; the rows once used 62267 both ways
		// and the golem climbed the wrong way down.
		{62267, 4435, 0},
		{62265, 740, 0},

		// The cave mouth, both ends: three ticks, and a 96-cycle clip that agrees.
		{62219, 2796, 3},
		{62220, 2796, 3},

		// A door, for calibration: one tick against a 30-cycle clip.
		{62368, 4282, 1},
		{62369, 4282, 1},
	};

	/** The measured animation for an object, or -1 if unmeasured. */
	static int animationFor(int objectId)
	{
		for (int[] row : MEASURED)
		{
			if (row[0] == objectId)
			{
				return row[1];
			}
		}
		return -1;
	}

	/** The measured duration in ticks, or 0 to use the clip's own length. */
	static int ticksFor(int objectId)
	{
		for (int[] row : MEASURED)
		{
			if (row[0] == objectId)
			{
				return row[2];
			}
		}
		return 0;
	}

	static boolean isMeasured(int objectId)
	{
		return animationFor(objectId) != -1;
	}
}

package com.golemsdontdie;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * Between an instance and the fixed place in the world it is copied from.
 *
 * <p>An instance — a boss room behind a church pew — is built fresh on every visit, in
 * coordinates that mean nothing next time. Its template, the static copy elsewhere assembled from
 * in eight-tile chunks, does stay put, so all a golem keeps about an instance is in template
 * coordinates: golems wander the template room and are drawn in whichever instance is loaded.
 *
 * <p>Only unrotated chunks are mapped; rotation turns walls and headings as well as positions.
 */
final class InstanceMap
{
	private static final int CHUNK = 8;

	private InstanceMap()
	{
	}

	/** The template of a loaded instance tile; the tile itself outside one; null if rotated. */
	static WorldPoint templateOf(WorldView wv, WorldPoint tile)
	{
		if (tile == null || wv == null || !wv.isInstance())
		{
			return tile;
		}
		int sceneX = tile.getX() - wv.getBaseX();
		int sceneY = tile.getY() - wv.getBaseY();
		int data = chunkAt(wv, tile.getPlane(), sceneX, sceneY);
		if (data <= 0 || rotation(data) != 0)
		{
			return null;
		}
		return new WorldPoint(templateChunkX(data) * CHUNK + (sceneX & (CHUNK - 1)),
			templateChunkY(data) * CHUNK + (sceneY & (CHUNK - 1)), templatePlane(data));
	}

	/** The raw chunk data under a scene tile, or -1 outside the scene. */
	static int chunkAt(WorldView wv, int plane, int sceneX, int sceneY)
	{
		int[][][] chunks = wv.getInstanceTemplateChunks();
		if (chunks == null || plane < 0 || plane >= chunks.length || sceneX < 0 || sceneY < 0)
		{
			return -1;
		}
		int cx = sceneX / CHUNK;
		int cy = sceneY / CHUNK;
		if (cx >= chunks[plane].length || cy >= chunks[plane][cx].length)
		{
			return -1;
		}
		return chunks[plane][cx][cy];
	}

	/**
	 * Where each template chunk sits in the loaded instance, as {sceneChunkX, sceneChunkY,
	 * scenePlane}, keyed by {@link #chunkKey} of the template chunk. Unrotated chunks only.
	 */
	static Map<Long, int[]> sceneChunks(WorldView wv)
	{
		Map<Long, int[]> out = new HashMap<>();
		int[][][] chunks = wv.getInstanceTemplateChunks();
		if (chunks == null)
		{
			return out;
		}
		for (int z = 0; z < chunks.length; z++)
		{
			for (int cx = 0; cx < chunks[z].length; cx++)
			{
				for (int cy = 0; cy < chunks[z][cx].length; cy++)
				{
					int data = chunks[z][cx][cy];
					if (data <= 0 || rotation(data) != 0)
					{
						continue;
					}
					out.putIfAbsent(chunkKey(templateChunkX(data), templateChunkY(data), templatePlane(data)),
						new int[]{cx, cy, z});
				}
			}
		}
		return out;
	}

	/**
	 * Where a template tile appears in the loaded instance, given {@link #sceneChunks}; null if
	 * its chunk is not part of it.
	 */
	static WorldPoint instanceTileOf(WorldView wv, Map<Long, int[]> sceneChunks, int x, int y, int plane)
	{
		int[] scene = sceneChunks.get(chunkKey(x >> 3, y >> 3, plane));
		if (scene == null)
		{
			return null;
		}
		return new WorldPoint(wv.getBaseX() + (scene[0] << 3) + (x & (CHUNK - 1)),
			wv.getBaseY() + (scene[1] << 3) + (y & (CHUNK - 1)), scene[2]);
	}

	static long chunkKey(int chunkX, int chunkY, int plane)
	{
		return ((long) plane << 40) | ((long) chunkX << 20) | chunkY;
	}

	static int rotation(int data)
	{
		return data >> 1 & 0x3;
	}

	static int templateChunkX(int data)
	{
		return data >> 14 & 0x3FF;
	}

	static int templateChunkY(int data)
	{
		return data >> 3 & 0x7FF;
	}

	static int templatePlane(int data)
	{
		return data >> 24 & 0x3;
	}
}

package com.golemsdontdie;

import java.util.List;

/**
 * One crossing a golem made in view: the route it used, and where it actually was while using it.
 *
 * <p>The golem's half of the obstacle record, so a slanted crossing shows up as a number; see
 * ObstacleDataBridge. Positions are in 128ths of a tile, as golems are simulated. Only short,
 * same-floor crossings are traced: a ladder has no path across it to be wrong about.
 */
final class GolemTraversal
{
	final GolemTransport route;

	/** Where the golem was when the crossing began and when it let go. */
	final int startX;
	final int startY;
	final int endX;
	final int endY;

	/** {cycles since the start, x, y}, a frame apart. */
	final List<int[]> samples;

	GolemTraversal(GolemTransport route, int startX, int startY, int endX, int endY, List<int[]> samples)
	{
		this.route = route;
		this.startX = startX;
		this.startY = startY;
		this.endX = endX;
		this.endY = endY;
		this.samples = samples;
	}
}

package com.golemsdontdie;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Picks somewhere for a golem to go, and works out how to walk there.
 *
 * <p>Everything is in world tiles, queried against {@link IslandMemory}, so a search works the
 * same whether the golem is on screen or three regions away: pathing cannot depend on the scene.
 * Paths are breadth-first over cardinal steps — distances are short, and BFS is exhaustive within
 * its budget, so a golem penned in by scenery finds out it is stuck rather than walking into it.
 */
@Singleton
class GolemPathfinder
{
	/** Ceiling on tiles per search. Reached when a golem is walled in, which recurs every plan. */
	private static final int NODE_BUDGET = 3000;

	/** Tries for a reachable destination before the golem gives up and idles. */
	private static final int DESTINATION_ATTEMPTS = 10;

	/**
	 * The eight steps a golem may take, cardinals first.
	 *
	 * <p>Uniform-cost BFS over eight neighbours is exact for this game: a diagonal step costs one
	 * game tick exactly as a cardinal does. Cardinals come first so that where two routes are the
	 * same length the straight one wins; whether a diagonal is legal is canStep's corner rule.
	 */
	private static final int[] DX = {1, -1, 0, 0, 1, -1, 1, -1};
	private static final int[] DY = {0, 0, 1, -1, 1, 1, -1, -1};

	@Inject
	private IslandMemory memory;

	/**
	 * A path to a random reachable destination inside {@code bounds}. Destinations are sampled and
	 * rejected rather than enumerated, which would bias the choice toward the densest part.
	 *
	 * @return world tiles to walk through, excluding the start; empty if nowhere goes
	 */
	Deque<int[]> wanderPath(int startX, int startY, int plane, RoamBounds bounds, Random random)
	{
		// Attempts are spent on searches, not on samples: a sample landing on a wall costs nothing to
		// reject, and counting it meant a golem in the cathedral, where most of the window is walls,
		// ran out of tries before it had searched once.
		int searched = 0;
		for (int sampled = 0; sampled < DESTINATION_ATTEMPTS * 8 && searched < DESTINATION_ATTEMPTS; sampled++)
		{
			int[] target = bounds.sample(random);
			if (target == null || (target[0] == startX && target[1] == startY))
			{
				continue;
			}
			if (!bounds.contains(target[0], target[1]) || !memory.isKnownWalkable(target[0], target[1], plane)
				|| bounds.avoids(target[0], target[1]))
			{
				continue;
			}
			searched++;

			Deque<int[]> path = findPath(startX, startY, plane, target[0], target[1], bounds);
			if (!path.isEmpty())
			{
				return path;
			}
		}
		return smallFloorPath(startX, startY, plane, bounds, random);
	}

	/** The most tiles a floor may have for its every tile to be worth listing when sampling misses. */
	private static final int SMALL_FLOOR = 200;

	/** A walk to a reachable tile when sampling found none, as on a lookout of a dozen tiles. */
	private Deque<int[]> smallFloorPath(int startX, int startY, int plane, RoamBounds bounds, Random random)
	{
		TileMap reach = flood(startX, startY, plane, SMALL_FLOOR);
		for (int tries = 0; tries < 8 && reach.size() > 1; tries++)
		{
			long pick = reach.keyAt(1 + random.nextInt(reach.size() - 1));
			int x = unpackX(pick);
			int y = unpackY(pick);
			if (bounds.contains(x, y) && !bounds.avoids(x, y))
			{
				return pathFrom(reach, startX, startY, x, y);
			}
		}
		return new ArrayDeque<>();
	}

	/**
	 * Breadth-first path between two world tiles, staying inside {@code bounds}.
	 *
	 * @return the tiles to walk through, excluding the start; empty if unreachable
	 */
	Deque<int[]> findPath(int startX, int startY, int plane, int goalX, int goalY, RoamBounds bounds)
	{
		Deque<int[]> result = new ArrayDeque<>();
		if (startX == goalX && startY == goalY)
		{
			return result;
		}

		// Keyed by packed world tile rather than indexed by scene position: in free roam there is no
		// fixed-size grid to index into. Every tile reached is queued exactly when it is recorded, so
		// the record's own order is the queue.
		TileMap cameFrom = new TileMap(1024);
		int head = 0;

		long start = pack(startX, startY);
		long goal = pack(goalX, goalY);
		cameFrom.add(start, start);

		int visited = 0;
		boolean found = false;

		while (head < cameFrom.size() && visited < NODE_BUDGET)
		{
			long current = cameFrom.keyAt(head++);
			visited++;

			if (current == goal)
			{
				found = true;
				break;
			}

			int cx = unpackX(current);
			int cy = unpackY(current);

			for (int d = 0; d < DX.length; d++)
			{
				int nx = cx + DX[d];
				int ny = cy + DY[d];
				long next = pack(nx, ny);

				if (cameFrom.containsKey(next)
					|| !bounds.contains(nx, ny)
					|| !memory.canStep(cx, cy, plane, DX[d], DY[d]))
				{
					continue;
				}

				cameFrom.add(next, current);
			}
		}

		if (!found)
		{
			return result;
		}

		// Walk the parent chain back, pushing onto the front to reverse it into start-to-goal order.
		for (long at = goal; at != start; at = cameFrom.get(at))
		{
			result.addFirst(new int[]{unpackX(at), unpackY(at)});
		}
		return result;
	}

	/**
	 * Every tile that can be walked to from a start, breadth first, up to a budget: each tile mapped
	 * to the one it was reached from, so {@link #pathFrom} reads back the walk without searching.
	 */
	TileMap flood(int startX, int startY, int plane, int budget)
	{
		// The record's order is the queue, as in findPath.
		TileMap cameFrom = new TileMap(budget + 8);
		int head = 0;
		long start = pack(startX, startY);
		cameFrom.add(start, start);

		while (head < cameFrom.size() && cameFrom.size() < budget)
		{
			long current = cameFrom.keyAt(head++);
			int cx = unpackX(current);
			int cy = unpackY(current);
			for (int d = 0; d < DX.length; d++)
			{
				int nx = cx + DX[d];
				int ny = cy + DY[d];
				long next = pack(nx, ny);
				if (cameFrom.containsKey(next)
					|| !memory.isKnownWalkable(nx, ny, plane)
					|| !memory.canStep(cx, cy, plane, DX[d], DY[d]))
				{
					continue;
				}
				cameFrom.add(next, current);
			}
		}
		return cameFrom;
	}

	/**
	 * The walk from a flood's start to a tile it reached, excluding the start.
	 *
	 * @return the tiles in order, empty if the goal is the start, null if it was not reached
	 */
	static Deque<int[]> pathFrom(TileMap cameFrom, int startX, int startY, int goalX, int goalY)
	{
		long start = pack(startX, startY);
		long goal = pack(goalX, goalY);
		if (!cameFrom.containsKey(goal))
		{
			return null;
		}
		Deque<int[]> result = new ArrayDeque<>();
		for (long at = goal; at != start; at = cameFrom.get(at))
		{
			result.addFirst(new int[]{unpackX(at), unpackY(at)});
		}
		return result;
	}

	/**
	 * How many tiles can be walked to from here, counting up to a limit. Stops there because only
	 * whether a space is small matters: an open field and a continent are the same to a golem.
	 */
	int areaSize(int x, int y, int plane, int limit)
	{
		TileMap seen = new TileMap(limit + 8);
		int head = 0;
		long start = pack(x, y);
		seen.add(start, 0);
		while (head < seen.size() && seen.size() < limit)
		{
			long current = seen.keyAt(head++);
			int cx = unpackX(current);
			int cy = unpackY(current);
			for (int d = 0; d < DX.length; d++)
			{
				long next = pack(cx + DX[d], cy + DY[d]);
				if (!seen.containsKey(next) && memory.canStep(cx, cy, plane, DX[d], DY[d]))
				{
					seen.add(next, 0);
				}
			}
		}
		return seen.size();
	}

	static long pack(int x, int y)
	{
		return ((long) x << 32) | (y & 0xFFFFFFFFL);
	}

	static int unpackX(long packed)
	{
		return (int) (packed >> 32);
	}

	static int unpackY(long packed)
	{
		return (int) packed;
	}
}

package com.golemsdontdie.telemetry;

/**
 * One crossing of an obstacle by the player, as it is kept on disk.
 *
 * <p>Plain numbers and the game's own text for the object. Positions are world tiles of the obstacle
 * itself; the path across it is measured relative to them, so it says how the obstacle moves a
 * player and nothing about where the player was otherwise.
 *
 * <p>Distances are in 128ths of a tile and times in client cycles (20 ms) unless a field says
 * otherwise — the units the game animates in.
 */
public final class PlayerCrossing
{
	/** The scene object used. */
	public final int objectId;

	/** The object's name, from the game cache. */
	public final String name;

	/** The menu option and target, e.g. "Climb-over Stile". */
	public final String menu;

	/** Every animation played, in order. */
	public final int[] animations;

	/** Game ticks (600 ms) from the first animation starting to standing still somewhere new. */
	public final int ticks;

	/** Cycles from the first animation starting until the player first moved. */
	public final int moveDelay;

	/** Cycles the movement itself lasted. */
	public final int moveSpan;

	/** The tile the crossing starts from and the tile it ends on: x, y and floor. */
	public final int fromX;
	public final int fromY;
	public final int fromPlane;
	public final int toX;
	public final int toY;
	public final int toPlane;

	/** How far the obstacle itself moved the player, in whole tiles east and north. */
	public final int lineX;
	public final int lineY;

	/** True if it happened inside an instance, whose coordinates are not the world's. */
	public final boolean instance;

	/**
	 * The path across, one entry every two cycles: {cycle, along, side}. Along is the distance
	 * towards the far tile, side the distance off to the left (negative) or right of the straight
	 * line between the two tiles. Empty if it could not be recorded.
	 */
	public final int[][] path;

	/** Each point the animation changed: {cycle, animation}. */
	public final int[][] animationChanges;

	/** Which way the player faced relative to the way they moved, 0 to 2047 (1024 is backwards); -1 unknown. */
	public final int facing;

	public PlayerCrossing(int objectId, String name, String menu, int[] animations, int ticks, int moveDelay,
		int moveSpan, int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane, int lineX, int lineY,
		boolean instance, int[][] path, int[][] animationChanges, int facing)
	{
		this.objectId = objectId;
		this.name = name;
		this.menu = menu;
		this.animations = animations;
		this.ticks = ticks;
		this.moveDelay = moveDelay;
		this.moveSpan = moveSpan;
		this.fromX = fromX;
		this.fromY = fromY;
		this.fromPlane = fromPlane;
		this.toX = toX;
		this.toY = toY;
		this.toPlane = toPlane;
		this.lineX = lineX;
		this.lineY = lineY;
		this.instance = instance;
		this.path = path;
		this.animationChanges = animationChanges;
		this.facing = facing;
	}
}

package com.golemsdontdie.telemetry;

/**
 * One crossing of an obstacle by a golem the player could see, as it is kept on disk.
 *
 * <p>The route is the pair of tiles the golem was meant to cross between; the positions are where it
 * actually was, frame by frame. {@link ObstacleDataFile} measures those against the route, the same
 * way a player's path is measured, so the two can be compared directly.
 *
 * <p>Positions are world coordinates in 128ths of a tile; times are client cycles (20 ms).
 */
public final class GolemCrossing
{
	/** The scene object crossed. */
	public final int objectId;

	/** The tile the route starts from and the tile it ends on: x, y and floor. */
	public final int fromX;
	public final int fromY;
	public final int fromPlane;
	public final int toX;
	public final int toY;
	public final int toPlane;

	/** Where the golem was at each frame of the crossing: {cycle, x, y}. First and last included. */
	public final int[][] positions;

	/** True if the route passed over a tile another short hop starts on: a stepping stone skipped. */
	public final boolean overStone;

	public GolemCrossing(int objectId, int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane,
		int[][] positions, boolean overStone)
	{
		this.objectId = objectId;
		this.fromX = fromX;
		this.fromY = fromY;
		this.fromPlane = fromPlane;
		this.toX = toX;
		this.toY = toY;
		this.toPlane = toPlane;
		this.positions = positions;
		this.overStone = overStone;
	}
}

package com.golemsdontdie.telemetry;

import java.io.BufferedReader;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * The obstacle data file: {@value #FILE_NAME} in the plugin's own folder.
 *
 * <p>Tab-separated text, readable in any spreadsheet. Lines starting {@code #} describe the file;
 * {@code P} lines are crossings by the player, {@code G} lines crossings by golems. Column names are
 * written into the file above each kind.
 *
 * <p>One line per distinct crossing. The same crossing again adds to its count instead of adding a
 * line; past {@link #MAX_LINES} of a kind, the one seen least recently is dropped. So the file stays
 * small however long the plugin is used.
 *
 * <p>Nothing here sends anything. See the package documentation for what is kept and why.
 */
@Slf4j
public final class ObstacleDataFile
{
	public static final String FILE_NAME = "golem-obstacle-data.tsv";

	/** Bumped whenever a column changes. A file from another schema is replaced, not misread. */
	static final int SCHEMA = 3;

	/** Lines kept of each kind. */
	static final int MAX_LINES = 2000;

	/** Points kept of any one path. A longer path is thinned evenly, keeping its first and last. */
	static final int PATH_POINTS = 60;

	/** 128ths of a tile in a tile. */
	private static final int TILE = 128;

	private static final String PLAYER_COLUMNS = "#P\tobject\tname\tmenu\tanimations\tticks\tmoveDelay\tmoveSpan"
		+ "\tfromX\tfromY\tfromPlane\ttoX\ttoY\ttoPlane\tlineX\tlineY\tinstance\tseen\tfacing"
		+ "\tanimationChanges\tpath";

	private static final String GOLEM_COLUMNS = "#G\tobject\tfromX\tfromY\tfromPlane\ttoX\ttoY\ttoPlane"
		+ "\tattempts\tworstSide\tworstLanding\tworstStart\toverStone\tpath";

	/** Where each counted column of a line is, looked up by its name in the headers above. */
	private static final int P_SEEN = column(PLAYER_COLUMNS, "seen");
	private static final int G_ATTEMPTS = column(GOLEM_COLUMNS, "attempts");
	private static final int G_WORST_SIDE = column(GOLEM_COLUMNS, "worstSide");
	private static final int G_WORST_LANDING = column(GOLEM_COLUMNS, "worstLanding");
	private static final int G_WORST_START = column(GOLEM_COLUMNS, "worstStart");
	private static final int G_OVER_STONE = column(GOLEM_COLUMNS, "overStone");

	/**
	 * Where the file is kept. In play, the plugin's own folder, through RuneLite's file utility, which
	 * is the only way a plugin touches the disk. In a test, a string in memory.
	 */
	public interface Store
	{
		boolean exists();

		BufferedReader reader() throws IOException;

		/** Replaces the whole file with this text. */
		void write(String text) throws IOException;
	}

	private final Store store;
	private final String pluginVersion;

	/** Lines by crossing, least recently seen first. The first column (P or G) is not stored. */
	private final Map<String, String[]> player = new LinkedHashMap<>(64, 0.75f, true);
	private final Map<String, String[]> golem = new LinkedHashMap<>(64, 0.75f, true);

	private boolean changed;

	public ObstacleDataFile(Store store, String pluginVersion)
	{
		this.store = store;
		this.pluginVersion = pluginVersion;
	}

	// ------------------------------------------------------------------ reading and writing

	/** Reads the file, if there is one. An unreadable file or another schema starts afresh. */
	public void load()
	{
		player.clear();
		golem.clear();
		changed = false;
		try
		{
			if (!store.exists())
			{
				return;
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Could not look for the obstacle data file", e);
			return;
		}
		try (BufferedReader in = store.reader())
		{
			boolean sameSchema = false;
			String line;
			while ((line = in.readLine()) != null)
			{
				String[] columns = line.split("\t", -1);
				if (columns[0].equals("#schema"))
				{
					sameSchema = columns.length > 1 && columns[1].equals(String.valueOf(SCHEMA));
				}
				else if (sameSchema && columns[0].equals("P") && columns.length == columnCount(PLAYER_COLUMNS))
				{
					String[] row = withoutKind(columns);
					player.put(playerKey(row), row);
				}
				else if (sameSchema && columns[0].equals("G") && columns.length == columnCount(GOLEM_COLUMNS))
				{
					String[] row = withoutKind(columns);
					golem.put(golemKey(row), row);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			player.clear();
			golem.clear();
			log.warn("Obstacle data unreadable; starting a fresh file", e);
		}
	}

	/** Writes the file, if anything has been added since it was last written. */
	public void save()
	{
		if (!changed)
		{
			return;
		}
		changed = false;
		StringBuilder out = new StringBuilder();
		out.append("# Golems Don't Die obstacle data. Kept on this computer; nothing in it is sent anywhere.\n");
		out.append("# P lines: crossings of obstacles by the player. G lines: crossings by golems.\n");
		out.append("# Distances in 128ths of a tile, times in 20 ms client cycles unless named otherwise.\n");
		out.append("# A path is cycle:along:side, measured from the start tile towards the end tile.\n");
		out.append("#schema\t").append(SCHEMA).append('\n');
		out.append("#plugin\t").append(pluginVersion).append('\n');
		out.append(PLAYER_COLUMNS).append('\n');
		for (String[] row : player.values())
		{
			out.append("P\t").append(String.join("\t", row)).append('\n');
		}
		out.append(GOLEM_COLUMNS).append('\n');
		for (String[] row : golem.values())
		{
			out.append("G\t").append(String.join("\t", row)).append('\n');
		}
		try
		{
			store.write(out.toString());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not write the obstacle data file", e);
		}
	}

	// ------------------------------------------------------------------ adding crossings

	/** Adds a crossing by the player, or counts another of one already kept. */
	public void add(PlayerCrossing c)
	{
		String[] row = {
			String.valueOf(c.objectId), text(c.name), text(c.menu), list(c.animations),
			String.valueOf(c.ticks), String.valueOf(c.moveDelay), String.valueOf(c.moveSpan),
			String.valueOf(c.fromX), String.valueOf(c.fromY), String.valueOf(c.fromPlane),
			String.valueOf(c.toX), String.valueOf(c.toY), String.valueOf(c.toPlane),
			String.valueOf(c.lineX), String.valueOf(c.lineY), c.instance ? "1" : "0",
			"1", String.valueOf(c.facing), pairs(c.animationChanges), path(c.path),
		};
		// The newest recording of a crossing replaces the old one; only the count carries over.
		String[] kept = player.get(playerKey(row));
		if (kept != null)
		{
			row[P_SEEN] = String.valueOf(number(kept[P_SEEN]) + 1);
		}
		put(player, playerKey(row), row);
	}

	/** Adds a crossing by a golem, or counts another on a route already kept. */
	public void add(GolemCrossing c)
	{
		// The route is the straight line between the middles of its two tiles.
		int fromX = c.fromX * TILE + TILE / 2;
		int fromY = c.fromY * TILE + TILE / 2;
		int toX = c.toX * TILE + TILE / 2;
		int toY = c.toY * TILE + TILE / 2;

		int[][] measured = new int[c.positions.length][];
		int worstSide = 0;
		for (int i = 0; i < c.positions.length; i++)
		{
			int[] p = c.positions[i];
			int[] alongSide = alongAndSide(p[1] - fromX, p[2] - fromY, toX - fromX, toY - fromY);
			measured[i] = new int[]{p[0], alongSide[0], alongSide[1]};
			worstSide = Math.max(worstSide, Math.abs(alongSide[1]));
		}
		int[] first = c.positions.length > 0 ? c.positions[0] : new int[]{0, fromX, fromY};
		int[] last = c.positions.length > 0 ? c.positions[c.positions.length - 1] : first;
		int start = distance(first[1] - fromX, first[2] - fromY);
		int landing = distance(last[1] - toX, last[2] - toY);

		String[] row = {
			String.valueOf(c.objectId),
			String.valueOf(c.fromX), String.valueOf(c.fromY), String.valueOf(c.fromPlane),
			String.valueOf(c.toX), String.valueOf(c.toY), String.valueOf(c.toPlane),
			"1", String.valueOf(worstSide), String.valueOf(landing), String.valueOf(start),
			c.overStone ? "1" : "0", path(measured),
		};
		// The newest path replaces the old; counts add up, and the worst of each measure is kept,
		// because the worst crossing is the one that needs fixing.
		String[] kept = golem.get(golemKey(row));
		if (kept != null)
		{
			row[G_ATTEMPTS] = String.valueOf(number(kept[G_ATTEMPTS]) + 1);
			row[G_WORST_SIDE] = String.valueOf(Math.max(worstSide, number(kept[G_WORST_SIDE])));
			row[G_WORST_LANDING] = String.valueOf(Math.max(landing, number(kept[G_WORST_LANDING])));
			row[G_WORST_START] = String.valueOf(Math.max(start, number(kept[G_WORST_START])));
			row[G_OVER_STONE] = String.valueOf(number(kept[G_OVER_STONE]) + (c.overStone ? 1 : 0));
		}
		put(golem, golemKey(row), row);
	}

	public int playerLines()
	{
		return player.size();
	}

	public int golemLines()
	{
		return golem.size();
	}

	// ------------------------------------------------------------------ helpers

	private void put(Map<String, String[]> lines, String key, String[] row)
	{
		lines.put(key, row);
		while (lines.size() > MAX_LINES)
		{
			lines.remove(lines.keySet().iterator().next());
		}
		changed = true;
	}

	/** A player crossing is the object, what it played, and its two tiles. */
	private static String playerKey(String[] row)
	{
		return row[0] + "|" + row[3] + "|" + row[7] + "," + row[8] + "," + row[9] + ">" + row[10] + "," + row[11]
			+ "," + row[12];
	}

	/** A golem crossing is the object and its two tiles. */
	private static String golemKey(String[] row)
	{
		return row[0] + "|" + row[1] + "," + row[2] + "," + row[3] + ">" + row[4] + "," + row[5] + "," + row[6];
	}

	/**
	 * A point measured along a line and to its side: {along, side}. Along is the distance towards
	 * the line's end, side the distance off it, negative to the left.
	 */
	static int[] alongAndSide(int x, int y, int lineX, int lineY)
	{
		double length = Math.hypot(lineX, lineY);
		if (length == 0)
		{
			return new int[]{0, distance(x, y)};
		}
		double ux = lineX / length;
		double uy = lineY / length;
		return new int[]{(int) Math.round(x * ux + y * uy), (int) Math.round(x * uy - y * ux)};
	}

	private static int distance(int x, int y)
	{
		return (int) Math.round(Math.hypot(x, y));
	}

	/** A path as cycle:along:side entries, thinned evenly to {@link #PATH_POINTS}. */
	private static String path(int[][] points)
	{
		StringBuilder sb = new StringBuilder();
		if (points == null)
		{
			return "";
		}
		int step = Math.max(1, (points.length + PATH_POINTS - 1) / PATH_POINTS);
		for (int i = 0; i < points.length; i++)
		{
			if (i % step == 0 || i == points.length - 1)
			{
				sb.append(sb.length() == 0 ? "" : ",")
					.append(points[i][0]).append(':').append(points[i][1]).append(':').append(points[i][2]);
			}
		}
		return sb.toString();
	}

	/** {a, b} pairs as a:b entries. */
	private static String pairs(int[][] values)
	{
		StringBuilder sb = new StringBuilder();
		if (values != null)
		{
			for (int[] pair : values)
			{
				sb.append(sb.length() == 0 ? "" : ",").append(pair[0]).append(':').append(pair[1]);
			}
		}
		return sb.toString();
	}

	private static String list(int[] values)
	{
		StringBuilder sb = new StringBuilder();
		if (values != null)
		{
			for (int value : values)
			{
				sb.append(sb.length() == 0 ? "" : ",").append(value);
			}
		}
		return sb.toString();
	}

	/** Game text with anything that would break a line or a column taken out. */
	private static String text(String value)
	{
		return value == null ? "" : value.replace('\t', ' ').replace('\n', ' ').replace('\r', ' ');
	}

	private static int number(String value)
	{
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** A named column's place in a stored line, which leaves out the header's first column (#P or #G). */
	private static int column(String header, String name)
	{
		String[] names = header.split("	");
		for (int i = 1; i < names.length; i++)
		{
			if (names[i].equals(name))
			{
				return i - 1;
			}
		}
		throw new IllegalArgumentException("no column " + name);
	}

	private static int columnCount(String header)
	{
		return header.split("\t").length;
	}

	private static String[] withoutKind(String[] columns)
	{
		String[] row = new String[columns.length - 1];
		System.arraycopy(columns, 1, row, 0, row.length);
		return row;
	}
}

