	 * typed into a chatbox prompt left open, must not save: the roster is empty by then, and
	 * saving it replaced every golem the player had.
	 */
	private volatile boolean running;

	/** The tick an asked-for roster save is due, or -1. Renames ask; the save waits a moment for more. */
	private int saveGolemsAt = -1;

	/** Ticks a rename waits before saving, so typing a name is one save, not one a keystroke. */
	private static final int RENAME_SAVE_DELAY = 2;

	/** Set when a sighting was recorded this tick; routes rebuild once, at its end. */
	private boolean routesChanged;

	/**
	 * Whether a learned route is an obstacle. The answer can take a path search, and every
	 * route used to be re-asked on every sighting — one search per stone of a crossing.
	 */
	private final java.util.Map<String, Boolean> obstacleVerdicts = new java.util.HashMap<>();

	@Inject
	private Voyage voyage;

	@Inject
	private GolemCensus census;

	/** How often golems are counted by region, in game ticks. See GolemCensus. */
	private static final int CENSUS_TICKS = 10;

	private int ticksSinceCensus;

	/** Set when a golem is added, removed or restored, so the panel redraws once. */
	private boolean rosterChanged = true;

	// ------------------------------------------------------------------ obstacles

	/**
	 * Takes one sighting from the observer. The player is told only when an obstacle unlocks:
	 * a message per traversal would be chat spam on an agility course.
	 */
	private void onObstacleSighting(ObstacleSighting sighting)
	{
		// Only obstacles: chopping a tree, using a bank booth and picking sweetcorn were all
		// learned as shortcuts, since an object clicked, an animation and the player elsewhere
		// afterwards is all a watcher can see.
		//
		// In a rotated instance no route is usable, but what the obstacle plays is as true
		// there, so it is still recorded; the route filter refuses the route.
		boolean inInstance = sighting.fromX >= INSTANCE_X || sighting.toX >= INSTANCE_X;
		boolean obstacle = inInstance
			? obstacleIndex.knows(sighting.objectId) || transports.isShippedObstacle(sighting.objectId)
			: isObstacle(sighting.objectId, sighting.fromX, sighting.fromY, sighting.fromPlane,
				sighting.toX, sighting.toY, sighting.toPlane);
		if (!obstacle)
		{
			log.debug("Not an obstacle: {}", sighting);
			return;
		}

		// Deliberately silent: learning happens constantly during ordinary play, and
		// announcing it would make a background nicety feel like a chore.
		if (obstacleKnowledge.record(sighting))
		{
			log.debug("Obstacle unlocked: {}", sighting);
		}

		// Routes go in as they are earned, not at the next start-up: somebody who has shown the
		// plugin a staircase twice should see golems use it. Once per tick, however many hops.
		routesChanged = true;

		// And kept on disk, for a later update to offer to send.
		obstacleData.playerCrossed(sighting);
	}

	/** Puts what this tick's sightings taught into the network, and saves it. */
	private void applyLearnedRoutes()
	{
		routesChanged = false;
		transports.setLearnedRoutes(obstacleKnowledge.learnedRoutes());
		// A new route can lead onto a floor nothing else reaches: ground from now on.
		worldMesh.admitTransportEnds(transports.all());
		setHomeRegions(transports.homeRegions());
		// A new route into an instance can mean a new room golems may stand in.
		instanceRoomTiles = instanceRooms();
		saveLearnedObstacles();
	}

	/** {@link #isObstacle}, remembered per route for the session. */
	private boolean isObstacleRoute(int[] r)
	{
		String key = r[0] + "," + r[1] + "," + r[2] + "," + r[3] + ">" + r[4] + "," + r[5] + "," + r[6];
		Boolean known = obstacleVerdicts.get(key);
		if (known == null)
		{
			known = isObstacle(r[0], r[1], r[2], r[3], r[4], r[5], r[6]);
			obstacleVerdicts.put(key, known);
		}
		return known;
	}

	/** Coordinates this far east are an instance's, never the world's. */
	private static final int INSTANCE_X = 6400;

	/**
	 * Whether something the player used is a way across, rather than anything else they clicked
	 * and walked away from. Yes if the cache or the transport tables say so; otherwise only if
	 * it took them somewhere they could not have walked — another floor, a long way off, or
	 * somewhere their map has no short walk to. A tree fails that, as does an open door. Routes
	 * in an instance's own coordinates point at a room that no longer exists.
	 */
	private boolean isObstacle(int objectId, int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane)
	{
		if (fromX >= INSTANCE_X || toX >= INSTANCE_X)
		{
			return false;
		}
		if (obstacleIndex.knows(objectId) || transports.isShippedObstacle(objectId))
		{
			return true;
		}
		if (fromPlane != toPlane || !RouteGeometry.local(toX - fromX, toY - fromY))
		{
			return true;
		}
		int steps = Math.max(Math.abs(toX - fromX), Math.abs(toY - fromY));
		java.util.Deque<int[]> walk = pathfinder.findPath(fromX, fromY, fromPlane, toX, toY,
			new RoamBounds(islandMemory, fromPlane, fromX, fromY));
		return walk.isEmpty() || walk.size() > steps * 2 + 4;
	}

	private void saveLearnedObstacles()
	{
		configManager.setConfiguration(GolemsDontDieConfig.GROUP,
			ObstacleKnowledge.LEARNED_KEY, obstacleKnowledge.serialise());
		configManager.setConfiguration(GolemsDontDieConfig.GROUP,
			ObstacleKnowledge.CONFIRMED_KEY, obstacleKnowledge.serialiseConfirmed());
		configManager.setConfiguration(GolemsDontDieConfig.GROUP,
			ObstacleKnowledge.ROUTES_KEY, obstacleKnowledge.serialiseRoutes());
		configManager.setConfiguration(GolemsDontDieConfig.GROUP,
			ObstacleKnowledge.CURVES_KEY, obstacleKnowledge.serialiseCurves());
		configManager.setConfiguration(GolemsDontDieConfig.GROUP,
			ObstacleKnowledge.LINES_KEY, obstacleKnowledge.serialiseLines());
	}

	/**
	 * Logs what every golem near the player is doing, at debug level, for chasing a bug. Confined
	 * to the scene: a line per tick for four hundred and fifty golems would be megabytes a minute.
	 */
	private void logGolemState()
	{
		if (!DevOptions.LOG_GOLEM_STATE)
		{
			return;
		}

		for (Golem golem : golems)
		{
			if (golem.getTier() != GolemTier.SCENE)
			{
				continue;
			}
			FakeGolem drawn = golem.getRenderer();
			log.debug("Golem {} {}", golem.getId(), golem.debugState()
				+ (drawn == null ? " undrawn" : " drawnAgo=" + (client.getGameCycle() - drawn.getLastDrawnCycle())));
			checkStep(golem);
			checkStanding(golem);
		}
	}

	/** Pushes the obstacle settings into the pieces that act on them. */
	private void applyObstacleSettings()
	{
		obstacleObserver.setExplaining(DevOptions.HIGHLIGHT_OBSTACLES);
	}

	@Provides
	GolemsDontDieConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GolemsDontDieConfig.class);
	}

	@Override
	protected void startUp()
	{
		running = true;
		// Before anything below writes a key, or every install looks like an update.
		checkForUpdate();

		// Obstacles already taught, and the settings governing learning. Before the transport
		// network, whose usability gate consults it.
		obstacleKnowledge.deserialise(
			configManager.getConfiguration(GolemsDontDieConfig.GROUP, ObstacleKnowledge.LEARNED_KEY));
		obstacleKnowledge.deserialiseConfirmed(
			configManager.getConfiguration(GolemsDontDieConfig.GROUP, ObstacleKnowledge.CONFIRMED_KEY));
		obstacleKnowledge.deserialiseRoutes(
			configManager.getConfiguration(GolemsDontDieConfig.GROUP, ObstacleKnowledge.ROUTES_KEY));
		obstacleKnowledge.deserialiseCurves(
			configManager.getConfiguration(GolemsDontDieConfig.GROUP, ObstacleKnowledge.CURVES_KEY));
		obstacleKnowledge.deserialiseLines(
			configManager.getConfiguration(GolemsDontDieConfig.GROUP, ObstacleKnowledge.LINES_KEY));
		applyObstacleSettings();

		obstacleObserver.setOnSighting(this::onObstacleSighting);
		obstacleObserver.startUp();
		// In the plugin's own folder, which RuneLite hands out; a plugin writes nowhere else.
		net.runelite.client.util.Filepath folder = null;
		try
		{
			folder = getPluginDirectory();
		}
		catch (java.io.IOException | RuntimeException e)
		{
			log.warn("No folder for the obstacle data; it will not be kept this session", e);
		}
		obstacleData.startUp(folder);

		// Saved map first, shipped baseline underneath: what the player has walked beats a
		// static export of the same ground.
		islandMemory.deserialise(configManager.getConfiguration(GolemsDontDieConfig.GROUP, IslandMemory.MAP_KEY));
		islandMemory.loadBundled();
		// Anywhere a transport from the island leads is ground golems will walk; resolved
		// lazily, after the network has loaded.
		islandMemory.setAlsoIsland(transports::leadsToRegion);

		// Read-only and shared, so loaded once here: a first-use load would land mid-frame,
		// the one place a few milliseconds shows.
		worldMesh.load();
		propFactory.load();
		transports.load();
		// The index before the routes, because the routes are filtered by it.
		obstacleIndex.load();
		obstacleVerdicts.clear();
		obstacleKnowledge.setRouteFilter(this::isObstacleRoute);
		transports.setLearnedRoutes(obstacleKnowledge.learnedRoutes());
		// Floors reached only by transports the land fill never had. See WorldMesh.
		worldMesh.admitTransportEnds(transports.all());
		setHomeRegions(transports.homeRegions());
		roamContext = new RoamContext(islandMemory, pathfinder, transports, abilities);
		roamContext.setKnowledge(obstacleKnowledge);
		roamContext.setObstacles(obstacleIndex);
		roamContext.setDecisions((golem, what) ->
		{
			if (DevOptions.LOG_GOLEM_STATE)
			{
				log.debug("Golem {} {}", golem.getId(), what);
			}
		});
		roamContext.setPlanner(roamPlanner);
		roamContext.setCensus(census);
		roamContext.setTraversals(obstacleData::golemCrossed);
		roamContext.setModels(modelFactory);

		pendingRestore.addAll(store.deserialise(
			configManager.getConfiguration(GolemsDontDieConfig.GROUP, GolemsDontDieConfig.SAVED_GOLEMS_KEY)));

		tally.load();

		// Enabling mid-session skips the login the count would have arrived at.
		clientThread.invokeLater(this::syncTally);

		// All three panel callbacks arrive on the Swing thread and touch the roster, which the
		// client thread owns, so each hops across.
		panel = new GolemListPanel(
			golem -> clientThread.invoke(() -> removeGolem(golem)),
			(golem, name) -> clientThread.invoke(() ->
			{
				golem.setNickname(name);
				saveGolemsSoon();
			}),
			() -> clientThread.invoke(this::reviveMissing));
		menu.setOnRenamed(golem ->
		{
			if (!running || panel == null)
			{
				return;
			}
			saveGolemsSoon();
			List<Golem> living = livingGolems();
			panel.refresh(living, missingGolems(living.size()), true);
		});
		navButton = NavigationButton.builder()
			.tooltip("Golems")
			.icon(ImageUtil.loadImageResource(GolemsDontDiePlugin.class, "/golem-icon.png"))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(minimapOverlay);
		overlayManager.add(obstacleHighlightOverlay);
		overlayManager.add(nameplateOverlay);

		renderCallbacks.register(drawCallback);
		callbackRegistered = true;

		lastGameCycle = -1;
		clientThread.invokeLater(this::restorePending);
	}

	@Override
	protected void shutDown()
	{
		// Nothing drawn from here on, so nothing reads what is cleared below.
		if (callbackRegistered)
		{
			renderCallbacks.unregister(drawCallback);
			callbackRegistered = false;
		}

		// Golems and their maps belong to the client thread and this runs on Swing's: saving
		// here iterated the roster while a frame could be moving it.
		onClientThread(() ->
		{
			// Each step on its own, so one failing cannot stop the rest: the old shutdown's
			// first line threw, the roster stayed in memory, and re-enabling doubled every
			// golem. Save before tearing down.
			safely("stopping the obstacle observer", obstacleObserver::shutDown);
			safely("saving obstacle data", obstacleData::save);
			safely("saving learned routes", () ->
			{
				if (routesChanged)
				{
					applyLearnedRoutes();
				}
				saveLearnedObstacles();
			});

			// Or shutdown is indistinguishable from deleting every golem the player has.
			safely("saving golems", this::saveGolems);
			safely("saving the island map", this::saveIslandMemory);
			running = false;

			safely("removing golems", () ->
			{
				for (Golem golem : golems)
				{
					detachRenderer(golem);
				}
			});
			golems.clear();
			pendingRestore.clear();
			safely("removing props", this::clearProps);
			safely("removing rafts", this::clearRafts);
			propFactory.clear();
			raftFactory.clear();
			census.clear();
			hiddenNpcs.clear();
			detector.reset();
			modelFactory.clear();
			saveGolemsAt = -1;
		});
		voyage.shutDown();

		overlayManager.remove(minimapOverlay);
		overlayManager.remove(obstacleHighlightOverlay);
		overlayManager.remove(nameplateOverlay);

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
	}

	/** Runs one step of shutdown, logging rather than throwing if it fails. */
	private void safely(String what, Runnable step)
	{
		try
		{
			step.run();
		}
		catch (RuntimeException | AssertionError e)
		{
			log.warn("Failed {} while shutting down; carrying on", what, e);
		}
	}

	/**
	 * Runs a task on the client thread: here if this is already it, queued otherwise.
	 *
	 * <p>Golems, their maps and everything drawn belong to that thread, and the plugin is stopped
	 * from Swing's. Nothing waits for the task: the client runs while the plugin is being stopped,
	 * so it is picked up on the next cycle, and a closing client has its own moment to save — see
	 * {@link #onClientShutdown}.
	 */
	private void onClientThread(Runnable task)
	{
		if (client.isClientThread())
		{
			task.run();
			return;
		}
		clientThread.invoke(task);
	}

	/**
	 * Saves before the client closes.
	 *
	 * <p>Stopping a plugin and closing the client are different moments, and only this one ends with
	 * the client thread going away. The save is handed to that thread and the client is asked to wait
	 * for it, which is how a plugin keeps work alive across shutdown without holding anything up.
	 */
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (!running)
		{
			return;
		}
		java.util.concurrent.CompletableFuture<Void> saved = new java.util.concurrent.CompletableFuture<>();
		event.waitFor(saved);
		onClientThread(() ->
		{
			safely("saving golems", this::saveGolems);
			safely("saving the island map", this::saveIslandMemory);
			safely("saving learned routes", this::saveLearnedObstacles);
			safely("saving obstacle data", obstacleData::save);
			saved.complete(null);
		});
	}

	/** Saves the roster shortly, folding in any other change asked for before then. */
	private void saveGolemsSoon()
	{
		if (saveGolemsAt < 0)
		{
			saveGolemsAt = client.getTickCount() + RENAME_SAVE_DELAY;
		}
	}

	// ---- watching the real golems ----

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (!detector.isGolem(npc))
		{
			return;
		}

		detector.track(npc);
		islandMemory.anchorAt(npc.getWorldLocation());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		if (tally.observe(event.getMessage()))
		{
			rosterChanged = true;
		}
	}

	/**
	 * Keeps the tally level with the game's own count of golems crafted: the half that works
	 * without the plugin having run, since the count arrives at login.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// A change can be reported against the varbit or the varp holding it, so both wake this.
		// Neither value is read: the varp's is the count over sixteen bits of carving state.
		if (event.getVarbitId() == GolemContent.GOLEM_COUNT_VARBIT
			|| event.getVarpId() == GolemContent.GOLEM_COUNT_VARP)
		{
			syncTally();
		}
	}

	/**
	 * Reads the game's count of golems crafted into the tally. Safe before the server has sent
	 * it: an unsent variable reads 0, which the tally ignores.
	 */
	private void syncTally()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int count = client.getVarbitValue(GolemContent.GOLEM_COUNT_VARBIT);
		if (tally.observeCount(count))
		{
			rosterChanged = true;
		}
		if (count > 0)
		{
			gameCount = count;
			claimRoster(count);
			trimToGameCount();
		}
	}

	/** Golems the game says have been crafted, as read this session, or -1 if unread. */
	private int gameCount = -1;

	/** Config key for the account and kind of world the saved roster belongs to. */
	private static final String ROSTER_OWNER_KEY = "rosterOwner";

	/** Whether the account last seen logged in is the one the saved roster belongs to. */
	private boolean rosterOwned;

	/**
	 * Decides whether the logged-in account owns the roster, which is kept once per RuneLite profile:
	 * an alt or seasonal world with fewer golems crafted trimmed a main's golems to its count. The
	 * owner is the first account and world type whose count covers the unnamed golems (named ones
	 * are kept whatever the count); any other never trims or saves.
	 */
	private void claimRoster(int count)
	{
		String here = client.getAccountHash() + ":" + RuneScapeProfileType.getCurrent(client);
		String owner = configManager.getConfiguration(GolemsDontDieConfig.GROUP, ROSTER_OWNER_KEY);
		int unnamed = 0;
		for (GolemStore.SavedGolem saved : pendingRestore)
		{
			unnamed += saved.nickname == null ? 1 : 0;
		}
		for (Golem golem : golems)
		{
			unnamed += golem.isDying() || isNamed(golem) ? 0 : 1;
		}
		if (owner == null && count >= unnamed)
		{
			configManager.setConfiguration(GolemsDontDieConfig.GROUP, ROSTER_OWNER_KEY, here);
			owner = here;
		}
		rosterOwned = here.equals(owner);
	}

	/**
	 * Removes unnamed golems beyond the number the game says were ever crafted. Any beyond it
	 * are copies, and there have been: a failed shutdown left the roster in memory, and
	 * re-enabling loaded the save on top, making one player's 451 golems 902. Only the game's
	 * own count is trusted. Unnamed golems go first, out of view before in view, then duplicate
	 * names; a golem with a name of its own is never removed.
	 */
	private void trimToGameCount()
	{
		if (gameCount <= 0 || !pendingRestore.isEmpty() || !rosterOwned)
		{
			return;
		}
		int excess = countLiving() - gameCount;
		if (excess <= 0)
		{
			return;
		}
		int removed = 0;

		// Unnamed first, newest first: a doubled roster's copies are the later half.
		for (int pass = 0; pass < 2 && removed < excess; pass++)
		{
			for (int i = golems.size() - 1; i >= 0 && removed < excess; i--)
			{
				Golem golem = golems.get(i);
				if (golem.isDying() || isNamed(golem) || pass == 0 && golem.getTier() != GolemTier.FAR)
				{
					continue;
				}
				golem.startDying();
				removed++;
			}
		}

		// Then, if still over, every golem after the first with each name.
		java.util.Set<String> names = new java.util.HashSet<>();
		for (Golem golem : golems)
		{
			if (removed >= excess)
			{
				break;
			}
			if (golem.isDying() || !isNamed(golem))
			{
				continue;
			}
			if (!names.add(golem.getNickname().trim().toLowerCase()))
			{
				golem.startDying();
				removed++;
			}
		}

		rosterChanged = true;
		saveGolems();
		log.debug("Removed {} golems beyond the {} the game says were crafted{}", removed, gameCount,
			removed < excess ? "; " + (excess - removed) + " more are named and kept" : "");
	}

	/**
	 * Brings the roster back up to the number of golems ever crafted: new golems on the plinth,
	 * dispersing as freshly made ones would, since nothing of a culled golem survives.
	 */
	private void reviveMissing()
	{
		int missing = missingGolems(countLiving());
		if (missing <= 0)
		{
			return;
		}

		WorldPoint plinth = new WorldPoint(GolemContent.PLINTH_X, GolemContent.PLINTH_Y, 0);
		int revived = 0;

		for (int i = 0; i < missing; i++)
		{
			GolemSnapshot snapshot = GolemSnapshot.restore(
				client, GolemContent.GOLEM_NPC_ID,
				GolemContent.GOLEM_IDLE_ANIMATION, GolemContent.GOLEM_WALK_ANIMATION, -1,
				plinth, 0);
			if (snapshot == null)
			{
				log.debug("Cannot revive golems: npc {} not in cache", GolemContent.GOLEM_NPC_ID);
				break;
			}

			// Seeded off a counter as well as the tile, so a batch revived onto one square
			// does not walk away in lockstep.
			long seed = uniqueSeed(((long) plinth.getX() << 32) ^ ((long) plinth.getY() << 8)
				^ ((golems.size() + i) * 0x9E3779B9L));
			golems.add(Golem.onTile(snapshot, plinth, seed, plinth));
			revived++;
		}

		if (revived > 0)
		{
			rosterChanged = true;
			saveGolems();
			log.debug("Revived {} golems", revived);
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		obstacleObserver.onAnimationChanged(event);

		if (!(event.getActor() instanceof NPC))
		{
			return;
		}
		NPC npc = (NPC) event.getActor();
		if (!detector.isGolem(npc))
		{
			return;
		}

		int animation = npc.getAnimation();
		if (detector.wasReplaced(npc))
		{
			return;
		}

		// As the golem finishes stepping off its plinth, not when it crumbles: waiting meant
		// taking over mid-stride, with a position, heading and half-step to reconcile.
		if (animation == -1 && detector.hasLeftPlinth(npc))
		{
			replace(npc);
			return;
		}

		if (animation == GolemContent.GOLEM_SPAWN_ANIMATION)
		{
			detector.noteLeftPlinth(npc);
		}

		// Fallback: if a golem is never seen stepping off, a jump at the crumble beats losing
		// it.
		if (detector.isDeathAnimation(animation))
		{
			replace(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (!detector.isGolem(npc))
		{
			return;
		}

		hiddenNpcs.remove(npc.getIndex());
		detector.forget(npc);
	}

	/**
	 * Takes over from a live golem: builds the copy and hides the original. The copy goes at the
	 * NPC's <i>local</i> location, not its world tile, which is the tile it is moving onto — one
	 * caught mid-step would appear to teleport.
	 */
	private void replace(NPC npc)
	{
		if (!hasRoomForAnother())
		{
			// Every slot is spoken for by a named golem; leave this one to the game.
			detector.markReplaced(npc);
			return;
		}

		GolemSnapshot snapshot = detector.snapshotOf(npc);
		if (snapshot == null)
		{
			snapshot = GolemSnapshot.of(npc);
		}
		if (snapshot == null)
		{
			log.debug("No usable snapshot for golem {}, letting it die", npc.getId());
			return;
		}

		WorldView wv = client.getTopLevelWorldView();
		LocalPoint local = npc.getLocalLocation();
		if (wv == null || local == null)
		{
			return;
		}

		// Local coordinates are scene-relative; the simulation is world-absolute.
		int fineX = local.getX() + wv.getBaseX() * Golem.TILE;
		int fineY = local.getY() + wv.getBaseY() * Golem.TILE;

		WorldPoint home = npc.getWorldLocation();
		long seed = uniqueSeed(((long) home.getX() << 32) ^ ((long) home.getY() << 8) ^ npc.getIndex());

		// Taken live, not from the snapshot, so the copy starts facing where the original
		// faced this frame.
		GolemSnapshot posed = snapshot.facing(npc.getCurrentOrientation());
		Golem golem = new Golem(posed, home, seed, fineX, fineY);

		golems.add(golem);
		rosterChanged = true;
		enforceGolemLimit();

		detector.markReplaced(npc);
		hiddenNpcs.add(npc.getIndex());
		saveGolems();
	}

	/** How many golems reviving would bring back: the gap to golems crafted, but never past the limit. */
	private int missingGolems(int living)
	{
		int missing = tally.getTotal() - living;
		if (config.limitGolems())
		{
			missing = Math.min(missing, Math.max(1, config.maxGolems()) - living);
		}
		return Math.max(0, missing);
	}

	/**
	 * Retires the oldest unnamed golems until the roster is inside the limit. Unlimited by
	 * default: a golem costs an animated model every frame, so a cap is worth offering, but
	 * choosing one would quietly delete golems collected on purpose.
	 *
	 * <p><b>Named golems are never culled</b>, even over the limit: a name is the one
	 * unambiguous signal the player cares. Retired golems crumble, and leave the roster when
	 * the animation finishes.
	 */
	private void enforceGolemLimit()
	{
		if (!config.limitGolems())
		{
			return;
		}

		int limit = Math.max(1, config.maxGolems());
		int alive = countLiving();

		for (Golem golem : golems)
		{
			if (alive <= limit)
			{
				break;
			}
			if (golem.isDying() || isNamed(golem))
			{
				continue;
			}
			golem.startDying();
			alive--;
		}
	}

	/**
	 * The roster as anything outside the client thread should see it: a copy, because the panel
	 * reads it on the Swing thread while this one changes it, with mid-crumble golems left out
	 * so pressing ✕ removes the entry at once.
	 */
	private List<Golem> livingGolems()
	{
		List<Golem> living = new ArrayList<>(golems.size());
		for (Golem golem : golems)
		{
			if (!golem.isDying())
			{
				living.add(golem);
			}
		}
		return living;
	}

	/** Golems not already crumbling: a dying one is on its way out and does not count. */
	private int countLiving()
	{
		int alive = 0;
		for (Golem golem : golems)
		{
			if (!golem.isDying())
			{
				alive++;
			}
		}
		return alive;
	}

	private static boolean isNamed(Golem golem)
	{
		String name = golem.getNickname();
		return name != null && !name.isEmpty();
	}

	/**
	 * Whether a new golem can be taken over. False when the roster is full of named golems:
	 * nothing can make room, so the plugin stands aside rather than killing one to pay.
	 */
	private boolean hasRoomForAnother()
	{
		if (!config.limitGolems())
		{
			return true;
		}
		if (countLiving() < Math.max(1, config.maxGolems()))
		{
			return true;
		}
		for (Golem golem : golems)
		{
			if (!golem.isDying() && !isNamed(golem))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Retires one golem, from the side panel's X button. Client thread only. It crumbles rather
	 * than vanishing, but the panel drops it at once so the button feels immediate.
	 */
	private void removeGolem(Golem golem)
	{
		golem.startDying();
		rosterChanged = true;
		saveGolems();
	}

	/**
	 * A seed, and so an id, that no golem has. Seeding from the plinth and the game's NPC slot
	 * gave golems crafted minutes apart the same seed, because the game reuses slots; a seed is
	 * everything a golem decides, so twins walked in lockstep and shared one raft, and four
	 * hundred ids were in two places at once in one session. Now mixed with a counter and the
	 * clock, and checked against the roster.
	 */
	private long uniqueSeed(long base)
	{
		long seed = base ^ (++seedsIssued * 0x9E3779B97F4A7C15L) ^ System.nanoTime();
		while (seedInUse(seed))
		{
			seed += 0x9E3779B97F4A7C15L;
		}
		return seed;
	}

	private long seedsIssued;

	private boolean seedInUse(long seed)
	{
		for (Golem golem : golems)
		{
			if (golem.getId() == seed)
			{
				return true;
			}
		}
		return false;
	}

	// ---- simulation ----

	/**
	 * Ticks between looks at a golem out of view. Three seconds: the near ring a golem must
	 * cross to reach the scene is over a hundred tiles wide, and a teleport rechecks everything
	 * anyway.
	 */
	private static final int FAR_CHECK_TICKS = 5;

	/** Tiles the player can move in one frame before it counts as a teleport. */
	private static final int TELEPORT_TILES = 8;

	/** What the view was last frame, to notice it changing at a stroke. */
	private int lastViewX = Integer.MIN_VALUE;
	private int lastViewY;
	private int lastViewPlane;
	private int lastBaseX;
	private int lastBaseY;
	private boolean lastInstance;
	private boolean lastRestrict;

	/**
	 * True if something since last frame could have brought golems into view, or sent them home,
	 * all at once, so every golem is looked at now rather than in turn.
	 */
	private boolean farViewChanged(WorldView wv, WorldPoint playerAt, boolean restrict)
	{
		int x = playerAt == null ? Integer.MIN_VALUE : playerAt.getX();
		int y = playerAt == null ? 0 : playerAt.getY();
		int plane = playerAt == null ? -1 : playerAt.getPlane();
		int baseX = wv == null ? Integer.MIN_VALUE : wv.getBaseX();
		int baseY = wv == null ? Integer.MIN_VALUE : wv.getBaseY();
		boolean instance = wv != null && wv.isInstance();

		boolean changed = lastViewX == Integer.MIN_VALUE || x == Integer.MIN_VALUE
			|| Math.abs(x - lastViewX) > TELEPORT_TILES || Math.abs(y - lastViewY) > TELEPORT_TILES
			|| plane != lastViewPlane || baseX != lastBaseX || baseY != lastBaseY
			|| instance != lastInstance || restrict != lastRestrict;

		lastViewX = x;
		lastViewY = y;
		lastViewPlane = plane;
		lastBaseX = baseX;
		lastBaseY = baseY;
		lastInstance = instance;
		lastRestrict = restrict;
		return changed;
	}

	/** Golems standing on, and drawn on, each tile; refilled every frame. */
	private final TileMap occupancy = new TileMap(256);
	private final TileMap drawnPerTile = new TileMap(256);

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (golems.isEmpty())
		{
			drawnGolems.clear();
			return;
		}

		int cycle = client.getGameCycle();
		int elapsed = lastGameCycle < 0 ? 0 : cycle - lastGameCycle;
		lastGameCycle = cycle;

		// A negative or absurd delta means a world hop or reconnect reset the cycle counter;
		// skip the frame rather than teleporting every golem.
		if (elapsed < 0 || elapsed > 200)
		{
			elapsed = 0;
		}

		// Rationed per frame: a golem only searches when it finishes a walk, but with hundreds
		// the arrivals bunch up and fifty breadth-first searches in a frame stutters. One
		// denied waits, indistinguishable from its usual pause.
		int searchBudget = PATH_SEARCHES_PER_FRAME;
		int farPlanBudget = FAR_PLANS_PER_FRAME;

		// Resolved once rather than per golem: both were built five hundred times a frame for
		// the same answer.
		WorldView wv = client.getTopLevelWorldView();

		// One context for the whole frame; only the two per-golem knobs change as the
		// roster is walked.
		roamContext.setTick(client.getTickCount());
		// Thirty client cycles to a tick.
		roamContext.setTickFraction(tickStartCycle < 0 ? 0f
			: Math.min(0.999f, Math.max(0f, (client.getGameCycle() - tickStartCycle) / 30f)));
		roamContext.setMaySearchSea(true);
		// Read once for the frame rather than through the config proxy for every golem.
		boolean restrictAmbition = config.restrictGolemAmbition();
		roamContext.setAmbitionRestricted(restrictAmbition);

		// In the main world even aboard a boat, whose coordinates would put golems out of range.
		WorldPoint playerAt = PlayerPosition.of(client);

		// Where golems are standing, to keep them off one tile. The same map every frame,
		// emptied and refilled, so a pen of golems does not box a key each.
		occupancy.clear();
		for (Golem golem : golems)
		{
			if (golem.getTier() != GolemTier.FAR)
			{
				occupancy.addTo(RoamContext.tileKey(golem.getFineX() / Golem.TILE,
					golem.getFineY() / Golem.TILE, golem.getPlane()), 1);
			}
		}
		roamContext.setOccupancy(occupancy);

		// Golems drawn per tile this frame. See updateRenderer.
		drawnPerTile.clear();

		// Inside an instance: which template chunks it is built from, and where the player is in
		// template terms. Golems live in the template; see tierFor.
		Map<Long, int[]> sceneChunks = wv != null && wv.isInstance() ? InstanceMap.sceneChunks(wv) : null;
		WorldPoint playerTemplate = sceneChunks == null ? playerAt : InstanceMap.templateOf(wv, playerAt);

		// Golems out of view are looked at every few ticks; see Golem.scheduleFarCheck. All at
		// once after a teleport, a new scene, a change of floor or the ambition setting.
		int tick = client.getTickCount();
		boolean lookAtAll = farViewChanged(wv, playerAt, restrictAmbition);

		for (Golem golem : golems)
		{
			if (!lookAtAll && golem.getTier() == GolemTier.FAR && golem.getRenderer() == null
				&& !golem.farCheckDue(tick))
			{
				continue;
			}
			if (golem.getTier() == GolemTier.FAR)
			{
				golem.catchUpFar(tick);
			}

			// A question about this golem, not the player's proximity to Wyrmscraig: the old
			// gate switched every golem off when the player left the island.
			GolemTier tier = tierFor(golem, wv, playerAt, playerTemplate, sceneChunks);

			golem.setTier(tier, roamContext, roamPlanner);

			if (tier == GolemTier.FAR)
			{
				if (golem.advanceFar(roamContext, roamPlanner, farPlanBudget > 0))
				{
					farPlanBudget--;
				}
				golem.scheduleFarCheck(tick, FAR_CHECK_TICKS);
			}
			else if (elapsed > 0)
			{
				roamContext.setMayPath(searchBudget > 0);
				if (golem.advance(elapsed, roamContext))
				{
					searchBudget--;
				}
			}

			if (restrictAmbition)
			{
				sendHomeIfAway(golem);
			}
			rescueIfStuck(golem, tier);

			updateRenderer(golem, wv, tier == GolemTier.SCENE, drawnPerTile);
			updateRaft(golem, tier == GolemTier.SCENE);

			// Scenery is only animated for a golem the player can see; a request from three
			// regions away is dropped, not queued, as nobody watched the plank lower.
			GolemTransport prop = golem.claimPendingProp();
			if (prop != null && tier == GolemTier.SCENE)
			{
				spawnProp(prop, wv);
			}
		}

		advanceProps();
		reapCrumbled();

		// Golems with a model in the scene, in roster order, for the overlays and the menu. A
		// renderer is only attached above, so nothing outside this list is drawn before it is
		// rebuilt; one detached since is skipped by their own checks.
		drawnGolems.clear();
		for (Golem golem : golems)
		{
			if (golem.getRenderer() != null)
			{
				drawnGolems.add(golem);
			}
		}
	}

	/**
	 * Moves a golem that has stopped getting anywhere. The watchdog on {@link Golem} decides
	 * <em>whether</em>; this decides <em>where</em>, because only the plugin has the mesh. The
	 * golem goes to the nearest tile it could walk out of, or home to the tent by the plinth, which always
	 * exists and is always walkable. Moved, never replaced: same name, id, seed and gait.
	 * Allowed even on screen, since a golem frozen in scenery is worse than one that slides.
	 */
	private void rescueIfStuck(Golem golem, GolemTier tier)
	{
		int tick = roamContext.getTick();

		// A visible golem somewhere it could not have walked to is wrong now, not in five
		// minutes, so it is put right rather than waiting for the watchdog — a net under
		// everything else. A stepping stone is the legitimate exception: blocked ground the
		// network says you may stand on.
		//
		// A golem mid-obstacle is exempt, because half of them legitimately stand on nothing.
		// Without this the watchdog fired every tick of every crossing and called relocate,
		// dropping the path, the step and the itinerary: golems were pulled off the stones by
		// the thing meant to rescue them, 8,855 times on one tile in one session. isStuck()
		// below exempts transitions; this check simply ran before it.
		//
		// Nor a golem at sea, which is on water because it is in a boat: without this every
		// golem that sailed in view was pulled back onto the nearest beach.
		if (tier != GolemTier.FAR && !golem.isDying() && !golem.inTransition() && !golem.isSailing(tick))
		{
			// The tile as numbers first: this runs for every golem in view every frame, and the
			// point is only needed once one turns out to be somewhere it should not be.
			int x = golem.getFineX() / Golem.TILE;
			int y = golem.getFineY() / Golem.TILE;
			if (!islandMemory.isKnownWalkable(x, y, golem.getPlane())
				&& !transports.hasOrigin(x, y))
			{
				WorldPoint on = golem.currentTile();
				WorldPoint safe = roamPlanner.snapToMesh(on);
				if (!safe.equals(on))
				{
					log.debug("Golem {} was on unwalkable ground at {}; moved to {}",
						golem.getId(), on, safe);
					noteRescue(golem, on, safe, "unwalkable");
					golem.relocate(safe);
					// Out of a room is out of its instance: left flagged, it was out of view for good.
					golem.setInInstance(false);
					golem.noteUnstuck(tick);
					return;
				}
			}
		}

		if (!golem.isStuck(tick))
		{
			return;
		}

		// The cheap, invisible things first — spin, back out, re-plan — before the golem is
		// picked up and put somewhere.
		if (golem.workFree(roamContext, roamPlanner))
		{
			return;
		}

		WorldPoint at = golem.currentTile();
		WorldPoint safe = roamPlanner.snapToMesh(at);

		if (safe.equals(at))
		{
			// The mesh says this tile is fine, so the golem is stuck for a reason the map
			// cannot see; home is the fallback that cannot fail.
			safe = GolemContent.RECOVERY;
		}

		log.debug("Rescuing stuck golem {} from {} to {} (tier {})",
			golem.getId(), at, safe, tier);
		noteRescue(golem, at, safe, "stuck");
		golem.relocate(safe);
		golem.setInInstance(false);
		golem.noteUnstuck(tick);
	}

	/** The plane last harvested for, so moving to another floor harvests that one. */
	private int harvestedPlane = -1;

	/** A door opened: the shut door's wall object went and the open door's came. */
	@Subscribe
	public void onWallObjectSpawned(net.runelite.api.events.WallObjectSpawned event)
	{
		islandMemory.passabilityChanged(event.getWallObject().getWorldLocation());
	}

	@Subscribe
	public void onWallObjectDespawned(net.runelite.api.events.WallObjectDespawned event)
	{
		islandMemory.passabilityChanged(event.getWallObject().getWorldLocation());
	}

	/** The last step of each golem already checked, by its step count. */
	private final Map<Long, Integer> loggedSteps = new HashMap<>();

	/**
	 * Logs a golem that has just walked across an edge the live game says is blocked, judged by
	 * the game's own collision at the moment of the step rather than the island memory the golem
	 * planned with, which is the thing that might be stale. A golem through a shut door is
	 * invisible to every other check: its path was valid when planned.
	 */
	private void checkStep(Golem golem)
	{
		// The step the golem actually began, not the tile it was logged on a tick ago:
		// comparing logged tiles called stepping-stone landings and half-finished diagonals
		// steps through walls, which was most of the first 169 reports.
		int serial = golem.getStepSerial();
		Integer checked = loggedSteps.put(golem.getId(), serial);
		if (checked == null || checked == serial || golem.lastStepClimbing())
		{
			return;
		}
		int[] step = golem.lastStep();
		WorldPoint before = new WorldPoint(step[0], step[1], golem.getPlane());
		WorldPoint now = new WorldPoint(step[2], step[3], golem.getPlane());
		int dx = now.getX() - before.getX();
		int dy = now.getY() - before.getY();
		if ((dx == 0 && dy == 0) || Math.abs(dx) > 1 || Math.abs(dy) > 1)
		{
			return;
		}
		WorldView wv = client.getTopLevelWorldView();
		// Not inside an instance: golems there are in template coordinates, which the loaded
		// scene's collision does not describe.
		if (wv == null || wv.isInstance() || wv.getCollisionMaps() == null
			|| now.getPlane() >= wv.getCollisionMaps().length
			|| wv.getCollisionMaps()[now.getPlane()] == null)
		{
			return;
		}
		int[][] flags = wv.getCollisionMaps()[now.getPlane()].getFlags();
		int sx = before.getX() - wv.getBaseX();
		int sy = before.getY() - wv.getBaseY();
		// Not near the scene edge, where the client marks a border blocked whatever is really
		// there; steps along it were reported as walls.
		int margin = 6;
		if (sx < margin || sy < margin || sx >= wv.getSizeX() - margin || sy >= wv.getSizeY() - margin
			|| sx + dx < margin || sy + dy < margin
			|| sx + dx >= wv.getSizeX() - margin || sy + dy >= wv.getSizeY() - margin)
		{
			return;
		}
		if (!liveStepBlocked(flags, sx, sy, dx, dy))
		{
			return;
		}
		log.debug("Golem {} {}", golem.getId(), "crossed blocked edge from "
			+ before.getX() + "," + before.getY() + "," + before.getPlane() + " to "
			+ now.getX() + "," + now.getY() + "," + now.getPlane()
			+ " flags=" + Integer.toHexString(flags[sx][sy]) + "," + Integer.toHexString(flags[sx + dx][sy + dy]));
	}

	/**
	 * Logs a golem standing on a tile the live game says nothing can stand on — water, or inside
	 * scenery — outside a traversal and off any transport's starting tile. Judged by the game's
	 * own collision, because the golems' map is the thing that can be wrong: false walls and
	 * holes both look fine from inside the plugin.
	 */
	private void checkStanding(Golem golem)
	{
		if (golem.inTransition())
		{
			return;
		}
		WorldView wv = client.getTopLevelWorldView();
		WorldPoint at = golem.currentTile();
		if (wv == null || wv.isInstance() || wv.getCollisionMaps() == null
			|| at.getPlane() >= wv.getCollisionMaps().length || wv.getCollisionMaps()[at.getPlane()] == null)
		{
			return;
		}
		int sx = at.getX() - wv.getBaseX();
		int sy = at.getY() - wv.getBaseY();
		int margin = 6;
		if (sx < margin || sy < margin || sx >= wv.getSizeX() - margin || sy >= wv.getSizeY() - margin)
		{
			return;
		}
		int flags = wv.getCollisionMaps()[at.getPlane()].getFlags()[sx][sy];
		if ((flags & LIVE_UNWALKABLE) == 0 || transports.hasOrigin(at.getX(), at.getY()))
		{
			return;
		}
		log.debug("Golem {} {}", golem.getId(), "standing on blocked tile "
			+ at.getX() + "," + at.getY() + "," + at.getPlane() + " flags=" + Integer.toHexString(flags)
			+ (golem.debugState().contains(" itinerary") ? " route" : ""));
	}

	private static final int LIVE_UNWALKABLE = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_FULL
		| net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
		| net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
		| net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;

	/** The game's rule for one step, on raw scene flags: both ways round a corner clear. */
	private static boolean liveStepBlocked(int[][] flags, int x, int y, int dx, int dy)
	{
		if (dx != 0 && dy != 0)
		{
			return liveStepBlocked(flags, x, y, dx, 0) || liveStepBlocked(flags, x, y, 0, dy)
				|| liveStepBlocked(flags, x + dx, y, 0, dy) || liveStepBlocked(flags, x, y + dy, dx, 0);
		}
		int nx = x + dx;
		int ny = y + dy;
		if (x < 0 || y < 0 || nx < 0 || ny < 0 || x >= flags.length || nx >= flags.length
			|| y >= flags[x].length || ny >= flags[nx].length)
		{
			return false;
		}
		int out;
		int in;
		if (dy == 1)
		{
			out = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_NORTH;
			in = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
		}
		else if (dy == -1)
		{
			out = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
			in = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_NORTH;
		}
		else if (dx == 1)
		{
			out = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_EAST;
			in = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_WEST;
		}
		else
		{
			out = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_WEST;
			in = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_EAST;
		}
		return (flags[x][y] & out) != 0 || (flags[nx][ny] & (in | LIVE_UNWALKABLE)) != 0;
	}

	/**
	 * Wyrmscraig, its caves and floors, and everywhere its own transports lead; recomputed
	 * whenever a route is learned. See {@link TransportNetwork#homeRegions}.
	 */
	private java.util.Set<Integer> homeRegions = java.util.Collections.emptySet();

	/** {@link #homeRegions} by region id, for the check made of every golem every frame. */
	private boolean[] homeRegionBits = new boolean[1 << 16];

	private void setHomeRegions(java.util.Set<Integer> regions)
	{
		boolean[] bits = new boolean[1 << 16];
		for (int regionId : regions)
		{
			if (regionId >= 0 && regionId < bits.length)
			{
				bits[regionId] = true;
			}
		}
		// Bits before the set: a check between the two sees the old set's emptiness with the new
		// bits, never a non-empty set with no bits, which would send every golem home.
		homeRegionBits = bits;
		homeRegions = regions;
	}

	/**
	 * Puts a golem back home if it is anywhere but home, for "Restrict Golem ambition".
	 * By region, which is all home is: the island, its caves and its upper floors are regions,
	 * and an instance is simulated at its template.
	 */
	private void sendHomeIfAway(Golem golem)
	{
		// Every golem every frame while the setting is on, so the region comes from the
		// golem's own numbers, exactly as WorldPoint.getRegionID does, rather than a new one.
		int regionId = ((golem.getFineX() / Golem.TILE >> 6) << 8) | (golem.getFineY() / Golem.TILE >> 6);
		if (homeRegions.isEmpty() || (regionId >= 0 && regionId < homeRegionBits.length
			? homeRegionBits[regionId] : homeRegions.contains(regionId)))
		{
			return;
		}
		WorldPoint at = golem.currentTile();
		noteRescue(golem, at, GolemContent.RECOVERY, "ambition");
		golem.relocate(GolemContent.RECOVERY);
		golem.setInInstance(false);
		golem.noteUnstuck(roamContext.getTick());
	}

	/**
	 * This release, as the plugin's own files record it. It sits beside
	 * {@code runelite-plugin.properties} and {@code build.gradle}, which the Plugin Hub reads;
	 * this one is what the plugin writes into the data it keeps.
	 */
	static final String VERSION = "2.0.2";

	/** Set once an update has been announced, or on a new install with nothing to say. */
	private static final String ANNOUNCED_KEY = "announcedSailing";

	/** Keys the version before sailing wrote; any of them means this is an update, not an install. */
	private static final String[] OLD_VERSION_KEYS = {
		GolemsDontDieConfig.SAVED_GOLEMS_KEY, GolemTally.TOTAL_KEY, IslandMemory.MAP_KEY,
	};

	/** True if this launch is an update from the version before sailing, not yet announced. */
	private boolean announcementPending;

	/**
	 * Decides, once, whether this is an update worth announcing. A new install has none of the
	 * old version's keys and is marked announced straight away; an update has some, and hears
	 * about it at its next login.
	 */
	private void checkForUpdate()
	{
		if (configManager.getConfiguration(GolemsDontDieConfig.GROUP, ANNOUNCED_KEY) != null)
		{
			return;
		}
		for (String key : OLD_VERSION_KEYS)
		{
			if (configManager.getConfiguration(GolemsDontDieConfig.GROUP, key) != null)
			{
				announcementPending = true;
				return;
			}
		}
		configManager.setConfiguration(GolemsDontDieConfig.GROUP, ANNOUNCED_KEY, true);
	}

	/** Says it once, on the first tick logged in, and marks it only once said. */
	private void announceUpdate()
	{
		if (!announcementPending || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		announcementPending = false;
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=ff0000>The Golems have learned to sail...</col>", null);
		configManager.setConfiguration(GolemsDontDieConfig.GROUP, ANNOUNCED_KEY, true);
	}

	/**
	 * Logs a rescue, which is otherwise invisible: the golem simply reappears at the plinth. Ninety
	 * came off one ladder in a single session.
	 */
	private void noteRescue(Golem golem, WorldPoint from, WorldPoint to, String reason)
	{
		if (DevOptions.LOG_GOLEM_STATE)
		{
			log.debug("Golem {} {}", golem.getId(), "rescued " + reason
				+ " from " + from.getX() + "," + from.getY() + "," + from.getPlane()
				+ " to " + to.getX() + "," + to.getY() + "," + to.getPlane()
				+ " tier=" + golem.getTier());
		}
	}

	/** Animated scenery currently on screen. Short-lived: each plays once and goes. */
	private final List<FakeProp> props = new ArrayList<>();

	/**
	 * Hulls drawn under golems at sea, keyed by the golem itself. Not by id: ids come from the
	 * crafting site and the game's NPC slot, which the game reuses, so two golems could share
	 * one raft — whichever was updated last had it, and if the other was ashore it took the
	 * raft away again, leaving a golem at the helm of nothing.
	 */
	private final Map<Golem, FakeRaft> rafts = new java.util.IdentityHashMap<>();

	/**
	 * Gives a golem a boat if it is standing on open water, and takes it away otherwise. About
	 * position, not intent: an "is sailing" flag would leave every unanticipated case standing
	 * on the sea.
	 */
	private void updateRaft(Golem golem, boolean visible)
	{
		if (!visible && rafts.isEmpty())
		{
			// Not afloat and no hull to take away: the usual case, no id boxed.
			return;
		}
		FakeRaft raft = rafts.get(golem);

		// On the sea, or anywhere else a crossing goes: the cave's lake is not the sea.
		boolean afloat = visible && (golem.isAfloat() || worldMesh.isOcean(
			golem.getFineX() / Golem.TILE, golem.getFineY() / Golem.TILE, golem.getPlane()));

		if (!afloat)
		{
			if (raft != null)
			{
				client.removeRuneLiteObject(raft);
				rafts.remove(golem);
			}
			return;
		}

		if (raft == null)
		{
			Model hull = raftFactory.raftModel();
			if (hull == null)
			{
				return;
			}
			raft = new FakeRaft(client, hull, modelFactory,
				golem.getFineX(), golem.getFineY(), golem.getOrientation());
			client.registerRuneLiteObject(raft);
			rafts.put(golem, raft);
		}

		// The hull follows the golem, which is at the helm at the stern, so the raft's middle is
		// a tile ahead — the way it faces: 0 south, 512 west, 1024 north, 1536 east.
		double facing = golem.getOrientation() * Math.PI / 1024;
		int aheadX = (int) Math.round(-Math.sin(facing) * GolemContent.RAFT_HELM_OFFSET);
		int aheadY = (int) Math.round(-Math.cos(facing) * GolemContent.RAFT_HELM_OFFSET);
		// At the golem's ground height, always in the scene when the golem is drawn.
		WorldView view = client.getTopLevelWorldView();
		int localX = golem.getFineX() - (view == null ? 0 : view.getBaseX() * Golem.TILE);
		int localY = golem.getFineY() - (view == null ? 0 : view.getBaseY() * Golem.TILE);
		if (view != null && Golem.isInScene(view, localX, localY))
		{
			int ground = Perspective.getTileHeight(client, new LocalPoint(localX, localY, view), 0);
			raft.steer(golem.getFineX() + aheadX, golem.getFineY() + aheadY, golem.getOrientation(), ground);
		}
		else
		{
			raft.steer(golem.getFineX() + aheadX, golem.getFineY() + aheadY, golem.getOrientation());
		}
	}

	/** Drops every hull: scene coordinates are changing, or the plugin is stopping. */
	private void clearRafts()
	{
		for (FakeRaft raft : rafts.values())
		{
			client.removeRuneLiteObject(raft);
		}
		rafts.clear();
	}

	/**
	 * Draws an animated copy of the object a golem is using. It sits on top of the real object
	 * rather than replacing it, which is why doors are excluded: over one already open, a
	 * second copy reads as a ghost.
	 */
	private void spawnProp(GolemTransport transport, WorldView wv)
	{
		if (wv == null)
		{
			return;
		}

		PropFactory.Prop prop = propFactory.propFor(transport.getObjectId());
		if (prop == null)
		{
			return;
		}
		Model model = propFactory.modelFor(prop);
		if (model == null)
		{
			return;
		}

		int fineX = transport.getFromX() * Golem.TILE + Golem.TILE / 2;
		int fineY = transport.getFromY() * Golem.TILE + Golem.TILE / 2;
		int localX = fineX - wv.getBaseX() * Golem.TILE;
		int localY = fineY - wv.getBaseY() * Golem.TILE;
		if (!Golem.isInScene(wv, localX, localY))
		{
			return;
		}

		int height = Perspective.getTileHeight(client,
			new LocalPoint(localX, localY, wv), transport.getFromPlane());

		FakeProp drawn = new FakeProp(client, model,
			modelFactory.animationFor(prop.getAnimation()), prop.getAnimation(),
			fineX, fineY, transport.getFromPlane(), height, GolemContent.PROP_CYCLES);

		client.registerRuneLiteObject(drawn);
		props.add(drawn);
	}

	/** Unregisters scenery whose animation has run out. */
	private void advanceProps()
	{
		for (Iterator<FakeProp> it = props.iterator(); it.hasNext(); )
		{
			FakeProp prop = it.next();
			if (prop.isFinished())
			{
				client.removeRuneLiteObject(prop);
				it.remove();
			}
		}
	}

	/** Drops every scenery copy, finished or not. */
	private void clearProps()
	{
		for (FakeProp prop : props)
		{
			client.removeRuneLiteObject(prop);
		}
		props.clear();
	}

	/**
	 * Drops golems whose crumble has finished. Separate from the loop above so the roster is
	 * not modified while being walked.
	 */
	private void reapCrumbled()
	{
		for (Iterator<Golem> it = golems.iterator(); it.hasNext(); )
		{
			Golem golem = it.next();
			if (golem.isCrumbled())
			{
				detachRenderer(golem);
				it.remove();
				rosterChanged = true;
			}
		}
	}

	/**
	 * Attaches or detaches a golem's drawn object as it crosses the scene boundary, which is
	 * what lets one wander off the edge of what is loaded and come back: leaving the scene
	 * costs it its renderer, not its existence.
	 */
	/**
	 * Most golems drawn on one tile. The game draws only a few objects per tile, and with more
	 * than that on one it chose a different few each frame and they flashed; the roster is
	 * walked in a fixed order instead, so the first few keep their place and the rest wait.
	 */
	private static final int MAX_DRAWN_PER_TILE = 4;

	/**
	 * Which tier a golem is in, and where it is drawn. Inside an instance, a golem standing in a
	 * chunk it was built from is in the scene, drawn at the matching place on the instance's
	 * plane; every other golem is judged by its distance from the player in template terms,
	 * which puts the overworld out of range.
	 */
	private GolemTier tierFor(Golem golem, WorldView wv, WorldPoint playerAt, WorldPoint playerTemplate,
		Map<Long, int[]> sceneChunks)
	{
		int tileX = golem.getFineX() / Golem.TILE;
		int tileY = golem.getFineY() / Golem.TILE;

		// Where a golem stands says whether it is in an instance, whatever it was told on the
		// way: the room exists only as a copy walked in template coordinates. Told wrongly, it
		// was drawn in the wrong world — golems that had climbed out of the Mad Angel's room
		// went on walking the instance's copy of the island. The flag was only set by the
		// crossing, and one performed as a walk, or cut short by going out of view, never set
		// it.
		if (!instanceRoomTiles.isEmpty())
		{
			boolean inRoom = instanceRoomTiles.contains(RoamContext.tileKey(tileX, tileY, golem.getPlane()));
			if (golem.isInInstance() != inRoom && !golem.inTransition())
			{
				golem.setInInstance(inRoom);
			}
		}
		if (sceneChunks == null)
		{
			golem.setDrawOffset(0, 0, -1);
			// A golem in an instance is somewhere the overworld cannot see, even though it
			// is simulated in the template room — a real, sealed room on the island.
			if (golem.isInInstance())
			{
				return GolemTier.FAR;
			}
			return playerAt == null ? GolemTier.FAR
				: GolemTier.of(wv, tileX, tileY, golem.getPlane(), playerAt.getX(), playerAt.getY(), playerAt.getPlane());
		}

		// The instance is built from the chunks around the room as well as the room, and golems
		// on the island in those chunks were drawn inside it; the rest wait out of range.
		int[] scene = golem.isInInstance()
			? sceneChunks.get(InstanceMap.chunkKey(tileX >> 3, tileY >> 3, golem.getPlane()))
			: null;
		if (scene != null)
		{
			int drawX = wv.getBaseX() + (scene[0] << 3) + (tileX & 7);
			int drawY = wv.getBaseY() + (scene[1] << 3) + (tileY & 7);
			golem.setDrawOffset((drawX - tileX) * Golem.TILE, (drawY - tileY) * Golem.TILE, scene[2]);
			return playerAt == null ? GolemTier.FAR
				: GolemTier.of(wv, drawX, drawY, scene[2], playerAt.getX(), playerAt.getY(), playerAt.getPlane());
		}

		golem.setDrawOffset(0, 0, -1);
		return GolemTier.FAR;
	}

	private void updateRenderer(Golem golem, WorldView wv, boolean inSceneTier, TileMap drawnPerTile)
	{
		boolean visible = inSceneTier
			&& wv != null
			&& wv.getPlane() == golem.getDrawPlane()
			&& inScene(wv, golem)
			&& drawnPerTile.addTo(RoamContext.tileKey(golem.getFineX() / Golem.TILE,
				golem.getFineY() / Golem.TILE, golem.getPlane()), 1) <= MAX_DRAWN_PER_TILE;

		if (!visible)
		{
			detachRenderer(golem);
			return;
		}

		if (golem.getRenderer() == null)
		{
			Model model = modelFactory.modelFor(golem.getSnapshot());
			if (model == null)
			{
				return;
			}
			FakeGolem renderer = new FakeGolem(client, golem, model, modelFactory);
			long traceId = golem.getId();
			renderer.setTrace(line -> log.debug("Golem {} frame {}", traceId, line), () -> DevOptions.LOG_GOLEM_STATE);
			golem.setRenderer(renderer);
			client.registerRuneLiteObject(renderer);
		}
	}

	private boolean inScene(WorldView wv, Golem golem)
	{
		return Golem.isInScene(wv,
			golem.getDrawFineX() - wv.getBaseX() * Golem.TILE,
			golem.getDrawFineY() - wv.getBaseY() * Golem.TILE);
	}

	private void detachRenderer(Golem golem)
	{
		FakeGolem renderer = golem.getRenderer();
		if (renderer != null)
		{
			client.removeRuneLiteObject(renderer);
			golem.setRenderer(null);
		}
		// Its raft goes with it: a golem removed or crumbled at sea is never updated again,
		// so nothing else would take the raft away.
		FakeRaft raft = rafts.remove(golem);
		if (raft != null)
		{
			client.removeRuneLiteObject(raft);
		}
	}

	// ---- per-tick upkeep ----

	/**
	 * Development only: records what a shortcut actually does when the player uses one. Which
	 * clip it plays, and how long it takes, is server-side and in no cache, so the only way to
	 * know is to use one and watch. Remove this and its two siblings before release.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		obstacleObserver.onMenuOptionClicked(event);
	}

	@Subscribe
	public void onHitsplatApplied(net.runelite.api.events.HitsplatApplied event)
	{
		// A hit while using an obstacle means it failed; a fall is not the way across.
		if (event.getActor() == client.getLocalPlayer())
		{
			obstacleObserver.onPlayerHurt();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tickStartCycle = client.getGameCycle();
		announceUpdate();
		obstacleObserver.onGameTick();
		logGolemState();
		// Refreshed continuously rather than read once at spawn: a golem steps off its
		// plinth and starts walking, and its pose animations need not be the ones it had
		// while standing on it.
		WorldView topLevel = client.getTopLevelWorldView();
		if (topLevel != null)
		{
			for (NPC npc : topLevel.npcs())
			{
				if (detector.isGolem(npc) && !detector.wasReplaced(npc))
				{
					detector.track(npc);
				}
			}
		}

		// A new floor is ground to learn even though no scene was loaded: the harvest reads the
		// player's plane and only ran on a scene load, which a ladder does not trigger, so
		// golems that climbed arrived on unknown ground and were lifted back to the plinth —
		// 217 times in one session.
		WorldPoint me = PlayerPosition.of(client);
		int plane = me == null ? -1 : me.getPlane();
		if (plane != harvestedPlane)
		{
			harvestedPlane = plane;
			islandMemory.sceneChanged();
		}
		islandMemory.harvestLoadedRegions();

		// Only when the roster has actually changed: copying five hundred golems every tick
		// to hand the panel an identical list is work for nothing.
		if (panel != null && rosterChanged)
		{
			rosterChanged = false;
			List<Golem> living = livingGolems();
			panel.refresh(living, missingGolems(living.size()));
		}

		if (routesChanged)
		{
			applyLearnedRoutes();
			obstacleData.save();
		}

		if (++ticksSinceCensus >= CENSUS_TICKS)
		{
			ticksSinceCensus = 0;
			census.recount(golems);
		}

		if (saveGolemsAt >= 0 && client.getTickCount() >= saveGolemsAt)
		{
			saveGolemsAt = -1;
			saveGolems();
		}

		if (++ticksSinceSave >= SAVE_INTERVAL_TICKS)
		{
			ticksSinceSave = 0;
			saveGolems();
			saveIslandMemory();
			// Golems crossing obstacles add to the record constantly; written with the rest.
			obstacleData.save();
		}
	}

	/**
	 * Offers the hovered golem's menu entries.
	 *
	 * <p>On client tick rather than game tick: this is when the client rebuilds its menu, and
	 * a golem waiting up to 600ms to become hoverable would feel broken beside a real NPC.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		obstacleObserver.onClientTick();

		if (!golems.isEmpty())
		{
			menu.addEntries(drawnGolems);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		if (state == GameState.LOADING)
		{
			// The scene is being rebuilt, so every registered object is about to refer to
			// coordinates that no longer mean what they did. Drop the renderers; the golems
			// themselves are in world space.
			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
			// Scenery copies are registered objects too, holding scene-local coordinates
			// about to mean something else. A prop is short-lived, so drop them all.
			clearProps();
			clearRafts();
			lastGameCycle = -1;
			islandMemory.sceneChanged();
			return;
		}

		if (state == GameState.LOGGED_IN)
		{
			// The dock table is game data, not a bundled resource, so it needs a logged-in
			// client. Here rather than in startUp is what lets the plugin be enabled at the
			// login screen.
			sailingDocks.load();
			// Belt and braces next to onVarbitChanged: whichever of the two sees the
			// count first, the other is a no-op.
			syncTally();
			restorePending();
			return;
		}

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Golems are permanent, so nothing is released here — only the renderers,
			// which belong to a scene that is going away.
			saveGolems();
			saveIslandMemory();
			// Quest progress is the account's, and the next login may be another account.
			// Not on every LOGGED_IN, which also follows each loading screen.
			sailingDocks.forgetQuests();
			abilities.forgetQuests();
			obstacleObserver.resetSession();
			detector.reset();
			hiddenNpcs.clear();
			lastGameCycle = -1;

			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!GolemsDontDieConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("maxGolems".equals(event.getKey()) || "limitGolems".equals(event.getKey()))
		{
			clientThread.invoke(() ->
			{
				enforceGolemLimit();
				saveGolems();
				// The revive button offers only what the limit leaves room for.
				rosterChanged = true;
			});
		}

		// The obstacle settings are developer options for now, not in the panel: see
		// DevOptions. They must take effect the moment they change, so this returns with them.
		// if ("highlightObstacles".equals(event.getKey()) || "logGolemState".equals(event.getKey()))
		// {
		// 	applyObstacleSettings();
		// }
	}

	// ---- persistence ----

	/** Every tile of every instance room, from the last time routes changed. */
	private java.util.Set<Long> instanceRoomTiles = java.util.Collections.emptySet();

	/** Tiles flooded from an instance route's landing before it counts as open ground. */
	private static final int ROOM_FLOOD = 4000;

	/**
	 * Tiles only a transport into an instance reaches: the template rooms golems walk while
	 * inside one, as {@link RoamContext#tileKey} keys. For golems saved before the plugin
	 * tracked which were in an instance, and ones that walked into the Mad Angel's sealed room
	 * before the planner learned not to.
	 */
	private java.util.Set<Long> instanceRooms()
	{
		java.util.Set<Long> rooms = new java.util.HashSet<>();
		for (GolemTransport t : transports.all())
		{
			if (!t.entersInstance())
			{
				continue;
			}
			TileMap reached = pathfinder.flood(t.getToX(), t.getToY(), t.getToPlane(), ROOM_FLOOD);
			// A landing the golem could walk back from, or that opens onto a whole island,
			// is not a room.
			if (reached.size() >= ROOM_FLOOD || (t.getFromPlane() == t.getToPlane()
				&& reached.containsKey(GolemPathfinder.pack(t.getFromX(), t.getFromY()))))
			{
				continue;
			}
			for (int i = 0; i < reached.size(); i++)
			{
				long tile = reached.keyAt(i);
				rooms.add(RoamContext.tileKey(GolemPathfinder.unpackX(tile), GolemPathfinder.unpackY(tile), t.getToPlane()));
			}
		}
		return rooms;
	}

	private void restorePending()
	{
		if (pendingRestore.isEmpty() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// The saved roster replaces whatever is in memory, never adding on top: golems already
		// here are left from a shutdown that did not finish, and are the same golems again.
		if (!golems.isEmpty())
		{
			log.warn("Restoring over {} golems left from before; replacing them", golems.size());
			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
			golems.clear();
		}

		List<GolemStore.SavedGolem> saved = new ArrayList<>(pendingRestore);
		java.util.Set<Long> rooms = instanceRooms();
		instanceRoomTiles = rooms;
		for (int i = 0; i < saved.size(); i++)
		{
			Golem golem = store.revive(saved.get(i), i);
			if (golem != null)
			{
				// A saved tile can have become unstandable, and a golem restored inside a new
				// wall would never path anywhere again. Moved while nothing is looking, and
				// moved rather than replaced: same name, same id.
				WorldPoint at = golem.currentTile();
				WorldPoint safe = roamPlanner.snapToMesh(at);
				if (!safe.equals(at))
				{
					log.debug("Relocated restored golem from {} to {}", at, safe);
					golem.relocate(safe);
				}
				WorldPoint restored = golem.currentTile();
				if (!golem.isInInstance()
					&& rooms.contains(RoamContext.tileKey(restored.getX(), restored.getY(), restored.getPlane())))
				{
					golem.setInInstance(true);
				}

				golems.add(golem);
				rosterChanged = true;
			}
		}
		pendingRestore.clear();
		enforceGolemLimit();
		// Now there is a whole roster to hold against the game's count.
		trimToGameCount();
		log.debug("Restored {} saved golems", golems.size());
	}

	/**
	 * Writes the roster out. Golems mid-crumble are excluded: they have been retired, and
	 * saving them would bring them back alive on the next login.
	 */
	private void saveGolems()
	{
		if (!running)
		{
			log.debug("Not saving golems: the plugin is not running");
			return;
		}
		// Nothing to write until the saved roster has been loaded: golems are restored at login,
		// and saving the empty roster before that replaced every saved golem with nothing —
		// launching the client and closing it without logging in was enough.
		if (!pendingRestore.isEmpty())
		{
			log.debug("Not saving golems: {} saved golems are not restored yet", pendingRestore.size());
			return;
		}
		if (!rosterOwned)
		{
			log.debug("Not saving golems: the roster belongs to another account or kind of world");
			return;
		}
		configManager.setConfiguration(
			GolemsDontDieConfig.GROUP, GolemsDontDieConfig.SAVED_GOLEMS_KEY, store.serialise(livingGolems()));
	}

	private void saveIslandMemory()
	{
		if (!islandMemory.isDirty())
		{
			return;
		}
		configManager.setConfiguration(
			GolemsDontDieConfig.GROUP, IslandMemory.MAP_KEY, islandMemory.serialise());
	}

	// ---- hiding the original ----

	/**
	 * Hides a real golem once its copy has taken over: both exist for the rest of the
	 * original's short life, so without this there would visibly be two.
	 */
	private boolean shouldDraw(Renderable renderable)
	{
		if (hiddenNpcs.isEmpty() || !(renderable instanceof NPC))
		{
			return true;
		}
		return !hiddenNpcs.contains(((NPC) renderable).getIndex());
	}

	/**
	 * The current roster, for the overlays. The live list, not a copy: the minimap overlay reads
	 * it once per frame and copying would allocate for nothing. Both are touched only on the
	 * client thread.
	 */
	List<Golem> activeGolems()
	{
		return golems;
	}

	/** Golems with a model in the scene this frame. See the end of onBeforeRender. */
	private final List<Golem> drawnGolems = new ArrayList<>();

	/**
	 * The golems being drawn, for the overlays and the menu: everything else is off the scene
	 * and would only be looked at to be skipped, thousands of times a frame.
	 */
	List<Golem> drawnGolems()
	{
		return drawnGolems;
	}
}

package com.golemsdontdie;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * What is actually known about how each obstacle is traversed, and what golems may use.
 *
 * <p>The shipped guess at each obstacle's animation comes from the menu text and is <b>often
 * wrong</b>: a basalt stepping stone is named "stepping stone" and there is a
 * {@code HUMAN_STEPPINGSTONEJUMP}, but the game plays {@code HUMAN_SPOT_JUMP}.
 *
 * <p>So two questions are kept apart: may a golem go through here, nearly always yes, and do we
 * know what it looks like, where a no means it plays nothing, as at a door. Locking one direction
 * of a two-way transport would strand golems upstairs.
 *
 * <p>{@link ObstacleObserver} watches the player, and two consistent sightings unlock an obstacle
 * permanently — two rather than one because a single animation after a click proves nothing.
 */
@Slf4j
@Singleton
class ObstacleKnowledge
{
	/** Consistent sightings before an obstacle is trusted enough for a golem to use. */
	private static final int SIGHTINGS_TO_UNLOCK = 2;

	/** Where learned obstacles are kept between sessions. */
	static final String LEARNED_KEY = "learnedObstacles";

	/** Where the individual obstacles the player has personally used are kept. */
	static final String CONFIRMED_KEY = "confirmedObstacles";

	/** Where routes learned by watching the player are kept. */
	static final String ROUTES_KEY = "learnedRoutes";

	/** Where recorded motions are kept. */
	static final String CURVES_KEY = "learnedCurves";

	/** Where the line each obstacle moves the player along is kept. */
	static final String LINES_KEY = "learnedLines";

	/**
	 * Tiles either side of a transport's origin that still count as the same obstacle. A sighting
	 * records where the player <i>stood</i>, the index where the object <i>is</i>, and on
	 * Wyrmscraig's rocks those are three apart. Measured from the nearest tile of the object's
	 * footprint, not its south-west corner, which put a three-tile cave nowhere near itself.
	 */
	private static final int CONFIRM_TOLERANCE = 3;

	/**
	 * How sure we are about one particular obstacle. Three states because an obstacle golems
	 * already use on inferred data is exactly the one worth walking over to and using once.
	 */
	enum Status
	{
		/** Seen being used, here, on this object. Golems copy what was observed. */
		CONFIRMED,

		/** Golems will use it, on data generalised from elsewhere. Worth confirming. */
		INFERRED,

		/** No usable animation, so golems route around it entirely. */
		UNUSABLE
	}

	/**
	 * What the player has been seen doing, by object id. Outranks everything shipped: the live
	 * game on this client beats anything measured elsewhere months ago.
	 */
	private final Map<Integer, Learned> learned = new LinkedHashMap<>();

	/**
	 * The individual obstacles the player has personally used. Kept apart from {@link #learned}
	 * because what a <i>kind</i> of object does applies everywhere, while a <i>particular</i>
	 * ladder somebody stood on only gets coloured in.
	 */
	private final Map<Integer, List<int[]>> confirmed = new LinkedHashMap<>();

	/**
	 * Where an obstacle actually took the player, by the tile they used it from: the other half of
	 * learning, since an animation alone cannot make an obstacle usable and for most of the game
	 * nothing says where it comes out. Keyed by object <i>and</i> origin, one ladder id being two
	 * thousand obstacles that each come out somewhere different.
	 */
	//
	// Insertion-ordered, as every map here is: a HashMap's order shifts as keys are added, and
	// routes become transports in that order, so each sighting renumbered every learned transport.
	private final Map<String, List<int[]>> routes = new LinkedHashMap<>();

	/**
	 * The recent recordings of each kind of obstacle, by object rather than by place: what a
	 * traversal looks like is a property of the obstacle, so one recording serves every copy.
	 * Several are kept, since keeping only the latest let one bad traversal replace good ones; the
	 * one performed is the one the others most agree with, see {@link #consensus}.
	 */
	private final Map<Integer, List<MotionCurve>> curves = new LinkedHashMap<>();

	/**
	 * The line each obstacle moves the player along, as counts of each direction seen — "0,1" for
	 * a stile crossed north or south. Counted, not taken from the first sighting, so one odd
	 * traversal cannot fix a line for good; see {@link RouteGeometry}.
	 */
	private final Map<Integer, Map<String, Integer>> lines = new LinkedHashMap<>();

	/**
	 * Which saved routes may be offered at all, as {objectId, fromX, fromY, fromPlane, toX, toY,
	 * toPlane}. Set by the plugin, so that what was learned before a rule existed is held to it:
	 * trees recorded as obstacles, routes in the coordinates of a vanished instance.
	 */
	@lombok.Setter
	private java.util.function.Predicate<int[]> routeFilter;

	/** The recording performed for each object, chosen from {@link #curves}. */
	private final Map<Integer, MotionCurve> chosenCurves = new HashMap<>();

	/**
	 * Recent {ticks, delay, span} per object, for the same reason. Only in memory: the saved value
	 * is itself a previous session's consensus, and seeds the history when next added to.
	 */
	private final Map<Integer, List<int[]>> timings = new HashMap<>();

	/** Recordings kept per object. Odd, so there is always a middle. */
	private static final int CURVES_KEPT = 5;

	/**
	 * How far two arrivals can differ and still count as the same route. Small, because a stepping
	 * stone mid-line leads two ways and those must stay apart.
	 */
	private static final int DESTINATION_TOLERANCE = 2;

	/**
	 * Bumped whenever anything here changes, for the highlight overlay: using an obstacle leaves
	 * you standing next to it, so its cache, keyed on the player moving, never refreshes when an
	 * obstacle changes colour.
	 */
	@lombok.Getter
	private int version;

	/** One obstacle as observed here, and how sure of it we are. */
	static final class Learned
	{
		final int[] clips;
		final int ticks;

		/** Cycles of stillness before the movement, and how long the movement lasts. */
		final int moveDelay;
		final int moveSpan;

		int sightings;

		Learned(int[] clips, int ticks, int sightings, int moveDelay, int moveSpan)
		{
			this.clips = clips;
			this.ticks = ticks;
			this.sightings = sightings;
			this.moveDelay = moveDelay;
			this.moveSpan = moveSpan;
		}

		boolean unlocked()
		{
			return sightings >= SIGHTINGS_TO_UNLOCK;
		}
	}

	// ------------------------------------------------------------------- the policy

	/**
	 * True if a golem may use this transport. The shipped defaults below are the archetypes whose
	 * animation has been measured or corroborated well enough to act on; the rest stay locked.
	 */
	boolean isUnlocked(GolemTransport transport)
	{
		if (isLearned(transport.getObjectId()))
		{
			return true;
		}
		if (MeasuredShortcuts.animationFor(transport.getObjectId()) != -1)
		{
			// Somebody stood in front of this exact object and watched it.
			return true;
		}
		return shippedConfidence(transport);
	}

	/**
	 * Whether a golem may traverse this at all, on the shipped data alone.
	 *
	 * <p>Locked means routing around the obstacle as though it were not there, reserved for cases
	 * where using it without the animation would look broken rather than plain: jumps over two
	 * tiles, only the short hop having been measured, and balances, tightropes, squeezes and
	 * stiles, which have plausible names and no measurements. Ladders going down are deliberately
	 * not locked despite the disputed animation, since blocking one direction of a two-way
	 * transport strands a golem upstairs; it traverses silently instead, see {@link #clipsFor}.
	 */
	private boolean shippedConfidence(GolemTransport transport)
	{
		switch (transport.getArchetype())
		{
			case GolemTransport.ARCHETYPE_JUMP:
			{
				int span = transport.travelDistance();
				return span >= 0 && span <= 2;
			}

			case GolemTransport.ARCHETYPE_BALANCE:
			case GolemTransport.ARCHETYPE_TIGHTROPE:
			case GolemTransport.ARCHETYPE_SQUEEZE:
			case GolemTransport.ARCHETYPE_STILE:
				return false;

			case GolemTransport.ARCHETYPE_DOOR:
				// A golem cannot open a door: that changes a real object every other player can see.
				// The tables carry door rows because a *player* can open them; walking through an
				// open doorway needs no row at all.
				return false;

			default:
				// Gangplanks, ditches, climbs, ladders and the great mass of unclassified rows:
				// measured, corroborated, or animating nothing.
				return true;
		}
	}

	/**
	 * True if the shipped archetype's animation is trustworthy enough to play. Separate from
	 * {@link #shippedConfidence}: not knowing what an obstacle looks like means playing nothing
	 * rather than inventing an animation.
	 */
	private boolean shippedAnimationKnown(GolemTransport transport)
	{
		switch (transport.getArchetype())
		{
			case GolemTransport.ARCHETYPE_NONE:
			case GolemTransport.ARCHETYPE_DOOR:
			case GolemTransport.ARCHETYPE_GANGPLANK:
				// Nothing is played on the golem, so nothing can be played wrongly.
				return true;

			case GolemTransport.ARCHETYPE_DITCH:
			case GolemTransport.ARCHETYPE_CLIMB_OVER:
			case GolemTransport.ARCHETYPE_CLIMB:
				return true;

			case GolemTransport.ARCHETYPE_LADDER:
				// Up is 828 and agreed everywhere. Down is 833 here, never measured, and three
				// server reimplementations say 827, so it plays silently until somebody is seen.
				return transport.getToPlane() >= transport.getFromPlane();

			case GolemTransport.ARCHETYPE_JUMP:
			{
				int span = transport.travelDistance();
				return span >= 0 && span <= 2;
			}

			default:
				return false;
		}
	}

	/**
	 * How sure we are about one obstacle standing at one place. Drives the highlight overlay only;
	 * golem behaviour is decided by {@link #isUnlocked} and {@link #clipsFor}.
	 */
	/**
	 * How sure we are about an obstacle known only by what and where it is. The overlay works from
	 * the obstacle index, which knows nothing about where obstacles lead, so there may be no row
	 * at all — itself the answer.
	 */
	Status statusAt(int objectId, int x, int y, int plane, int sizeX, int sizeY,
		int archetype)
	{
		// Knowing the animation is not enough: something also has to say where an obstacle comes
		// out, and for many nothing does. First, because the colour has to mean "will a golem use
		// this", which it did not.
		boolean routed = archetype >= 0 || hasRoute(objectId, x, y, plane, sizeX, sizeY);
		if (!routed)
		{
			return Status.UNUSABLE;
		}

		if (!usableArchetype(archetype) && !isLearned(objectId)
			&& MeasuredShortcuts.animationFor(objectId) == -1)
		{
			return Status.UNUSABLE;
		}

		// Confirmed means the whole thing is known here: what it looks like, and where it
		// goes. Either half missing is "will use it, on generalised data".
		if (isLearned(objectId)
			&& isConfirmedAt(objectId, x, y, plane, sizeX, sizeY)
			&& hasRoute(objectId, x, y, plane, sizeX, sizeY))
		{
			return Status.CONFIRMED;
		}
		return Status.INFERRED;
	}

	/**
	 * Everything known about one obstacle, in one line, for reading in game. Four things decide
	 * the colour: the animation, the confirmation that it was this obstacle, the route, and
	 * whether the table describes it at all.
	 */
	String explain(int objectId, int x, int y, int plane, int sizeX, int sizeY, int archetype)
	{
		Learned known = learned.get(objectId);
		StringBuilder sb = new StringBuilder();
		sb.append(statusAt(objectId, x, y, plane, sizeX, sizeY, archetype)).append(" | ");

		if (known == null)
		{
			sb.append("anim: never seen");
		}
		else
		{
			sb.append("anim: ");
			if (known.clips.length == 0)
			{
				sb.append("none(silent)");
			}
			else
			{
				for (int i = 0; i < known.clips.length; i++)
				{
					sb.append(i == 0 ? "" : ",").append(known.clips[i]);
				}
			}
			sb.append(" ").append(known.ticks).append("t x").append(known.sightings)
				.append(known.unlocked() ? "" : " (needs another)");
		}

		sb.append(" | route: ")
			.append(hasRoute(objectId, x, y, plane, sizeX, sizeY) ? "known" : "unknown");
		sb.append(" | here: ")
			.append(isConfirmedAt(objectId, x, y, plane, sizeX, sizeY) ? "yes" : "no");
		sb.append(" | table: ").append(archetype < 0 ? "no rows" : "arch " + archetype);
		return sb.toString();
	}

	/**
	 * Whether golems will take this kind of obstacle on shipped data alone: the set
	 * {@link #shippedConfidence} locks, minus the parts needing a transport row. A ladder is
	 * usable both ways, simply playing nothing going down.
	 */
	private boolean usableArchetype(int archetype)
	{
		switch (archetype)
		{
			case GolemTransport.ARCHETYPE_BALANCE:
			case GolemTransport.ARCHETYPE_TIGHTROPE:
			case GolemTransport.ARCHETYPE_SQUEEZE:
			case GolemTransport.ARCHETYPE_STILE:
			case GolemTransport.ARCHETYPE_DOOR:
				return false;
			default:
				return true;
		}
	}

	/**
	 * Whether an archetype alone is enough, where no transport row is to hand. Coarser than
	 * {@link #shippedAnimationKnown}, which sees the plane change and distance: ladders come out
	 * unknown here, there being no direction to ask about.
	 */
	private boolean shippedAnimationForArchetype(int archetype)
	{
		switch (archetype)
		{
			case GolemTransport.ARCHETYPE_GANGPLANK:
			case GolemTransport.ARCHETYPE_DITCH:
			case GolemTransport.ARCHETYPE_CLIMB_OVER:
			case GolemTransport.ARCHETYPE_CLIMB:
				return true;
			default:
				return false;
		}
	}

	Status statusAt(GolemTransport transport)
	{
		if (!isUnlocked(transport))
		{
			return Status.UNUSABLE;
		}
		// Confirmed means both that this kind of object has been watched enough to be trusted and
		// that this particular one is what was watched; a single sighting is neither.
		Learned known = learned.get(transport.getObjectId());
		if (known != null && known.unlocked()
			&& isConfirmedAt(transport.getObjectId(), transport.getFromX(),
				transport.getFromY(), transport.getFromPlane(), 1, 1))
		{
			return Status.CONFIRMED;
		}
		return Status.INFERRED;
	}

	private boolean isConfirmedAt(int objectId, int x, int y, int plane,
		int sizeX, int sizeY)
	{
		List<int[]> places = confirmed.get(objectId);
		if (places == null)
		{
			return false;
		}
		for (int[] at : places)
		{
			if (at[2] != plane)
			{
				continue;
			}
			// Distance to the nearest tile the object occupies, not to its corner.
			int dx = Math.max(Math.max(x - at[0], at[0] - (x + sizeX - 1)), 0);
			int dy = Math.max(Math.max(y - at[1], at[1] - (y + sizeY - 1)), 0);
			if (dx <= CONFIRM_TOLERANCE && dy <= CONFIRM_TOLERANCE)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Records where an obstacle led, when that is worth anything. Instances are refused: rebuilt
	 * with fresh coordinates each time, so a destination inside one describes a vanished room.
	 */
	private void noteRoute(ObstacleSighting sighting)
	{
		if (sighting.instance || !sighting.moved())
		{
			return;
		}

		String key = routeKey(sighting.objectId, sighting.fromX, sighting.fromY,
			sighting.fromPlane);
		List<int[]> here = routes.computeIfAbsent(key, k -> new ArrayList<>());

		int flags = sighting.toInstance && !sighting.fromInstance ? GolemTransport.INTO_INSTANCE
			: sighting.fromInstance && !sighting.toInstance ? GolemTransport.OUT_OF_INSTANCE : 0;

		for (int[] seen : here)
		{
			// Near enough is the same route: a rock climb landed on 2555 one time and 2556 the next,
			// and demanding the same tile reset the count after every use.
			if (seen[2] == sighting.toPlane
				&& Math.abs(seen[0] - sighting.toX) <= DESTINATION_TOLERANCE
				&& Math.abs(seen[1] - sighting.toY) <= DESTINATION_TOLERANCE)
			{
				// The same route, and the newest sighting's end is kept: keeping the first left the
				// way out of the stile's pen saved ending on the stile itself, so golems went in and
				// never came out.
				seen[0] = sighting.toX;
				seen[1] = sighting.toY;
				seen[3]++;
				seen[4] = flags;
				return;
			}
		}

		// Genuinely somewhere else, so a second route from this tile rather than a contradiction
		// of the first: the middle of a line of stepping stones really does lead two ways.
		here.add(new int[]{sighting.toX, sighting.toY, sighting.toPlane, 1, flags});
	}

	/** How far apart two origins of the same move can be and still be one obstacle. */
	private static final int NEIGHBOUR_ORIGIN = 2;

	/**
	 * Sightings behind a route, counting its neighbours. A church pew is climbed from whichever end
	 * is nearer, so its routes, the same hop a tile apart, were each seen once and never reached
	 * two.
	 *
	 * @param to {toX, toY, toPlane, count, flags}
	 */
	private int sightingsFor(int objectId, int fromX, int fromY, int fromPlane, int[] to)
	{
		int total = 0;
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			String[] key = e.getKey().split(",");
			int otherX = Integer.parseInt(key[1]);
			int otherY = Integer.parseInt(key[2]);
			if (Integer.parseInt(key[0]) != objectId || Integer.parseInt(key[3]) != fromPlane
				|| Math.abs(otherX - fromX) > NEIGHBOUR_ORIGIN || Math.abs(otherY - fromY) > NEIGHBOUR_ORIGIN)
			{
				continue;
			}
			for (int[] other : e.getValue())
			{
				if (other[2] == to[2] && other[0] - otherX == to[0] - fromX && other[1] - otherY == to[1] - fromY)
				{
					total += other[3];
				}
			}
		}
		return total;
	}

	/**
	 * A route's flags, taken with its neighbours' as its sightings are: the Mad Angel's pew was
	 * learned from two tiles a row apart, and the route that did not know it led into the instance
	 * was unlocked without the flag.
	 */
	private int flagsFor(int objectId, int fromX, int fromY, int fromPlane, int[] to)
	{
		int flags = to[4];
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			String[] key = e.getKey().split(",");
			int otherX = Integer.parseInt(key[1]);
			int otherY = Integer.parseInt(key[2]);
			if (Integer.parseInt(key[0]) != objectId || Integer.parseInt(key[3]) != fromPlane
				|| Math.abs(otherX - fromX) > NEIGHBOUR_ORIGIN || Math.abs(otherY - fromY) > NEIGHBOUR_ORIGIN)
			{
				continue;
			}
			for (int[] other : e.getValue())
			{
				if (other[2] == to[2] && other[0] - otherX == to[0] - fromX && other[1] - otherY == to[1] - fromY)
				{
					flags |= other[4];
				}
			}
		}
		return flags;
	}

	/** Every obstacle the player has used and where, as {objectId, x, y, plane}. */
	List<int[]> confirmedPlaces()
	{
		List<int[]> out = new ArrayList<>();
		for (Map.Entry<Integer, List<int[]>> e : confirmed.entrySet())
		{
			for (int[] at : e.getValue())
			{
				out.add(new int[]{e.getKey(), at[0], at[1], at[2]});
			}
		}
		return out;
	}

	private static String routeKey(int objectId, int x, int y, int plane)
	{
		return objectId + "," + x + "," + y + "," + plane;
	}

	/**
	 * Every route seen often enough to act on, as {objectId, fromX, fromY, fromPlane, toX, toY,
	 * toPlane, ticks}. The ticks matter as much as the coordinates: a duration of one compressed
	 * a rockslide's four ticks into one tick of gliding.
	 */
	List<int[]> learnedRoutes()
	{
		// Every tile a learned route along its obstacle's line starts or ends on; see jumpsOver.
		// Routes off the line are no evidence, an old diagonal stile route ending beside the right
		// one.
		java.util.Set<Long> ends = new java.util.HashSet<>();
		// Each key read as numbers once, not once per use.
		List<int[]> keys = new ArrayList<>(routes.size());
		for (String key : routes.keySet())
		{
			String[] parts = key.split(",");
			keys.add(new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]),
				Integer.parseInt(parts[3])});
		}
		int entry = 0;
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			int[] from = keys.get(entry++);
			int objectId = from[0];
			int fromX = from[1];
			int fromY = from[2];
			int fromPlane = from[3];
			for (int[] to : e.getValue())
			{
				if (followsObjectLine(objectId, fromX, fromY, fromPlane, to))
				{
					ends.add(RoamContext.tileKey(fromX, fromY, fromPlane));
					ends.add(RoamContext.tileKey(to[0], to[1], to[2]));
				}
			}
		}

		List<int[]> out = new ArrayList<>();
		entry = 0;
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			int[] from = keys.get(entry++);
			for (int[] to : e.getValue())
			{
				if (jumpsOver(from[1], from[2], from[3], to, ends))
				{
					continue;
				}
				if (to[3] < SIGHTINGS_TO_UNLOCK && sightingsFor(from[0], from[1], from[2], from[3], to) < SIGHTINGS_TO_UNLOCK)
				{
					continue;
				}
				// A route saved before its obstacle's line was known is held to it now, so the
				// diagonal stile routes already in a profile stop being used once the stile is
				// crossed, without anybody deleting them.
				if (!followsObjectLine(from[0], from[1], from[2], from[3], to))
				{
					continue;
				}
				Learned known = learned.get(from[0]);
				int[] route = {
					from[0], from[1], from[2], from[3],
					to[0], to[1], to[2],
					known == null ? 1 : Math.max(1, known.ticks),
					flagsFor(from[0], from[1], from[2], from[3], to),
				};
				if (routeFilter == null || routeFilter.test(route))
				{
					out.add(route);
				}
			}
		}
		return out;
	}

	/**
	 * True if a route leaps over a tile some other learned route starts or ends on — a stepping
	 * stone. A hop recorded wrongly came out two tiles long, over the stone the true hops use;
	 * held out rather than deleted, the next correct crossing overwriting it in place.
	 */
	private static boolean jumpsOver(int fromX, int fromY, int plane, int[] to, java.util.Set<Long> ends)
	{
		int dx = to[0] - fromX;
		int dy = to[1] - fromY;
		int span = Math.max(Math.abs(dx), Math.abs(dy));
		if (to[2] != plane || span < 2 || dx != 0 && dy != 0 && Math.abs(dx) != Math.abs(dy))
		{
			return false;
		}
		for (int step = 1; step < span; step++)
		{
			if (ends.contains(RoamContext.tileKey(fromX + Integer.signum(dx) * step, fromY + Integer.signum(dy) * step, plane)))
			{
				return true;
			}
		}
		return false;
	}

	/** True if the player has shown us where this obstacle goes from near this tile. */
	boolean hasRoute(int objectId, int x, int y, int plane, int sizeX, int sizeY)
	{
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			String[] from = e.getKey().split(",");
			// Which obstacle first, because it is cheap and nearly always no: the overlay asks this
			// of every obstacle in range, and counting a route's sightings is not free.
			if (Integer.parseInt(from[0]) != objectId
				|| Integer.parseInt(from[3]) != plane)
			{
				continue;
			}
			int fx = Integer.parseInt(from[1]);
			int fy = Integer.parseInt(from[2]);
			int dx = Math.max(Math.max(x - fx, fx - (x + sizeX - 1)), 0);
			int dy = Math.max(Math.max(y - fy, fy - (y + sizeY - 1)), 0);
			if (dx > CONFIRM_TOLERANCE || dy > CONFIRM_TOLERANCE)
			{
				continue;
			}
			for (int[] to : e.getValue())
			{
				if ((to[3] >= SIGHTINGS_TO_UNLOCK
						|| sightingsFor(objectId, fx, fy, plane, to) >= SIGHTINGS_TO_UNLOCK)
					&& followsObjectLine(objectId, fx, fy, plane, to)
					&& (routeFilter == null || routeFilter.test(new int[]{
						objectId, fx, fy, plane, to[0], to[1], to[2]})))
				{
					return true;
				}
			}
		}
		return false;
	}

	private void noteLine(ObstacleSighting sighting)
	{
		if (sighting.fromPlane != sighting.toPlane || !RouteGeometry.local(sighting.lineX, sighting.lineY))
		{
			return;
		}
		int[] direction = RouteGeometry.canonical(sighting.lineX, sighting.lineY);
		lines.computeIfAbsent(sighting.objectId, k -> new LinkedHashMap<>())
			.merge(direction[0] + "," + direction[1], 1, Integer::sum);
	}

	/** The line this obstacle most often moves players along, or null if none is known. */
	int[] lineOf(int objectId)
	{
		Map<String, Integer> seen = lines.get(objectId);
		if (seen == null || seen.isEmpty())
		{
			return null;
		}
		String best = null;
		for (Map.Entry<String, Integer> e : seen.entrySet())
		{
			if (best == null || e.getValue() > seen.get(best))
			{
				best = e.getKey();
			}
		}
		String[] parts = best.split(",");
		return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])};
	}

	/** Whether this sighting's route lies along its own movement and its obstacle's line. */
	private boolean followsLine(ObstacleSighting sighting)
	{
		if (sighting.fromPlane != sighting.toPlane)
		{
			return true;
		}
		int routeX = sighting.toX - sighting.fromX;
		int routeY = sighting.toY - sighting.fromY;
		int[] line = lineOf(sighting.objectId);
		return RouteGeometry.follows(routeX, routeY, sighting.lineX, sighting.lineY)
			&& (line == null || RouteGeometry.follows(routeX, routeY, line[0], line[1]));
	}

	/** Whether a stored route, {toX, toY, toPlane, count}, lies along its obstacle's line. */
	private boolean followsObjectLine(int objectId, int fromX, int fromY, int fromPlane, int[] to)
	{
		int[] line = lineOf(objectId);
		return line == null || to[2] != fromPlane
			|| RouteGeometry.follows(to[0] - fromX, to[1] - fromY, line[0], line[1]);
	}

	/** {@code objectId=x,y,count|x,y,count;...} */
	String serialiseLines()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, Map<String, Integer>> e : lines.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(e.getKey()).append('=');
			boolean first = true;
			for (Map.Entry<String, Integer> direction : e.getValue().entrySet())
			{
				sb.append(first ? "" : "|").append(direction.getKey()).append(',')
					.append(direction.getValue());
				first = false;
			}
		}
		return sb.toString();
	}

	void deserialiseLines(String saved)
	{
		lines.clear();
		version++;
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String entry : saved.split(";"))
		{
			try
			{
				int split = entry.indexOf('=');
				Map<String, Integer> seen = new LinkedHashMap<>();
				for (String direction : entry.substring(split + 1).split("\\|"))
				{
					String[] parts = direction.split(",");
					seen.put(parts[0] + "," + parts[1], Integer.parseInt(parts[2]));
				}
				lines.put(Integer.parseInt(entry.substring(0, split)), seen);
			}
			catch (RuntimeException e)
			{
				log.debug("Skipping unreadable line: {}", entry);
			}
		}
	}

	String serialiseCurves()
	{
		// One entry per recording, oldest first, so an object with several repeats its id. Files
		// written when only one was kept read back unchanged.
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, List<MotionCurve>> e : curves.entrySet())
		{
			for (MotionCurve curve : e.getValue())
			{
				if (sb.length() > 0)
				{
					sb.append(';');
				}
				sb.append(e.getKey()).append('=').append(curve.serialise());
			}
		}
		return sb.toString();
	}

	void deserialiseCurves(String saved)
	{
		curves.clear();
		chosenCurves.clear();
		version++;
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String entry : saved.split(";"))
		{
			int split = entry.indexOf('=');
			if (split <= 0)
			{
				continue;
			}
			try
			{
				MotionCurve curve = MotionCurve.parse(entry.substring(split + 1));
				if (curve != null)
				{
					addCurve(Integer.parseInt(entry.substring(0, split)), curve);
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Skipping unreadable curve: {}", entry.substring(0, split));
			}
		}
		log.debug("Restored recorded motions for {} obstacles", curves.size());
	}

	private void addCurve(int objectId, MotionCurve curve)
	{
		List<MotionCurve> kept = curves.computeIfAbsent(objectId, k -> new ArrayList<>());
		// A recording that knows which way the player faced supersedes every one that does not,
		// or the older ones outvote it and the golem keeps facing forwards down the rockslide.
		if (curve.hasFacing())
		{
			kept.removeIf(old -> !old.hasFacing());
		}
		// Likewise keyframes: an older recording without them plays the clip at its authored
		// speed and hops before the jump.
		if (curve.hasKeyframes())
		{
			kept.removeIf(old -> !old.hasKeyframes());
		}
		kept.add(curve);
		while (kept.size() > CURVES_KEPT)
		{
			kept.remove(0);
		}
		chosenCurves.put(objectId, consensus(kept));
	}

	/**
	 * The recording the others most agree with: a medoid, not an average, since averaging two
	 * recordings of a door produces a glide neither contains. Compared on length, reach, lateral
	 * drift and number of movements; with two, the more ordinary wins.
	 */
	static MotionCurve consensus(List<MotionCurve> kept)
	{
		MotionCurve best = null;
		double bestScore = Double.MAX_VALUE;
		for (int i = kept.size() - 1; i >= 0; i--)
		{
			MotionCurve candidate = kept.get(i);
			double score = kept.size() < 3 ? oddness(candidate) : 0;
			for (MotionCurve other : kept)
			{
				if (other != candidate)
				{
					score += difference(candidate, other);
				}
			}
			if (score < bestScore - 1e-6)
			{
				best = candidate;
				bestScore = score;
			}
		}
		return best;
	}

	private static double difference(MotionCurve a, MotionCurve b)
	{
		return Math.abs(a.cycles() - b.cycles()) / (double) Math.max(1, Math.max(a.cycles(), b.cycles()))
			+ Math.abs(a.reach() - b.reach()) / (double) Golem.TILE
			+ Math.abs(a.maxLateral() - b.maxLateral()) / (double) Golem.TILE
			+ Math.abs(a.bursts() - b.bursts());
	}

	private static double oddness(MotionCurve curve)
	{
		return curve.maxLateral() / (double) Golem.TILE + Math.max(0, curve.bursts() - 1);
	}

	/** The middle value of one column of {@link #timings}. */
	private static int median(List<int[]> rows, int column)
	{
		int[] values = new int[rows.size()];
		for (int i = 0; i < values.length; i++)
		{
			values[i] = rows.get(i)[column];
		}
		java.util.Arrays.sort(values);
		return values[values.length / 2];
	}

	String serialiseRoutes()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			for (int[] to : e.getValue())
			{
				if (sb.length() > 0)
				{
					sb.append(';');
				}
				sb.append(e.getKey()).append('>').append(to[0]).append(',').append(to[1])
					.append(',').append(to[2]).append(',').append(to[3]);
				// Only where there is one, so a profile without instances saves as it always did.
				if (to[4] != 0)
				{
					sb.append(',').append(to[4]);
				}
			}
		}
		return sb.toString();
	}

	void deserialiseRoutes(String saved)
	{
		routes.clear();
		version++;
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String entry : saved.split(";"))
		{
			try
			{
				String[] halves = entry.split(">");
				String[] to = halves[1].split(",");
				// The key is read back as numbers whenever routes are listed, outside any try, so
				// one bad key saved here would stop the plugin starting.
				String[] from = halves[0].split(",");
				if (from.length != 4)
				{
					throw new IllegalArgumentException("route key " + halves[0]);
				}
				for (String part : from)
				{
					Integer.parseInt(part);
				}
				routes.computeIfAbsent(halves[0], k -> new ArrayList<>())
					.add(new int[]{Integer.parseInt(to[0]), Integer.parseInt(to[1]),
						Integer.parseInt(to[2]), Integer.parseInt(to[3]),
						to.length > 4 ? Integer.parseInt(to[4]) : 0});
			}
			catch (RuntimeException e)
			{
				log.debug("Skipping unreadable route: {}", entry);
			}
		}
	}

	private void noteConfirmed(ObstacleSighting sighting)
	{
		List<int[]> places = confirmed.computeIfAbsent(sighting.objectId, k -> new ArrayList<>());
		if (isConfirmedAt(sighting.objectId, sighting.fromX, sighting.fromY,
			sighting.fromPlane, 1, 1))
		{
			return;
		}
		places.add(new int[]{sighting.fromX, sighting.fromY, sighting.fromPlane});
	}

	// ------------------------------------------------------------- what to play

	/**
	 * The clips a golem should play for this transport, best source first: what the player was
	 * seen doing beats what was shipped, which beats the archetype's guess.
	 */
	/**
	 * True if the player has been watched using this obstacle, whatever the outcome. Tells "seen,
	 * and it plays nothing" from "never seen", which an empty clip set cannot do on its own.
	 */
	boolean isLearned(int objectId)
	{
		Learned known = learned.get(objectId);
		return known != null && known.unlocked();
	}

	int[] clipsFor(GolemTransport transport)
	{
		// Only once it has cleared the bar everything else clears: a single sighting can be a
		// player attacked between clicking a ladder and reaching it.
		Learned known = learned.get(transport.getObjectId());
		if (known != null && known.unlocked())
		{
			// Including when it is empty: that is a measured "plays nothing".
			return known.clips;
		}
		if (MeasuredShortcuts.animationFor(transport.getObjectId()) != -1
			|| shippedAnimationKnown(transport))
		{
			return transport.animations();
		}

		// Not known, so the golem goes through in its ordinary pose rather than performing
		// something invented, as it already does for a door: plain, not wrong.
		return NOTHING;
	}

	private static final int[] NOTHING = new int[0];

	/** The recorded motion for this obstacle, or null if nobody has been watched doing it. */
	MotionCurve curveFor(GolemTransport transport)
	{
		return chosenCurves.get(transport.getObjectId());
	}

	/** Cycles a golem should stand still before moving, or 0 if unknown. */
	int moveDelayFor(GolemTransport transport)
	{
		Learned known = learned.get(transport.getObjectId());
		return known != null && known.unlocked() ? known.moveDelay : 0;
	}

	/** Cycles the movement itself should take, or 0 if unknown. */
	int moveSpanFor(GolemTransport transport)
	{
		Learned known = learned.get(transport.getObjectId());
		return known != null && known.unlocked() ? known.moveSpan : 0;
	}


	/**
	 * How long the traversal should take, or 0 to fall back to the clip and the table. A learned
	 * duration runs from the first clip to the player standing still, which for a single clip
	 * includes the pause afterwards and stretched a 38-cycle hop over 60, so a single clip is left
	 * at its own length and only a motion built in parts takes it.
	 */
	int ticksFor(GolemTransport transport)
	{
		Learned known = learned.get(transport.getObjectId());
		if (known != null && known.unlocked() && known.ticks > 0 && known.clips.length != 1)
		{
			return known.ticks;
		}
		return MeasuredShortcuts.ticksFor(transport.getObjectId());
	}

	// ---------------------------------------------------------------- learning

	/**
	 * Records one sighting, and reports whether it has just unlocked the obstacle. A sighting that
	 * disagrees with what was learned resets the count rather than averaging: averaging two
	 * animation ids produces a third that is not an animation.
	 */
	boolean record(ObstacleSighting sighting)
	{
		// An empty clip set is not a failed observation but the observation that this obstacle
		// animates nobody, as a staircase and fifteen hundred other rows do.
		version++;
		noteConfirmed(sighting);
		noteLine(sighting);

		// Only a route lying along the obstacle is learned — along this traversal's movement and the
		// line the obstacle is known to move players — since a route off the line is performed off
		// it, as with the stile crossed on a slant. The animation is still learned.
		if (followsLine(sighting))
		{
			noteRoute(sighting);
			if (sighting.curve != null && !sighting.curve.isEmpty())
			{
				addCurve(sighting.objectId, sighting.curve);
			}
		}
		else
		{
			log.debug("Refused route off the line of {}: {}", sighting.objectId, sighting);
		}

		// One crossing is not one use: a sighting covers click to arrival, so three stepping stones
		// came back as 741,741,741 over six ticks while the table stores one row per hop. A run of
		// the same clip collapses to that motion and its share of the time.
		int[] clips = collapseRepeats(sighting.clips);
		int ticks = clips.length == sighting.clips.length || clips.length == 0
			? sighting.ticks
			: Math.max(1, Math.round(sighting.ticks / (float) sighting.clips.length));

		Learned existing = learned.get(sighting.objectId);
		if (existing == null || !sameClips(existing.clips, clips))
		{
			List<int[]> fresh = new ArrayList<>();
			fresh.add(new int[]{ticks, sighting.moveDelay, sighting.moveSpan});
			timings.put(sighting.objectId, fresh);
			learned.put(sighting.objectId,
				new Learned(clips, ticks, 1, sighting.moveDelay, sighting.moveSpan));
			return false;
		}

		boolean wasUnlocked = existing.unlocked();
		existing.sightings++;

		// The middle of the recent sightings, not the latest: one unusual traversal otherwise
		// rewrites what every golem does, a two-tick door being stored as three. What is saved
		// seeds the history across a restart.
		List<int[]> history = timings.computeIfAbsent(sighting.objectId, k ->
		{
			List<int[]> seeded = new ArrayList<>();
			seeded.add(new int[]{existing.ticks, existing.moveDelay, existing.moveSpan});
			return seeded;
		});
		history.add(new int[]{ticks, sighting.moveDelay, sighting.moveSpan});
		while (history.size() > CURVES_KEPT)
		{
			history.remove(0);
		}

		Learned updated = new Learned(existing.clips, median(history, 0), existing.sightings,
			median(history, 1), median(history, 2));
		learned.put(sighting.objectId, updated);

		return !wasUnlocked && updated.unlocked();
	}

	/**
	 * Reduces a run of one repeated clip to a single instance. Only when every clip is the same:
	 * a mixed set is a motion with parts, and losing them leaves a golem playing a mount and
	 * standing still.
	 */
	private static int[] collapseRepeats(int[] clips)
	{
		if (clips.length < 2)
		{
			return clips;
		}
		for (int clip : clips)
		{
			if (clip != clips[0])
			{
				return clips;
			}
		}
		return new int[]{clips[0]};
	}

	private static boolean sameClips(int[] a, int[] b)
	{
		if (a.length != b.length)
		{
			return false;
		}
		for (int i = 0; i < a.length; i++)
		{
			if (a[i] != b[i])
			{
				return false;
			}
		}
		return true;
	}

	/** How many obstacles the player has taught the plugin so far. */
	int unlockedCount()
	{
		int n = 0;
		for (Learned l : learned.values())
		{
			if (l.unlocked())
			{
				n++;
			}
		}
		return n;
	}

	int sightingCount()
	{
		return learned.size();
	}

	// -------------------------------------------------------------- persistence

	/**
	 * Everything learned, as one line: {@code objectId:clip|clip|clip:ticks:sightings},
	 * semicolon separated. Compact because it lives in the RuneLite config, which is not a
	 * database.
	 */
	String serialise()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, Learned> e : learned.entrySet())
		{
			Learned l = e.getValue();
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(e.getKey()).append(':');
			for (int i = 0; i < l.clips.length; i++)
			{
				sb.append(i == 0 ? "" : "|").append(l.clips[i]);
			}
			sb.append(':').append(l.ticks).append(':').append(l.sightings)
				.append(':').append(l.moveDelay).append(':').append(l.moveSpan);
		}
		return sb.toString();
	}

	/**
	 * The obstacles the player has personally used, as one line: {@code objectId,x,y,plane}
	 * groups separated by semicolons. Purely cosmetic — losing it costs some green outlines.
	 */
	String serialiseConfirmed()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, List<int[]>> e : confirmed.entrySet())
		{
			for (int[] at : e.getValue())
			{
				if (sb.length() > 0)
				{
					sb.append(';');
				}
				sb.append(e.getKey()).append(',').append(at[0]).append(',')
					.append(at[1]).append(',').append(at[2]);
			}
		}
		return sb.toString();
	}

	void deserialiseConfirmed(String saved)
	{
		confirmed.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}

		for (String entry : saved.split(";"))
		{
			try
			{
				String[] parts = entry.split(",");
				if (parts.length != 4)
				{
					continue;
				}
				confirmed.computeIfAbsent(Integer.parseInt(parts[0]), k -> new ArrayList<>())
					.add(new int[]{Integer.parseInt(parts[1]), Integer.parseInt(parts[2]),
						Integer.parseInt(parts[3])});
			}
			catch (RuntimeException e)
			{
				log.debug("Skipping unreadable confirmed obstacle: {}", entry);
			}
		}
	}

	/** Restores what was learned in previous sessions. Bad rows are skipped, not fatal. */
	void deserialise(String saved)
	{
		version++;
		learned.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}

		for (String entry : saved.split(";"))
		{
			try
			{
				String[] parts = entry.split(":");
				if (parts.length < 4)
				{
					continue;
				}

				// An empty clip field is a learned "plays nothing", not a broken row: parsing it as a
				// number throws, and every silent obstacle taught was forgotten at the next login.
				int[] clips;
				if (parts[1].isEmpty())
				{
					clips = new int[0];
				}
				else
				{
					String[] clipText = parts[1].split("\\|");
					clips = new int[clipText.length];
					for (int i = 0; i < clips.length; i++)
					{
						clips[i] = Integer.parseInt(clipText[i]);
					}
				}

				// Repaired on the way in as well as out: entries written before the repeat collapse
				// existed hold a whole crossing where they should hold one hop.
				int ticks = Integer.parseInt(parts[2]);
				int[] collapsed = collapseRepeats(clips);
				if (collapsed.length != clips.length && clips.length > 0)
				{
					ticks = Math.max(1, Math.round(ticks / (float) clips.length));
				}

				// Rows written before the movement window was recorded have four fields; they load
				// with zeroes and are filled the next time anybody uses the obstacle.
				int delay = parts.length > 4 ? Integer.parseInt(parts[4]) : 0;
				int span = parts.length > 5 ? Integer.parseInt(parts[5]) : 0;
				learned.put(Integer.parseInt(parts[0]),
					new Learned(collapsed, ticks, Integer.parseInt(parts[3]), delay, span));
			}
			catch (RuntimeException e)
			{
				// One malformed entry must not cost everything else the player has taught.
				log.debug("Skipping unreadable learned obstacle: {}", entry);
			}
		}

		log.debug("Restored {} learned obstacles, {} unlocked", learned.size(), unlockedCount());
	}
}

package com.golemsdontdie;

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

/**
 * Builds the animated scenery drawn beside a golem that is using something.
 *
 * <p>{@code ObjectComposition} exposes an object's name, actions and size but <b>not its
 * model ids</b>, where {@code NPCComposition} does, so there is no runtime route from an
 * object id to its geometry. The ids are read offline from the game cache and shipped: 206
 * objects the transport network
 * references, in about a kilobyte. Each carries the animation the object itself plays, so a
 * gate, a portcullis and a fairy ring each get their own motion with nothing enumerating
 * which is which.
 *
 * <p>Models are cached and shared as the golems' are: a hundred golems boarding the same
 * ferry build one plank between them.
 */
@Slf4j
@Singleton
class PropFactory
{
	private static final String RESOURCE = "/props.gz";

	/** The client's own lighting for a scene object, before the object's own offsets. */
	private static final int BASE_AMBIENT = 64;
	private static final int BASE_CONTRAST = 768;
	private static final int LIGHT_X = -50;
	private static final int LIGHT_Y = -10;
	private static final int LIGHT_Z = -50;

	@Inject
	private Client client;

	/** What the cache says about one animated object. */
	static final class Prop
	{
		@Getter
		private final int objectId;
		@Getter
		private final int animation;
		private final int ambient;
		private final int contrast;
		@Getter
		private final int sizeX;
		@Getter
		private final int sizeY;
		private final int[] models;

		Prop(int objectId, int animation, int ambient, int contrast,
			int sizeX, int sizeY, int[] models)
		{
			this.objectId = objectId;
			this.animation = animation;
			this.ambient = ambient;
			this.contrast = contrast;
			this.sizeX = sizeX;
			this.sizeY = sizeY;
			this.models = models;
		}
	}

	private final Map<Integer, Prop> props = new HashMap<>();
	private final Map<Integer, Model> built = new HashMap<>();

	private boolean loaded;

	void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;

		try (InputStream raw = PropFactory.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.debug("No prop table in the jar; scenery will not be animated");
				return;
			}
			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int objectId = data.readInt();
					int animation = data.readInt();
					int ambient = data.readShort();
					int contrast = data.readShort();
					int sizeX = data.readByte();
					int sizeY = data.readByte();
					int[] models = new int[data.readByte() & 0xFF];
					for (int m = 0; m < models.length; m++)
					{
						models[m] = data.readInt();
					}
					props.put(objectId, new Prop(objectId, animation, ambient, contrast,
						sizeX, sizeY, models));
				}
				log.debug("Loaded {} animated props", props.size());
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Prop table unreadable", e);
			props.clear();
		}
	}

	/** Null if the object has no animation worth drawing. */
	Prop propFor(int objectId)
	{
		return props.get(objectId);
	}

	/**
	 * The object's model, built once and shared. Sharing is safe because the client's
	 * transformation clones vertices out of its source, so the base is never written to.
	 *
	 * @return the lit model, or null if the cache would not give up the parts
	 */
	Model modelFor(Prop prop)
	{
		if (prop == null)
		{
			return null;
		}
		Model cached = built.get(prop.getObjectId());
		if (cached != null)
		{
			return cached;
		}

		try
		{
			ModelData merged = merge(prop.models);
			if (merged == null)
			{
				return null;
			}
			Model model = merged.light(BASE_AMBIENT + prop.ambient,
				BASE_CONTRAST + prop.contrast, LIGHT_X, LIGHT_Y, LIGHT_Z);
			built.put(prop.getObjectId(), model);
			return model;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not build prop {}", prop.getObjectId(), e);
			return null;
		}
	}

	private ModelData merge(int[] modelIds)
	{
		if (modelIds.length == 1)
		{
			ModelData one = client.loadModelData(modelIds[0]);
			return one == null ? null : one.cloneVertices();
		}

		ModelData[] parts = new ModelData[modelIds.length];
		for (int i = 0; i < modelIds.length; i++)
		{
			parts[i] = client.loadModelData(modelIds[i]);
			if (parts[i] == null)
			{
				return null;
			}
		}
		return client.mergeModels(parts).cloneVertices();
	}

	void clear()
	{
		built.clear();
	}
}

package com.golemsdontdie;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.DBTableID;

/**
 * The game's own list of ports, read from its database at login.
 *
 * <p>Sailing ships a table of docks — sixty-odd, with a name, a level and sometimes a quest.
 * Reading it live means the plugin gains new ports when the game does.
 *
 * <p>Two things are defensive on purpose. The location sits in one of the table's unnamed
 * columns, so every column is probed and the one decoding to a plausible world coordinate wins.
 * And a dock's authored position is a marker, not necessarily a tile anything can float on — the
 * Summer Shore's is one fully blocked tile — so each dock is snapped onto open water at load.
 */
@Slf4j
@Singleton
class SailingDocks
{
	/** How far to look for open water around a dock's authored position. */
	private static final int SNAP_RADIUS = 24;

	@Inject
	private Client client;

	@Inject
	private WorldMesh mesh;

	@Getter
	private final List<Dock> docks = new ArrayList<>();

	private boolean loaded;

	/** One port: where it is, and what it takes to be allowed there. */
	static final class Dock
	{
		@Getter
		private final int rowId;
		@Getter
		private final String name;
		@Getter
		private final int levelRequired;
		@Getter
		private final int questId;

		/** Water beside the dock, snapped onto the mesh where there was any to snap to. */
		@Getter
		private final WorldPoint mooring;

		/**
		 * True if this dock sits on the one connected ocean. Not every dock does: Wyrmscraig has a
		 * second inside its caves, whose water is its own body. The flag decides how a voyage is
		 * expressed — an open-sea dock gets a drawn route, a cave dock a timed passage.
		 */
		@Getter
		private final boolean onOpenSea;

		/**
		 * The quayside: the land a golem stands on to board, and arrives on to leave. The gangplank is
		 * spawned with a vessel rather than built into the map, so there is no fixed plank tile to
		 * walk to. Boarding requires the golem to be here; arriving does not.
		 */
		@Getter
		private final WorldPoint shore;

		/**
		 * The open water nearest the gangplank: where a raft sets out from and comes in to. Not the
		 * buoy, which can sit well out in the harbour. Sea routes still run from the mooring.
		 */
		@Getter
		private final WorldPoint berth;

		Dock(int rowId, String name, int levelRequired, int questId, WorldPoint mooring,
			boolean onOpenSea, WorldPoint shore)
		{
			this(rowId, name, levelRequired, questId, mooring, onOpenSea, shore, mooring);
		}

		Dock(int rowId, String name, int levelRequired, int questId, WorldPoint mooring,
			boolean onOpenSea, WorldPoint shore, WorldPoint berth)
		{
			this.rowId = rowId;
			this.name = name;
			this.levelRequired = levelRequired;
			this.questId = questId;
			this.mooring = mooring;
			this.onOpenSea = onOpenSea;
			this.shore = shore;
			this.berth = berth;
		}
	}

	/** Reads the dock table, once, on the client thread. Safe to call repeatedly. */
	void load()
	{
		if (loaded)
		{
			return;
		}

		loadBuoys();

		List<Integer> rows;
		try
		{
			rows = client.getDBTableRows(DBTableID.SailingDock.ID);
		}
		catch (RuntimeException e)
		{
			// Absent on a client older than Sailing; golems then simply stay on land.
			log.debug("Sailing dock table unavailable", e);
			return;
		}

		if (rows == null || rows.isEmpty())
		{
			return;
		}
		loaded = true;

		for (int row : rows)
		{
			// Ask for the row's config before reading any of its fields: a row's data is fetched on
			// demand, and a field of a row the client has not pulled comes back empty rather than
			// failing, which reads exactly like a table with no columns in it.
			try
			{
				client.getDBRowConfig(row);
			}
			catch (RuntimeException e)
			{
				log.debug("Dock row {} would not load", row, e);
			}

			WorldPoint authored = findCoordinate(row);
			if (authored == null)
			{
				continue;
			}
			// A dock with no ocean nearby is kept at its authored position rather than dropped:
			// dropping it silently lost Wyrmscraig's cave dock, a port that simply is not on the sea.
			WorldPoint ocean = snapToWater(authored);
			WorldPoint mooring = ocean != null ? ocean : authored;

			WorldPoint shore = quayside(integer(row, DBTableID.SailingDock.COL_DOCK_ID, -1), authored, ocean != null);
			// On the sea, the sea nearest the gangplank. In a cave, the cave's own water beside it.
			WorldPoint berth = ocean != null ? snapToWater(shore) : snapToInlandWater(shore);
			docks.add(new Dock(row,
				string(row, DBTableID.SailingDock.COL_NICE_NAME),
				integer(row, DBTableID.SailingDock.COL_LEVEL_REQUIRED, 1),
				integer(row, DBTableID.SailingDock.COL_QUEST_REQUIRED, -1),
				mooring, ocean != null, shore, berth != null ? berth : mooring));
		}

		// A quayside on an island the land fill never reached is land from now on, or a golem that
		// sails there has nowhere to step off.
		for (Dock dock : docks)
		{
			// Only docks on the sea: a cave dock stands on ground the fill knows, and admitting more
			// there admitted the cave's lake.
			if (!dock.isOnOpenSea())
			{
				continue;
			}
			WorldPoint shore = dock.getShore();
			mesh.admitDockFloor(shore.getX(), shore.getY(), shore.getPlane());
		}

		log.debug("Loaded {} sailing docks of {} rows; {} open to golems at Sailing level {}", docks.size(),
			rows.size(), openDocks().size(), client.getRealSkillLevel(Skill.SAILING));

		if (docks.isEmpty() && !rows.isEmpty())
		{
			// Every row rejected means the table's shape is not what this code expects, which is
			// worth saying loudly: silent no-sailing with a healthy row count takes an afternoon.
			dumpTable(rows);
		}
	}

	/**
	 * Dumps what the dock table actually contains, when nothing could be read from it. The location
	 * is in an unnamed column and found by inspection, so if the packing ever changes this turns
	 * "no golems sail" into a five-line answer.
	 */
	private void dumpTable(List<Integer> rows)
	{
		log.warn("No sailing dock resolved a location. Dumping the first rows of table {}:",
			DBTableID.SailingDock.ID);

		for (int i = 0; i < Math.min(3, rows.size()); i++)
		{
			int row = rows.get(i);
			StringBuilder sb = new StringBuilder("  row ").append(row).append(':');

			try
			{
				sb.append(" config=").append(client.getDBRowConfig(row));
			}
			catch (RuntimeException e)
			{
				sb.append(" config threw ").append(e);
			}

			for (int column = 0; column < 24; column++)
			{
				Object[] values;
				try
				{
					values = client.getDBTableField(row, column, 0);
				}
				catch (RuntimeException e)
				{
					sb.append("\n    [").append(column).append("] threw ").append(e);
					continue;
				}
				if (values == null)
				{
					sb.append("\n    [").append(column).append("] null");
					continue;
				}
				if (values.length == 0)
				{
					sb.append("\n    [").append(column).append("] empty");
					continue;
				}
				sb.append("\n    [").append(column).append("] ");
				for (Object value : values)
				{
					sb.append(value == null ? "null" : value.getClass().getSimpleName()
						+ "=" + value).append(' ');
				}
			}
			log.warn(sb.toString());
		}
	}

	/**
	 * True if a golem is allowed to sail to this dock: the player's real Sailing level and the dock's
	 * quest, both applied. Never a boost — a port that opened only while boosted would strand golems.
	 */
	boolean isOpen(Dock dock)
	{
		if (client.getRealSkillLevel(Skill.SAILING) < dock.getLevelRequired())
		{
			return false;
		}
		if (dock.getQuestId() <= 0)
		{
			return true;
		}
		Quest quest = QUESTS_BY_ID.get(dock.getQuestId());
		return quest == null || questFinished(quest);
	}

	/** How long a quest's state is trusted. Asking runs a client script, once per dock considered. */
	private static final long QUEST_RECHECK_MILLIS = 5 * 60 * 1000L;

	/** Quest id to {finished ? 1 : 0, when it was asked}. */
	private final java.util.Map<Integer, long[]> questStates = new java.util.HashMap<>();

	private boolean questFinished(Quest quest)
	{
		long now = System.currentTimeMillis();
		long[] known = questStates.get(quest.getId());
		if (known == null || now - known[1] >= QUEST_RECHECK_MILLIS)
		{
			known = new long[]{quest.getState(client) == QuestState.FINISHED ? 1 : 0, now};
			questStates.put(quest.getId(), known);
		}
		return known[0] == 1;
	}

	/** Forgets every quest state, for a login that may be another account. */
	void forgetQuests()
	{
		questStates.clear();
	}

	/** Quests by id. Quest.values() copies the whole list each call, once per dock considered. */
	private static final java.util.Map<Integer, Quest> QUESTS_BY_ID = new java.util.HashMap<>();

	static
	{
		for (Quest quest : Quest.values())
		{
			QUESTS_BY_ID.putIfAbsent(quest.getId(), quest);
		}
	}

	/** Every dock currently open to a golem. */
	List<Dock> openDocks()
	{
		List<Dock> out = new ArrayList<>();
		for (Dock dock : docks)
		{
			if (isOpen(dock))
			{
				out.add(dock);
			}
		}
		return out;
	}

	Dock byRow(int rowId)
	{
		for (Dock dock : docks)
		{
			if (dock.getRowId() == rowId)
			{
				return dock;
			}
		}
		return null;
	}

	// ---------------------------------------------------------------- reading

	/**
	 * Where a dock is, from the shipped table of docking buoys.
	 *
	 * <p>The dock table has no location in it — a dock's position is that of its <em>docking
	 * buoy</em>, a scene object with a {@code Dock} action, read offline from the cache. The
	 * link is {@link DBTableID.SailingDock#COL_DOCK_ID}, the index into that list in object-id
	 * order: Wyrmscraig's row reads dock id 59, the 60th buoy.
	 */
	private WorldPoint findCoordinate(int row)
	{
		int dockId = integer(row, DBTableID.SailingDock.COL_DOCK_ID, -1);
		if (dockId < 0 || dockId >= buoys.size())
		{
			return null;
		}
		return buoys.get(dockId);
	}

	/** Docking buoy positions, indexed by dock id. Read once from the jar. */
	private final List<WorldPoint> buoys = new ArrayList<>();

	/**
	 * Gangplank positions, indexed the same way; the buoy's own tile where none was found. The plank
	 * is where a person walks aboard, so it beats the nearest land to the buoy — across the water,
	 * or the wrong pier.
	 */
	private final List<WorldPoint> gangplanks = new ArrayList<>();

	/**
	 * Reads the shipped table: a count, then six shorts a dock — the buoy's tile then the
	 * gangplank's, each x, y and plane, in the order they were written. Reading
	 * {@code int, short, short, byte} put every dock at something like 0,3038 on plane 12.
	 */
	private void loadBuoys()
	{
		if (!buoys.isEmpty())
		{
			return;
		}

		try (java.io.InputStream raw = SailingDocks.class.getResourceAsStream(BUOYS))
		{
			if (raw == null)
			{
				log.warn("Docking buoy table missing from the jar; golems cannot sail");
				return;
			}
			try (java.util.zip.GZIPInputStream gz = new java.util.zip.GZIPInputStream(raw);
				 java.io.DataInputStream data = new java.io.DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int buoyX = data.readShort() & 0xFFFF;
					int buoyY = data.readShort() & 0xFFFF;
					int buoyPlane = data.readShort() & 0xFFFF;
					int plankX = data.readShort() & 0xFFFF;
					int plankY = data.readShort() & 0xFFFF;
					int plankPlane = data.readShort() & 0xFFFF;
					buoys.add(new WorldPoint(buoyX, buoyY, buoyPlane));
					gangplanks.add(new WorldPoint(plankX, plankY, plankPlane));
				}
				log.debug("Loaded {} docking buoys", buoys.size());
			}
		}
		catch (java.io.IOException | RuntimeException e)
		{
			log.warn("Docking buoy table unreadable", e);
			buoys.clear();
			gangplanks.clear();
		}
	}

	/**
	 * Where a golem boards this dock: the gangplank if the harvest found one and a golem can stand on
	 * it, else the nearest land to the buoy. A plank equal to its buoy means none was found in range.
	 */
	private WorldPoint quayside(int dockId, WorldPoint buoy)
	{
		return quayside(dockId, buoy, true);
	}

	/**
	 * @param onOpenSea false for a dock on water that is not the sea — Wyrmscraig's cave, where
	 *                  every open tile near the buoy is the lake, passable but not ocean, so it was
	 *                  chosen as the quayside, admitted as floor, and golems walked on the water.
	 */
	private WorldPoint quayside(int dockId, WorldPoint buoy, boolean onOpenSea)
	{
		WorldPoint plank = dockId < gangplanks.size() ? gangplanks.get(dockId) : null;
		if (plank != null && !plank.equals(buoy)
			&& mesh.isLandWalkable(plank.getX(), plank.getY(), plank.getPlane()))
		{
			return plank;
		}
		return snapToShore(buoy, onOpenSea);
	}

	private static final String BUOYS = "/docks.gz";

	/**
	 * The nearest land a golem could stand on, spiralling out from the buoy, which sits on water.
	 * Falls back to the buoy, leaving the port usable by sea where the mesh has nothing ashore.
	 */
	private WorldPoint snapToShore(WorldPoint at)
	{
		return snapToShore(at, true);
	}

	/** @param piers false to take only ground the land fill reached. See quayside. */
	private WorldPoint snapToShore(WorldPoint at, boolean piers)
	{
		for (int radius = 0; radius <= SNAP_RADIUS; radius++)
		{
			WorldPoint pier = null;
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (radius > 0 && Math.abs(dx) != radius && Math.abs(dy) != radius)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (mesh.isLandWalkable(x, y, at.getPlane())
						&& !mesh.isIsolated(x, y, at.getPlane()))
					{
						return new WorldPoint(x, y, at.getPlane());
					}
					// Ground the land fill never reached is still ground: most of Sailing's
					// islands are like that. Taken only if nothing the fill knows is as close.
					if (piers && pier == null && mesh.isWalkable(x, y, at.getPlane())
						&& !mesh.isOcean(x, y, at.getPlane()) && mesh.componentAt(x, y, at.getPlane()) != 0)
					{
						pier = new WorldPoint(x, y, at.getPlane());
					}
				}
			}
			if (pier != null)
			{
				return pier;
			}
		}
		return at;
	}

	/**
	 * The nearest water that is not the sea: open in the map, not land the fill reached, part of some
	 * connected space. Around the cave dock that is its lake.
	 */
	private WorldPoint snapToInlandWater(WorldPoint at)
	{
		for (int radius = 1; radius <= SNAP_RADIUS; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (Math.abs(dx) != radius && Math.abs(dy) != radius)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (mesh.isWalkable(x, y, at.getPlane()) && !mesh.isOcean(x, y, at.getPlane())
						&& !mesh.isLandWalkable(x, y, at.getPlane()) && mesh.componentAt(x, y, at.getPlane()) != 0)
					{
						return new WorldPoint(x, y, at.getPlane());
					}
				}
			}
		}
		return null;
	}

	/** The nearest tile of the connected ocean, spiralling outward. */
	private WorldPoint snapToWater(WorldPoint at)
	{
		if (mesh.isOcean(at.getX(), at.getY(), at.getPlane()))
		{
			return at;
		}
		for (int radius = 1; radius <= SNAP_RADIUS; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (Math.abs(dx) != radius && Math.abs(dy) != radius)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (mesh.isOcean(x, y, 0))
					{
						return new WorldPoint(x, y, 0);
					}
				}
			}
		}
		return null;
	}

	private String string(int row, int column)
	{
		try
		{
			Object[] values = client.getDBTableField(row, column, 0);
			return values != null && values.length > 0 && values[0] != null
				? String.valueOf(values[0]) : "";
		}
		catch (RuntimeException e)
		{
			return "";
		}
	}

	private int integer(int row, int column, int fallback)
	{
		try
		{
			Object[] values = client.getDBTableField(row, column, 0);
			return values != null && values.length > 0 && values[0] instanceof Integer
				? (Integer) values[0] : fallback;
		}
		catch (RuntimeException e)
		{
			return fallback;
		}
	}
}

package com.golemsdontdie;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

/**
 * Builds the boat drawn under a golem at sea, once: Sailing's raft, assembled from its hull, sail
 * and helm models. See {@link GolemContent#RAFT_HULL_MODEL}.
 */
@Slf4j
@Singleton
class RaftFactory
{
	/** The client's own lighting for an actor, matching {@link GolemModelFactory}. */
	private static final int BASE_AMBIENT = 64;
	private static final int BASE_CONTRAST = 850;
	private static final int LIGHT_X = -30;
	private static final int LIGHT_Y = -50;
	private static final int LIGHT_Z = -30;

	@Inject
	private Client client;

	private Model model;
	private boolean searched;

	/**
	 * The boat model, or null if it could not be built.
	 *
	 * <p>Built once and shared by every golem at sea; safe because the client's transformation
	 * clones vertices rather than writing to its source. Client thread only.
	 */
	Model raftModel()
	{
		if (searched)
		{
			return model;
		}
		searched = true;

		try
		{
			ModelData hull = client.loadModelData(GolemContent.RAFT_HULL_MODEL);
			ModelData mast = client.loadModelData(GolemContent.RAFT_SAIL_MODEL);
			ModelData cloth = client.loadModelData(GolemContent.RAFT_SAIL_CLOTH_MODEL);
			ModelData helm = client.loadModelData(GolemContent.RAFT_HELM_MODEL);
			if (hull == null || mast == null || cloth == null || helm == null)
			{
				log.debug("Raft models not loaded yet");
				searched = false;
				return null;
			}
			// Painted as the objects paint them; the raw models are place-holder purple.
			hull = recolour(hull.cloneVertices().cloneColors(), GolemContent.RAFT_HULL_RECOLOUR_FROM,
				GolemContent.RAFT_HULL_RECOLOUR_TO);
			helm = recolour(helm.cloneVertices().cloneColors(), GolemContent.RAFT_HELM_RECOLOUR_FROM,
				GolemContent.RAFT_HELM_RECOLOUR_TO);
			// Hull, mast and sail sit on the middle tile; the helm is its own tile at the stern.
			helm = helm.translate(0, 0, GolemContent.RAFT_HELM_OFFSET);
			ModelData merged = client.mergeModels(hull, mast.cloneVertices(), cloth.cloneVertices(), helm);
			model = merged.light(BASE_AMBIENT, BASE_CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
			log.debug("Raft model built from hull, sail and helm");
			return model;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not build the boat model", e);
			return null;
		}
	}

	private static ModelData recolour(ModelData model, short[] from, short[] to)
	{
		for (int i = 0; i < from.length; i++)
		{
			model.recolor(from[i], to[i]);
		}
		return model;
	}

	void clear()
	{
		model = null;
		searched = false;
	}
}

package com.golemsdontdie;

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Constants;

/**
 * Where a golem may walk, anywhere in the world. Read-only, shipped, never written to.
 *
 * <p>The island map this replaces covered nine regions and fitted in a config value; this
 * covers 1,158, the ocean plus every bit of land reachable from Lumbridge, and at 440 KB
 * belongs in the jar.
 *
 * <p>Three bits per tile rather than two. <b>north</b> and <b>east</b> use the packing
 * Shortest Path and {@code IslandMemory} use; south and west are the neighbouring tile's.
 * <b>ocean</b> is the single connected sea: two ports are only sailable between if both sit
 * on it, and enclosed water exists — Karamja's inland body is 26,000 tiles leading nowhere.
 * <b>isolated</b> marks components under 50 tiles, computed offline rather than by a flood
 * fill the client cannot afford.
 *
 * @see IslandMemory the live harvest, which takes precedence over this everywhere
 */
@Slf4j
@Singleton
class WorldMesh
{
	private static final String RESOURCE = "/world-mesh.gz";

	private static final int REGION_SIZE = Constants.REGION_SIZE;
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int TILES_PER_PLANE = REGION_SIZE * REGION_SIZE;

	/** Two bits per tile for passability, one each for the two derived maps. */
	private static final int COLLISION_BYTES = TILES_PER_PLANE * 2 / 8;
	private static final int DERIVED_BYTES = TILES_PER_PLANE / 8;

	/** Two bytes a tile: there are 14,288 components, which does not fit in one. */
	private static final int COMPONENT_BYTES = TILES_PER_PLANE * 2;

	/** Impossible as an entry count, so an old file is refused rather than misread. */
	private static final int MAGIC = -0x60137;

	/** 2 added the per-tile component map. */
	private static final int VERSION = 2;

	static final int FLAG_NORTH = 0;
	static final int FLAG_EAST = 1;

	/**
	 * Everything the mesh holds for one region and plane. One object rather than five maps
	 * keyed alike: a walkability check touches several, planning asks millions of times,
	 * and the boxed lookups were most of the cost.
	 */
	private static final class Region
	{
		/** Two bits per tile for passability. */
		final byte[] collision;

		/** The single connected sea. */
		final byte[] ocean;

		/** Components too small to wander. */
		final byte[] isolated;

		/**
		 * Which connected component each tile belongs to, two bytes per tile, 0 for none.
		 * The one thing no per-tile flag can say: whether two tiles are connected <b>to each
		 * other</b>. Everything else answers "may a golem stand there", and a sealed room is
		 * good ground. {@code isolated} only caught components under fifty tiles.
		 */
		final byte[] components;

		/**
		 * Tiles the land fill reached — ground a golem may stand on, on foot. The ocean bit
		 * marks only the one connected sea, so cave water, lakes and enclosed basins read as
		 * passable and golems walked out across them. Shoreline edges are blocked, so a fill
		 * starting on land cannot leak.
		 */
		final byte[] land;

		Region(byte[] collision, byte[] ocean, byte[] isolated, byte[] components, byte[] land)
		{
			this.collision = collision;
			this.ocean = ocean;
			this.isolated = isolated;
			this.components = components;
			this.land = land;
		}
	}

	/** Region and plane to what the mesh holds for it. */
	private final Map<Long, Region> regions = new HashMap<>();

	/**
	 * The same regions by region id and plane for planes 0 to 3, so the common case is an
	 * array read with no key boxed. Anything else goes through {@link #regions}.
	 */
	private final Region[] byRegion = new Region[FAST_REGIONS << 2];

	private static final int FAST_REGIONS = 1 << 16;

	private boolean loaded;

	/**
	 * Reads the bundled mesh. A missing or corrupt resource leaves every query answering
	 * "unknown", which is survivable: the live harvest still works, so golems roam what the
	 * player has walked.
	 */
	void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;

		try (InputStream raw = WorldMesh.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.warn("Bundled world mesh missing from the jar");
				return;
			}

			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				// A negative first field is the version marker. An entry count cannot be
				// negative, so a file without one is the old format and is refused rather
				// than read as though its component map were region ids.
				int first = data.readInt();
				if (first != MAGIC)
				{
					log.warn("World mesh is an old format; it needs rebuilding");
					return;
				}
				int version = data.readInt();
				if (version != VERSION)
				{
					log.warn("World mesh is version {}, expected {}", version, VERSION);
					return;
				}

				int entries = data.readInt();
				for (int i = 0; i < entries; i++)
				{
					int regionId = data.readInt();
					int plane = data.readByte();
					long key = key(regionId, plane);

					byte[] flags = new byte[COLLISION_BYTES];
					data.readFully(flags);

					byte[] sea = new byte[DERIVED_BYTES];
					data.readFully(sea);

					byte[] alone = new byte[DERIVED_BYTES];
					data.readFully(alone);

					byte[] parts = new byte[COMPONENT_BYTES];
					data.readFully(parts);

					byte[] ground = new byte[DERIVED_BYTES];
					data.readFully(ground);

					Region region = new Region(flags, sea, alone, parts, ground);
					regions.put(key, region);
					if (regionId >= 0 && regionId < FAST_REGIONS && (plane & 0xF) < 4)
					{
						byRegion[regionId << 2 | (plane & 0xF)] = region;
					}
				}
				log.debug("Loaded world mesh: {} region-planes", entries);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled world mesh unreadable", e);
			regions.clear();
			java.util.Arrays.fill(byRegion, null);
		}
	}

	/** True if the mesh has anything at all to say about this region and plane. */
	boolean covers(int regionId, int plane)
	{
		return region(regionId, plane) != null;
	}

	boolean north(int x, int y, int plane)
	{
		return flag(x, y, plane, FLAG_NORTH);
	}

	boolean east(int x, int y, int plane)
	{
		return flag(x, y, plane, FLAG_EAST);
	}

	/** True if this tile is part of the single connected sea. */
	boolean isOcean(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		return region != null && bit(region.ocean, x, y);
	}

	/**
	 * True if this tile sits in a component too small to wander — the question stuck
	 * detection asks, as a bit lookup. A golem restored onto one is relocated rather than
	 * left walking into the same four walls forever.
	 */
	boolean isIsolated(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		return region != null && bit(region.isolated, x, y);
	}

	/**
	 * Which connected space this tile belongs to, or 0 if the mesh does not know. Zero means
	 * "no answer", not "no component": refusing a tile outside the shipped regions would
	 * shrink the world to the shipped file.
	 */
	int componentAt(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		if (region == null)
		{
			return 0;
		}
		byte[] parts = region.components;
		int tile = (y & REGION_MASK) * REGION_SIZE + (x & REGION_MASK);
		return ((parts[tile * 2] & 0xff) << 8) | (parts[tile * 2 + 1] & 0xff);
	}

	/**
	 * True if a golem standing at the first tile could walk to the second. Unknown counts as
	 * yes: the live harvest covers ground the mesh never will, so a silent answer must not
	 * be read as a refusal.
	 */
	boolean sameComponent(int fromX, int fromY, int toX, int toY, int plane)
	{
		int from = componentAt(fromX, fromY, plane);
		int to = componentAt(toX, toY, plane);
		return from == 0 || to == 0 || from == to;
	}

	/**
	 * True if this tile is water a boat sails but nobody walks, and is not the sea:
	 * Wyrmscraig's underground lake, which has no bit of its own. It is passable because
	 * boats cross it and the client does not block it, so the golems' map read it as ground
	 * and golems walked on the water. Known by its connected component, bounds-checked
	 * first so the rest of the world pays one comparison.
	 */
	boolean isInlandWater(int x, int y, int plane)
	{
		if (plane != 0)
		{
			return false;
		}
		if (lakeComponent < 0)
		{
			findLake();
		}
		return lakeComponent != 0 && x >= lakeMinX && x <= lakeMaxX && y >= lakeMinY && y <= lakeMaxY
			&& componentAt(x, y, 0) == lakeComponent;
	}

	/** The underground lake's component and bounds; -1 until looked for, 0 if the mesh has none. */
	private int lakeComponent = -1;
	private int lakeMinX;
	private int lakeMaxX;
	private int lakeMinY;
	private int lakeMaxY;

	/** How far from its mouth the lake is looked for, in tiles. It is a few dozen across. */
	private static final int LAKE_SEARCH = 96;

	private synchronized void findLake()
	{
		if (lakeComponent >= 0)
		{
			return;
		}
		int lake = componentAt(GolemContent.CAVE_LAKE_MOUTH_X, GolemContent.CAVE_LAKE_MOUTH_Y, 0);
		int minX = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxY = Integer.MIN_VALUE;
		if (lake != 0)
		{
			for (int x = GolemContent.CAVE_LAKE_MOUTH_X - LAKE_SEARCH; x <= GolemContent.CAVE_LAKE_MOUTH_X + LAKE_SEARCH; x++)
			{
				for (int y = GolemContent.CAVE_LAKE_MOUTH_Y - LAKE_SEARCH; y <= GolemContent.CAVE_LAKE_MOUTH_Y + LAKE_SEARCH; y++)
				{
					if (componentAt(x, y, 0) == lake)
					{
						minX = Math.min(minX, x);
						maxX = Math.max(maxX, x);
						minY = Math.min(minY, y);
						maxY = Math.max(maxY, y);
					}
				}
			}
		}
		lakeMinX = minX;
		lakeMaxX = maxX;
		lakeMinY = minY;
		lakeMaxY = maxY;
		lakeComponent = lake;
	}

	/** True if something could stand here — the tile can be left in some direction. */
	boolean isWalkable(int x, int y, int plane)
	{
		return north(x, y, plane) || east(x, y, plane)
			|| north(x, y - 1, plane) || east(x - 1, y, plane);
	}

	/**
	 * True if a golem could stand here <em>on foot</em>. Leaving this distinction out put
	 * golems on the open sea: water is <b>passable</b> in the source collision map, which is
	 * why sea navigation works, so the passability bits alone cannot tell walkable ground
	 * from crossable water. Only {@link SeaMesh}, routing a boat, may treat the sea as
	 * passable.
	 */
	boolean isLandWalkable(int x, int y, int plane)
	{
		if (isInlandWater(x, y, plane))
		{
			return false;
		}
		Region region = region(regionIdOf(x, y), plane);
		if (region == null)
		{
			// Nothing known here: no land bit and no component that could have been admitted.
			return false;
		}
		if (!bit(region.land, x, y))
		{
			// Only worth reading the component when some floor has been admitted at all.
			if (admittedFloors == 0)
			{
				return false;
			}
			int component = componentOf(region, x, y);
			if (!landComponents[component] && !dockFloors[component])
			{
				return false;
			}
		}
		return isWalkable(x, y, plane);
	}

	/**
	 * Floors counted as land because a dock stands on them. Kept apart from the transport
	 * floors, which are replaced whenever a route is learned. Sailing added islands no
	 * transport table has a row on: twenty-two of the sixty-one docks had no land beside
	 * them, so a golem sailing there could not step off.
	 */
	private final boolean[] dockFloors = new boolean[1 << 16];

	/** How many floors either kind of admission holds, so a check can skip reading the component. */
	private int admittedFloors;

	/** How many of them came from transports, for the log. */
	private int transportFloors;

	/** Admits the floor under a dock's quayside, if it is a floor at all. */
	void admitDockFloor(int x, int y, int plane)
	{
		if (x >= 6400 || isOcean(x, y, plane))
		{
			return;
		}
		int component = componentAt(x, y, plane);
		if (component != 0 && !dockFloors[component])
		{
			dockFloors[component] = true;
			admittedFloors += landComponents[component] ? 0 : 1;
		}
	}

	/**
	 * Floors counted as land because a transport starts or ends on them, beyond what the
	 * shipped land fill reached.
	 *
	 * <p>The fill was run offline from Lumbridge over the tables it was given, so a floor
	 * reachable only by a ladder no table lists has collision, a component and every wall
	 * but no land bit — Wyrmscraig's ladder tops, the cathedral basement, every place newer
	 * than the tables. A transport row is the same evidence the fill used. The exact end
	 * tile only: a stepping stone's tile is blocked, and snapping to the water beside it
	 * would admit a river as land.
	 */
	private final boolean[] landComponents = new boolean[1 << 16];

	/** Admits the floor under both ends of every transport. Replaces what was admitted before. */
	void admitTransportEnds(java.util.List<GolemTransport> transports)
	{
		java.util.Arrays.fill(landComponents, false);
		transportFloors = 0;
		admittedFloors = 0;
		for (boolean dock : dockFloors)
		{
			admittedFloors += dock ? 1 : 0;
		}
		for (GolemTransport t : transports)
		{
			admit(t.getFromX(), t.getFromY(), t.getFromPlane());
			admit(t.getToX(), t.getToY(), t.getToPlane());
		}
		log.debug("{} floors admitted as land from transport ends", transportFloors);
	}

	private void admit(int x, int y, int plane)
	{
		// Instances are rebuilt each visit; their coordinates name no lasting floor.
		if (x >= 6400 || isLand(x, y, plane) || isOcean(x, y, plane))
		{
			return;
		}
		int component = componentAt(x, y, plane);
		if (component != 0 && !landComponents[component])
		{
			landComponents[component] = true;
			transportFloors++;
			admittedFloors += dockFloors[component] ? 0 : 1;
		}
	}

	private boolean flag(int x, int y, int plane, int which)
	{
		Region region = region(regionIdOf(x, y), plane);
		if (region == null)
		{
			return false;
		}
		byte[] bits = region.collision;
		int bit = ((y & REGION_MASK) * REGION_SIZE + (x & REGION_MASK)) * 2 + which;
		return (bits[bit >> 3] >>> (bit & 7) & 1) != 0;
	}

	/** The land fill's bit for this tile. */
	private boolean isLand(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		return region != null && bit(region.land, x, y);
	}

	private Region region(int regionId, int plane)
	{
		if (regionId >= 0 && regionId < FAST_REGIONS && (plane & 0xF) < 4)
		{
			return byRegion[regionId << 2 | (plane & 0xF)];
		}
		return regions.get(key(regionId, plane));
	}

	private static boolean bit(byte[] bits, int x, int y)
	{
		int bit = (y & REGION_MASK) * REGION_SIZE + (x & REGION_MASK);
		return (bits[bit >> 3] >>> (bit & 7) & 1) != 0;
	}

	private static int componentOf(Region region, int x, int y)
	{
		int tile = (y & REGION_MASK) * REGION_SIZE + (x & REGION_MASK);
		return ((region.components[tile * 2] & 0xff) << 8) | (region.components[tile * 2 + 1] & 0xff);
	}

	private static int regionIdOf(int x, int y)
	{
		return ((x >> 6) << 8) | (y >> 6);
	}

	private static long key(int regionId, int plane)
	{
		return ((long) regionId << 4) | (plane & 0xF);
	}
}

package com.golemsdontdie;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Routes a raft across the ocean.
 *
 * <p>The collision map already marks open water as passable and shoreline edges as blocked,
 * which is why Wyrmscraig reads as a sealed 2,456-tile island <em>and</em> why 2,458,003 tiles
 * of connected sea sit in the same resource: golems path the ocean with the same flags and corner
 * rule they use in a corridor. Three differences, all because an ocean is enormous: A*, since
 * three thousand nodes does not cross one; an inflated heuristic, which expands far fewer nodes
 * and gives straighter routes; and straightening afterwards, sailing moving in long runs.
 */
@Slf4j
@Singleton
class SeaMesh
{
	/** Ceiling on tiles expanded for one crossing. Large: a crossing is planned once per pair. */
	private static final int NODE_BUDGET = 200_000;

	/** Heuristic inflation. Above 1 it is fast and straight, not optimal; a weaving boat reads badly. */
	private static final float HEURISTIC_WEIGHT = 1.4f;

	private static final int[] DX = {0, 0, 1, -1, 1, -1, 1, -1};
	private static final int[] DY = {1, -1, 0, 0, 1, 1, -1, -1};

	@Inject
	private WorldMesh mesh;

	/**
	 * True if two points sit on the same body of water. Always ask before pathing: the inland body
	 * on Karamja is 26,000 tiles connecting to nothing, and a search between basins burns the budget.
	 */
	boolean sameWater(WorldPoint a, WorldPoint b)
	{
		return mesh.isOcean(a.getX(), a.getY(), 0) && mesh.isOcean(b.getX(), b.getY(), 0);
	}

	/**
	 * Routes already computed, keyed by the pair of endpoints.
	 *
	 * <p>What makes the search affordable at all: there are only sixty-odd ports, so a real session
	 * sees a handful of crossings. Failures are cached too, as an empty list.
	 */
	private final Map<Long, List<int[]>> routes = new HashMap<>();

	/**
	 * A cached route, or null if this pair has not been searched yet. Separate from {@link #route}
	 * so the caller can take the cheap answer on a render frame and defer the expensive one.
	 */
	/**
	 * Crossings between every pair of moorings, computed offline and shipped. The live search could
	 * not be
	 * relied on: sampling forty pairs of ports it found no route for twenty-one — the ocean being
	 * one body of water, every one was the budget running out, at a quarter to two fifths of a
	 * second each on the client thread. It remains for a pair the table does not have.
	 */
	private static final String SHIPPED = "/sea-routes.gz";

	private boolean shippedLoaded;

	private void loadShipped()
	{
		if (shippedLoaded)
		{
			return;
		}
		shippedLoaded = true;
		try (java.io.InputStream raw = SeaMesh.class.getResourceAsStream(SHIPPED))
		{
			if (raw == null)
			{
				log.warn("Shipped sea routes missing from the jar; crossings will be searched live");
				return;
			}
			try (java.util.zip.GZIPInputStream gz = new java.util.zip.GZIPInputStream(raw);
				 java.io.DataInputStream data = new java.io.DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int legs = data.readShort() & 0xFFFF;
					List<int[]> route = new ArrayList<>(legs);
					for (int j = 0; j < legs; j++)
					{
						route.add(new int[]{data.readShort() & 0xFFFF, data.readShort() & 0xFFFF});
					}
					int[] first = route.get(0);
					int[] last = route.get(route.size() - 1);
					routes.put(key(first[0], first[1], last[0], last[1]), route);
					List<int[]> back = new ArrayList<>(route);
					Collections.reverse(back);
					routes.put(key(last[0], last[1], first[0], first[1]), back);
				}
				log.debug("Loaded {} shipped sea routes", count);
			}
		}
		catch (java.io.IOException | RuntimeException e)
		{
			log.warn("Shipped sea routes unreadable; crossings will be searched live", e);
		}
	}

	List<int[]> cachedRoute(WorldPoint from, WorldPoint to)
	{
		loadShipped();
		List<int[]> cached = routes.get(key(from, to));
		return cached == null || cached.isEmpty() ? null : cached;
	}

	/** True if this pair has already been searched, successfully or not. */
	boolean isSearched(WorldPoint from, WorldPoint to)
	{
		loadShipped();
		return routes.containsKey(key(from, to));
	}

	/**
	 * A route between two moorings, as straightened legs. Cached, so this is expensive exactly once
	 * per pair of ports; every call after the first is a map lookup.
	 *
	 * @return waypoints including both ends, or null
	 */
	List<int[]> route(WorldPoint from, WorldPoint to)
	{
		loadShipped();
		long key = key(from, to);
		List<int[]> cached = routes.get(key);
		if (cached != null)
		{
			return cached.isEmpty() ? null : cached;
		}

		if (!sameWater(from, to))
		{
			routes.put(key, Collections.emptyList());
			return null;
		}

		Map<Long, Long> cameFrom = new HashMap<>();
		Map<Long, Integer> best = new HashMap<>();
		PriorityQueue<long[]> open = new PriorityQueue<>((p, q) -> Integer.compare(
			(int) p[1], (int) q[1]));

		long start = pack(from.getX(), from.getY());
		long goal = pack(to.getX(), to.getY());
		best.put(start, 0);
		open.add(new long[]{start, heuristic(from.getX(), from.getY(), to.getX(), to.getY())});

		int expanded = 0;
		boolean found = false;

		while (!open.isEmpty() && expanded < NODE_BUDGET)
		{
			long[] current = open.poll();
			long at = current[0];
			if (at == goal)
			{
				found = true;
				break;
			}
			expanded++;

			int cx = unpackX(at);
			int cy = unpackY(at);
			int cost = best.getOrDefault(at, Integer.MAX_VALUE);

			for (int d = 0; d < 8; d++)
			{
				int nx = cx + DX[d];
				int ny = cy + DY[d];
				if (!mesh.isOcean(nx, ny, 0) || !canStep(cx, cy, DX[d], DY[d]))
				{
					continue;
				}

				long next = pack(nx, ny);
				int tentative = cost + 1;
				if (tentative >= best.getOrDefault(next, Integer.MAX_VALUE))
				{
					continue;
				}
				best.put(next, tentative);
				cameFrom.put(next, at);
				open.add(new long[]{next,
					tentative + heuristic(nx, ny, to.getX(), to.getY())});
			}
		}

		if (!found)
		{
			log.debug("No sea route from {} to {} after {} nodes", from, to, expanded);
			routes.put(key, Collections.emptyList());
			return null;
		}

		List<int[]> path = new ArrayList<>();
		for (long at = goal; at != start; at = cameFrom.get(at))
		{
			path.add(0, new int[]{unpackX(at), unpackY(at)});
		}
		path.add(0, new int[]{from.getX(), from.getY()});

		List<int[]> straightened = straighten(path);
		routes.put(key, straightened);
		return straightened;
	}

	/**
	 * Collapses runs of tiles into legs. The tile path is only interesting where it turns; keeping
	 * every tile would mean the same motion at many times the storage.
	 */
	private static List<int[]> straighten(List<int[]> path)
	{
		if (path.size() < 3)
		{
			return path;
		}
		List<int[]> out = new ArrayList<>();
		out.add(path.get(0));

		int dx = Integer.signum(path.get(1)[0] - path.get(0)[0]);
		int dy = Integer.signum(path.get(1)[1] - path.get(0)[1]);

		for (int i = 1; i < path.size(); i++)
		{
			int ndx = Integer.signum(path.get(i)[0] - path.get(i - 1)[0]);
			int ndy = Integer.signum(path.get(i)[1] - path.get(i - 1)[1]);
			if (ndx != dx || ndy != dy)
			{
				out.add(path.get(i - 1));
				dx = ndx;
				dy = ndy;
			}
		}
		out.add(path.get(path.size() - 1));
		return out;
	}

	/** Octile distance, weighted. Admissible before the weight, deliberately not after. */
	private static int heuristic(int x, int y, int goalX, int goalY)
	{
		int dx = Math.abs(x - goalX);
		int dy = Math.abs(y - goalY);
		return (int) (Math.max(dx, dy) * HEURISTIC_WEIGHT);
	}

	/** True if every tile a straight line between two points passes over, sampled four times a tile, is open sea. */
	boolean clearLine(int fromX, int fromY, int toX, int toY)
	{
		int dx = toX - fromX;
		int dy = toY - fromY;
		int samples = Math.max(1, Math.max(Math.abs(dx), Math.abs(dy)) * 4);
		for (int s = 0; s <= samples; s++)
		{
			int x = (int) Math.floor(fromX + 0.5 + dx * (double) s / samples);
			int y = (int) Math.floor(fromY + 0.5 + dy * (double) s / samples);
			if (!mesh.isOcean(x, y, 0))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Distance to a destination by sea, for every tile of open water near a route to it. Travel
	 * distance, not straight-line: filled outward from the destination round every headland, so from
	 * any tile some neighbour is one step nearer. Only within {@code band} tiles of the route.
	 */
	/** Which tiles a raft may sail on: the ocean, or one enclosed body of water. */
	interface Water
	{
		boolean at(int x, int y);
	}

	/** The one connected sea. */
	final Water ocean = (x, y) -> mesh.isOcean(x, y, 0);

	/** Water that is not the sea, by component: a cave lake, passable and marked as nothing else. */
	Water lake(int component)
	{
		return (x, y) -> component != 0 && mesh.componentAt(x, y, 0) == component;
	}

	/** Which connected component a surface tile belongs to, 0 for none. */
	int componentAt(int x, int y)
	{
		return mesh.componentAt(x, y, 0);
	}

	static final class Field
	{
		private final TileMap distance;
		private final SeaMesh sea;
		private final Water water;

		private Field(TileMap distance, SeaMesh sea, Water water)
		{
			this.distance = distance;
			this.sea = sea;
			this.water = water;
		}

		/** True if a raft sailing this field may be on this tile. */
		boolean isWater(int x, int y)
		{
			return water.at(x, y);
		}

		/** Steps to the destination from this tile, or -1 if it is not in the field. */
		int distance(int x, int y)
		{
			return (int) distance.getOrDefault(pack(x, y), -1);
		}

		/** A neighbour one step nearer the destination, or null at the destination itself. */
		int[] downhill(int x, int y)
		{
			int here = distance(x, y);
			for (int d = 0; d < 8; d++)
			{
				int nx = x + DX[d];
				int ny = y + DY[d];
				int there = distance(nx, ny);
				if (there >= 0 && there < here && canStep(water, x, y, DX[d], DY[d]))
				{
					return new int[]{nx, ny};
				}
			}
			return null;
		}

		int size()
		{
			return distance.size();
		}
	}

	/** True if this tile of the surface is open sea. */
	boolean isWater(int x, int y)
	{
		return mesh.isOcean(x, y, 0);
	}

	/** The distance field to the last point of a route, over open water within {@code band} tiles of the route. */
	Field fieldAlong(List<int[]> route, int band)
	{
		return fieldAlong(route, band, 0, 0);
	}

	/**
	 * As {@link #fieldAlong(List, int)}, over water with room around it. A raft is three tiles long
	 * and a tile wide, and a course plotted for the golem at its helm ran it through gaps its bow
	 * could not fit; {@code openNearEnds} tiles of either end are exempt, for coming in to a dock.
	 */
	Field fieldAlong(List<int[]> route, int band, int clearance, int openNearEnds)
	{
		return fieldAlong(route, band, clearance, openNearEnds, ocean);
	}

	/** As {@link #fieldAlong(List, int, int, int)}, over a given body of water. */
	Field fieldAlong(List<int[]> route, int band, int clearance, int openNearEnds, Water water)
	{
		int[] start = route.get(0);
		int[] goal = route.get(route.size() - 1);
		// Breadth first, and every tile is queued exactly when its distance is recorded, so the
		// record's own order is the queue.
		TileMap distance = new TileMap(1 << 14);
		distance.add(pack(goal[0], goal[1]), 0);
		// Water refused for itself: too far from the route, or too near a shore. Both are questions
		// about the tile alone, and each of its neighbours offers it again, so the answer is kept.
		TileMap tooFar = new TileMap(1 << 12);
		int head = 0;
		while (head < distance.size())
		{
			long at = distance.keyAt(head++);
			int x = (int) (at >> 32);
			int y = (int) at;
			long steps = distance.get(at);
			for (int d = 0; d < 8; d++)
			{
				int nx = x + DX[d];
				int ny = y + DY[d];
				long key = pack(nx, ny);
				if (distance.containsKey(key) || !water.at(nx, ny) || !canStep(water, x, y, DX[d], DY[d])
					|| tooFar.containsKey(key))
				{
					continue;
				}
				if (!near(route, nx, ny, band) || !roomy(water, nx, ny, clearance, start, goal, openNearEnds))
				{
					tooFar.add(key, 0);
					continue;
				}
				distance.add(key, steps + 1);
			}
		}
		return new Field(distance, this, water);
	}

	/** True if a tile has open sea for {@code clearance} tiles all round, or is near enough an end not to need it. */
	private static boolean roomy(Water water, int x, int y, int clearance, int[] start, int[] goal, int openNearEnds)
	{
		if (clearance <= 0
			|| Math.max(Math.abs(x - start[0]), Math.abs(y - start[1])) <= openNearEnds
			|| Math.max(Math.abs(x - goal[0]), Math.abs(y - goal[1])) <= openNearEnds)
		{
			return true;
		}
		for (int dx = -clearance; dx <= clearance; dx++)
		{
			for (int dy = -clearance; dy <= clearance; dy++)
			{
				if (!water.at(x + dx, y + dy))
				{
					return false;
				}
			}
		}
		return true;
	}

	/** True if a tile is within {@code band} tiles of any leg of a route. */
	private static boolean near(List<int[]> route, int x, int y, int band)
	{
		for (int i = 0; i + 1 < route.size(); i++)
		{
			int[] a = route.get(i);
			int[] b = route.get(i + 1);
			double dx = b[0] - a[0];
			double dy = b[1] - a[1];
			double lengthSquared = dx * dx + dy * dy;
			double t = lengthSquared == 0 ? 0 : Math.max(0, Math.min(1, ((x - a[0]) * dx + (y - a[1]) * dy) / lengthSquared));
			if (Math.hypot(x - (a[0] + dx * t), y - (a[1] + dy * t)) <= band)
			{
				return true;
			}
		}
		return route.size() == 1 && Math.max(Math.abs(x - route.get(0)[0]), Math.abs(y - route.get(0)[1])) <= band;
	}

	/** The game's corner rule, restricted to water. */
	boolean canStep(int x, int y, int dx, int dy)
	{
		return canStep(ocean, x, y, dx, dy);
	}

	static boolean canStep(Water water, int x, int y, int dx, int dy)
	{
		if (dx == 0 || dy == 0)
		{
			return true;
		}
		// A diagonal needs both ways round to be water, or the raft would cut a headland.
		return water.at(x + dx, y) && water.at(x, y + dy);
	}

	/** Endpoint pair key. Direction matters: a route is reversed, not reused. */
	private static long key(WorldPoint from, WorldPoint to)
	{
		return key(from.getX(), from.getY(), to.getX(), to.getY());
	}

	private static long key(int fromX, int fromY, int toX, int toY)
	{
		return ((long) fromX << 45) ^ ((long) fromY << 30) ^ ((long) toX << 15) ^ toY;
	}

	private static long pack(int x, int y)
	{
		return ((long) x << 32) | (y & 0xFFFFFFFFL);
	}

	private static int unpackX(long packed)
	{
		return (int) (packed >> 32);
	}

	private static int unpackY(long packed)
	{
		return (int) packed;
	}
}

package com.golemsdontdie;

import lombok.Getter;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;

/**
 * A one-shot animated object played beside a golem that is using something.
 *
 * <p>Some transport animations belong to the scenery, not the person: {@code DOCK_GANGPLANK01}
 * is on framemap 2503 and the fairy ring's spin is the ring's own, so neither can play on the
 * golem's human rig. A copy of the object can, which is what this is.
 *
 * <p>Fire-and-forget and never reused; keeping props alive would mean tracking scenery state
 * across a scene reload for under a second of animation. The real object is untouched; the
 * copy is drawn over it, visible only to this player.
 */
class FakeProp extends RuneLiteObjectController
{
	private final Client client;
	private final Model model;
	private final AnimationController animation;

	/** World position in 128ths of a tile, as for golems. */
	private final int fineX;
	private final int fineY;
	private final int plane;
	private final int height;

	/** Cycles left before the prop is dropped. */
	private int remaining;

	@Getter
	private final int animationId;

	FakeProp(Client client, Model model, Animation clip, int animationId,
		int fineX, int fineY, int plane, int height, int cycles)
	{
		this.client = client;
		this.model = model;
		this.animationId = animationId;
		this.fineX = fineX;
		this.fineY = fineY;
		this.plane = plane;
		this.height = height;
		this.remaining = cycles;

		this.animation = new AnimationController(client, -1);
		this.animation.setAnimation(clip);

		setRadius(80);
		setDrawFrontTilesFirst(true);
		syncTransform();
	}

	@Override
	public void tick(int ticksSinceLastFrame)
	{
		remaining -= ticksSinceLastFrame;
		syncTransform();
		animation.tick(ticksSinceLastFrame);
	}

	@Override
	public Model getModel()
	{
		if (animation.getAnimation() == null)
		{
			return model;
		}
		Model posed = animation.animate(model);
		return posed == null ? model : posed;
	}

	/** True once the clip has run out and the prop should be unregistered. */
	boolean isFinished()
	{
		return remaining <= 0;
	}

	private void syncTransform()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}
		setX(fineX - wv.getBaseX() * Golem.TILE);
		setY(fineY - wv.getBaseY() * Golem.TILE);
		setWorldView(wv.getId());
		setLevel(plane);
		setZ(height);
	}
}

