	/** Out of the sea mouth is west; into the lake from its mouth is east. */
	static final int CAVE_SEA_MOUTH_OUTWARD = 512;
	static final int CAVE_LAKE_MOUTH_INWARD = 1536;

	/**
	 * Where the helm's tile sits from the middle of the raft, along its length, in model units:
	 * the stern, one tile behind. Behind is +z, a model facing -z. This was -128, which put the
	 * helm two tiles from the golem meant to be holding it.
	 */
	static final int RAFT_HELM_OFFSET = 128;

	/**
	 * The player's pose at a raft's helm, {@code HUMAN_SAILING_ALPHA_HELM_RAFT01_ACTIVE01_LOOP}.
	 * On framemap 0, the golem's own rig; the raft-side clips (13334–13336) are on 2486.
	 */
	static final int ANIM_GOLEM_HELM = 13341;

	/**
	 * Scenery animations, framemaps 2503 and 2486 against the golem's 0, so only {@link FakeProp}
	 * can draw them.
	 */
	/**
	 * Kept for the record rather than used: {@link PropFactory} reads each object's own
	 * {@code animationID} from the cache, so a plank, a gate and a fairy ring each get their own.
	 */
	static final int ANIM_PROP_GANGPLANK = 13562;
	static final int PROP_GANGPLANK_FRAMEMAP = 2503;

	/** How long a scenery animation is drawn for, in client cycles. */
	static final int PROP_CYCLES = 60;

	static boolean isGolem(int npcId)
	{
		return npcId == GOLEM_NPC_ID;
	}

}

package com.golemsdontdie;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Plans where a far-away golem goes next, without pathing on tiles.
 *
 * <p>A tile-accurate search is more than the answer is worth when nobody is watching: a far golem
 * aims at a transport or at open ground a few dozen tiles off, by a straight run. The inaccuracy
 * is invisible: the moment a player could see it, the golem is promoted and snapped onto ground.
 */
@Slf4j
@Singleton
class RoamPlanner
{
	/** How far a far-roaming golem will wander in one leg, in tiles. */
	private static final int LEG_MIN = 12;
	private static final int LEG_SPREAD = 40;

	/** Tries at finding a destination before the golem simply stays put for a while. */
	private static final int ATTEMPTS = 6;

	/** How far out to look for a transport worth heading to. */
	private static final int TRANSPORT_SEARCH = 48;

	@Inject
	private WorldMesh mesh;

	/** True if golems are kept on Wyrmscraig, which means no sailing at all. */
	private static boolean ambitionRestricted(RoamContext context)
	{
		return context != null && context.isAmbitionRestricted();
	}

	/**
	 * Collision harvested from the live scene, which outranks the shipped mesh: that mesh's fill
	 * spreads only through the transports shipped with it, so anywhere reached only by a taught
	 * obstacle is neither land nor reachable — Wyrmscraig's upper floors, where golems climbed a
	 * taught staircase and took it straight back down.
	 */
	@Inject
	private IslandMemory memory;

	@Inject
	private TransportNetwork transports;

	@Inject
	private GolemAbilities abilities;


	@Inject
	private Voyage voyage;

	@Inject
	private SailingDocks docks;

	/** Chance per plan that a golem at a port sets sail. Low: a golem plans every half-minute. */
	private static final float SAIL_CHANCE = 0.125f;

	/** How close to the quayside counts as being at the port, in tiles: at the dock, not near. */
	private static final int DOCK_REACH = 2;

	/** Plans the next leg for a golem that nobody can see; null if nowhere sensible was found. */
	Itinerary plan(WorldPoint from, int tick, Random random, TransportMemory memory,
		RoamContext context)
	{
		lastCandidates = 0;
		Itinerary crossing = planVoyage(from, tick, random, memory, context, AT_DOCK_SAIL_CHANCE);
		if (crossing != null)
		{
			lastOutcome = Outcome.VOYAGE;
			return crossing;
		}
		if (memory != null && memory.getPendingPort() >= 0)
		{
			// Waiting at the dock for its crossing to be worked out: a golem that walked away here left
			// the field to be evicted before it came back, and never sailed.
			lastOutcome = Outcome.TO_DOCK;
			return Itinerary.of(single(from), from.getPlane(), tick, DOCK_WAIT_POLL);
		}

		// Standing where no walk starts — a stepping stone, a landing the map calls blocked — the
		// only way on is a transport from this very tile; sampling the area left the golem on it.
		if (!isSafe(from.getX(), from.getY(), from.getPlane()))
		{
			// Unless it can simply step off. A fairy ring puts you down on the ring, which no map calls
			// ground, beside ground that is: as a stone mid-river, golems rode the whole network in step.
			WorldPoint off = transports.isStone(from.getX(), from.getY(), from.getPlane()) ? null : safeNeighbour(from);
			if (off != null)
			{
				List<int[]> step = single(from);
				step.add(new int[]{off.getX(), off.getY()});
				lastOutcome = Outcome.WALK;
				return Itinerary.of(step, from.getPlane(), tick, 0);
			}
			GolemTransport onward = fromHere(from, tick, memory, random);
			if (onward != null)
			{
				noteTaken(onward, tick, memory);
				lastOutcome = Outcome.ONWARD;
				return Itinerary.thenTransport(single(from), from.getPlane(), tick, onward);
			}
		}

		boolean pressed = context != null && context.crowdedRegion(from.getX(), from.getY(), from.getPlane());
		Reach reach = new Reach(from, context, FAR_SEARCH_BUDGET);

		// Somewhere it knows no way out of: now and then, back out the way it came in.
		if (random.nextFloat() < HOMEWARD_CHANCE)
		{
			GolemTransport home = wayHome(from.getX(), from.getY(), from.getPlane(), tick, memory, random);
			List<int[]> path = home == null ? null : walk(from, home.getFromX(), home.getFromY(), reach);
			if (path != null)
			{
				noteTaken(home, tick + path.size() - 1, memory);
				lastOutcome = Outcome.TRANSPORT;
				return Itinerary.thenTransport(path, from.getPlane(), tick, home);
			}
		}

		// Out of view a golem only sailed if a leg ended within two tiles of a quayside, which almost
		// never happens; now and then it goes to one on purpose.
		if (random.nextFloat() < DOCK_SEEK_CHANCE)
		{
			Itinerary toDock = toNearbyDock(from, tick, memory, reach);
			if (toDock != null)
			{
				lastOutcome = Outcome.TO_DOCK;
				return toDock;
			}
		}

		// A golem in a crowd is looking for the way out, so it neither rolls for this nor rests first.
		if (pressed || random.nextFloat() < TRANSPORT_CHANCE && (memory == null || !memory.restingFromTransports(tick)))
		{
			Itinerary toTransport = toNearbyTransport(from, tick, random, memory, reach);
			if (toTransport != null)
			{
				lastOutcome = Outcome.TRANSPORT;
				return toTransport;
			}
		}

		Itinerary leg = wander(from, tick, random, reach);
		lastOutcome = leg != null ? Outcome.WALK : Outcome.NOTHING;
		return leg;
	}

	/**
	 * Chance per decision that a golem with no known way out heads back out the way it came in. Not
	 * every time: it has only just arrived, and the way back is on the way in's cooldown anyway.
	 */
	static final float HOMEWARD_CHANCE = 0.25f;

	/** The network revision the component index below was built from; -1 before the first. */
	private int componentsRevision = -1;

	/** Per mesh component: transports starting in it that go somewhere else. */
	private final java.util.Map<Integer, List<GolemTransport>> exitsFrom = new java.util.HashMap<>();

	/** Per mesh component: the way back out through each transport that comes into it from elsewhere. */
	private final java.util.Map<Integer, List<GolemTransport>> waysBackFrom = new java.util.HashMap<>();

	/**
	 * The way back out through something that led here, for a golem somewhere with no known way out;
	 * or null if it knows one, or the mesh cannot say.
	 *
	 * <p>A player can learn the way into a place without the way out — in by cave, out by teleport —
	 * and golems gathered in Wyrmscraig's cave until taught the exit. Refusing to go in would bar
	 * every such dungeon, so a golem leaves the way it came; "somewhere" is the mesh's component.
	 */
	GolemTransport wayHome(int x, int y, int plane, int tick, TransportMemory memory, Random random)
	{
		if (mesh == null || transports == null || abilities == null)
		{
			return null;
		}
		indexComponents();
		int component = componentNear(x, y, plane);
		List<GolemTransport> ways = component == 0 ? unmeshedWaysHome(x, y, plane) : waysHome.get(component);
		if (ways == null)
		{
			ways = findWaysHome(component);
			waysHome.put(component, ways);
		}
		if (ways.isEmpty())
		{
			return null;
		}
		GolemTransport way = ways.get(random.nextInt(ways.size()));
		return memory != null && memory.onCooldown(way, tick) ? null : way;
	}

	/** Ways home for ground the mesh has nothing on, by tile, worked out once per change to the network. */
	private final java.util.Map<Long, List<GolemTransport>> unmeshedWays = new java.util.HashMap<>();

	/**
	 * The ways back out of a room the mesh knows nothing about, if nothing offered leads out of it.
	 * The Doom of Mokhaiotl's arena is left by an interface, a teleport or death, none of them
	 * learned, and golems that followed the player in stayed for good.
	 */
	private List<GolemTransport> unmeshedWaysHome(int x, int y, int plane)
	{
		List<GolemTransport> known = unmeshedWays.get(RoamContext.tileKey(x, y, plane));
		if (known != null)
		{
			return known;
		}
		// Not remembered for ground not yet read: asked again once the room's floor is known.
		boolean remember = memory.isKnownWalkable(x, y, plane);
		TileMap room = unmeshedRoom(x, y, plane);
		if (room == null)
		{
			if (remember)
			{
				unmeshedWays.put(RoamContext.tileKey(x, y, plane), java.util.Collections.emptyList());
			}
			return java.util.Collections.emptyList();
		}
		List<GolemTransport> ways = new ArrayList<>();
		List<GolemTransport> fromMesh = new ArrayList<>();
		for (GolemTransport t : transports.all())
		{
			if (!transports.isOffered(t) || !abilities.canUse(t))
			{
				continue;
			}
			boolean fromIn = t.getFromPlane() == plane && inRoom(room, t.getFromX(), t.getFromY());
			boolean toIn = t.getToPlane() == plane && inRoom(room, t.getToX(), t.getToY());
			// A way out only if it lands on ground the mesh knows. One into another unmeshed room, as
			// the Gap leads from the Doom lobby down into the arena, is deeper in, not out: counted as
			// a way out, it left the lobby with no way home, and golems led up out of the arena jumped
			// straight back down.
			if (fromIn && !toIn && componentNear(t.getToX(), t.getToY(), t.getToPlane()) != 0)
			{
				ways = java.util.Collections.emptyList();
				fromMesh = ways;
				break;
			}
			// Only what leads in from outside: one part of the room to another is no way home. Best,
			// what came in from ground the mesh knows, so a chain of rooms is left the whole way out.
			if (toIn && !fromIn)
			{
				ways.add(t.backThrough());
				if (componentNear(t.getFromX(), t.getFromY(), t.getFromPlane()) != 0)
				{
					fromMesh.add(t.backThrough());
				}
			}
		}
		if (!fromMesh.isEmpty())
		{
			ways = fromMesh;
		}
		for (int i = 0; remember && i < room.size(); i++)
		{
			long tile = room.keyAt(i);
			unmeshedWays.put(RoamContext.tileKey(GolemPathfinder.unpackX(tile), GolemPathfinder.unpackY(tile), plane), ways);
		}
		return ways;
	}

	/** The unmeshed floor walkable from a tile, of any size, or null once it reaches the mesh. */
	private TileMap unmeshedRoom(int x, int y, int plane)
	{
		TileMap room = new TileMap(1024);
		room.add(GolemPathfinder.pack(x, y), 0);
		for (int head = 0; head < room.size(); head++)
		{
			long at = room.keyAt(head);
			int cx = GolemPathfinder.unpackX(at);
			int cy = GolemPathfinder.unpackY(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					long next = GolemPathfinder.pack(cx + dx, cy + dy);
					if (room.containsKey(next) || !memory.isKnownWalkable(cx + dx, cy + dy, plane)
						|| !memory.canStep(cx, cy, plane, dx, dy))
					{
						continue;
					}
					if (mesh.componentAt(cx + dx, cy + dy, plane) != 0)
					{
						return null;
					}
					room.add(next, 0);
				}
			}
		}
		return room;
	}

	/** Whether a transport's end is in a room, or beside it: an end can sit on its object. */
	private static boolean inRoom(TileMap room, int x, int y)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (room.containsKey(GolemPathfinder.pack(x + dx, y + dy)))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Spaces reachable by shortcuts and still shut in: the open world reaches hundreds. */
	private static final int SHUT_IN = 8;

	/** Ways home by component, worked out once per change to the network; empty where there is no need. */
	private final java.util.Map<Integer, List<GolemTransport>> waysHome = new java.util.HashMap<>();

	/**
	 * The ways back out, for a golem in this component, if everywhere it can reach from here is shut
	 * in; otherwise none.
	 *
	 * <p>Shut in is not only one room: a courtyard whose only way out is a cave whose only way out
	 * is the courtyard is two spaces leading to each other, and a simulated year found golems dozens
	 * to a tile in just that. If usable shortcuts run out within a few spaces, the golem may leave.
	 */
	private List<GolemTransport> findWaysHome(int start)
	{
		java.util.Set<Integer> reached = new java.util.HashSet<>();
		java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
		reached.add(start);
		queue.add(start);
		while (!queue.isEmpty())
		{
			List<GolemTransport> exits = exitsFrom.get(queue.poll());
			if (exits == null)
			{
				continue;
			}
			for (GolemTransport exit : exits)
			{
				if (!abilities.canUse(exit) || !landsSomewhereUseful(exit))
				{
					continue;
				}
				int to = componentNear(exit.getToX(), exit.getToY(), exit.getToPlane());
				// Somewhere the mesh knows nothing about is somewhere else entirely: not shut in.
				if (to == 0)
				{
					return java.util.Collections.emptyList();
				}
				if (reached.add(to))
				{
					if (reached.size() > SHUT_IN)
					{
						return java.util.Collections.emptyList();
					}
					queue.add(to);
				}
			}
		}

		List<GolemTransport> ways = new ArrayList<>();
		for (GolemTransport way : waysBackFrom.getOrDefault(start, java.util.Collections.emptyList()))
		{
			// Back to somewhere outside the trap, not to another room of it.
			int to = componentNear(way.getToX(), way.getToY(), way.getToPlane());
			if (!reached.contains(to))
			{
				ways.add(way);
			}
		}
		return ways;
	}

	/** The component of a tile, or of a tile beside it: a transport's end can sit on its object. */
	private int componentNear(int x, int y, int plane)
	{
		int here = mesh.componentAt(x, y, plane);
		for (int dx = -1; dx <= 1 && here == 0; dx++)
		{
			for (int dy = -1; dy <= 1 && here == 0; dy++)
			{
				here = mesh.componentAt(x + dx, y + dy, plane);
			}
		}
		return here;
	}

	/** Sorts every transport into the components it leaves and enters, once per change to the network. */
	private void indexComponents()
	{
		if (componentsRevision == transports.revision())
		{
			return;
		}
		componentsRevision = transports.revision();
		exitsFrom.clear();
		waysBackFrom.clear();
		waysHome.clear();
		unmeshedWays.clear();
		for (GolemTransport t : transports.all())
		{
			if (!transports.isOffered(t))
			{
				continue;
			}
			int from = componentNear(t.getFromX(), t.getFromY(), t.getFromPlane());
			int to = componentNear(t.getToX(), t.getToY(), t.getToPlane());
			boolean elsewhere = from == 0 || to == 0 || from != to || t.getFromPlane() != t.getToPlane();
			if (!elsewhere)
			{
				continue;
			}
			if (from != 0)
			{
				exitsFrom.computeIfAbsent(from, k -> new ArrayList<>()).add(t);
			}
			if (to != 0)
			{
				waysBackFrom.computeIfAbsent(to, k -> new ArrayList<>()).add(t.backThrough());
			}
		}
	}

	/** Tiles a far golem's flood may visit: a third of a golem in view's, and the plan's only one. */
	private static final int FAR_SEARCH_BUDGET = 1000;

	// A longer flood for golems in a crowd cost two and a half times the planning and got no more of
	// them out of Meiyerditch, whose ways out are two tiles in a warren.

	/**
	 * Everywhere a golem can walk to from where it stands, within the budget — flooded at most once
	 * per plan, only after a straight line fails, and underground those almost never exist.
	 */
	private static final class Reach
	{
		private final WorldPoint from;
		private final RoamContext context;
		private final int budget;
		private TileMap cameFrom;

		Reach(WorldPoint from, RoamContext context, int budget)
		{
			this.from = from;
			this.context = context;
			this.budget = budget;
		}

		/** The flood, made on first use; empty without a pathfinder. */
		TileMap tiles()
		{
			if (cameFrom == null)
			{
				cameFrom = context == null || context.getPathfinder() == null
					? new TileMap(4)
					: context.getPathfinder().flood(from.getX(), from.getY(), from.getPlane(), budget);
			}
			return cameFrom;
		}

		/** The walk to a tile the flood reached, the golem's own tile first; null if not reached. */
		List<int[]> pathTo(int x, int y)
		{
			java.util.Deque<int[]> found = GolemPathfinder.pathFrom(tiles(), from.getX(), from.getY(), x, y);
			if (found == null)
			{
				return null;
			}
			List<int[]> path = new ArrayList<>(found.size() + 1);
			path.add(new int[]{from.getX(), from.getY()});
			path.addAll(found);
			return path;
		}
	}

	/**
	 * A walk somewhere else, or null: a straight leg of a few dozen tiles where there is one, else
	 * somewhere in the far half of the flood, so a golem in a corridor still goes somewhere.
	 */
	private Itinerary wander(WorldPoint from, int tick, Random random, Reach reach)
	{
		for (int attempt = 0; attempt < ATTEMPTS; attempt++)
		{
			int distance = LEG_MIN + random.nextInt(LEG_SPREAD);
			double angle = random.nextDouble() * Math.PI * 2;
			int toX = from.getX() + (int) Math.round(Math.cos(angle) * distance);
			int toY = from.getY() + (int) Math.round(Math.sin(angle) * distance);

			if (!isSafe(toX, toY, from.getPlane()))
			{
				continue;
			}

			// And in the same connected space: a destination inside a sealed courtyard can have a
			// perfectly walkable line to it and still be unreachable on foot.
			if (!mesh.sameComponent(from.getX(), from.getY(), toX, toY, from.getPlane()))
			{
				continue;
			}
			lastCandidates++;
			List<int[]> leg = straightLine(from.getX(), from.getY(), toX, toY, from.getPlane());
			if (leg == null)
			{
				continue;
			}
			return Itinerary.of(leg, from.getPlane(), tick, 0);
		}

		TileMap tiles = reach.tiles();
		if (tiles.size() < 2)
		{
			return null;
		}
		int reached = tiles.size();
		int half = reached / 2;
		for (int attempt = 0; attempt < ATTEMPTS; attempt++)
		{
			long tile = tiles.keyAt(half + random.nextInt(reached - half));
			int x = GolemPathfinder.unpackX(tile);
			int y = GolemPathfinder.unpackY(tile);
			if ((x == from.getX() && y == from.getY()) || !isSafe(x, y, from.getPlane()))
			{
				continue;
			}
			lastCandidates++;
			List<int[]> path = reach.pathTo(x, y);
			if (path != null)
			{
				return Itinerary.of(path, from.getPlane(), tick, 0);
			}
		}
		return null;
	}

	/** Ticks a golem out of view stands before looking again, when nowhere was found. */
	private static final int IDLE_MIN = 8;
	private static final int IDLE_SPREAD = 16;

	/**
	 * A pause on the spot, for a golem that found nowhere to go.
	 *
	 * <p>Without it a golem with no plan asked again the next frame, and a golem with no plan is
	 * exactly one whose plans fail: a search and two dozen probes, sixty times a second.
	 *
	 * @param failures plans in a row that found nothing, before this one
	 */
	static Itinerary idle(WorldPoint at, int tick, Random random, int failures)
	{
		int ticks = (IDLE_MIN + random.nextInt(IDLE_SPREAD)) << Math.min(Math.max(0, failures), 3);
		return Itinerary.of(single(at), at.getPlane(), tick, ticks);
	}

	private static List<int[]> single(WorldPoint at)
	{
		List<int[]> path = new ArrayList<>(1);
		path.add(new int[]{at.getX(), at.getY()});
		return path;
	}

	/**
	 * A walk to the quayside of the nearest open dock in reach, or null. Not while on shore leave,
	 * and not to a dock the golem is already at — that is the voyage roll's business.
	 */
	private Itinerary toNearbyDock(WorldPoint from, int tick, TransportMemory memory, Reach reach)
	{
		if (docks == null || memory == null || ambitionRestricted(reach.context) || memory.onShoreLeave())
		{
			return null;
		}
		List<SailingDocks.Dock> near = new ArrayList<>();
		for (SailingDocks.Dock dock : docks.getDocks())
		{
			WorldPoint shore = dock.getShore();
			int distance = Math.max(Math.abs(shore.getX() - from.getX()), Math.abs(shore.getY() - from.getY()));
			if (shore.getPlane() == from.getPlane() && distance > DOCK_REACH && distance <= TRANSPORT_SEARCH
				&& docks.isOpen(dock))
			{
				near.add(dock);
			}
		}
		near.sort((a, b) -> Integer.compare(
			Math.max(Math.abs(a.getShore().getX() - from.getX()), Math.abs(a.getShore().getY() - from.getY())),
			Math.max(Math.abs(b.getShore().getX() - from.getX()), Math.abs(b.getShore().getY() - from.getY()))));
		for (SailingDocks.Dock dock : near)
		{
			List<int[]> path = walk(from, dock.getShore().getX(), dock.getShore().getY(), reach);
			if (path != null)
			{
				return Itinerary.of(path, from.getPlane(), tick, 0);
			}
		}
		return null;
	}

	/**
	 * A walk to a tile — a straight line where there is one, otherwise through the flood — the
	 * golem's own tile first; null if there is no way within reach.
	 */
	private List<int[]> walk(WorldPoint from, int toX, int toY, Reach reach)
	{
		List<int[]> line = straightLine(from.getX(), from.getY(), toX, toY, from.getPlane());
		return line != null ? line : reach.pathTo(toX, toY);
	}

	/**
	 * Puts a transport a far golem has chosen on its cooldown, from when it will be used. Far golems
	 * never did, and at the foot of a ladder the nearest transport is the ladder: nine in ten climbs
	 * on Wyrmscraig were undone at once.
	 */
	private static void noteTaken(GolemTransport transport, int whenUsed, TransportMemory memory)
	{
		if (memory != null)
		{
			memory.used(transport, whenUsed);
		}
	}

	/**
	 * A transport starting on exactly this tile, for a golem that cannot walk off it. One not on
	 * cooldown if there is one; failing that the way back, since standing on a stone is worse.
	 */
	private GolemTransport fromHere(WorldPoint at, int tick, TransportMemory memory, Random random)
	{
		GolemTransport back = null;
		// Any of the ways on, not the first listed: always the first sent every golem the same way.
		List<GolemTransport> onward = new ArrayList<>();
		for (GolemTransport transport : transports.from(at.getX(), at.getY()))
		{
			if (transport.getFromPlane() != at.getPlane() || !abilities.canUse(transport)
				|| !landsSomewhereUseful(transport))
			{
				continue;
			}
			if (memory == null || !memory.onCooldown(transport, tick))
			{
				onward.add(transport);
			}
			else if (back == null)
			{
				back = transport;
			}
		}
		return onward.isEmpty() ? back : onward.get(random.nextInt(onward.size()));
	}

	private WorldPoint safeNeighbour(WorldPoint at)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if ((dx != 0 || dy != 0) && isSafe(at.getX() + dx, at.getY() + dy, at.getPlane()))
				{
					return new WorldPoint(at.getX() + dx, at.getY() + dy, at.getPlane());
				}
			}
		}
		return null;
	}

	/**
	 * True if a golem arriving by this transport has somewhere to go: walkable ground, or a chain of
	 * transports onward — not this one in reverse — ending on some. See leadsToGround.
	 */
	private boolean landsSomewhereUseful(GolemTransport transport)
	{
		return transports.leadsToGround(transport.getToX(), transport.getToY(), transport.getToPlane(),
			transport.getFromX(), transport.getFromY(), transport.getFromPlane(), TransportNetwork.CHAIN_HOPS,
			abilities::canUse, this::isSafe);
	}

	/**
	 * Rolls for a crossing, for a golem standing at a port.
	 *
	 * <p>Called from two places, which is the point: a far golem plans one when its route runs out,
	 * and a golem in view rolls as it steps onto a tile, sailing having once happened only out of
	 * range. Affordable in view because crossings are cached per pair of ports.
	 *
	 * @return a crossing, or null if the golem is not at a port, is on shore leave, lost the roll,
	 *         or the route is unknown and the frame's search is spent
	 */
	Itinerary planVoyage(WorldPoint from, int tick, Random random, TransportMemory memory,
		RoamContext context)
	{
		return planVoyage(from, tick, random, memory, context, SAIL_CHANCE);
	}

	/** Chance a far golem at a dock sets sail, per plan: higher, as it plans once per leg. */
	private static final float AT_DOCK_SAIL_CHANCE = 0.6f;

	/** Ticks a far golem at a dock waits before asking again whether its crossing is ready. */
	private static final int DOCK_WAIT_POLL = 4;

	/** Chance per plan that a far golem with a dock in reach heads for it. */
	private static final float DOCK_SEEK_CHANCE = 0.1f;

	/**
	 * How near a gangplank, in tiles, draws a golem in view toward it. A golem only rolled to sail
	 * on stepping within a couple of tiles of the quayside, which at random it almost never did.
	 */
	static final int DOCK_ATTRACTION = 15;

	/** Chance, each time a golem in view picks somewhere to walk, that a dock in range is where. */
	private static final float DOCK_ATTRACTION_CHANCE = 0.25f;

	/**
	 * A dock a golem in view has chosen to walk up to, or null: the nearest open one within
	 * {@link #DOCK_ATTRACTION} tiles, not one it is at, and not on shore leave.
	 */
	SailingDocks.Dock dockToVisit(WorldPoint from, TransportMemory memory, RoamContext context, Random random)
	{
		if (docks == null || memory == null || ambitionRestricted(context) || memory.onShoreLeave())
		{
			return null;
		}
		SailingDocks.Dock nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (SailingDocks.Dock dock : docks.getDocks())
		{
			WorldPoint shore = dock.getShore();
			if (shore.getPlane() != from.getPlane())
			{
				continue;
			}
			int distance = Math.max(Math.abs(shore.getX() - from.getX()), Math.abs(shore.getY() - from.getY()));
			if (distance > DOCK_REACH && distance <= DOCK_ATTRACTION && distance < nearestDistance && docks.isOpen(dock))
			{
				nearest = dock;
				nearestDistance = distance;
			}
		}
		if (nearest == null || random.nextFloat() >= DOCK_ATTRACTION_CHANCE)
		{
			return null;
		}
		return nearest;
	}

	SailingDocks.Dock dockAt(WorldPoint from)
	{
		return voyage == null ? null : voyage.dockAt(from, DOCK_REACH);
	}

	boolean atDock(WorldPoint from, SailingDocks.Dock dock)
	{
		WorldPoint shore = dock.getShore();
		return shore.getPlane() == from.getPlane()
			&& Math.max(Math.abs(shore.getX() - from.getX()), Math.abs(shore.getY() - from.getY())) <= DOCK_REACH;
	}

	/** Rolls for a crossing for a golem that walked to a dock on purpose: the far golem's chance. */
	Itinerary planVoyageAtDock(WorldPoint from, int tick, Random random, TransportMemory memory, RoamContext context)
	{
		return planVoyage(from, tick, random, memory, context, AT_DOCK_SAIL_CHANCE);
	}

	private Itinerary planVoyage(WorldPoint from, int tick, Random random, TransportMemory memory,
		RoamContext context, float chance)
	{
		// A golem already waiting to sail has made its decision and does not roll again, but only at
		// the dock it is waiting at. See TransportMemory.holdPending.
		boolean waiting = memory != null && memory.getPendingPort() >= 0;
		if (memory == null || voyage == null || ambitionRestricted(context) || memory.onShoreLeave()
			|| !waiting && random.nextFloat() >= chance)
		{
			return null;
		}

		SailingDocks.Dock dock = voyage.dockAt(from, DOCK_REACH);
		if (waiting && (dock == null || dock.getRowId() != memory.getPendingFrom()))
		{
			memory.clearPending();
			if (dock == null || random.nextFloat() >= chance)
			{
				return null;
			}
		}
		if (dock == null || !docks.isOpen(dock))
		{
			return null;
		}

		Itinerary crossing = voyage.depart(dock, from, memory, tick, random, context);
		if (crossing == null)
		{
			return null;
		}

		// Ashore at the far end, the golem walks inland a while before it may think about boats
		// again; otherwise a golem that arrives at a port simply leaves it again.
		memory.beginShoreLeaveOnArrival(tick + crossing.getDuration(), tick, random);
		return crossing;
	}

	/**
	 * Chance per plan that a golem heads for a transport rather than wandering. Finding one used to
	 * cap this by itself; now every transport in range is considered, and always taking one is hops.
	 */
	private static final float TRANSPORT_CHANCE = 0.5f;

	/** How a plan came out, for the debug log. */
	enum Outcome
	{
		VOYAGE,
		/** Walked toward a dock, to sail from it. */
		TO_DOCK,
		/** Took the only way off a tile that cannot be walked from. */
		ONWARD,
		TRANSPORT,
		WALK,
		NOTHING,
	}

	@lombok.Getter
	private Outcome lastOutcome = Outcome.NOTHING;

	/** Wander destinations the last plan found to be real ground in the golem's own space. */
	@lombok.Getter
	private int lastCandidates;

	/**
	 * A walk to a transport in range and the transport itself, or null. Every transport starting
	 * within reach is considered in a random order, which keeps the choice fair.
	 */
	private Itinerary toNearbyTransport(WorldPoint from, int tick, Random random, TransportMemory memory,
		Reach reach)
	{
		List<GolemTransport> near = new ArrayList<>();
		transports.near(from.getX(), from.getY(), TRANSPORT_SEARCH, near);
		java.util.Collections.shuffle(near, random);

		int walksTried = 0;
		// The first one it passed over for being crowded, in case nothing roomier turns up.
		GolemTransport crowdedChoice = null;
		for (GolemTransport transport : near)
		{
			// Landing judged by the same test as everywhere else in the planner: this one alone asked
			// for the shipped land fill, so the cathedral's interior never counted as somewhere to be.
			if (transport.getFromPlane() != from.getPlane()
				|| (memory != null && memory.onCooldown(transport, tick))
				|| !mesh.sameComponent(from.getX(), from.getY(), transport.getFromX(), transport.getFromY(),
					from.getPlane())
				|| !abilities.canUse(transport)
				|| !landsSomewhereUseful(transport))
			{
				continue;
			}
			// Somewhere with room in it, by preference; see RoamContext.appeal. One that turns a
			// transport down falls back on the first it passed over rather than staying put.
			float appeal = reach.context == null ? 1f
				: reach.context.appeal(from.getX(), from.getY(), from.getPlane(),
					transport.getToX(), transport.getToY(), transport.getToPlane());
			if (appeal < 1f && random.nextFloat() >= appeal)
			{
				if (crowdedChoice == null)
				{
					crowdedChoice = transport;
				}
				continue;
			}
			List<int[]> path = walk(from, transport.getFromX(), transport.getFromY(), reach);
			if (path != null)
			{
				noteTaken(transport, tick + path.size() - 1, memory);
				return Itinerary.thenTransport(path, from.getPlane(), tick, transport);
			}
			// Past the first few, each try is a line and a lookup in the flood — cheap, but a town
			// can have a hundred rows in range.
			if (++walksTried >= ATTEMPTS * 4)
			{
				break;
			}
		}
		if (crowdedChoice != null)
		{
			List<int[]> path = walk(from, crowdedChoice.getFromX(), crowdedChoice.getFromY(), reach);
			if (path != null)
			{
				noteTaken(crowdedChoice, tick + path.size() - 1, memory);
				return Itinerary.thenTransport(path, from.getPlane(), tick, crowdedChoice);
			}
		}
		return null;
	}

	/**
	 * A straight run of tiles between two points, eight-directional. Deliberately not a search: at
	 * Tier 3 nothing observes the route, only where the golem ends up and roughly how long it took.
	 */
	private List<int[]> straightLine(int fromX, int fromY, int toX, int toY, int plane)
	{
		List<int[]> path = new ArrayList<>();
		int x = fromX;
		int y = fromY;
		path.add(new int[]{x, y});

		while (x != toX || y != toY)
		{
			int stepX = Integer.signum(toX - x);
			int stepY = Integer.signum(toY - y);

			// The step, not only the tile it lands on: two walkable tiles either side of a wall are
			// both fine ground, and a line checking tiles alone walked through the wall between them.
			if (!memory.canStep(x, y, plane, stepX, stepY))
			{
				return null;
			}
			x += stepX;
			y += stepY;

			// Every tile is checked, not just the destination, which left golems standing on water in
			// Wyrmscraig's caves. Harvested ground counts too, or golems upstairs went back down.
			if (!mesh.isLandWalkable(x, y, plane) && !memory.isKnownWalkable(x, y, plane))
			{
				return null;
			}

			path.add(new int[]{x, y});

			if (path.size() > 512)
			{
				// A leg this long means nonsense: most likely an underground coordinate against a
				// surface one.
				return null;
			}
		}
		return path;
	}

	/**
	 * The nearest tile a golem could actually stand on, spiralling outward.
	 *
	 * <p>Used when a golem is promoted into view, and when one is restored onto ground that has since
	 * changed. A golem is moved, never replaced — name, id and gait kept — since golems do not die.
	 *
	 * @return a safe tile, or the original if nothing better was found within range
	 */
	WorldPoint snapToMesh(WorldPoint at)
	{
		if (isSafe(at.getX(), at.getY(), at.getPlane()))
		{
			return at;
		}
		// Standing on water no golem can walk: the nearest ground, on whatever side of the shore.
		// Kept to the golem's own component, the search found only more water and left it there.
		if (mesh.isInlandWater(at.getX(), at.getY(), at.getPlane()))
		{
			WorldPoint shore = nearestSafe(at, false);
			return shore != null ? shore : at;
		}
		WorldPoint near = nearestSafe(at, true);
		return near != null ? near : at;
	}

	/**
	 * The nearest tile a golem can stand on, up to 32 tiles out, or null; {@code sameSpace} keeps it
	 * to the connected space the golem is in, as far as the mesh knows it.
	 */
	private WorldPoint nearestSafe(WorldPoint at, boolean sameSpace)
	{

		// Where the golem is now decides where it may be put: the nearest walkable tile to one in a
		// wall is often inside the building. Zero means the mesh has nothing to say, and is a match.
		int origin = mesh.componentAt(at.getX(), at.getY(), at.getPlane());

		for (int radius = 1; radius <= 32; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					// Only the shell of the square, so each ring is tested once.
					if (Math.abs(dx) != radius && Math.abs(dy) != radius)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (sameSpace && origin != 0)
					{
						int here = mesh.componentAt(x, y, at.getPlane());
						if (here != 0 && here != origin)
						{
							continue;
						}
					}
					if (isSafe(x, y, at.getPlane()))
					{
						return new WorldPoint(x, y, at.getPlane());
					}
				}
			}
		}
		return null;
	}

	/**
	 * Walkable, and not in a pocket too small to wander out of. Ground the player has stood on
	 * counts whatever the shipped mesh says: the harvest is this client, this revision, this floor.
	 */
	private boolean isSafe(int x, int y, int plane)
	{
		if (memory.isKnownWalkable(x, y, plane))
		{
			return true;
		}
		return mesh.isLandWalkable(x, y, plane) && !mesh.isIsolated(x, y, plane);
	}
}

package com.golemsdontdie;

import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Draws the boat a golem crosses the ocean in.
 *
 * <p>{@code WorldEntity} — what the game's own boats are — is read-only to a plugin, so this
 * is a drawn model at a position, as a fake golem is. It turns at a third of a golem's rate,
 * because a boat pivoting at a golem's rate reads as a sliding crate, and its heading leads
 * its motion.
 */
class FakeRaft extends RuneLiteObjectController
{
	/** Orientation units per cycle; a third of a golem's. */
	private static final int TURN_PER_CYCLE = 8;

	private final Client client;
	private final Model model;
	private final AnimationController animation;

	/** Where the boat is, in 128ths of a tile, as for golems. */
	private int fineX;
	private int fineY;

	private int orientation;
	private int targetOrientation;

	/**
	 * The ground height the boat sits at: the golem's, not the ground under the boat's own middle.
	 *
	 * <p>The raft's middle is a tile ahead of the golem and at sea the ground under water is
	 * seabed, so a raft on its own tile sank out of sight where that drops away, leaving the
	 * golem on nothing at the helm; one whose middle lay outside the scene got no height at all.
	 */
	private int groundZ = Integer.MIN_VALUE;

	FakeRaft(Client client, Model model, GolemModelFactory shared, int fineX, int fineY,
		int orientation)
	{
		this.client = client;
		this.model = model;
		this.fineX = fineX;
		this.fineY = fineY;
		this.orientation = orientation;
		this.targetOrientation = orientation;

		// The raft's models carry no rig, so it plays nothing; the golem at the helm does.
		this.animation = new AnimationController(client, -1);

		// A boat covers several tiles; ground under its footprint must draw first or the hull
		// z-fights with the water.
		setRadius(3 * 64);
		setDrawFrontTilesFirst(true);
		syncTransform();
	}

	/** Moves the boat to a world position, easing the heading round. */
	void steer(int worldFineX, int worldFineY, int heading)
	{
		this.fineX = worldFineX;
		this.fineY = worldFineY;
		this.targetOrientation = heading & 2047;
	}

	/** As {@link #steer(int, int, int)}, at this ground height. */
	void steer(int worldFineX, int worldFineY, int heading, int groundZ)
	{
		steer(worldFineX, worldFineY, heading);
		this.groundZ = groundZ;
	}

	@Override
	public void tick(int ticksSinceLastFrame)
	{
		turn(ticksSinceLastFrame);
		syncTransform();
		animation.tick(ticksSinceLastFrame);
	}

	@Override
	public Model getModel()
	{
		if (animation.getAnimation() == null)
		{
			return model;
		}
		Model posed = animation.animate(model);
		return posed == null ? model : posed;
	}

	/** Eases the heading round the short way, at a boat's rate. */
	private void turn(int cycles)
	{
		if (orientation == targetOrientation || cycles <= 0)
		{
			return;
		}
		int delta = ((targetOrientation - orientation + 1024) & 2047) - 1024;
		int step = Math.min(Math.abs(delta), TURN_PER_CYCLE * cycles);
		orientation = (orientation + Integer.signum(delta) * step) & 2047;
	}

	private void syncTransform()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		int localX = fineX - wv.getBaseX() * Golem.TILE;
		int localY = fineY - wv.getBaseY() * Golem.TILE;
		setX(localX);
		setY(localY);
		setWorldView(wv.getId());
		setLevel(0);
		setOrientation(orientation);
		if (groundZ != Integer.MIN_VALUE)
		{
			setZ(groundZ);
		}
		else if (Golem.isInScene(wv, localX, localY))
		{
			setZ(Perspective.getTileHeight(client, new LocalPoint(localX, localY, wv), 0));
		}
	}
}

package com.golemsdontdie;

import java.util.Random;

/**
 * The area a golem is allowed to wander: everywhere the island map says is walkable.
 *
 * <p>A penned shape holding golems near their plinth used to exist too. No outer edge is needed:
 * {@link IslandMemory} only knows the island, so asking whether a tile is walkable asks that.
 */
class RoamBounds
{
	/**
	 * How far a golem looks for its next destination, in tiles. Sampling the whole island
	 * sends golems on island-long treks and runs every path search to its node budget; a
	 * window reaches the same coverage by random walk.
	 */
	private static final int WANDER_WINDOW = 12;

	private final IslandMemory memory;
	private final int plane;
	private final int centreX;
	private final int centreY;

	/** Destinations to pass over — a crowded tile — or null. Never blocks walking through. */
	private final java.util.function.BiPredicate<Integer, Integer> avoid;

	RoamBounds(IslandMemory memory, int plane, int centreX, int centreY)
	{
		this(memory, plane, centreX, centreY, null);
	}

	RoamBounds(IslandMemory memory, int plane, int centreX, int centreY,
		java.util.function.BiPredicate<Integer, Integer> avoid)
	{
		this.memory = memory;
		this.plane = plane;
		this.centreX = centreX;
		this.centreY = centreY;
		this.avoid = avoid;
	}

	boolean avoids(int worldX, int worldY)
	{
		return avoid != null && avoid.test(worldX, worldY);
	}

	/** True if a golem may enter this world tile. */
	boolean contains(int worldX, int worldY)
	{
		return memory.isKnownWalkable(worldX, worldY, plane);
	}

	/** A candidate destination. May be unwalkable — the caller rejects and retries. */
	int[] sample(Random random)
	{
		return new int[]{
			centreX - WANDER_WINDOW + random.nextInt(WANDER_WINDOW * 2 + 1),
			centreY - WANDER_WINDOW + random.nextInt(WANDER_WINDOW * 2 + 1),
		};
	}
}

package com.golemsdontdie;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Base64;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Constants;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * The plugin's memory of where a golem can walk on Wyrmscraig, in world coordinates,
 * learned by watching the scene and kept across logins.
 *
 * <p>Free roam needs passability for the whole island, but the scene only holds the
 * 104×104 tiles around the player, so every region's collision flags are copied out as it
 * loads and folded into a world-space record that outlives the scene.
 *
 * <p>Storage is the two-bit-per-tile north/east scheme Shortest Path uses. South and west
 * are not stored because they are the north and east of the neighbouring tile; halving the
 * data for free matters when it has to fit in a config value.
 *
 * <p>The <i>live</i> half of a pair: {@link WorldMesh} is the shipped read-only floor for
 * the whole reachable world, and this takes precedence wherever the two disagree, because
 * a harvest reflects the world as it is now — objects that come and go included, and the
 * window between a game update and the mesh being regenerated.
 *
 * <p>Only the island is persisted. Nine regions of base64 in a properties file is
 * reasonable; the 1,158 the mesh covers would be an abuse of one, so world-scale
 * passability lives in the jar and the live harvest beyond the island is session-scoped.
 */
@Slf4j
@Singleton
class IslandMemory
{
	/** Config key the serialised map is stored under. Plugin-written, so not a config item. */
	static final String MAP_KEY = "islandMap";

	/**
	 * The island map shipped with the plugin, covering the nine regions around the crafting
	 * site. Built from Shortest Path's world collision map — generated from the cache with XTEA
	 * keys the local key file lacks for these regions — and cross-checked tile by tile against
	 * live collision. Without it, free roam could only cover ground the player had walked.
	 *
	 * @see #loadBundled()
	 */
	private static final String BUNDLED_MAP = "/island-map.gz";

	private static final int REGION_SIZE = 64;
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int FLAGS_PER_TILE = 2;
	private static final int FLAG_NORTH = 0;
	private static final int FLAG_EAST = 1;
	private static final int BITS_PER_REGION = REGION_SIZE * REGION_SIZE * FLAGS_PER_TILE;
	private static final int WORDS_PER_REGION = BITS_PER_REGION / Long.SIZE;

	/**
	 * Tiles at the edge of the loaded scene that are never harvested. The client fills a border
	 * of the scene's collision with "blocked" whatever is really there — harmless while
	 * harvesting only added open edges, but once a harvest cleared what it re-read it wrote a
	 * band of false walls, boxing the plinth into two hundred tiles.
	 */
	private static final int SCENE_MARGIN = 6;

	/** Blocked for standing on: an object, a wall filling the tile, or bad ground. */
	private static final int UNWALKABLE = CollisionDataFlag.BLOCK_MOVEMENT_FULL
		| CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;

	/**
	 * Passability per region-and-plane. The key packs both so that a multi-level
	 * island does not collapse its floors onto each other.
	 */
	private final Map<Long, long[]> regions = new HashMap<>();

	/**
	 * Region ids that may have an entry in {@link #regions}, on any plane. Nearly every tile a
	 * far golem asks about is somewhere the player has never been, and finding that out boxed a
	 * key several times a step; a clear bit answers with an array read. A set bit only means
	 * look, so it may outlive the entry.
	 */
	private final boolean[] mayHold = new boolean[1 << 16];

	/** Notes that {@link #regions} now holds this key. */
	private void held(long key)
	{
		int regionId = (int) (key >> 8);
		if (regionId >= 0 && regionId < mayHold.length)
		{
			mayHold[regionId] = true;
		}
	}

	/** Empties {@link #regions}, and what is known about what it holds. */
	private void clearRegions()
	{
		regions.clear();
		java.util.Arrays.fill(mayHold, false);
	}

	/** Regions harvested this session, so a reload is not redone every scene change. */
	private final Set<Long> harvested = new HashSet<>();

	/**
	 * Which tiles of a harvested region have actually been read from a scene, one bit a tile,
	 * keyed as {@link #regions}. No entry means fully known: the shipped island map, or a save
	 * from before this was kept.
	 *
	 * <p>A region is 64 tiles square and a scene rarely shows all of one. Unread tiles were
	 * zeros, zeros read as walls, and those walls stood in front of the shipped mesh for the
	 * whole region — golems were rescued off cave ground the mesh knows perfectly well.
	 */
	private final Map<Long, long[]> seen = new HashMap<>();

	private static final int TILE_WORDS = REGION_SIZE * REGION_SIZE / Long.SIZE;

	private static void markSeen(long[] mask, int rx, int ry)
	{
		int tile = ry * REGION_SIZE + rx;
		mask[tile >> 6] |= 1L << (tile & 63);
	}

	private static boolean isSeen(long[] mask, int rx, int ry)
	{
		int tile = ry * REGION_SIZE + rx;
		return (mask[tile >> 6] >>> (tile & 63) & 1L) != 0L;
	}

	/**
	 * The region the first golem was seen in; everything the island is taken to be is measured
	 * from here. Hardcoding Wyrmscraig's region IDs is not available: the content is newer than
	 * this plugin, and a wrong constant would silently disable free roam.
	 */
	@Getter
	private int anchorRegionId = -1;

	@Getter
	private boolean dirty = false;

	@Inject
	private Client client;

	@Inject
	private WorldMesh worldMesh;

	// ---- the shipped baseline ----

	/**
	 * Loads the bundled island map without disturbing anything already learned. Merged
	 * <i>under</i> what is there, because a live harvest reflects the island as it is now. Called
	 * at start-up, before the saved map is restored, so it is the floor free roam stands on when
	 * the player has never been to Wyrmscraig.
	 */
	void loadBundled()
	{
		try (InputStream raw = IslandMemory.class.getResourceAsStream(BUNDLED_MAP))
		{
			if (raw == null)
			{
				log.warn("Bundled island map missing from the jar");
				return;
			}

			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 java.io.DataInputStream data = new java.io.DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int regionId = data.readInt();
					int plane = data.readInt();
					byte[] packed = new byte[BITS_PER_REGION / 8];
					data.readFully(packed);

					long key = key(regionId, plane);
					if (regions.containsKey(key))
					{
						// A live scene is the better source, but only for the tiles it showed;
						// the rest are filled from the shipped map to make the region whole.
						long[] mask = seen.remove(key);
						if (mask != null)
						{
							fillUnseen(regions.get(key), toWords(packed), mask);
						}
						continue;
					}
					regions.put(key, toWords(packed));
					held(key);
				}

				if (anchorRegionId == -1)
				{
					anchorRegionId = GolemContent.WYRMSCRAIG_REGION;
				}
				log.debug("Loaded bundled island map: {} region-planes", count);
			}
		}
		catch (IOException | RuntimeException e)
		{
			// Survivable: golems fall back to roaming only what the player has walked.
			log.warn("Bundled island map unreadable", e);
		}
	}

	/** Copies both edges of every tile the mask has not seen from {@code source} into {@code target}. */
	private static void fillUnseen(long[] target, long[] source, long[] mask)
	{
		for (int ry = 0; ry < REGION_SIZE; ry++)
		{
			for (int rx = 0; rx < REGION_SIZE; rx++)
			{
				if (isSeen(mask, rx, ry))
				{
					continue;
				}
				for (int flag = 0; flag < FLAGS_PER_TILE; flag++)
				{
					int bit = bitIndex(rx, ry, flag);
					long one = 1L << (bit & 63);
					target[bit >> 6] = (target[bit >> 6] & ~one) | (source[bit >> 6] & one);
				}
			}
		}
	}

	/** Repacks the bundled byte layout into the long words used at runtime. */
	private static long[] toWords(byte[] packed)
	{
		long[] words = new long[WORDS_PER_REGION];
		for (int i = 0; i < packed.length; i++)
		{
			words[i >> 3] |= (packed[i] & 0xFFL) << ((i & 7) * 8);
		}
		return words;
	}

	// ---- learning ----

	/**
	 * Records where the golems live, if it is not already known. Called the first
	 * time a golem is seen.
	 */
	void anchorAt(WorldPoint point)
	{
		if (anchorRegionId == -1)
		{
			anchorRegionId = point.getRegionID();
			dirty = true;
			log.debug("Island anchored at region {}", anchorRegionId);
		}
	}

	/**
	 * True once there is an anchor. With the bundled map loaded this is true from
	 * start-up, so golems can roam before the player has ever seen one made.
	 */
	boolean hasAnchor()
	{
		return anchorRegionId != -1;
	}

	/**
	 * True if the player is close enough to the island for golems to be worth
	 * simulating. Away from Wyrmscraig the whole plugin should cost nothing.
	 */
	boolean playerNearIsland()
	{
		if (!hasAnchor())
		{
			return false;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return false;
		}
		for (int regionId : wv.getMapRegions())
		{
			if (withinIsland(regionId))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * True if a region is part of the island. A fixed list rather than a radius: the bundled map
	 * defines exactly which regions the golems have, so harvesting outside it would accumulate
	 * ground they can never reach.
	 */
	private boolean withinIsland(int regionId)
	{
		for (int island : GolemContent.ISLAND_REGIONS)
		{
			if (island == regionId)
			{
				return true;
			}
		}
		return alsoIsland != null && alsoIsland.test(regionId);
	}

	/**
	 * Regions beyond the nine around the plinth that golems can reach and so need mapping:
	 * wherever a transport from the island leads. Set by the plugin, which has the network. The
	 * cathedral's basement is under the island but in another region, and golems that went down
	 * found nowhere to walk.
	 */
	private java.util.function.IntPredicate alsoIsland;

	void setAlsoIsland(java.util.function.IntPredicate alsoIsland)
	{
		this.alsoIsland = alsoIsland;
	}

	/**
	 * Copies passability for every island region currently loaded out of the scene. Bounded to
	 * regions near the anchor, so walking across the rest of Gielinor does not accumulate a
	 * world map in the player's config.
	 */
	/**
	 * Asks for one more harvest pass. Called when the scene is rebuilt, because nothing about
	 * the scene changes between ticks: harvesting every tick re-scanned in full, sixty times a
	 * minute, every region clipped by the scene edge, which can never have all 4096 of its
	 * tiles in the scene at once.
	 */
	void sceneChanged()
	{
		pendingHarvest = true;
	}

	private boolean pendingHarvest = true;

	void harvestLoadedRegions()
	{
		if (!pendingHarvest)
		{
			return;
		}
		pendingHarvest = false;

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !hasAnchor())
		{
			return;
		}

		CollisionData[] maps = wv.getCollisionMaps();
		int plane = wv.getPlane();
		if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return;
		}
		int[][] flags = maps[plane].getFlags();
		if (flags == null)
		{
			return;
		}

		if (wv.isInstance())
		{
			harvestInstance(wv, plane, flags);
			return;
		}

		int baseX = wv.getBaseX();
		int baseY = wv.getBaseY();

		for (int regionId : wv.getMapRegions())
		{
			long key = key(regionId, plane);
			if (!withinIsland(regionId) || harvested.contains(key))
			{
				continue;
			}

			if (!regions.containsKey(key))
			{
				seen.put(key, new long[TILE_WORDS]);
			}
			long[] bits = regions.computeIfAbsent(key, k -> new long[WORDS_PER_REGION]);
			held(key);
			long[] seenHere = seen.get(key);
			int regionBaseX = (regionId >> 8) << 6;
			int regionBaseY = (regionId & 0xFF) << 6;
			int tilesSeen = 0;

			for (int rx = 0; rx < REGION_SIZE; rx++)
			{
				for (int ry = 0; ry < REGION_SIZE; ry++)
				{
					int sceneX = regionBaseX + rx - baseX;
					int sceneY = regionBaseY + ry - baseY;
					if (sceneX < SCENE_MARGIN || sceneY < SCENE_MARGIN
						|| sceneX >= Constants.SCENE_SIZE - SCENE_MARGIN
						|| sceneY >= Constants.SCENE_SIZE - SCENE_MARGIN
						|| sceneX >= flags.length || sceneY >= flags[sceneX].length)
					{
						continue;
					}

					tilesSeen++;

					// Cleared before being set: a harvest that only added open edges left a door
					// open in memory after it was shut. An edge is only rewritten where the
					// tile it leads to is inside the harvested area; beyond that the scene's
					// border would answer.
					boolean northKnown = sceneY + 1 < Constants.SCENE_SIZE - SCENE_MARGIN;
					boolean eastKnown = sceneX + 1 < Constants.SCENE_SIZE - SCENE_MARGIN;
					// A tile on the harvest's far edge has an edge nobody could read; counting
					// it seen would make that edge a wall, so the mesh answers instead.
					if (seenHere != null && northKnown && eastKnown)
					{
						markSeen(seenHere, rx, ry);
					}
					int here = flags[sceneX][sceneY];
					boolean blocked = (here & UNWALKABLE) != 0;
					if (northKnown || blocked)
					{
						clear(bits, rx, ry, FLAG_NORTH);
					}
					if (eastKnown || blocked)
					{
						clear(bits, rx, ry, FLAG_EAST);
					}
					if (blocked)
					{
						continue;
					}

					// North and east are blocked by a wall here or by the destination being
					// unstandable. At a region edge the destination may be outside the scene:
					// leave the bit clear for the neighbour's harvest.
					if (northKnown && (here & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0
						&& standable(flags, sceneX, sceneY + 1))
					{
						set(bits, rx, ry, FLAG_NORTH);
					}
					if (eastKnown && (here & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0
						&& standable(flags, sceneX + 1, sceneY))
					{
						set(bits, rx, ry, FLAG_EAST);
					}
				}
			}

			if (tilesSeen > 0)
			{
				dirty = true;
			}

			// Only done when every tile was actually in the scene: the scene is 104 tiles
			// square and regions are 64, so edge regions are always clipped, and marking one
			// complete would freeze it half-scanned with holes that never fill.
			if (tilesSeen == REGION_SIZE * REGION_SIZE)
			{
				harvested.add(key);
				seen.remove(key);
				log.debug("Harvested island region {} plane {}", regionId, plane);
			}
		}
	}

	/**
	 * Records an instance's ground under its template's coordinates, which is where golems in an
	 * instance are simulated. The template room is sealed off — nothing leads into it on foot,
	 * which is why golems that wandered in were stuck — so its floor can only be learned from an
	 * instance built on it. An edge is only recorded where both tiles come from the same
	 * template, side by side: chunks are stitched together as the instance is built, so
	 * neighbours there need not be neighbours in the world.
	 */
	private void harvestInstance(WorldView wv, int plane, int[][] flags)
	{
		int edgeX = Math.min(flags.length, wv.getSizeX()) - SCENE_MARGIN;
		for (int sceneX = SCENE_MARGIN; sceneX < edgeX; sceneX++)
		{
			int edgeY = Math.min(flags[sceneX].length, wv.getSizeY()) - SCENE_MARGIN;
			for (int sceneY = SCENE_MARGIN; sceneY < edgeY; sceneY++)
			{
				int[] here = template(wv, plane, sceneX, sceneY);
				if (here == null)
				{
					continue;
				}
				long key = key(regionIdOf(here[0], here[1]), here[2]);
				if (!regions.containsKey(key))
				{
					seen.put(key, new long[TILE_WORDS]);
				}
				long[] bits = regions.computeIfAbsent(key, k -> new long[WORDS_PER_REGION]);
				held(key);
				int rx = here[0] & REGION_MASK;
				int ry = here[1] & REGION_MASK;
				long[] seenHere = seen.get(key);
				if (seenHere != null)
				{
					markSeen(seenHere, rx, ry);
				}
				boolean northKnown = sceneY + 1 < edgeY;
				boolean eastKnown = sceneX + 1 < edgeX;
				boolean blocked = (flags[sceneX][sceneY] & UNWALKABLE) != 0;
				if (northKnown || blocked)
				{
					clear(bits, rx, ry, FLAG_NORTH);
				}
				if (eastKnown || blocked)
				{
					clear(bits, rx, ry, FLAG_EAST);
				}
				if (blocked)
				{
					continue;
				}
				int[] north = template(wv, plane, sceneX, sceneY + 1);
				if (northKnown && (flags[sceneX][sceneY] & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0
					&& standable(flags, sceneX, sceneY + 1)
					&& north != null && north[0] == here[0] && north[1] == here[1] + 1 && north[2] == here[2])
				{
					set(bits, rx, ry, FLAG_NORTH);
				}
				int[] east = template(wv, plane, sceneX + 1, sceneY);
				if (eastKnown && (flags[sceneX][sceneY] & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0
					&& standable(flags, sceneX + 1, sceneY)
					&& east != null && east[0] == here[0] + 1 && east[1] == here[1] && east[2] == here[2])
				{
					set(bits, rx, ry, FLAG_EAST);
				}
			}
		}
		dirty = true;
	}

	/** {x, y, plane} of the template tile under a scene tile, or null. Unrotated chunks only. */
	private static int[] template(WorldView wv, int plane, int sceneX, int sceneY)
	{
		int data = InstanceMap.chunkAt(wv, plane, sceneX, sceneY);
		if (data <= 0 || InstanceMap.rotation(data) != 0)
		{
			return null;
		}
		return new int[]{InstanceMap.templateChunkX(data) * 8 + (sceneX & 7),
			InstanceMap.templateChunkY(data) * 8 + (sceneY & 7), InstanceMap.templatePlane(data)};
	}

	private static boolean standable(int[][] flags, int sceneX, int sceneY)
	{
		if (sceneX < 0 || sceneY < 0
			|| sceneX >= flags.length || flags[sceneX] == null || sceneY >= flags[sceneX].length)
		{
			return false;
		}
		return (flags[sceneX][sceneY] & UNWALKABLE) == 0;
	}

	// ---- querying ----

	/** True if the tile has been harvested and something may stand on it. */
	boolean isKnownWalkable(int worldX, int worldY, int plane)
	{
		// Walkable if it can be left in any direction; an isolated tile with no exits is
		// of no use to a wandering golem.
		return north(worldX, worldY, plane) || east(worldX, worldY, plane)
			|| north(worldX, worldY - 1, plane) || east(worldX - 1, worldY, plane);
	}

	boolean north(int x, int y, int plane)
	{
		return get(x, y, plane, FLAG_NORTH);
	}

	boolean east(int x, int y, int plane)
	{
		return get(x, y, plane, FLAG_EAST);
	}

	/** The four cardinals, named as the collision format stores them. */
	private boolean south(int x, int y, int plane)
	{
		return north(x, y - 1, plane);
	}

	private boolean west(int x, int y, int plane)
	{
		return east(x - 1, y, plane);
	}

	/**
	 * Can something step one tile from (x, y), cardinal or diagonal? A diagonal is a corner and
	 * the game will not cut one: both ways round must be clear, or a golem would slip between
	 * two walls meeting at a point. The four-term tests below are the game's own rule, from
	 * Shortest Path's {@code CollisionMap}. Diagonals matter — Port Tasks' sailing routes are
	 * 854 perfect diagonals against 817 axis-aligned segments.
	 */
	boolean canStep(int x, int y, int plane, int dx, int dy)
	{
		if (dx == 0 && dy == 1)
		{
			return north(x, y, plane);
		}
		if (dx == 0 && dy == -1)
		{
			return south(x, y, plane);
		}
		if (dx == 1 && dy == 0)
		{
			return east(x, y, plane);
		}
		if (dx == -1 && dy == 0)
		{
			return west(x, y, plane);
		}
		if (dx == 1 && dy == 1)
		{
			return north(x, y, plane) && east(x, y + 1, plane)
				&& east(x, y, plane) && north(x + 1, y, plane);
		}
		if (dx == -1 && dy == 1)
		{
			return north(x, y, plane) && west(x, y + 1, plane)
				&& west(x, y, plane) && north(x - 1, y, plane);
		}
		if (dx == 1 && dy == -1)
		{
			return south(x, y, plane) && east(x, y - 1, plane)
				&& east(x, y, plane) && south(x + 1, y, plane);
		}
		if (dx == -1 && dy == -1)
		{
			return south(x, y, plane) && west(x, y - 1, plane)
				&& west(x, y, plane) && south(x - 1, y, plane);
		}
		return false;
	}

	/**
	 * Passability for one tile and direction, live harvest first: a harvest reflects the world
	 * as it is now where the mesh was only true when generated, which also covers the window
	 * between a game update and the mesh being rebuilt. The mesh below it is what lets a golem
	 * walk ground the player has never stood on.
	 */
	private boolean get(int x, int y, int plane, int flag)
	{
		// The client does not block the open sea — boats sail it — so a harvest reads it as
		// open ground, and the shipped island map lists the water off the cathedral as
		// walkable. The mesh's ocean bit marks exactly that sea, so it overrules every source.
		int toX = flag == FLAG_EAST ? x + 1 : x;
		int toY = flag == FLAG_NORTH ? y + 1 : y;
		if (worldMesh.isOcean(x, y, plane) || worldMesh.isOcean(toX, toY, plane)
			|| worldMesh.isInlandWater(x, y, plane) || worldMesh.isInlandWater(toX, toY, plane))
		{
			return false;
		}

		int regionId = regionIdOf(x, y);
		long key = key(regionId, plane);
		long[] bits = regionId >= 0 && regionId < mayHold.length && !mayHold[regionId] ? null : regions.get(key);
		long[] mask = bits == null ? null : seen.get(key);
		if (bits != null && (mask == null || isSeen(mask, x & REGION_MASK, y & REGION_MASK)))
		{
			int bit = bitIndex(x & REGION_MASK, y & REGION_MASK, flag);
			return (bits[bit >> 6] >>> (bit & 63) & 1L) != 0L;
		}

		// The mesh says water is passable, because it is — to a boat. A step is refused unless
		// both ends are ground the land fill reached; both, because land beside water has a
		// perfectly open edge leading off the beach.
		//
		// The land mask, not the ocean bit: ocean marks only the one connected sea, so cave
		// water, lakes and enclosed basins passed the old check, most visibly inside
		// Wyrmscraig's caves. The live harvest needs no such check, except that the client
		// does not block water a boat can sail — which is why the sea and the underground lake
		// are refused first. See WorldMesh.isInlandWater.
		if (flag == FLAG_NORTH)
		{
			return worldMesh.isLandWalkable(x, y, plane)
				&& worldMesh.isLandWalkable(x, y + 1, plane)
				&& worldMesh.north(x, y, plane);
		}
		return worldMesh.isLandWalkable(x, y, plane)
			&& worldMesh.isLandWalkable(x + 1, y, plane)
			&& worldMesh.east(x, y, plane);
	}

	private static void clear(long[] bits, int rx, int ry, int flag)
	{
		int bit = bitIndex(rx, ry, flag);
		bits[bit >> 6] &= ~(1L << (bit & 63));
	}

	/**
	 * Something that changes passability was added or removed — a door opening or shutting — so
	 * its region is read again on the next harvest. A region was harvested once a session and
	 * then trusted, which a door makes wrong: open when read, shut a minute later, and golems
	 * still walking through.
	 */
	void passabilityChanged(WorldPoint at)
	{
		if (at == null || !withinIsland(at.getRegionID()))
		{
			return;
		}
		harvested.remove(key(at.getRegionID(), at.getPlane()));
		pendingHarvest = true;
	}

	private static void set(long[] bits, int rx, int ry, int flag)
	{
		int bit = bitIndex(rx, ry, flag);
		bits[bit >> 6] |= 1L << (bit & 63);
	}

	private static int bitIndex(int rx, int ry, int flag)
	{
		return (ry * REGION_SIZE + rx) * FLAGS_PER_TILE + flag;
	}

	private static int regionIdOf(int worldX, int worldY)
	{
		return ((worldX >> 6) << 8) | (worldY >> 6);
	}

	private static long key(int regionId, int plane)
	{
		return ((long) regionId << 8) | (plane & 0xFF);
	}

	// ---- persistence ----

	/**
	 * Encodes the whole memory as one string: anchor, then each region-plane's bits, gzipped
	 * and base64'd. Compression is not a nicety — a region is 1KB of flags and a passability
	 * map is overwhelmingly long runs of "walkable", so it deflates to a fraction, which is the
	 * difference between a config value and an abuse of one.
	 */
	String serialise()
	{
		try
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			try (GZIPOutputStream gz = new GZIPOutputStream(out);
				 java.io.DataOutputStream data = new java.io.DataOutputStream(gz))
			{
				data.writeInt(anchorRegionId);
				data.writeInt(regions.size());
				for (Map.Entry<Long, long[]> entry : regions.entrySet())
				{
					data.writeLong(entry.getKey());
					for (long word : entry.getValue())
					{
						data.writeLong(word);
					}
				}
				// Which tiles of each partly harvested region were read; after the regions,
				// so a save without this section still loads.
				data.writeInt(seen.size());
				for (Map.Entry<Long, long[]> entry : seen.entrySet())
				{
					data.writeLong(entry.getKey());
					for (long word : entry.getValue())
					{
						data.writeLong(word);
					}
				}
			}
			dirty = false;
			return Base64.getEncoder().encodeToString(out.toByteArray());
		}
		catch (IOException e)
		{
			log.warn("Could not save island map", e);
			return "";
		}
	}

	/** Restores a memory previously written by {@link #serialise()}. */
	void deserialise(String encoded)
	{
		clearRegions();
		harvested.clear();
		seen.clear();
		anchorRegionId = -1;
		dirty = false;

		if (encoded == null || encoded.isEmpty())
		{
			return;
		}

		try (GZIPInputStream gz = new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(encoded)));
			 java.io.DataInputStream data = new java.io.DataInputStream(gz))
		{
			anchorRegionId = data.readInt();
			int count = data.readInt();
			for (int i = 0; i < count; i++)
			{
				long key = data.readLong();
				long[] words = new long[WORDS_PER_REGION];
				for (int w = 0; w < WORDS_PER_REGION; w++)
				{
					words[w] = data.readLong();
				}
				regions.put(key, words);
				held(key);
				// Deliberately not added to `harvested`: a restored region is re-scanned
				// once when it next loads, so map edits heal themselves.
			}

			boolean masked;
			try
			{
				int masks = data.readInt();
				for (int i = 0; i < masks; i++)
				{
					long key = data.readLong();
					long[] words = new long[TILE_WORDS];
					for (int w = 0; w < TILE_WORDS; w++)
					{
						words[w] = data.readLong();
					}
					seen.put(key, words);
				}
				masked = true;
			}
			catch (java.io.EOFException e)
			{
				masked = false;
			}

			// A save from before seen tiles were kept cannot tell a wall from a tile it never
			// read. Best guess: a tile with an open edge was read, one with none is left to
			// the mesh, which keeps ground only a harvest knows. Island regions have the
			// shipped map filled in under the guess.
			if (!masked)
			{
				for (Map.Entry<Long, long[]> entry : regions.entrySet())
				{
					long[] words = entry.getValue();
					long[] mask = new long[TILE_WORDS];
					for (int ry = 0; ry < REGION_SIZE; ry++)
					{
						for (int rx = 0; rx < REGION_SIZE; rx++)
						{
							for (int flag = 0; flag < FLAGS_PER_TILE; flag++)
							{
								int bit = bitIndex(rx, ry, flag);
								if ((words[bit >> 6] >>> (bit & 63) & 1L) != 0L)
								{
									markSeen(mask, rx, ry);
								}
							}
						}
					}
					seen.put(entry.getKey(), mask);
				}
				dirty = true;
			}
			log.debug("Loaded island map: anchor {}, {} region-planes, {} partly read", anchorRegionId,
				regions.size(), seen.size());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Island map unreadable, starting fresh", e);
			clearRegions();
			anchorRegionId = -1;
		}
	}

	/** Throws away everything learned. */
	void forget()
	{
		clearRegions();
		harvested.clear();
		seen.clear();
		anchorRegionId = -1;
		dirty = true;
	}
}

package com.golemsdontdie;

import java.awt.Shape;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxPanelManager;

/**
 * Gives the copies the right-click menu the real golems have.
 *
 * <p>A {@link net.runelite.api.RuneLiteObjectController} is drawn by the client but is not
 * an entity it builds a menu from, so hovering a copy would otherwise produce nothing. The
 * hit test is done by hand each tick, against the posed model's clickbox. Entries use
 * {@link MenuAction#RUNELITE} with their own handlers, so nothing reaches the server.
 */
@Singleton
class GolemMenu
{
	/** Target colour the client uses for an NPC with no combat level. */
	private static final String NPC_COLOUR = "<col=ffff00>";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	/** Told when a golem is named here, so the roster is saved and the sidebar shows it. */
	private Consumer<Golem> onRenamed = golem ->
	{
	};

	void setOnRenamed(Consumer<Golem> onRenamed)
	{
		this.onRenamed = onRenamed;
	}

	/**
	 * Adds entries for whichever golem is under the cursor. Called once per client tick,
	 * when the client rebuilds its menu. Only the topmost golem gets entries.
	 */
	void addEntries(List<Golem> golems)
	{
		if (client.isMenuOpen() || golems.isEmpty())
		{
			return;
		}

		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || mouse.getX() < 0 || mouse.getY() < 0)
		{
			return;
		}

		Golem hovered = topmostAt(golems, mouse);
		if (hovered == null)
		{
			return;
		}

		// Shown by its name. Every real golem is called "Golem", so this costs some of the
		// disguise, but a name is only there because the player put it there.
		String name = hovered.getNickname();
		if (name == null || name.isEmpty())
		{
			name = hovered.getSnapshot().getName();
		}
		String target = NPC_COLOUR + name + "</col>";

		// Index 1, immediately above Cancel, which the client keeps at index 0. The menu
		// array is drawn bottom-up: inserting at 0 put Examine *below* Cancel.
		client.getMenu().createMenuEntry(1)
			.setOption("Examine")
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> message(GolemContent.GOLEM_EXAMINE));

		// Shift held, as NPC Indicators offers its tag. Added after Examine at the same
		// index, so it sits just above Cancel.
		if (client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			client.getMenu().createMenuEntry(1)
				.setOption("Set Name")
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> askForName(hovered));
		}
	}

	/** Opens the chatbox prompt for a golem's name. Left empty, the golem is "Golem" again. */
	private void askForName(Golem golem)
	{
		String current = golem.getNickname();
		chatboxPanelManager.openTextInput("Name this golem")
			.value(current == null ? "" : current)
			// Enter arrives on the AWT thread; golems are only touched on the client's.
			.onDone((String text) -> clientThread.invoke(() ->
			{
				String name = text.trim();
				golem.setNickname(name.isEmpty() ? null : name);
				onRenamed.accept(golem);
			}))
			.build();
	}

	/**
	 * How far from the cursor, in pixels, a golem's ground point can be and still be worth
	 * an exact hit test. Generous enough for a golem drawn tall, camera zoomed in.
	 */
	private static final int CANDIDATE_RADIUS = 180;

	/**
	 * Ceiling on exact hit tests per tick. Only reached when the cursor sits over golems
	 * near it but not under it, the one case the early exit cannot help with.
	 */
	private static final int MAX_CLICKBOX_TESTS = 10;

	/** Lower on screen first — that is nearer the camera. */
	private static final Comparator<Candidate> BY_DEPTH =
		(a, b) -> Integer.compare(b.screenY, a.screenY);

	/** Reused between ticks so hovering the scene does not allocate every frame. */
	private final List<Candidate> candidates = new ArrayList<>();

	/**
	 * The golem whose clickbox contains the mouse and is nearest the camera. Nearest is the
	 * largest canvas Y — in an isometric view a golem drawn lower is closer — the ordering
	 * the client's own entity picking produces. Clickboxes are only computed for golems
	 * already near the cursor: building one projects every face of the model, and doing
	 * that for a few hundred golems every client tick made the client stutter.
	 */
	private Golem topmostAt(List<Golem> golems, Point mouse)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}

		// Golems near enough the cursor to be worth an exact test.
		candidates.clear();
		for (Golem golem : golems)
		{
			FakeGolem renderer = golem.getRenderer();
			if (renderer == null)
			{
				continue;
			}

			Point ground = Perspective.localToCanvas(client,
				new LocalPoint(renderer.getX(), renderer.getY(), wv), golem.getPlane());
			if (ground == null
				|| Math.abs(ground.getX() - mouse.getX()) > CANDIDATE_RADIUS
				|| Math.abs(ground.getY() - mouse.getY()) > CANDIDATE_RADIUS)
			{
				continue;
			}
			candidates.add(new Candidate(golem, ground.getY()));
		}

		// Nearest the camera first, so the first golem whose box contains the cursor is the
		// answer and the rest are never projected — the early exit that keeps this cheap
		// when hundreds are piled under the mouse, where the radius filter cannot.
		candidates.sort(BY_DEPTH);

		int tested = 0;
		for (Candidate candidate : candidates)
		{
			if (tested++ >= MAX_CLICKBOX_TESTS)
			{
				// In a pile this deep, one more golem's
				// right-click is not worth a frame drop.
				break;
			}
			Shape clickbox = candidate.golem.getRenderer().clickbox();
			if (clickbox != null && clickbox.contains(mouse.getX(), mouse.getY()))
			{
				return candidate.golem;
			}
		}
		return null;
	}

	/** A golem near the cursor, with how far down the screen it is drawn. */
	private static final class Candidate
	{
		final Golem golem;
		final int screenY;

		Candidate(Golem golem, int screenY)
		{
			this.golem = golem;
			this.screenY = screenY;
		}
	}

	/** Sent as the game sends a real NPC's examine, so chat filters and colours treat it as one. */
	private void message(String text)
	{
		client.addChatMessage(ChatMessageType.NPC_EXAMINE, "", text, null);
	}
}

package com.golemsdontdie;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the copies onto the minimap, the way a real golem is drawn.
 *
 * <p>The client dots every NPC whose composition asks for one, and the golem's does; a
 * {@link net.runelite.api.RuneLiteObject} is not an NPC, so the copies showed as bare minimap
 * beside real golems. The dot is the game's own sprite, not an approximation: the real one is a
 * shaded circle, and two subtly different yellow dots draw the eye to the fakes. Drawing is
 * clipped to the minimap widget so a golem at the edge slides under the frame.
 */
class GolemMinimapOverlay extends Overlay
{
	/**
	 * Candidate minimap widgets, one per interface layout. Only one exists at a time, and which
	 * depends on settings this plugin does not read, so all four are tried.
	 */
	private static final int[] MINIMAP_WIDGETS = {
		InterfaceID.Toplevel.MINIMAP,
		InterfaceID.ToplevelOsrsStretch.MINIMAP,
		InterfaceID.ToplevelPreEoc.MINIMAP,
		InterfaceID.ToplevelOsm.MINIMAP,
	};

	/** How far the minimap reaches, in tiles, zoomed all the way out. Beyond this, skip the projection. */
	private static final int MINIMAP_RANGE_TILES = 40;

	private final Client client;
	private final GolemsDontDiePlugin plugin;
	private final SpriteManager spriteManager;

	/** The game's yellow NPC dot, fetched once the sprite cache can supply it. */
	private BufferedImage dot;

	@Inject
	GolemMinimapOverlay(Client client, GolemsDontDiePlugin plugin, SpriteManager spriteManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<Golem> golems = plugin.drawnGolems();
		if (golems.isEmpty())
		{
			return null;
		}

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}

		if (dot == null)
		{
			// Lazily: the sprite cache may not be ready at start-up, and null means
			// trying again next frame.
			dot = spriteManager.getSprite(SpriteID.MapdotsInterface.YELLOW_NPC, 0);
			if (dot == null)
			{
				return null;
			}
		}

		Rectangle minimap = minimapBounds();
		if (minimap == null)
		{
			return null;
		}

		// Beyond the minimap's reach no projection can yield a dot, and a tile-distance test is
		// two subtractions against a matrix transform — this runs every frame with hundreds of
		// golems. Measured in the main world, aboard a boat too; see PlayerPosition.
		WorldPoint me = PlayerPosition.of(client);
		if (me == null)
		{
			return null;
		}
		int playerX = me.getX();
		int playerY = me.getY();

		Shape original = graphics.getClip();
		graphics.setClip(minimap);
		try
		{
			for (Golem golem : golems)
			{
				// Only golems in the scene: one that has wandered out is off the minimap
				// anyway, and its local coordinates would be meaningless. Where it is drawn, not
				// where it is simulated: inside an instance the two are rooms apart.
				if (golem.getRenderer() == null || golem.getDrawPlane() != wv.getPlane())
				{
					continue;
				}

				if (Math.abs(golem.getDrawFineX() / Golem.TILE - playerX) > MINIMAP_RANGE_TILES
					|| Math.abs(golem.getDrawFineY() / Golem.TILE - playerY) > MINIMAP_RANGE_TILES)
				{
					continue;
				}

				int localX = golem.getDrawFineX() - wv.getBaseX() * Golem.TILE;
				int localY = golem.getDrawFineY() - wv.getBaseY() * Golem.TILE;
				if (!Golem.isInScene(wv, localX, localY))
				{
					continue;
				}

				Point at = Perspective.localToMinimap(client, new LocalPoint(localX, localY, wv));
				if (at == null)
				{
					continue;
				}

				// Centred on the point, matching how the client places its own dots.
				graphics.drawImage(dot,
					at.getX() - dot.getWidth() / 2,
					at.getY() - dot.getHeight() / 2,
					null);
			}
		}
		finally
		{
			graphics.setClip(original);
		}

		return null;
	}

	/**
	 * The on-screen rectangle of whichever minimap widget is live.
	 *
	 * @return the bounds, or null if no minimap is showing
	 */
	private Rectangle minimapBounds()
	{
		for (int id : MINIMAP_WIDGETS)
		{
			Widget widget = client.getWidget(id);
			if (widget != null && !widget.isHidden())
			{
				return widget.getBounds();
			}
		}
		return null;
	}
}

