package com.golemsdontdie;

/**
 * Whether a learned route follows the obstacle it was learned from.
 *
 * <p>An obstacle moves the player along a fixed line: a stile from one of its tiles to the other.
 * A route is the two tiles a golem gets on and off at, travelled in a straight line, so off that
 * line is off the obstacle. That is how the stile came to be crossed diagonally — its ends came
 * from where the player happened to stand, eighteen degrees off. Such a route is refused when
 * learned and ignored if already saved.
 */
final class RouteGeometry
{
	/**
	 * How far off an obstacle's line a route may run. Both are whole tiles, so a real route is on
	 * the line or off by a whole tile's angle — the diagonal stile was eighteen — never between.
	 */
	static final double MAX_DEGREES_OFF = 10;

	/** Beyond this many tiles a traversal is a teleport (cave mouth, staircase) with no line. */
	static final int LOCAL_TILES = 8;

	private RouteGeometry()
	{
	}

	/** True if a movement is short enough to have a line at all. */
	static boolean local(int dx, int dy)
	{
		return (dx != 0 || dy != 0) && Math.abs(dx) <= LOCAL_TILES && Math.abs(dy) <= LOCAL_TILES;
	}

	/**
	 * True if a route runs along a line, either direction. A line of (0, 0) is unknown and a
	 * non-local route has none, so both pass; only a short route beside a known line is refused.
	 */
	static boolean follows(int routeX, int routeY, int lineX, int lineY)
	{
		if (!local(lineX, lineY) || !local(routeX, routeY))
		{
			return true;
		}
		return degreesOff(routeX, routeY, lineX, lineY) <= MAX_DEGREES_OFF;
	}

	static double degreesOff(int routeX, int routeY, int lineX, int lineY)
	{
		double cos = Math.abs(routeX * lineX + routeY * lineY)
			/ (Math.hypot(routeX, routeY) * Math.hypot(lineX, lineY));
		return Math.toDegrees(Math.acos(Math.min(1, cos)));
	}

	/** A direction with length and sense removed: (0, 3), (0, -1) and (0, 2) are all (0, 1). */
	static int[] canonical(int dx, int dy)
	{
		int divisor = gcd(Math.abs(dx), Math.abs(dy));
		if (divisor == 0)
		{
			return new int[]{0, 0};
		}
		int x = dx / divisor;
		int y = dy / divisor;
		if (x < 0 || (x == 0 && y < 0))
		{
			x = -x;
			y = -y;
		}
		return new int[]{x, y};
	}

	private static int gcd(int a, int b)
	{
		return b == 0 ? a : gcd(b, a % b);
	}
}

package com.golemsdontdie;

import java.util.List;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Decides where a golem sails, and plans the crossing.
 *
 * <p>Two rules, both chosen because they need no tuning. <b>Uniform dispersal:</b> the
 * destination is drawn evenly from every port the golem may reach, since weighting by distance
 * compounds — a golem near Catherby draws Catherby's neighbours forever. <b>One blocked port:</b>
 * a golem may not sail straight back where it came from, one field of state rather than a timer,
 * leaving home reachable again from the third hop. Wyrmscraig's population thins over a long
 * session as a result, but the island refills with every craft.
 */
@Slf4j
@Singleton
class Voyage
{
	@Inject
	private SailingDocks docks;

	@Inject
	private SeaMesh sea;

	/**
	 * Present in the client, null in the offline tools, which build fields in line. Only a marker:
	 * fields are built on {@link #builder}, a queue of sea searches here having delayed config
	 * saves.
	 */
	@Inject
	private java.util.concurrent.ScheduledExecutorService executor;

	/** How many field builds may wait for the builder; beyond it a golem asks later. */
	private static final int BUILD_QUEUE = 8;

	/** One low-priority daemon thread of its own, made on first use; see {@link #shutDown}. */
	private java.util.concurrent.ThreadPoolExecutor builder;

	private synchronized java.util.concurrent.ThreadPoolExecutor builder()
	{
		if (builder == null)
		{
			builder = new java.util.concurrent.ThreadPoolExecutor(1, 1, 30, java.util.concurrent.TimeUnit.SECONDS,
				new java.util.concurrent.ArrayBlockingQueue<>(BUILD_QUEUE), task ->
				{
					Thread thread = new Thread(task, "golems-sea-fields");
					thread.setDaemon(true);
					thread.setPriority(Thread.MIN_PRIORITY);
					return thread;
				});
			builder.allowCoreThreadTimeOut(true);
		}
		return builder;
	}

	/**
	 * Stops the builder and forgets every field, when the plugin stops.
	 *
	 * <p>Queued builds are dropped and the thread is left to finish the one in hand, which takes a
	 * fraction of a second and touches nothing but the mesh. It is a daemon thread and times out
	 * when idle, so nothing holds the client open.
	 */
	synchronized void shutDown()
	{
		if (builder != null)
		{
			builder.getQueue().clear();
			builder.shutdown();
			builder = null;
		}
		building.clear();
		synchronized (fields)
		{
			fields.clear();
			cachedTiles = 0;
		}
	}

	/**
	 * Plans a crossing from a dock, or returns null if the golem should stay ashore.
	 *
	 * @param from   the dock the golem is leaving
	 * @param memory the golem's own memory, consulted and updated for the blocked port
	 */
	Itinerary depart(SailingDocks.Dock from, WorldPoint at, TransportMemory memory, int tick, Random random,
		RoamContext context)
	{
		List<SailingDocks.Dock> open = docks.openDocks();
		if (open.size() < 2)
		{
			return null;
		}

		// Candidates: anywhere open, except here and except where we just came from.
		List<SailingDocks.Dock> candidates = new java.util.ArrayList<>(open);
		candidates.removeIf(d -> d.getRowId() == from.getRowId()
			|| d.getRowId() == memory.getBlockedPort());

		if (candidates.isEmpty())
		{
			// Deliberately not relaxed: if the only place left is where we came from, the golem
			// roams locally rather than bouncing between two docks.
			return null;
		}

		// The port it already chose, if still waiting at this dock to sail there; waited long
		// enough, it gives up.
		SailingDocks.Dock chosen = null;
		if (memory.getPendingPort() >= 0 && memory.getPendingFrom() != from.getRowId())
		{
			memory.clearPending();
		}
		if (memory.getPendingPort() >= 0 && tick > memory.getPendingUntil())
		{
			memory.clearPending();
			return null;
		}
		for (SailingDocks.Dock candidate : candidates)
		{
			if (candidate.getRowId() == memory.getPendingPort())
			{
				chosen = candidate;
			}
		}
		if (chosen == null)
		{
			// A few tries for a port with room ashore, then wherever the last roll lands.
			for (int attempt = 0; attempt < 3 && chosen == null; attempt++)
			{
				SailingDocks.Dock candidate = candidates.get(random.nextInt(candidates.size()));
				WorldPoint shore = candidate.getShore();
				float roominess = context == null || shore == null ? 1f
					: context.roominess(shore.getX(), shore.getY(), shore.getPlane());
				if (roominess >= 1f || random.nextFloat() < roominess)
				{
					chosen = candidate;
				}
			}
			if (chosen == null)
			{
				chosen = candidates.get(random.nextInt(candidates.size()));
			}
		}

		notReady = false;
		Itinerary crossing = crossTo(from, chosen, at, memory, tick, random, context);
		// Waiting on this crossing's field, or its one search this frame: hold the choice.
		if (crossing == null && notReady)
		{
			memory.holdPending(from.getRowId(), chosen.getRowId(), tick);
		}
		else
		{
			memory.clearPending();
		}
		return crossing;
	}

	/**
	 * Set when a crossing could not be planned only because something is not ready: a field being
	 * built, or this frame's sea search spent. Client thread only.
	 */
	private boolean notReady;

	/** Plans the crossing from one dock to a chosen other, or null if it cannot be sailed now. */
	Itinerary crossTo(SailingDocks.Dock from, SailingDocks.Dock to, WorldPoint at, TransportMemory memory, int tick,
		Random random, RoamContext context)
	{
		// A crossing that starts or ends off the open sea cannot cross the ocean mesh, the two ends
		// not being on the same water: Wyrmscraig's cave dock sits on the underground map. That is
		// a passage, not a voyage.
		boolean fromCave = isCaveDock(from);
		boolean toCave = isCaveDock(to);
		if (fromCave != toCave)
		{
			// Wyrmscraig's cave: across its lake, out through its mouth onto the sea, and on.
			return throughCave(from, to, fromCave, memory, tick, random, context);
		}
		if (!from.isOnOpenSea() || !to.isOnOpenSea())
		{
			memory.setBlockedPort(from.getRowId());
			log.debug("Golem taking the passage {} -> {}", from.getName(), to.getName());
			return passage(from, to, at, tick);
		}

		boolean searched = sea.isSearched(from.getMooring(), to.getMooring());

		if (!searched && (context == null || !context.isMaySearchSea()))
		{
			// Never computed, and the frame's one sea search is spent, so the golem tries again.
			notReady = true;
			return null;
		}

		List<int[]> route = sea.route(from.getMooring(), to.getMooring());
		if (!searched && context != null)
		{
			// Spend the budget on the attempt, not on success: a crossing with no route costs as
			// much to discover as one that has.
			context.spendSeaSearch();
		}
		if (route == null)
		{
			return null;
		}
		// From the water beside one gangplank to the other, by the shipped route between moorings.
		List<int[]> course = new java.util.ArrayList<>(route.size() + 2);
		WorldPoint setOut = from.getBerth();
		WorldPoint comeIn = to.getBerth();
		if (setOut.getX() != route.get(0)[0] || setOut.getY() != route.get(0)[1])
		{
			course.add(new int[]{setOut.getX(), setOut.getY()});
		}
		course.addAll(route);
		int[] last = route.get(route.size() - 1);
		if (comeIn.getX() != last[0] || comeIn.getY() != last[1])
		{
			course.add(new int[]{comeIn.getX(), comeIn.getY()});
		}

		SeaMesh.Field field = fieldFor(course);
		if (field == null)
		{
			// Being built. The golem waits for it.
			notReady = true;
			return null;
		}

		memory.setBlockedPort(from.getRowId());
		log.debug("Golem sailing {} -> {}", from.getName(), to.getName());

		// Gangplank to gangplank: the golem steps onto the raft on the water and off at the far
		// quayside. Beginning ashore had it gliding toward a raft not there yet.
		return steer(course, field, random, tick, to.getShore());
	}

	/** Crossings whose distance field is being built right now, so each is built once. */
	private final java.util.Set<Long> building = java.util.concurrent.ConcurrentHashMap.newKeySet();

	/**
	 * The distance field for a route, or null while it is built in the background. Safe off the
	 * client thread: it reads only the shipped mesh, fixed after load, and its route.
	 */
	private SeaMesh.Field fieldFor(List<int[]> route)
	{
		return fieldFor(route, sea.ocean);
	}

	/** As {@link #fieldFor(List)}, over a given body of water. */
	private SeaMesh.Field fieldFor(List<int[]> route, SeaMesh.Water water)
	{
		int[] start = route.get(0);
		int[] goal = route.get(route.size() - 1);
		long key = ((long) start[0] << 45) ^ ((long) start[1] << 30) ^ ((long) goal[0] << 15) ^ goal[1]
			^ (water == sea.ocean ? 0L : 0x5A5A5AL << 40);
		synchronized (fields)
		{
			SeaMesh.Field known = fields.get(key);
			if (known != null)
			{
				return known;
			}
		}
		if (executor == null)
		{
			SeaMesh.Field built = buildField(route, water);
			remember(key, built);
			return built;
		}
		if (building.add(key))
		{
			try
			{
				builder().execute(() ->
				{
					try
					{
						remember(key, buildField(route, water));
					}
					finally
					{
						building.remove(key);
					}
				});
			}
			catch (java.util.concurrent.RejectedExecutionException e)
			{
				// Queue full, or stopping. Nothing is building it, so the next golem to ask may try.
				building.remove(key);
			}
		}
		return null;
	}

	/** How far off the shortest route a golem may wander, in tiles. */
	private static final int BAND = 40;

	/** Tiles of open sea a raft keeps all round it where the water allows. */
	private static final int SHORE_CLEARANCE = 2;

	/** How near either gangplank's water a raft may hug the shore, to get in and out. */
	private static final int OPEN_NEAR_BERTH = 12;

	/**
	 * A route's field, kept off the shore where it can be: two tiles of sea all round, then one,
	 * then none, whichever first joins the two ends.
	 */
	private SeaMesh.Field buildField(List<int[]> route, SeaMesh.Water water)
	{
		int[] start = route.get(0);
		SeaMesh.Field field = null;
		for (int clearance = SHORE_CLEARANCE; clearance >= 0; clearance--)
		{
			field = sea.fieldAlong(route, BAND, clearance, OPEN_NEAR_BERTH, water);
			if (field.distance(start[0], start[1]) >= 0)
			{
				return field;
			}
		}
		return field;
	}

	/**
	 * How near the far gangplank, in tiles, a raft puts its golem ashore: a player can step off a
	 * boat this far out.
	 */
	private static final int DISEMBARK_RANGE = 10;

	/**
	 * How far the raft's bow reaches ahead of the golem, in 128ths of a tile: the golem is at the
	 * helm on the stern tile, the middle a tile ahead.
	 */
	private static final int BOW_REACH = 340;

	/** Half the raft's width, near the bow. */
	private static final int BOW_HALF_WIDTH = 80;

	/**
	 * Distance fields for the crossings most recently planned, least recently used first, so a
	 * busy port does not refill one per golem. Bounded by tiles held, not count: eight fields was
	 * far fewer than sixty ports make.
	 */
	private final java.util.LinkedHashMap<Long, SeaMesh.Field> fields = new java.util.LinkedHashMap<>(64, 0.75f, true);

	/** Tiles across every cached field. Guarded by {@link #fields}. */
	private long cachedTiles;

	/** Tiles the cache may hold, about fifty megabytes, beyond the {@link #MIN_FIELDS} kept. */
	private static final long FIELD_TILE_BUDGET = 1_250_000;

	/** Fields kept whatever their size. */
	private static final int MIN_FIELDS = 8;

	private void remember(long key, SeaMesh.Field field)
	{
		synchronized (fields)
		{
			SeaMesh.Field old = fields.put(key, field);
			cachedTiles += field.size() - (old == null ? 0 : old.size());
			java.util.Iterator<SeaMesh.Field> oldest = fields.values().iterator();
			while (fields.size() > MIN_FIELDS && cachedTiles > FIELD_TILE_BUDGET && oldest.hasNext())
			{
				cachedTiles -= oldest.next().size();
				oldest.remove();
			}
		}
	}

	/*
	 * How a boat moves, from the Turning Circles plugin; not measured against a raft here.
	 *
	 *  - It faces one of sixteen compass points and turns one point, 128 of 2048, per tick, moving
	 *    as it turns, which makes a turn an arc.
	 *  - It only moves the way it faces, speed changing toward the chosen speed by a fixed
	 *    acceleration each tick, each axis rounded to a quarter tile.
	 */

	/** One compass point, in the client's 2048ths of a turn: the most a boat turns in a tick. */
	private static final int TURN_PER_TICK = 128;

	/** A raft at full sail, 1.5 tiles a tick, and at half speed, 1 tile a tick, in 128ths of a tile. */
	private static final int FULL_SPEED = 192;
	private static final int HALF_SPEED = 128;

	/** Speed gained or lost in a tick. Not in the cache, and a guess until it is measured. */
	private static final int ACCELERATION = 64;

	/** Movement snaps to quarter tiles on each axis. */
	private static final int QUARTER_TILE = 32;

	/** How far ahead a golem looks when it picks a heading, in tiles. */
	private static final int LOOK_AHEAD = 6;

	/** Ticks a golem holds a chosen heading before choosing again. */
	private static final int HOLD_MIN = 4;
	private static final int HOLD_SPREAD = 7;

	/**
	 * How strongly a golem prefers getting closer, in tiles of progress over the look ahead;
	 * lower is more decided.
	 */
	private static final double TEMPERATURE = 1.6;

	/** How much a golem dislikes each compass point of turn from where it faces. */
	private static final double TURN_RELUCTANCE = 0.35;

	/** Steps from the mooring by sea at which a golem stops wandering and comes in. */
	private static final int ARRIVE = 8;

	/** Ticks without getting nearer before a wandering golem is taken in hand. */
	private static final int STALL_TICKS = 40;

	/** Ticks spent working a raft carefully out of a tight spot before wandering again. */
	private static final int CAREFUL_TICKS = 12;

	/** Chance a crossing stops along the way, and how long it sits, in ticks. */
	private static final float REST_CHANCE = 0.5f;
	private static final int REST_MIN = 8;
	private static final int REST_SPREAD = 20;

	/** Chance a golem takes the whole crossing at half speed. */
	private static final float HALF_SPEED_CHANCE = 0.15f;

	/**
	 * A golem's own way across, sailed as a raft sails: a heading, a speed and a turn of one
	 * compass point a tick, worked out when the crossing is planned and replayed afterward, so a
	 * golem nobody is watching costs nothing on the way.
	 *
	 * <p>Every few ticks it picks a heading at random from the compass, weighted toward getting
	 * nearer and away from turning hard — nearer by sea, the distance being filled outward from
	 * the destination round every headland, so the way out of a bay is the way closer. It turns
	 * toward that heading a point a tick while moving, and where its next move would ground it,
	 * edges out a tile at a time down the travel distance, which is also how it moors.
	 *
	 * @return a tick-by-tick recording, or null if the mooring is not in the field
	 */
	private Itinerary steer(List<int[]> route, SeaMesh.Field field, Random random, int tick, WorldPoint landing)
	{
		Wake wake = new Wake();
		if (!sailLeg(route, field, random, wake, landing, false))
		{
			return null;
		}
		return Itinerary.steered(wake.xs.toArray(), wake.ys.toArray(), wake.facings.toArray(), 0, tick, landing);
	}

	/** A crossing's track so far, and how the raft is moving at the end of it. */
	private static final class Wake
	{
		final IntList xs = new IntList();
		final IntList ys = new IntList();
		final IntList facings = new IntList();
		int speed;

		boolean isEmpty()
		{
			return xs.size() == 0;
		}
	}

	/**
	 * Sails one leg of a crossing onto the end of a wake. An empty wake sets out from the route's
	 * first tile at a standstill; otherwise the leg starts where the wake ends, heading and speed
	 * and all.
	 *
	 * @param landing  the gangplank to come in to and stop by, or null to end at the route's end
	 * @param throughMouth true to end the moment the raft reaches the route's end, still under way,
	 *                     because it goes through a cave mouth there
	 * @return false if the leg's start is not in the field
	 */
	private boolean sailLeg(List<int[]> route, SeaMesh.Field field, Random random, Wake wake, WorldPoint landing,
		boolean throughMouth)
	{
		int[] start = route.get(0);
		int[] goal = route.get(route.size() - 1);
		IntList xs = wake.xs;
		IntList ys = wake.ys;
		IntList facings = wake.facings;

		int x;
		int y;
		int facing;
		int speed;
		if (wake.isEmpty())
		{
			x = centre(start[0]);
			y = centre(start[1]);
			facing = pickHeading(field, x, y, -1, random, true);
			speed = 0;
		}
		else
		{
			x = xs.get(xs.size() - 1);
			y = ys.get(ys.size() - 1);
			facing = facings.get(facings.size() - 1);
			speed = wake.speed;
		}
		int startDistance = field.distance(Math.floorDiv(x, Golem.TILE), Math.floorDiv(y, Golem.TILE));
		if (startDistance < 0)
		{
			return false;
		}
		int cruise = random.nextFloat() < HALF_SPEED_CHANCE ? HALF_SPEED : FULL_SPEED;
		int turnSign = -1;
		int wanted = facing;
		int holdUntil = 0;

		int restAt = random.nextFloat() < REST_CHANCE && startDistance > ARRIVE * 4
			? ARRIVE * 2 + random.nextInt(startDistance - ARRIVE * 3) : -1;
		int restLeft = REST_MIN + random.nextInt(REST_SPREAD);
		boolean resting = false;

		boolean docking = false;
		boolean docked = false;

		int careful = 0;
		int best = startDistance;
		int bestAt = 0;
		int wanderBudget = startDistance * 8 + 300;
		int hardLimit = startDistance * 16 + 600;

		if (wake.isEmpty())
		{
			xs.add(x);
			ys.add(y);
			facings.add(facing);
		}
		for (int t = 1; t <= hardLimit; t++)
		{
			int tileX = Math.floorDiv(x, Golem.TILE);
			int tileY = Math.floorDiv(y, Golem.TILE);
			int here = field.distance(tileX, tileY);

			if (here == 0 && x == centre(goal[0]) && y == centre(goal[1]))
			{
				docked = true;
				break;
			}
			if (throughMouth && here >= 0 && here <= 1)
			{
				// At the cave mouth, and through it. Not off the field, whose distance is -1, which
				// put rafts through the mouth from mid-sea.
				docked = true;
				break;
			}
			if (docking && speed == 0)
			{
				docked = true;
				break;
			}
			if (!docking && t > 1 && landing != null
				&& Math.max(Math.abs(tileX - landing.getX()), Math.abs(tileY - landing.getY())) <= DISEMBARK_RANGE)
			{
				// In range of the gangplank: bring the raft to a stop, and the golem steps ashore.
				docking = true;
			}
			if (here < best)
			{
				best = here;
				bestAt = t;
			}

			if (docking)
			{
				// Coasting to a stop, straight on; stopped short if the way ahead closes.
				speed = Math.max(0, speed - ACCELERATION);
				int[] v = velocity(facing, speed);
				if (speed > 0 && clear(field, x, y, x + v[0], y + v[1]) && bowClear(field, x + v[0], y + v[1], facing))
				{
					x += v[0];
					y += v[1];
				}
				else
				{
					speed = 0;
				}
			}
			else if (resting)
			{
				// Sails down and sitting. It comes to a stop first, then waits.
				if (speed > 0)
				{
					speed = Math.max(0, speed - ACCELERATION);
					int[] v = velocity(facing, speed);
					if (clear(field, x, y, x + v[0], y + v[1]) && bowClear(field, x + v[0], y + v[1], facing))
					{
						x += v[0];
						y += v[1];
					}
					else
					{
						speed = 0;
					}
				}
				else if (--restLeft <= 0)
				{
					resting = false;
					bestAt = t;
				}
			}
			else if (here < 0 || here <= ARRIVE && !throughMouth || careful > 0 || t > wanderBudget)
			{
				// Carefully: down the travel distance a tile at a time, turning on the spot when the
				// way on is over a point off the bow.
				careful = Math.max(0, careful - 1);
				if (here < 0)
				{
					// Off the field: halfway through a diagonal step, on the corner tile between two
					// in it. There is no way downhill from a tile with no distance.
					int[] back = nearestInField(field, tileX, tileY);
					if (back != null)
					{
						x = centre(back[0]);
						y = centre(back[1]);
						speed = 0;
					}
					xs.add(x);
					ys.add(y);
					facings.add(facing);
					continue;
				}
				int[] next = here == 0 ? goal : field.downhill(tileX, tileY);
				int targetX = next == null ? centre(tileX) : centre(next[0]);
				int targetY = next == null ? centre(tileY) : centre(next[1]);
				boolean centred = x == centre(tileX) && y == centre(tileY);
				if (!centred && !clear(field, x, y, targetX, targetY))
				{
					// Off the middle of the tile, and the corner is land: straighten up first. Only
					// when off the middle, the field already allowing the step from the middle.
					targetX = centre(tileX);
					targetY = centre(tileY);
				}
				int dx = targetX - x;
				int dy = targetY - y;
				int gap = Math.max(Math.abs(dx), Math.abs(dy));
				if (gap > 0)
				{
					int toward = compassPoint(dx, dy);
					int off = offBy(facing, toward);
					facing = turn(facing, toward, turnSign);
					turnSign = turning(facing, toward, turnSign);
					if (Math.abs(off) <= TURN_PER_TICK)
					{
						speed = Math.min(speed + ACCELERATION, HALF_SPEED);
						if (speed >= gap)
						{
							x = targetX;
							y = targetY;
						}
						else
						{
							x += (int) Math.round(dx * (double) speed / gap);
							y += (int) Math.round(dy * (double) speed / gap);
						}
					}
					else
					{
						speed = 0;
					}
				}
				else
				{
					speed = 0;
				}
			}
			else
			{
				if (restAt >= 0 && here <= restAt)
				{
					restAt = -1;
					resting = true;
				}

				if (t - bestAt > STALL_TICKS)
				{
					careful = CAREFUL_TICKS;
					bestAt = t;
				}

				if (t >= holdUntil || !clearAhead(field, x, y, wanted, LOOK_AHEAD / 2))
				{
					wanted = pickHeading(field, x, y, facing, random, false);
					holdUntil = t + HOLD_MIN + random.nextInt(HOLD_SPREAD);
				}
				if (wanted < 0)
				{
					// Nowhere worth heading from here: work out of it carefully.
					wanted = facing;
					careful = CAREFUL_TICKS;
					speed = 0;
				}
				else
				{
					facing = turn(facing, wanted, turnSign);
					turnSign = turning(facing, wanted, turnSign);

					int lookTiles = Math.max(2, speed * 3 / Golem.TILE);
					int[] look = velocity(facing, lookTiles * Golem.TILE);
					int target = clearAhead(field, x, y, facing, lookTiles) && bowClear(field, x + look[0], y + look[1], facing)
						? cruise : HALF_SPEED;
					speed = speed < target ? Math.min(target, speed + ACCELERATION) : Math.max(target, speed - ACCELERATION);

					int[] v = velocity(facing, speed);
					if (!clear(field, x, y, x + v[0], y + v[1]) || !bowClear(field, x + v[0], y + v[1], facing))
					{
						speed = Math.min(speed, HALF_SPEED);
						v = velocity(facing, speed);
					}
					if (clear(field, x, y, x + v[0], y + v[1]) && bowClear(field, x + v[0], y + v[1], facing))
					{
						x += v[0];
						y += v[1];
					}
					else
					{
						// About to ground. Stop, and pick the way out.
						speed = 0;
						careful = CAREFUL_TICKS;
					}
				}
			}

			xs.add(x);
			ys.add(y);
			facings.add(facing);
		}

		int last = xs.size() - 1;
		if (!docked && (xs.get(last) != centre(goal[0]) || ys.get(last) != centre(goal[1])))
		{
			// Out of time, which careful sailing should never allow. Finish at the mooring rather
			// than not at all.
			log.debug("Crossing ran out of ticks {} tiles from its mooring", field.distance(
				Math.floorDiv(xs.get(last), Golem.TILE), Math.floorDiv(ys.get(last), Golem.TILE)));
			xs.add(centre(goal[0]));
			ys.add(centre(goal[1]));
			facings.add(facings.get(last));
			speed = 0;
		}
		wake.speed = speed;
		return true;
	}

	// ------------------------------------------------------------------ the cave

	/**
	 * True if a dock is on the sailable cave's lake: its berth is on the water joined to the
	 * cave mouth underground.
	 */
	private boolean isCaveDock(SailingDocks.Dock dock)
	{
		if (dock.isOnOpenSea())
		{
			return false;
		}
		int lake = sea.componentAt(GolemContent.CAVE_LAKE_MOUTH_X, GolemContent.CAVE_LAKE_MOUTH_Y);
		WorldPoint berth = dock.getBerth();
		return lake != 0 && berth.getPlane() == 0 && sea.componentAt(berth.getX(), berth.getY()) == lake;
	}

	/**
	 * A crossing to or from the cave dock, sailed as the game sails it: a boat there sails its
	 * lake to the cave mouth and is put out at the mouth on the island's coast, on the real sea.
	 * The sea leg joins the shipped routes at Wyrmscraig's own dock, the nearest port to the
	 * mouth; only the short way between the two is searched live, once.
	 */
	private Itinerary throughCave(SailingDocks.Dock from, SailingDocks.Dock to, boolean fromCave, TransportMemory memory,
		int tick, Random random, RoamContext context)
	{
		SailingDocks.Dock caveDock = fromCave ? from : to;
		SailingDocks.Dock seaDock = fromCave ? to : from;
		SailingDocks.Dock gateway = nearestSeaDock(GolemContent.CAVE_SEA_MOUTH_X, GolemContent.CAVE_SEA_MOUTH_Y);
		if (gateway == null)
		{
			return null;
		}

		WorldPoint seaMouth = new WorldPoint(GolemContent.CAVE_SEA_MOUTH_X, GolemContent.CAVE_SEA_MOUTH_Y, 0);
		int[] lakeMouth = {GolemContent.CAVE_LAKE_MOUTH_X, GolemContent.CAVE_LAKE_MOUTH_Y};
		int[] caveBerth = {caveDock.getBerth().getX(), caveDock.getBerth().getY()};

		// The sea between the cave mouth and the sea dock, by way of the gateway.
		List<int[]> mouthToGateway = searchedRoute(seaMouth, gateway.getMooring(), context);
		if (mouthToGateway == null)
		{
			return null;
		}
		List<int[]> seaCourse = new java.util.ArrayList<>(mouthToGateway);
		if (seaDock.getRowId() != gateway.getRowId())
		{
			List<int[]> onward = searchedRoute(gateway.getMooring(), seaDock.getMooring(), context);
			if (onward == null)
			{
				return null;
			}
			seaCourse.addAll(onward.subList(1, onward.size()));
		}
		seaCourse.add(new int[]{seaDock.getBerth().getX(), seaDock.getBerth().getY()});
		if (!fromCave)
		{
			java.util.Collections.reverse(seaCourse);
		}

		List<int[]> lakeCourse = new java.util.ArrayList<>();
		lakeCourse.add(fromCave ? caveBerth : lakeMouth);
		lakeCourse.add(fromCave ? lakeMouth : caveBerth);

		SeaMesh.Water lake = sea.lake(sea.componentAt(lakeMouth[0], lakeMouth[1]));
		SeaMesh.Field lakeField = fieldFor(lakeCourse, lake);
		SeaMesh.Field seaField = fieldFor(seaCourse);
		if (lakeField == null || seaField == null)
		{
			// Being built. The golem waits for it.
			notReady = true;
			return null;
		}

		Wake wake = new Wake();
		if (fromCave)
		{
			if (!sailLeg(lakeCourse, lakeField, random, wake, null, true))
			{
				return null;
			}
			putThrough(wake, seaMouth.getX(), seaMouth.getY(), GolemContent.CAVE_SEA_MOUTH_OUTWARD);
			if (!sailLeg(seaCourse, seaField, random, wake, to.getShore(), false))
			{
				return null;
			}
		}
		else
		{
			if (!sailLeg(seaCourse, seaField, random, wake, null, true))
			{
				return null;
			}
			putThrough(wake, lakeMouth[0], lakeMouth[1], GolemContent.CAVE_LAKE_MOUTH_INWARD);
			if (!sailLeg(lakeCourse, lakeField, random, wake, to.getShore(), false))
			{
				return null;
			}
		}

		memory.setBlockedPort(from.getRowId());
		log.debug("Golem sailing {} -> {} through the cave", from.getName(), to.getName());
		return Itinerary.steered(wake.xs.toArray(), wake.ys.toArray(), wake.facings.toArray(), 0, tick, to.getShore());
	}

	/** Moves the raft through a cave mouth: next tick it is at the other, facing out, under way. */
	private static void putThrough(Wake wake, int tileX, int tileY, int facing)
	{
		wake.xs.add(centre(tileX));
		wake.ys.add(centre(tileY));
		wake.facings.add(facing);
	}

	/** The open-sea dock whose mooring is nearest a tile. */
	private SailingDocks.Dock nearestSeaDock(int x, int y)
	{
		SailingDocks.Dock nearest = null;
		int best = Integer.MAX_VALUE;
		for (SailingDocks.Dock dock : docks.getDocks())
		{
			if (!dock.isOnOpenSea())
			{
				continue;
			}
			int distance = Math.max(Math.abs(dock.getMooring().getX() - x), Math.abs(dock.getMooring().getY() - y));
			if (distance < best)
			{
				best = distance;
				nearest = dock;
			}
		}
		return nearest;
	}

	/** A sea route, searched now if never before and this frame's search is free; else null. */
	private List<int[]> searchedRoute(WorldPoint from, WorldPoint to, RoamContext context)
	{
		boolean searched = sea.isSearched(from, to);
		if (!searched && context != null && !context.isMaySearchSea())
		{
			notReady = true;
			return null;
		}
		List<int[]> route = sea.route(from, to);
		if (!searched && context != null)
		{
			context.spendSeaSearch();
		}
		return route;
	}


	/**
	 * A compass point to steer for, weighted toward progress by sea and against turning.
	 *
	 * @param facing   the way the raft faces now, or -1 if it has not set off
	 * @param decisive take the best rather than drawing at random
	 * @return a compass point, or -1 if no direction is clear
	 */
	private int pickHeading(SeaMesh.Field field, int x, int y, int facing, Random random, boolean decisive)
	{
		int here = field.distance(Math.floorDiv(x, Golem.TILE), Math.floorDiv(y, Golem.TILE));
		double[] weights = new double[16];
		double sum = 0;
		int bestPoint = -1;
		for (int h = 0; h < 16; h++)
		{
			int point = h * TURN_PER_TICK;
			int[] ahead = velocity(point, LOOK_AHEAD * Golem.TILE);
			int tx = x + ahead[0];
			int ty = y + ahead[1];
			int there = field.distance(Math.floorDiv(tx, Golem.TILE), Math.floorDiv(ty, Golem.TILE));
			if (there < 0 || !clear(field, x, y, tx, ty) || !bowClear(field, tx, ty, point))
			{
				continue;
			}
			double turn = facing < 0 ? 0 : Math.abs(offBy(facing, point)) / (double) TURN_PER_TICK;
			weights[h] = Math.exp((here - there) / TEMPERATURE - turn * TURN_RELUCTANCE);
			sum += weights[h];
			if (bestPoint < 0 || weights[h] > weights[bestPoint / TURN_PER_TICK])
			{
				bestPoint = point;
			}
		}
		if (sum <= 0)
		{
			if (facing < 0)
			{
				// Setting off from a mooring with no open water in sight: face the way on.
				int[] next = field.downhill(Math.floorDiv(x, Golem.TILE), Math.floorDiv(y, Golem.TILE));
				return next == null ? 0 : compassPoint(centre(next[0]) - x, centre(next[1]) - y);
			}
			return -1;
		}
		if (decisive)
		{
			return bestPoint;
		}
		double pick = random.nextDouble() * sum;
		for (int h = 0; h < 16; h++)
		{
			pick -= weights[h];
			if (weights[h] > 0 && pick <= 0)
			{
				return h * TURN_PER_TICK;
			}
		}
		return bestPoint;
	}

	/**
	 * True if the raft's bow is over open water with the golem here, facing this way: the tip and
	 * both sides behind it.
	 */
	private static boolean bowClear(SeaMesh.Field field, int x, int y, int facing)
	{
		int[] tip = velocity(facing, BOW_REACH);
		int[] shoulder = velocity(facing, BOW_REACH * 3 / 4);
		int[] side = velocity((facing + 512) & 2047, BOW_HALF_WIDTH);
		return water(field, x + tip[0], y + tip[1])
			&& water(field, x + shoulder[0] + side[0], y + shoulder[1] + side[1])
			&& water(field, x + shoulder[0] - side[0], y + shoulder[1] - side[1]);
	}

	private static boolean water(SeaMesh.Field field, int fineX, int fineY)
	{
		return field.isWater(Math.floorDiv(fineX, Golem.TILE), Math.floorDiv(fineY, Golem.TILE));
	}

	/** The neighbouring tile in the field nearest the destination, or null if none is. */
	private static int[] nearestInField(SeaMesh.Field field, int tileX, int tileY)
	{
		int[] best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				int distance = field.distance(tileX + dx, tileY + dy);
				if (distance >= 0 && distance < bestDistance)
				{
					bestDistance = distance;
					best = new int[]{tileX + dx, tileY + dy};
				}
			}
		}
		return best;
	}

	/** One tick's movement at this heading and speed, each axis on a quarter tile. */
	static int[] velocity(int facing, int speed)
	{
		// 0 south, 512 west, 1024 north, 1536 east.
		double angle = (facing - 1024) * Math.PI / 1024;
		return new int[]{
			quarter(Math.sin(angle) * speed),
			quarter(Math.cos(angle) * speed),
		};
	}

	private static int quarter(double fine)
	{
		return (int) (Math.signum(fine) * Math.round(Math.abs(fine) / QUARTER_TILE)) * QUARTER_TILE;
	}

	/** The compass point nearest a direction. */
	static int compassPoint(int dx, int dy)
	{
		int exact = (int) (1024 + Math.round(Math.atan2(dx, dy) / Math.PI * 1024)) & 2047;
		return ((exact + TURN_PER_TICK / 2) / TURN_PER_TICK * TURN_PER_TICK) & 2047;
	}

	/** Signed turn from one heading to another, the short way; exactly about is -1024. */
	private static int offBy(int from, int to)
	{
		return ((to - from + 1024) & 2047) - 1024;
	}

	/**
	 * A tick's turn toward a heading. A turn exactly about keeps going the way the raft was
	 * already turning, rather than flipping between the two ways.
	 */
	private static int turn(int facing, int toward, int turnSign)
	{
		int off = offBy(facing, toward);
		if (off == 0)
		{
			return facing;
		}
		int sign = off == -1024 ? turnSign : Integer.signum(off);
		return (facing + sign * Math.min(Math.abs(off), TURN_PER_TICK)) & 2047;
	}

	/** Which way the raft is turning after a tick's turn, kept when it is not turning. */
	private static int turning(int facing, int toward, int turnSign)
	{
		int off = offBy(facing, toward);
		return off == 0 || off == -1024 ? turnSign : Integer.signum(off);
	}

	/** True if the raft could move straight between these points without leaving the field. */
	private static boolean clear(SeaMesh.Field field, int fromX, int fromY, int toX, int toY)
	{
		int span = Math.max(Math.abs(toX - fromX), Math.abs(toY - fromY));
		int samples = Math.max(1, span / (QUARTER_TILE / 2));
		for (int s = 0; s <= samples; s++)
		{
			int px = fromX + (int) Math.round((toX - fromX) * (double) s / samples);
			int py = fromY + (int) Math.round((toY - fromY) * (double) s / samples);
			if (field.distance(Math.floorDiv(px, Golem.TILE), Math.floorDiv(py, Golem.TILE)) < 0)
			{
				return false;
			}
		}
		return true;
	}

	/** True if the water is open for this many tiles along a heading. */
	private static boolean clearAhead(SeaMesh.Field field, int x, int y, int facing, int tiles)
	{
		if (facing < 0)
		{
			return false;
		}
		int[] ahead = velocity(facing, tiles * Golem.TILE);
		return clear(field, x, y, x + ahead[0], y + ahead[1]);
	}

	private static int centre(int tile)
	{
		return tile * Golem.TILE + Golem.TILE / 2;
	}

	/** A growable int array, so a few hundred ticks are not a few hundred boxes. */
	private static final class IntList
	{
		private int[] values = new int[256];
		private int size;

		void add(int value)
		{
			if (size == values.length)
			{
				values = java.util.Arrays.copyOf(values, size * 2);
			}
			values[size++] = value;
		}

		int get(int index)
		{
			return values[index];
		}

		int size()
		{
			return size;
		}

		int[] toArray()
		{
			return java.util.Arrays.copyOf(values, size);
		}
	}

	/**
	 * A crossing with no drawn route: the golem leaves one dock and arrives at the other, timed by
	 * straight-line distance, floored so a short one is not instant.
	 */
	private Itinerary passage(SailingDocks.Dock from, SailingDocks.Dock to, WorldPoint at, int tick)
	{
		WorldPoint a = from.getMooring();
		WorldPoint b = to.getMooring();

		// Underground maps sit thousands of tiles from the surface above them, so the separation
		// between a cave dock and a sea one is meaningless. Capped, not used directly.
		int spread = Math.min(400,
			Math.abs(a.getX() - b.getX()) + Math.abs(a.getY() - b.getY()));

		// Held at the quayside and then put ashore, not walked: as a two-point route the golem
		// slid six thousand tiles from the cave to the surface.
		return Itinerary.passage(at != null ? at : from.getShore(), to.getShore(), tick, Math.max(50, spread));
	}

	/**
	 * The dock a golem standing here could embark from, or null. Generous about distance, the
	 * mooring being water beside the dock and the golem on land.
	 */
	SailingDocks.Dock dockAt(WorldPoint at, int radius)
	{
		for (SailingDocks.Dock dock : docks.getDocks())
		{
			// Measured to the quayside, not the buoy out on the water, which had golems boarding
			// from wherever the radius caught them.
			WorldPoint shore = dock.getShore();
			if (shore.getPlane() == at.getPlane()
				&& Math.abs(shore.getX() - at.getX()) <= radius
				&& Math.abs(shore.getY() - at.getY()) <= radius)
			{
				return dock;
			}
		}
		return null;
	}
}

package com.golemsdontdie;

import java.util.ArrayList;
import java.util.List;

/**
 * A traversal as it actually happened, cycle by cycle, ready to be performed again.
 *
 * <p>This replaces a parametric model of clip, delay and duration, which had to rebuild the
 * motion differently for every obstacle shape — a hop, a climb and a door all want something
 * else — so fitting it to one broke it on another. The position is already recorded every
 * 20ms, so the motion is kept and replayed instead; a teleport is a curve that does not move
 * and then does.
 *
 * <h2>Why it is stored rotated</h2>
 *
 * <p>Samples run along the traversal's own axis, <b>forward</b> toward the destination and
 * <b>sideways</b>, not north and east, so one recording serves every instance of that
 * obstacle whichever way it faces.
 */
final class MotionCurve
{
	/**
	 * Client cycles between stored samples. Two: movement is interpolated between samples
	 * anyway, and at 40ms a hop is twenty numbers rather than forty, small enough to keep
	 * hundreds of these in a config value.
	 */
	static final int SAMPLE_EVERY = 2;

	/** Longest curve worth keeping, in cycles. Beyond this it is not a traversal. */
	static final int MAX_CYCLES = 600;

	/**
	 * Distance along the traversal axis at each sample, in 128ths of a tile, forward being
	 * toward the destination. Ending short is normal: the last part of some traversals is a
	 * teleport, so the final sample is nowhere near the end.
	 */
	private final short[] forward;

	/** Sideways offset at each sample. Nonzero for anything that swings or staggers. */
	private final short[] lateral;

	/**
	 * {cycle, animationId, startingFrame} at each point the animation changed. The frame
	 * matters because the client advances the clip at the render rate while position
	 * advances on cycle count; any disagreement reads as the animation skipping.
	 */
	private final int[][] animations;

	private final int cycles;

	/**
	 * Which way the player faced while traversing, relative to the direction of travel, in
	 * orientation units — 0 forwards, 1024 backwards — or -1 if not recorded. Not always
	 * forwards: on the rockslide they face the rock and move away from it, and a golem
	 * facing its travel climbs off the cliff.
	 */
	private final int facing;

	/**
	 * The keyframe the player's animation was on at each sample, -1 where none, or null for
	 * a recording predating keyframes. The clip does not run at authored speed: on a basalt
	 * stone it holds its first keyframe about twenty-five cycles, so played as authored a
	 * golem finished the hop before leaving the ground.
	 */
	private final short[] keyframes;

	MotionCurve(short[] forward, short[] lateral, int[][] animations, int cycles, int facing,
		short[] keyframes)
	{
		this.forward = forward;
		this.lateral = lateral;
		this.animations = animations;
		this.cycles = cycles;
		this.facing = facing;
		this.keyframes = keyframes;
	}

	boolean hasKeyframes()
	{
		return keyframes != null;
	}

	/** Facing relative to travel, or -1 if the recording predates it. */
	int facing()
	{
		return facing;
	}

	boolean hasFacing()
	{
		return facing >= 0;
	}

	int cycles()
	{
		return cycles;
	}

	/**
	 * The recording as plain numbers, one entry per sample: {cycle, forward, lateral}. For
	 * the obstacle data file, which depends on nothing in this class.
	 */
	int[][] samples()
	{
		int[][] out = new int[forward.length][];
		for (int i = 0; i < forward.length; i++)
		{
			out[i] = new int[]{i * SAMPLE_EVERY, forward[i], i < lateral.length ? lateral[i] : 0};
		}
		return out;
	}

	/** Each point the animation changed, as plain numbers: {cycle, animation}. */
	int[][] animationChanges()
	{
		int[][] out = new int[animations.length][];
		for (int i = 0; i < animations.length; i++)
		{
			out[i] = new int[]{animations[i][0], animations[i][1]};
		}
		return out;
	}

	boolean isEmpty()
	{
		return forward.length == 0;
	}

	/**
	 * The animation that should be playing at this point, or -1. Read from the recorded
	 * timeline rather than decided: an obstacle that plays three clips in sequence does so
	 * because the recording did.
	 */
	int animationAt(int cycle)
	{
		int playing = -1;
		for (int[] change : animations)
		{
			if (change[0] > cycle)
			{
				break;
			}
			playing = change[1];
		}
		return playing;
	}

	/** The frame the animation should be on at this point, or -1 if not recorded. */
	int frameAt(int cycle)
	{
		// Between clips there is no frame to drive: the golem's idle runs on the client's
		// clock, as does any recording made before keyframes were kept.
		if (keyframes == null || animationAt(cycle) == -1)
		{
			return -1;
		}
		return keyframes[Math.max(0, Math.min(cycle / SAMPLE_EVERY, keyframes.length - 1))];
	}

	/** How far along its axis the recording travelled in total, in fine units. */
	int reach()
	{
		return forward.length == 0 ? 0 : forward[forward.length - 1];
	}

	/** Movement smaller than this, in fine units, is sampling rather than going anywhere. */
	private static final int STILL = 8;

	/**
	 * Samples of stillness that separate two movements. Six is twelve cycles: the quantised
	 * source stalls a cycle or two mid-climb, which is sampling, while the pause between two
	 * basalt hops is over fifteen, which is a second step.
	 */
	private static final int HOLD_SAMPLES = 6;

	/** The furthest the recording strays from its own axis. */
	int maxLateral()
	{
		int most = 0;
		for (short value : lateral)
		{
			most = Math.max(most, Math.abs(value));
		}
		return most;
	}

	/**
	 * How many separate movements the recording holds. One for any single obstacle; more
	 * means a chained crossing was captured as one traversal, which a transport covering
	 * one step of it cannot replay.
	 */
	int bursts()
	{
		int count = 0;
		int still = HOLD_SAMPLES;
		for (int i = 1; i < forward.length; i++)
		{
			boolean moved = Math.abs(forward[i] - forward[i - 1])
				+ Math.abs(lateral[i] - lateral[i - 1]) > 1;
			if (moved)
			{
				if (still >= HOLD_SAMPLES)
				{
					count++;
				}
				still = 0;
			}
			else
			{
				still++;
			}
		}
		return count;
	}

	/** The cycle the first animation starts on, or 0 if there is none. */
	int firstAnimationCycle()
	{
		for (int[] change : animations)
		{
			if (change[1] != -1)
			{
				return change[0];
			}
		}
		return 0;
	}

	/**
	 * The cycle the recording first moves once its animation has begun, or -1 if it never
	 * does. From the animation, not the start, since a walk onto the obstacle may come
	 * first; the wind-up measured is the pause between the clip starting and the jump.
	 */
	int firstMoveCycle()
	{
		int from = Math.min(firstAnimationCycle() / SAMPLE_EVERY, forward.length - 1);
		for (int i = from; i < forward.length; i++)
		{
			if (Math.abs(forward[i] - forward[from]) + Math.abs(lateral[i] - lateral[from]) > STILL)
			{
				return i * SAMPLE_EVERY;
			}
		}
		return -1;
	}

	/** The cycle the recording arrives where it finishes, or -1 if it never moved. */
	int lastMoveCycle()
	{
		int end = forward.length - 1;
		for (int i = end; i >= 0; i--)
		{
			if (Math.abs(forward[i] - forward[end]) + Math.abs(lateral[i] - lateral[end]) > STILL)
			{
				return Math.min(cycles, (i + 1) * SAMPLE_EVERY);
			}
		}
		return -1;
	}

	/**
	 * Where the golem should be at this cycle, as an offset from where it started, into
	 * {@code out} in world fine units. {@code axisX, axisY} is the unit vector toward the
	 * destination, turning the stored forward-and-sideways pair back into a direction.
	 */
	void offsetAt(int cycle, float axisX, float axisY, int[] out)
	{
		offsetAt(cycle, axisX, axisY, 1f, out);
	}

	/**
	 * As {@link #offsetAt}, with the forward distance scaled. A golem may take an obstacle
	 * from a tile or two from where the player did, so scaling lands it where its own
	 * transport says, keeping the recording's timing and sideways movement.
	 */
	void offsetAt(int cycle, float axisX, float axisY, float scale, int[] out)
	{
		if (forward.length == 0)
		{
			out[0] = 0;
			out[1] = 0;
			return;
		}

		// Between samples, because the samples are every other cycle and a golem is drawn
		// every one of them.
		float at = Math.max(0, Math.min(cycle, cycles)) / (float) SAMPLE_EVERY;
		int i = Math.min((int) at, forward.length - 1);
		int j = Math.min(i + 1, forward.length - 1);
		float t = at - i;

		// Except across a teleport, which is not interpolated. A door moves the player a
		// whole tile in one cycle and samples are two cycles apart, so interpolating slid
		// the golem through the door instead of putting it on one side and then the other.
		if (Math.abs(forward[j] - forward[i]) + Math.abs(lateral[j] - lateral[i]) > NOISE_STEP)
		{
			t = 0f;
		}

		float f = (forward[i] + (forward[j] - forward[i]) * t) * scale;
		float l = lateral[i] + (lateral[j] - lateral[i]) * t;

		// Forward along the axis, sideways across it.
		out[0] = Math.round(f * axisX - l * axisY);
		out[1] = Math.round(f * axisY + l * axisX);
	}

	/**
	 * Builds a curve from positions sampled during a traversal.
	 *
	 * @param samples  {cycle, worldFineX, worldFineY} for each observation, in order
	 * @param anims    {cycle, animationId} for each animation change
	 * @param toFineX  the destination, for working out which way is forward
	 */
	static MotionCurve record(List<int[]> samples, List<int[]> anims,
		int fromFineX, int fromFineY, int toFineX, int toFineY)
	{
		if (samples.isEmpty())
		{
			return null;
		}

		int span = samples.get(samples.size() - 1)[0] - samples.get(0)[0];
		if (span <= 0 || span > MAX_CYCLES)
		{
			return null;
		}

		// The axis is the straight line to the destination. Where a traversal does not move
		// at all — a ladder, which animates and then teleports — north stands in; nothing is
		// projected onto it anyway.
		float dx = toFineX - fromFineX;
		float dy = toFineY - fromFineY;
		float length = (float) Math.sqrt(dx * dx + dy * dy);
		float axisX = length < 1 ? 0f : dx / length;
		float axisY = length < 1 ? 1f : dy / length;

		int base = samples.get(0)[0];
		int count = span / SAMPLE_EVERY + 1;
		short[] forward = new short[count];
		short[] lateral = new short[count];

		short[] keys = new short[count];
		boolean[] seen = new boolean[count];
		boolean anyKey = false;

		int next = 0;
		for (int[] sample : samples)
		{
			int slot = (sample[0] - base) / SAMPLE_EVERY;
			if (slot < next || slot >= count)
			{
				continue;
			}
			float ox = sample[1] - fromFineX;
			float oy = sample[2] - fromFineY;
			forward[slot] = (short) Math.round(ox * axisX + oy * axisY);
			lateral[slot] = (short) Math.round(-ox * axisY + oy * axisX);
			keys[slot] = (short) (sample.length > 5 ? sample[5] : -1);
			anyKey |= keys[slot] >= 0;
			seen[slot] = true;
			next = slot + 1;
		}
		for (int i = 0; i < count; i++)
		{
			if (!seen[i])
			{
				keys[i] = i == 0 ? -1 : keys[i - 1];
			}
		}

		// Any slot no sample landed in carries the one before it, so a gap in the
		// observations holds still rather than snapping back to the start.
		for (int i = 1; i < count; i++)
		{
			if (forward[i] == 0 && lateral[i] == 0 && (forward[i - 1] != 0 || lateral[i - 1] != 0))
			{
				forward[i] = forward[i - 1];
				lateral[i] = lateral[i - 1];
			}
		}

		smooth(forward);
		smooth(lateral);

		// Starting frames are stored as zero rather than left out. Leaving them out made a
		// curve recorded this session play on the client's clock and the same curve loaded
		// from config play on the recording's, so one obstacle behaved two ways.
		List<int[]> kept = new ArrayList<>();
		for (int i = 0; i < anims.size(); i++)
		{
			int[] change = anims.get(i);
			// A looping clip reports -1 for a cycle between repeats. Not the animation
			// ending; honouring it would flash the golem out of its climb.
			if (change[1] == -1 && i + 1 < anims.size() && anims.get(i + 1)[0] - change[0] <= 4)
			{
				continue;
			}
			kept.add(new int[]{Math.max(0, change[0] - base), change[1], 0});
		}
		int[][] timeline = kept.toArray(new int[0][]);

		// Facing relative to the way the traversal goes, from the moment it animates. The
		// most common of eight directions: the player turns once at the start and holds it.
		int facing = -1;
		if (length >= Golem.TILE / 2f)
		{
			int heading = (int) (1024 + Math.round(Math.atan2(dx, dy) / Math.PI * 1024)) & 2047;
			int from = anims.isEmpty() ? base : anims.get(0)[0];
			int[] bins = new int[8];
			int counted = 0;
			for (int[] sample : samples)
			{
				if (sample.length > 4 && sample[4] >= 0 && sample[0] >= from)
				{
					bins[((sample[4] - heading + 128) & 2047) / 256]++;
					counted++;
				}
			}
			if (counted > 0)
			{
				int best = 0;
				for (int b = 1; b < bins.length; b++)
				{
					if (bins[b] > bins[best])
					{
						best = b;
					}
				}
				facing = best * 256;
			}
		}

		return new MotionCurve(forward, lateral, timeline, span, facing, anyKey ? keys : null);
	}

	/**
	 * The largest step that can be sampling noise rather than real movement. Three quarters
	 * of a tile: climb artefacts came back as steps of forty to sixty units, a door's
	 * teleport is a whole tile in one sample, and nothing observed sits between.
	 */
	private static final int NOISE_STEP = Golem.TILE * 3 / 4;

	/**
	 * Evens out the sampling, which is coarser than the motion it samples, but only where
	 * the motion really is continuous.
	 *
	 * <p>{@code getLocalLocation} does not report the smooth position the client draws, so a
	 * recorded climb came back as plateaus of two or three samples and then a jump of forty
	 * to sixty, which a golem performed as holding still and lurching. Averaging all of it
	 * was wrong the other way, beginning a door's teleport before its animation finished, so
	 * a step larger than {@link #NOISE_STEP} is taken to be real and never averaged across.
	 */
	private static void smooth(short[] values)
	{
		if (values.length < 3)
		{
			return;
		}

		short[] source = values.clone();
		for (int i = 1; i < values.length - 1; i++)
		{
			if (Math.abs(source[i] - source[i - 1]) > NOISE_STEP
				|| Math.abs(source[i + 1] - source[i]) > NOISE_STEP)
			{
				// A real discontinuity on one side or the other. Leave it alone.
				continue;
			}
			values[i] = (short) Math.round((source[i - 1] + source[i] + source[i + 1]) / 3f);
		}
	}

	// ------------------------------------------------------------------ storage

	/** {@code cycles|f,f,f|l,l,l|cycle:anim:frame,...|facing|k,k,k} */
	String serialise()
	{
		StringBuilder sb = new StringBuilder().append(cycles).append('|');
		for (int i = 0; i < forward.length; i++)
		{
			sb.append(i == 0 ? "" : ",").append(forward[i]);
		}
		sb.append('|');
		for (int i = 0; i < lateral.length; i++)
		{
			sb.append(i == 0 ? "" : ",").append(lateral[i]);
		}
		sb.append('|');
		for (int i = 0; i < animations.length; i++)
		{
			sb.append(i == 0 ? "" : ",").append(animations[i][0]).append(':')
				.append(animations[i][1]).append(':')
				.append(animations[i].length > 2 ? animations[i][2] : 0);
		}
		sb.append('|').append(facing).append('|');
		if (keyframes != null)
		{
			for (int i = 0; i < keyframes.length; i++)
			{
				sb.append(i == 0 ? "" : ",").append(keyframes[i]);
			}
		}
		return sb.toString();
	}

	static MotionCurve parse(String text)
	{
		try
		{
			String[] parts = text.split("\\|", -1);
			if (parts.length < 4)
			{
				return null;
			}

			int cycles = Integer.parseInt(parts[0]);
			short[] forward = shorts(parts[1]);
			short[] lateral = shorts(parts[2]);
			if (forward.length != lateral.length || forward.length == 0)
			{
				return null;
			}

			List<int[]> anims = new ArrayList<>();
			if (!parts[3].isEmpty())
			{
				for (String change : parts[3].split(","))
				{
					String[] pair = change.split(":");
					anims.add(pair.length > 2
						? new int[]{Integer.parseInt(pair[0]), Integer.parseInt(pair[1]),
							Integer.parseInt(pair[2])}
						: new int[]{Integer.parseInt(pair[0]), Integer.parseInt(pair[1])});
				}
			}
			// Recordings made before facing was kept have four fields and load as unknown.
			int facing = parts.length > 4 && !parts[4].isEmpty() ? Integer.parseInt(parts[4]) : -1;
			short[] keyframes = parts.length > 5 && !parts[5].isEmpty() ? shorts(parts[5]) : null;
			if (keyframes != null && keyframes.length != forward.length)
			{
				keyframes = null;
			}
			return new MotionCurve(forward, lateral, anims.toArray(new int[0][]), cycles, facing,
				keyframes);
		}
		catch (RuntimeException e)
		{
			// One unreadable curve costs its own obstacle and nothing else.
			return null;
		}
	}

	private static short[] shorts(String csv)
	{
		if (csv.isEmpty())
		{
			return new short[0];
		}
		String[] parts = csv.split(",");
		short[] out = new short[parts.length];
		for (int i = 0; i < parts.length; i++)
		{
			out[i] = Short.parseShort(parts[i]);
		}
		return out;
	}

	@Override
	public String toString()
	{
		return "curve " + cycles + "c " + forward.length + " samples, "
			+ animations.length + " anim changes";
	}
}

package com.golemsdontdie;

import java.util.List;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

/**
 * Where a golem will be, expressed so that knowing costs nothing until someone asks.
 *
 * <p>A golem out of view need only be somewhere plausible by the time anyone looks, so instead
 * of ticking it the plugin records its route and start tick; position is then a pure function of
 * elapsed time. More correct than a tick, not cheaper: no drift, nothing to catch up after an
 * hour tabbed out, no dependence on framerate.
 *
 * <p>Measured in <b>distance</b>, not waypoints: a straightened sea route can have waypoints
 * fifty tiles apart, and advancing one per tick made a three-hundred-tile crossing take twenty
 * ticks. Position is interpolated along the polyline, in 128ths of a tile.
 */
final class Itinerary
{
	/** Tiles of the route, in order. The first is where the golem set off from. */
	private final int[] xs;
	private final int[] ys;
	private final int plane;

	/** Distance from the start to each waypoint, in tiles. */
	private final int[] reached;

	/** Total length of the route in tiles. */
	private final int length;

	/** The tick the golem left the first waypoint. */
	@Getter
	private final int startTick;

	/** Ticks the whole route takes, so expiry is a comparison rather than a walk. */
	@Getter
	private final int duration;

	/**
	 * True if this route crosses water rather than walking. A roaming route is a straight line
	 * drawn without consulting the map, since at Tier 3 nothing observes it, so a golem promoted
	 * into view mid-route must be put back on walkable ground first. A voyage was searched
	 * across the ocean mesh, so it survives being watched.
	 */
	@Getter
	private final boolean voyage;

	/**
	 * Where a transport at the end of the walk puts the golem, or null for a plain route. Kept
	 * apart from the waypoints: as the last one, a ladder into a dungeon joins tiles some six
	 * thousand apart, and that distance was walked at a tick a tile — one ladder took an hour.
	 * Using the transport is a wait at the end of the walk.
	 */
	private final WorldPoint landing;

	/** The transport that ends the route, or null. Taken on arrival, not when planned. */
	private final GolemTransport transport;

	/**
	 * For a crossing, where the raft is at the end of every tick and which way it faces, in fine
	 * units and 2048ths of a turn; null otherwise. A boat turns a compass point a tick and moves
	 * the way it faces, so its path is decided when the crossing is planned and only read here.
	 */
	private final int[] fineXs;
	private final int[] fineYs;
	private final int[] facings;

	private Itinerary(int[] xs, int[] ys, int[] reached, int length, int plane,
		int startTick, int duration, boolean voyage, WorldPoint landing, GolemTransport transport,
		int[] fineXs, int[] fineYs, int[] facings)
	{
		this.fineXs = fineXs;
		this.fineYs = fineYs;
		this.facings = facings;
		this.transport = transport;
		this.xs = xs;
		this.ys = ys;
		this.reached = reached;
		this.length = length;
		this.plane = plane;
		this.startTick = startTick;
		this.duration = duration;
		this.voyage = voyage;
		this.landing = landing;
	}

	/** Plans a walking route, one tick per tile. */
	static Itinerary of(List<int[]> path, int plane, int startTick, int extra)
	{
		return of(path, plane, startTick, 1, extra, false);
	}

	/**
	 * Plans a route.
	 *
	 * @param path         tiles in order, as {@code {x, y}} pairs; the golem's tile first
	 * @param ticksPerTile pace — one for walking, more for something slower
	 * @param extra        ticks on top of the travel itself, for boarding and the like
	 * @param voyage       true if this crosses water
	 */
	static Itinerary of(List<int[]> path, int plane, int startTick, int ticksPerTile,
		int extra, boolean voyage)
	{
		if (path == null || path.isEmpty())
		{
			return null;
		}

		int[] xs = new int[path.size()];
		int[] ys = new int[path.size()];
		int[] reached = new int[path.size()];

		int travelled = 0;
		for (int i = 0; i < path.size(); i++)
		{
			xs[i] = path.get(i)[0];
			ys[i] = path.get(i)[1];
			if (i > 0)
			{
				// Chebyshev: a diagonal step costs one tick exactly as a cardinal one does.
				// Euclidean tiles would make diagonal legs take longer than the game does.
				travelled += Math.max(Math.abs(xs[i] - xs[i - 1]), Math.abs(ys[i] - ys[i - 1]));
			}
			reached[i] = travelled;
		}

		return new Itinerary(xs, ys, reached, travelled, plane, startTick,
			Math.max(1, travelled * ticksPerTile + extra), voyage, null, null, null, null, null);
	}

	/**
	 * Plans a walk to a transport's origin, then the transport. The walk takes a tick a tile, the
	 * golem then waits at the origin for as long as the transport takes.
	 *
	 * @param walk tiles to the transport's origin, the golem's own tile first
	 */
	static Itinerary thenTransport(List<int[]> walk, int plane, int startTick, GolemTransport transport)
	{
		Itinerary route = of(walk, plane, startTick, 1, 0, false);
		if (route == null)
		{
			return null;
		}
		return new Itinerary(route.xs, route.ys, route.reached, route.length, plane, startTick,
			route.length + Math.max(1, transport.getDuration()), false, transport.destination(), transport, null, null, null);
	}

	/**
	 * A crossing with no drawn route: the golem waits where it is, then is at the landing. A
	 * voyage, so it survives being watched.
	 */
	static Itinerary passage(WorldPoint from, WorldPoint landing, int startTick, int ticks)
	{
		int[] xs = {from.getX()};
		int[] ys = {from.getY()};
		return new Itinerary(xs, ys, new int[]{0}, 0, from.getPlane(), startTick, Math.max(1, ticks), true,
			landing, null, null, null, null);
	}

	/**
	 * A crossing by sea, sailed tick by tick: where the raft is and which way it faces at the end
	 * of each tick, then the golem stepping ashore. It starts on the water, at the mooring, so
	 * the golem is on the raft from its first frame.
	 *
	 * @param fineXs  position at the end of each tick, in fine units; the mooring first
	 * @param facings heading at the end of each tick, 0 south, 512 west, 1024 north, 1536 east
	 */
	static Itinerary steered(int[] fineXs, int[] fineYs, int[] facings, int plane, int startTick, WorldPoint landing)
	{
		int n = fineXs.length;
		int[] xs = new int[n];
		int[] ys = new int[n];
		int[] reached = new int[n];
		int travelled = 0;
		for (int i = 0; i < n; i++)
		{
			xs[i] = Math.floorDiv(fineXs[i], Golem.TILE);
			ys[i] = Math.floorDiv(fineYs[i], Golem.TILE);
			if (i > 0)
			{
				travelled += Math.max(Math.abs(xs[i] - xs[i - 1]), Math.abs(ys[i] - ys[i - 1]));
			}
			reached[i] = travelled;
		}
		return new Itinerary(xs, ys, reached, travelled, plane, startTick, Math.max(1, n - 1), true, landing,
			null, fineXs, fineYs, facings);
	}

	/** Where a crossing is this far in, in fine units: gliding from one tick's position to the next. */
	private int[] alongCrossing(double time)
	{
		int last = fineXs.length - 1;
		if (time >= last)
		{
			return new int[]{fineXs[last], fineYs[last]};
		}
		int i = (int) Math.floor(time);
		if (jumps(i))
		{
			// Through a cave mouth: out of one and straight in at the other, not sliding
			// the thousands of tiles between.
			return new int[]{fineXs[i], fineYs[i]};
		}
		double into = time - i;
		return new int[]{
			fineXs[i] + (int) Math.round((fineXs[i + 1] - fineXs[i]) * into),
			fineYs[i] + (int) Math.round((fineYs[i + 1] - fineYs[i]) * into),
		};
	}

	/** A move between two ticks longer than any boat makes: a raft put through from one cave mouth to the other. */
	private static final int JUMP = 16 * Golem.TILE;

	private boolean jumps(int tick)
	{
		return Math.abs(fineXs[tick + 1] - fineXs[tick]) > JUMP || Math.abs(fineYs[tick + 1] - fineYs[tick]) > JUMP;
	}

	/**
	 * Which way a crossing's raft faces part way through a tick, turning the short way from one
	 * tick's heading to the next; -1 for any other route.
	 */
	int facingAt(int tick, float fraction)
	{
		if (facings == null)
		{
			return -1;
		}
		int last = facings.length - 1;
		double time = Math.max(0, tick + (double) fraction - startTick);
		if (time >= last)
		{
			return facings[last];
		}
		int i = (int) Math.floor(time);
		if (jumps(i))
		{
			return facings[i];
		}
		int turn = ((facings[i + 1] - facings[i] + 1024) & 2047) - 1024;
		return (facings[i] + (int) Math.round(turn * (time - i))) & 2047;
	}

	/** The waypoint the golem is at or has most recently passed at this tick. */
	private int segmentAt(int tick)
	{
		return fineXs != null ? Math.min(fineXs.length - 1, Math.max(0, tick - startTick))
			: segmentFor((int) Math.floor(travelledAt(tick)));
	}

	/**
	 * Where the golem is at this tick, in 128ths of a tile. Interpolated by distance, so a golem
	 * on a long straight leg moves along it, and clamped at both ends: an expired route means it
	 * has arrived and waits, not that it has vanished.
	 */
	int[] fineAt(int tick)
	{
		return fineAt(tick, 0f);
	}

	/**
	 * As {@link #fineAt(int)}, part way through a tick. For a golem in view: read in whole ticks
	 * and tiles, a boat stepped across the sea instead of gliding.
	 *
	 * @param fraction how far through the tick, 0 to 1
	 */
	int[] fineAt(int tick, float fraction)
	{
		if (landing != null && isFinished(tick))
		{
			return fine(landing.getX(), landing.getY());
		}
		if (fineXs != null)
		{
			return alongCrossing(Math.max(0, tick + (double) fraction - startTick));
		}
		return along(travelledAt(tick + (double) fraction));
	}

	/** The tick {@link #memoX} and {@link #memoY} were worked out for. */
	private int memoTick = Integer.MIN_VALUE;
	private int memoX;
	private int memoY;

	/**
	 * {@link #fineAt(int)}'s x, kept for the tick it was asked for: a route never changes once
	 * planned, so a tick's answer is worked out once however many frames ask for it.
	 */
	int fineXAt(int tick)
	{
		memoise(tick);
		return memoX;
	}

	/** {@link #fineAt(int)}'s y; see {@link #fineXAt}. */
	int fineYAt(int tick)
	{
		memoise(tick);
		return memoY;
	}

	private void memoise(int tick)
	{
		if (tick != memoTick)
		{
			int[] at = fineAt(tick);
			memoX = at[0];
			memoY = at[1];
			memoTick = tick;
		}
	}

	/** Tiles along the waypoints the golem has covered by this time, in ticks. */
	private double travelledAt(double time)
	{
		double elapsed = Math.min(Math.max(0, time - startTick), duration);
		if (landing != null)
		{
			// A tick a tile, then standing at the transport until it is used.
			return Math.min(elapsed, length);
		}
		return length <= 0 || duration <= 0 ? 0 : elapsed * length / duration;
	}

	/** The position a given distance along the waypoints, in fine units. */
	private int[] along(double travelled)
	{
		int segment = segmentFor((int) Math.floor(travelled));
		if (segment >= xs.length - 1)
		{
			return fine(xs[xs.length - 1], ys[ys.length - 1]);
		}

		int from = reached[segment];
		int span = reached[segment + 1] - from;
		if (span <= 0)
		{
			return fine(xs[segment], ys[segment]);
		}

		// Sub-tile position along this leg, so movement is smooth rather than stepped.
		double into = travelled - from;
		int fromX = fine(xs[segment]);
		int fromY = fine(ys[segment]);
		int toX = fine(xs[segment + 1]);
		int toY = fine(ys[segment + 1]);

		return new int[]{
			fromX + (int) Math.round((toX - fromX) * into / span),
			fromY + (int) Math.round((toY - fromY) * into / span),
		};
	}

	/** The waypoint the golem has most recently passed. */
	private int segmentFor(int travelled)
	{
		int low = 0;
		int high = reached.length - 1;
		while (low < high)
		{
			int mid = (low + high + 1) >>> 1;
			if (reached[mid] <= travelled)
			{
				low = mid;
			}
			else
			{
				high = mid - 1;
			}
		}
		return low;
	}

	/** Where the golem is at this tick, to the nearest tile. */
	WorldPoint positionAt(int tick)
	{
		int[] at = fineAt(tick);
		return new WorldPoint(at[0] / Golem.TILE, at[1] / Golem.TILE, planeAt(tick));
	}

	/**
	 * The plane the golem is on at this tick: the walk's, until a transport has moved it.
	 * Reading the destination's plane had a golem walking to a ladder already upstairs.
	 */
	int planeAt(int tick)
	{
		return landing != null && isFinished(tick) ? landing.getPlane() : plane;
	}

	/**
	 * The direction the golem is travelling at this tick, as a fine-unit delta. Taken from the
	 * leg it is on, not from where it was last frame, so a stationary golem still faces the way
	 * it is going.
	 */
	int[] headingAt(int tick)
	{
		if (facings != null)
		{
			double angle = (facingAt(tick, 0f) - 1024) * Math.PI / 1024;
			return new int[]{(int) Math.round(Math.sin(angle) * Golem.TILE), (int) Math.round(Math.cos(angle) * Golem.TILE)};
		}
		if (length <= 0)
		{
			return new int[]{0, 0};
		}
		int segment = segmentAt(tick);
		if (segment >= xs.length - 1)
		{
			segment = Math.max(0, xs.length - 2);
		}
		return new int[]{
			(xs[segment + 1] - xs[segment]) * Golem.TILE,
			(ys[segment + 1] - ys[segment]) * Golem.TILE,
		};
	}

	/** True once the route has been fully travelled and a new one is needed. */
	boolean isFinished(int tick)
	{
		return tick - startTick >= duration;
	}

	/** Where the golem ends up: the landing of a transport, or the last waypoint. */
	WorldPoint destination()
	{
		return landing != null ? landing : walkEnd();
	}

	/** The last waypoint: the origin of a transport, or the destination of a plain route. */
	WorldPoint walkEnd()
	{
		// Made once: a golem out of view that has arrived asks for this every frame until
		// it gets a new route.
		if (walkEnd == null)
		{
			walkEnd = new WorldPoint(xs[xs.length - 1], ys[ys.length - 1], plane);
		}
		return walkEnd;
	}

	private WorldPoint walkEnd;

	/** True if this route ends by taking a transport rather than on its last tile. */
	boolean endsInTransport()
	{
		return transport != null;
	}

	/** True if this is a crossing by sea with legs to sail, rather than a passage or a walk. */
	boolean isSailed()
	{
		return voyage && xs.length > 1;
	}

	/** The transport this route ends in, or null. */
	GolemTransport transport()
	{
		return transport;
	}

	int waypoints()
	{
		return xs.length;
	}

	/**
	 * The same route walked backwards from where the golem has got to: the second rung of the
	 * raft's unstick ladder, since a boat in a dead-end inlet got there along an open route.
	 *
	 * @return a route back toward the start, or null if there is nothing to back out of
	 */
	Itinerary reversed(int tick, int newStartTick)
	{
		int at = segmentAt(tick);
		if (at < 1)
		{
			return null;
		}

		List<int[]> back = new java.util.ArrayList<>();
		for (int i = at; i >= 0; i--)
		{
			back.add(new int[]{xs[i], ys[i]});
		}

		// Same pace it came in at, which the route's length over its duration already says; a
		// walk to a transport went at a tick a tile.
		int ticksPerTile = landing != null ? 1 : Math.max(1, duration / Math.max(1, length));
		return of(back, plane, newStartTick, ticksPerTile, 0, voyage);
	}

	/**
	 * How far along the route the golem is, for deciding whether interrupting a journey is worth
	 * it: a golem nine tenths across an ocean should finish even if the reason has evaporated.
	 */
	float progress(int tick)
	{
		return duration <= 0 ? 1f
			: Math.min(1f, Math.max(0f, (tick - startTick) / (float) duration));
	}

	private static int fine(int tile)
	{
		return tile * Golem.TILE + Golem.TILE / 2;
	}

	private static int[] fine(int tileX, int tileY)
	{
		return new int[]{fine(tileX), fine(tileY)};
	}
}

package com.golemsdontdie;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel listing every golem, with a name field and a remove button each.
 *
 * <p>A panel rather than config items because the list is not a setting: it grows and shrinks
 * as golems are made and retired, and RuneLite's config UI is generated from a fixed interface,
 * so a dynamic list with per-row controls must be built by hand. It replaces a "forget saved
 * golems" tick box that could only delete every golem at once.
 */
class GolemListPanel extends PluginPanel
{
	private static final Font HEADING = FontManager.getRunescapeBoldFont().deriveFont(18f);
	private static final Font ROW = FontManager.getRunescapeFont().deriveFont(16f);
	private static final Font PLACEHOLDER = ROW.deriveFont(Font.ITALIC);

	/** Dim enough to read as absent text rather than as a name someone chose. */
	private static final Color PLACEHOLDER_COLOUR = new Color(120, 120, 120);

	private final JPanel rows = new JPanel();
	private final JLabel summary = new JLabel();

	/**
	 * Offers to make up the difference when fewer golems are roaming than have been crafted.
	 * Hidden whenever the two agree.
	 */
	private final JButton revive = new JButton();

	private final Consumer<Golem> onRemove;

	/** A golem and its new name, or null for none. Called on the Swing thread. */
	private final java.util.function.BiConsumer<Golem, String> onRename;

	private final Runnable onRevive;

	/**
	 * The row showing each golem, keyed by the golem itself: one restored at login is a new
	 * object, and a row holding the old one would rename a golem no longer in the roster.
	 */
	private final java.util.Map<Golem, Row> shown = new java.util.IdentityHashMap<>();

	/** One golem's row: what goes in the list, and the name field in it. */
	private static final class Row
	{
		final JPanel component;
		final JTextField name;

		/** Set while the name is being put in from the game, so it is not taken for typing. */
		boolean settingName;

		Row(JPanel component, JTextField name)
		{
			this.component = component;
			this.name = name;
		}
	}

	GolemListPanel(Consumer<Golem> onRemove, java.util.function.BiConsumer<Golem, String> onRename, Runnable onRevive)
	{
		super(false);
		this.onRemove = onRemove;
		this.onRename = onRename;
		this.onRevive = onRevive;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(16, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		summary.setFont(HEADING);
		summary.setForeground(Color.WHITE);
		summary.setHorizontalAlignment(SwingConstants.CENTER);
		summary.setBorder(BorderFactory.createEmptyBorder(0, 0, 12, 0));

		revive.setFont(ROW);
		revive.setFocusPainted(false);
		revive.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		revive.setForeground(Color.WHITE);
		revive.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		revive.addActionListener(e -> onRevive.run());
		revive.setVisible(false);

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 12, 0));
		header.add(summary, BorderLayout.NORTH);
		header.add(revive, BorderLayout.CENTER);
		add(header, BorderLayout.NORTH);

		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Rows are pinned to the top of a filler panel so a short list does not stretch
		// down the whole panel.
		JPanel filler = new JPanel(new BorderLayout());
		filler.setBackground(ColorScheme.DARK_GRAY_COLOR);
		filler.add(rows, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(filler,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);
	}

	/**
	* Redraws the list. Rebuilt only when the set of golems changes: this is called every game
	* tick, and recreating a text field the player might be typing in would make renaming
	* impossible.
	*
	* @param missing how many fewer golems are roaming than crafted; the revive button shows
	*                only when this is positive
	*/
	void refresh(List<Golem> golems, int missing)
	{
		refresh(golems, missing, false);
	}

	/**
	 * Brings the list up to date with the roster, changing only what changed: rebuilding the
	 * whole list made three thousand rows of components every time a golem was made or
	 * crumbled, and threw away a half-typed name.
	 *
	 * @param names also show names given in game, which leave the roster otherwise unchanged
	 */
	void refresh(List<Golem> golems, int missing, boolean names)
	{
		SwingUtilities.invokeLater(() ->
		{
			updateRevive(missing);

			java.util.Set<Golem> wanted = java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<>());
			wanted.addAll(golems);
			boolean changed = false;

			// Gone first, so what is left in the list is only rows that are staying.
			java.util.Iterator<java.util.Map.Entry<Golem, Row>> it = shown.entrySet().iterator();
			while (it.hasNext())
			{
				java.util.Map.Entry<Golem, Row> entry = it.next();
				if (!wanted.contains(entry.getKey()))
				{
					rows.remove(entry.getValue().component);
					it.remove();
					changed = true;
				}
			}

			// Then walk the roster against what is displayed: a row in its place is left
			// alone, a new golem's is inserted, one out of place is moved.
			for (int i = 0; i < golems.size(); i++)
			{
				Golem golem = golems.get(i);
				Row row = shown.get(golem);
				if (row == null)
				{
					row = row(golem);
					shown.put(golem, row);
					rows.add(row.component, i);
					changed = true;
				}
				else
				{
					if (i >= rows.getComponentCount() || rows.getComponent(i) != row.component)
					{
						rows.remove(row.component);
						rows.add(row.component, Math.min(i, rows.getComponentCount()));
						changed = true;
					}
					if (names)
					{
						showName(row, golem);
					}
				}
			}

			updateSummary(golems.size());
			if (changed)
			{
				rows.revalidate();
				rows.repaint();
			}
		});
	}

	/** Puts a golem's name into its field, if it differs, without that counting as typing. */
	private static void showName(Row row, Golem golem)
	{
		String name = golem.getNickname() == null ? "" : golem.getNickname();
		if (!row.name.getText().trim().equals(name))
		{
			row.settingName = true;
			try
			{
				row.name.setText(name);
			}
			finally
			{
				row.settingName = false;
			}
		}
	}

	/**
	 * Shows or hides the revive button: only present when there is something to revive, since a
	 * button that does nothing most of the time is worse than no button.
	 */
	private void updateRevive(int missing)
	{
		boolean show = missing > 0;
		if (show)
		{
			revive.setText("Revive missing golems (" + missing + ")");
		}
		if (revive.isVisible() != show)
		{
			revive.setVisible(show);
			revalidate();
			repaint();
		}
	}

	private void updateSummary(int count)
	{
		summary.setText(count == 0
			? "No golems yet"
			: count + (count == 1 ? " golem" : " golems") + " unleashed");
	}

	private Row row(Golem golem)
	{
		JPanel panel = new JPanel(new BorderLayout(6, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 6));
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));

		JTextField name = new PlaceholderField(golem.getNickname());
		Row[] self = new Row[1];
		name.setToolTipText("Name this golem");
		name.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rename();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rename();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rename();
			}

			private void rename()
			{
				if (self[0] != null && self[0].settingName)
				{
					return;
				}
				// Not set here: golems belong to the client thread, and this is Swing's.
				String text = name.getText().trim();
				onRename.accept(golem, text.isEmpty() ? null : text);
			}
		});
		panel.add(name, BorderLayout.CENTER);

		JButton remove = new JButton("✕");
		remove.setToolTipText("Remove this golem");
		remove.setFont(ROW);
		remove.setFocusPainted(false);
		remove.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		remove.setForeground(Color.LIGHT_GRAY);
		remove.setBorder(BorderFactory.createEmptyBorder(2, 8, 2, 8));
		remove.addActionListener(e -> onRemove.accept(golem));
		panel.add(remove, BorderLayout.EAST);

		// Spacing between rows, which a BoxLayout will not do on its own.
		JPanel spaced = new JPanel(new BorderLayout());
		spaced.setBackground(ColorScheme.DARK_GRAY_COLOR);
		spaced.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		spaced.setMaximumSize(new Dimension(Integer.MAX_VALUE, 46));
		spaced.add(panel, BorderLayout.CENTER);
		self[0] = new Row(spaced, name);
		return self[0];
	}

	/**
	 * A text field that shows dimmed italic prompt text while it is empty. Swing has no
	 * placeholder, and the obvious workaround — real text cleared on focus — is wrong here:
	 * that text is indistinguishable from a name and would be saved as one.
	 */
	private static final class PlaceholderField extends JTextField
	{
		private static final String PROMPT = "Unnamed Golem";

		PlaceholderField(String initial)
		{
			super(initial == null ? "" : initial);
			setFont(ROW);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setForeground(Color.WHITE);
			setCaretColor(Color.WHITE);
			setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);

			if (!getText().isEmpty())
			{
				return;
			}

			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
					RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				g2.setFont(PLACEHOLDER);
				g2.setColor(PLACEHOLDER_COLOUR);

				// On the same baseline as the real text, so the prompt does not jump
				// when the player types over it.
				int x = getInsets().left;
				int y = (getHeight() - g2.getFontMetrics().getHeight()) / 2
					+ g2.getFontMetrics().getAscent();
				g2.drawString(PROMPT, x, y);
			}
			finally
			{
				g2.dispose();
			}
		}
	}
}

package com.golemsdontdie;

import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Draws a {@link Golem} while it is inside the loaded scene.
 *
 * <p>Deliberately thin: it decides nothing about where the golem goes, only reading the
 * simulation's position each frame, and a golem that leaves the scene loses its renderer but
 * keeps walking. The pose is applied here rather than copied from a real NPC, which would need
 * an original still alive and posed every frame; the base model is the cache's rest pose, driven
 * by an {@link AnimationController} of our own.
 */
class FakeGolem extends RuneLiteObjectController
{
	/** 128ths of a tile per tile, for scene-to-local conversion. */
	private static final int TILE = Golem.TILE;

	private final Client client;
	private final Golem golem;
	private final Model baseModel;

	/** Source of the shared model and animation definitions. */
	private final GolemModelFactory shared;

	/**
	 * Drives the walk or idle loop. One controller, not the client's active-plus-pose pair:
	 * a wandering golem only ever plays one thing at a time.
	 */
	private final AnimationController animation;

	/** Which animation ID the controller currently holds, to avoid resetting it every frame. */
	private int loadedAnimationId = Integer.MIN_VALUE;

	/**
	 * Where each drawn frame of a traversal is reported, or null. Here rather than in the
	 * simulation because this is what is on screen: the position after the renderer copied it.
	 */
	private java.util.function.Consumer<String> trace;

	/**
	 * Whether anyone is recording. A golem mid-obstacle otherwise built a dozen strings every
	 * frame for nothing to read.
	 */
	private java.util.function.BooleanSupplier tracing = () -> true;

	/** How tall the golem is drawn, in the client's height units, for putting things above its head. */
	int getModelHeight()
	{
		return baseModel.getModelHeight();
	}

	/** Whether the last traced frame was mid-traversal. */
	private boolean wasTraversing;

	FakeGolem(Client client, Golem golem, Model baseModel, GolemModelFactory shared)
	{
		this.client = client;
		this.golem = golem;
		this.baseModel = baseModel;
		this.shared = shared;
		this.animation = new AnimationController(client, -1);

		// The default radius suits a single-tile object; a bigger golem needs the tiles under
		// its footprint drawn first or it z-fights with the ground.
		int size = Math.max(1, golem.getSnapshot().getSize());
		setRadius(size * 64 - 4);
		setDrawFrontTilesFirst(true);

		syncTransform();
		applyPose();
	}

	void setTrace(java.util.function.Consumer<String> trace, java.util.function.BooleanSupplier tracing)
	{
		this.trace = trace;
		this.tracing = tracing;
	}

	/**
	 * Called by the client once per frame while registered. Only the animation is advanced here;
	 * position is advanced centrally for every golem, including those off screen, or one would
	 * freeze on leaving the scene.
	 */
	@Override
	public void tick(int ticksSinceLastFrame)
	{
		syncTransform();
		applyPose();

		// A recording drives its own keyframes, so the client's clock must not also
		// advance them — that was the drift.
		if (golem.getMotionFrame() < 0)
		{
			animation.tick(ticksSinceLastFrame);
		}

		// One frame past the end too: a door teleports on the frame its transition ends, so
		// stopping there logged its last position halfway across.
		boolean traversing = golem.inTransition();
		boolean landed = wasTraversing && !traversing;
		wasTraversing = traversing;
		if (trace != null && (traversing || landed) && tracing.getAsBoolean())
		{
			Animation playing = animation.getAnimation();
			trace.accept("fine=" + golem.getFineX() + "," + golem.getFineY()
				+ " drawn=" + getX() + "," + getY()
				+ " orient=" + golem.getOrientation()
				+ " anim=" + loadedAnimationId
				+ " keyframe=" + (playing == null ? -1 : animation.getFrame())
				+ " keyframes=" + (playing == null ? -1 : playing.getNumFrames())
				+ " motionFrame=" + golem.getMotionFrame());
		}
	}

	/** The client cycle this golem was last asked for a model, which is when it was drawn. */
	private int lastDrawnCycle = -1;

	int getLastDrawnCycle()
	{
		return lastDrawnCycle;
	}

	@Override
	public Model getModel()
	{
		// Only asked for when the client actually draws the object, so a golem registered but
		// not drawn shows in the debug log.
		lastDrawnCycle = client.getGameCycle();
		if (animation.getAnimation() == null)
		{
			return baseModel;
		}
		Model posed = animation.animate(baseModel);
		return posed == null ? baseModel : posed;
	}

	/**
	 * The shape the mouse has to be inside for this golem to be hovered. A
	 * {@link RuneLiteObjectController} is drawn but not clickable, the client building its menu
	 * from real entities, so the hit test is done by hand.
	 *
	 * <p>Tested against the <b>rest pose</b>, so the box ignores a swinging arm:
	 * {@link #getModel()} meant a skeletal transform per golem per tick on top of the
	 * projection, which stalled the client whenever the cursor sat over the scene, and was
	 * unsound, that model being a shared buffer the API forbids holding across another
	 * transformation.
	 *
	 * @return the clickbox, or null if it cannot be computed this frame
	 */
	java.awt.Shape clickbox()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || baseModel == null)
		{
			return null;
		}
		try
		{
			return Perspective.getClickbox(client, wv, baseModel, getOrientation(), getX(), getY(), getZ());
		}
		catch (RuntimeException e)
		{
			// Off-screen or degenerate geometry; not being hoverable for a frame is
			// not worth propagating.
			return null;
		}
	}

	/** Copies the simulation's position and heading onto the drawn object. */
	private void syncTransform()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		// Drawn where the golem appears to the player, which inside an instance is not where
		// it is simulated. See Golem.setDrawOffset.
		int localX = golem.getDrawFineX() - wv.getBaseX() * TILE;
		int localY = golem.getDrawFineY() - wv.getBaseY() * TILE;

		setX(localX);
		setY(localY);
		setWorldView(wv.getId());
		setLevel(golem.getDrawPlane());
		setOrientation(golem.getOrientation());

		// Ground height is re-read as the golem moves: Wyrmscraig is not flat, and a golem
		// holding its spawn height would sink into a rise.
		if (Golem.isInScene(wv, localX, localY))
		{
			// Terrain height plus whatever the golem is doing above it — mid-jump an arc, so
			// a hop leaves the ground instead of sliding at ankle height.
			setZ(Perspective.getTileHeight(client, new LocalPoint(localX, localY, wv), golem.getDrawPlane())
				- golem.jumpArc() - golem.deckLift());
		}
	}

	/** Switches between the walk and idle loops as the simulation changes its mind. */
	private void applyPose()
	{
		int wanted = golem.currentPoseAnimation();
		if (wanted != loadedAnimationId || animation.getAnimation() == null)
		{
			loadedAnimationId = wanted;
			animation.setAnimation(shared.animationFor(wanted));
		}

		// While performing a recording, the keyframe is the player's own, set directly.
		// Advancing the clip by elapsed cycles at its authored speed is wrong: on a basalt
		// stone the player holds keyframe one for about twenty-five cycles then runs the other
		// seven during the jump, where the authored clip takes forty — golems finished hopping
		// before leaving the ground.
		//
		// Never past the last keyframe: the controller nulls a completed one-shot, and the
		// next frame would load and play it again.
		int frame = golem.getMotionFrame();
		Animation loaded = animation.getAnimation();
		if (frame >= 0 && loaded != null && loaded.getNumFrames() > 0)
		{
			animation.setFrame(Math.min(frame, loaded.getNumFrames() - 1));
		}
	}
}

package com.golemsdontdie;

/**
 * Developer switches that are not in the settings panel.
 *
 * <p>Settings once, but nothing a player should meet. Flip one here, or restore its
 * commented-out item in {@link GolemsDontDieConfig}.
 */
final class DevOptions
{
	/** Outline shortcuts nearby by how well golems know them. See ObstacleHighlightOverlay. */
	static final boolean HIGHLIGHT_OBSTACLES = false;

	/**
	 * Log every visible golem's state each tick, and what it decides, at debug level. Very loud;
	 * only useful beside a bug. Nothing is written to a file: {@link ObstacleDataBridge} keeps what
	 * ordinary play is worth keeping, in the plugin's own folder.
	 */
	static final boolean LOG_GOLEM_STATE = false;

	private DevOptions()
	{
	}
}

package com.golemsdontdie;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Random;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * One golem, simulated in world coordinates whether or not it is on screen.
 *
 * <p>A golem is a position, a heading and an intention; drawing it is a view attached only
 * while it is inside the loaded scene, so one that wanders off the edge keeps walking.
 * Positions are integer 128ths of a tile, the unit the client's local coordinates use;
 * floats would accumulate error over a golem that walks for hours.
 */
class Golem
{
	/** 128 units of position per tile, matching {@link net.runelite.api.coords.LocalPoint}. */
	static final int TILE = 128;

	/** Client cycles (20ms) per tile walked. One game tick, i.e. normal NPC walking pace. */
	private static final int CYCLES_PER_TILE = 30;

	/** Orientation units turned per cycle. 2048 is a full circle. */
	private static final int TURN_PER_CYCLE = 24;

	/** Angle units: 0 south, 512 west, 1024 north, 1536 east. */
	private static final int SOUTH = 0, WEST = 512, NORTH = 1024, EAST = 1536;

	/** Cycles a golem stands still between walks, before and after a random spread. */
	private static final int DWELL_MIN = 20;
	private static final int DWELL_SPREAD = 130;

	@Getter
	private final GolemSnapshot snapshot;

	/** Where it was made. The penned roam area is measured from here. */
	@Getter
	private final WorldPoint home;

	/**
	 * Which floor the golem is on. Fixed in the island-only plugin; mutable now because the
	 * transport network is mostly vertical — 2,262 of the 5,168 plain rows change plane.
	 * Only {@link #relocate} may change it, and never mid-step.
	 */
	@Getter
	private int plane;

	/**
	 * Seeded per golem so two made on the same tile do not walk in lockstep, and a restored
	 * golem carries on with its own gait.
	 */
	private final Random random;

	/** Position in 128ths of a tile, world-absolute. */
	@Getter
	private int fineX;
	@Getter
	private int fineY;

	@Getter
	private int orientation;
	private int targetOrientation;

	/** Remaining tiles of the current walk, as world tile pairs. */
	private final Deque<int[]> path = new ArrayDeque<>();

	/** The step in progress, interpolated between two tile centres. */
	private int stepFromX, stepFromY, stepToX, stepToY;
	private int stepElapsed;
	private boolean stepping;

	/** Cycles left standing still before choosing somewhere new to go. */
	private int dwellRemaining;

	/** Whether this golem used a path search on the current frame. */
	private boolean searched;

	/**
	 * What this golem has used recently, so it does not pace through the same door. Per
	 * golem rather than shared: two golems meeting at a ladder should both be able to climb.
	 */
	private final TransportMemory transportMemory = new TransportMemory();

	/**
	 * The route this golem is on while nobody can see it, or null if it is being simulated
	 * properly. Set when it drops out of range, cleared when it comes back; while set the
	 * golem is not stepped, and its position is whatever the route says at this tick.
	 */
	private Itinerary itinerary;

	/** The tier the golem was in last frame, so crossings can be acted on once. */
	@Getter
	private GolemTier tier = GolemTier.SCENE;

	// ---------------------------------------------------------------- watchdog

	/**
	 * Consecutive destination searches that found nowhere to go.
	 *
	 * <p>One failure is ordinary; a run of them means the golem cannot walk out of where it
	 * is, which is a death in all but name.
	 */
	private int failedSearches;

	/** Where the golem was when it last actually got somewhere, and when that was. */
	private int progressX;
	private int progressY;
	private int progressTick;

	/** Failed searches in a row before the golem is treated as stuck. */
	private static final int STUCK_SEARCHES = 12;

	/** Game ticks without meaningful movement before the golem is treated as stuck. */
	private static final int STUCK_TICKS = 500;

	/** How far the golem must get for it to count as having moved at all. */
	private static final int PROGRESS_TILES = 3;

	/**
	 * True if this golem has stopped getting anywhere and should be relocated. Two signals:
	 * failed searches catch a golem walled in on ground the map says is walkable, and no net
	 * movement catches searches that succeed but leave it shuffling between two tiles. Slow
	 * to fire, since standing still a few minutes is normal.
	 */
	boolean isStuck(int tick)
	{
		if (isDying() || inTransition())
		{
			return false;
		}

		// A golem on a route is travelling, not stuck; a passage holds it at the first
		// waypoint for the whole crossing, so the watchdog hauled golems off boats.
		if (itinerary != null && !itinerary.isFinished(tick))
		{
			return false;
		}
		if (failedSearches >= STUCK_SEARCHES)
		{
			return true;
		}

		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		if (progressTick == 0
			|| Math.abs(tileX - progressX) + Math.abs(tileY - progressY) >= PROGRESS_TILES)
		{
			progressX = tileX;
			progressY = tileY;
			progressTick = tick;
			return false;
		}
		return tick - progressTick > STUCK_TICKS;
	}

	/** When this golem may next sail, in real time; 0 if it may now. For the save. */
	long getShoreLeaveUntil()
	{
		return transportMemory.getShoreLeaveUntil();
	}

	void setShoreLeaveUntil(long until)
	{
		transportMemory.setShoreLeaveUntil(until);
	}

	/**
	 * True while the golem is drawn at a raft's helm on the open sea. Set as a crossing is
	 * followed in view, cleared when it ends or the golem moves.
	 */
	@Getter
	private boolean afloat;

	/** How far above the water a golem at the helm stands: on the deck, not in the sea. */
	private static final int DECK_HEIGHT = 30;

	/** Height to lift the golem by, in the client's height units: the deck, while afloat. */
	int deckLift()
	{
		return afloat ? DECK_HEIGHT : 0;
	}

	/** True while the golem is on a crossing: afloat, or waiting out a passage. */
	boolean isSailing(int tick)
	{
		return itinerary != null && itinerary.isVoyage() && !itinerary.isFinished(tick);
	}

	/**
	 * Where to write this golem down in a save: the end of its route, ground the planner chose. Partway
	 * along a crossing it is on water, and out of view on foot it can be inside a wall beside the route.
	 */
	WorldPoint saveTile()
	{
		return itinerary != null ? itinerary.destination() : currentTile();
	}

	/** Clears the watchdog after the golem has been moved somewhere it can walk. */
	void noteUnstuck(int tick)
	{
		failedSearches = 0;
		progressTick = tick;
		progressX = fineX / TILE;
		progressY = fineY / TILE;
		eddyCycles = 0;
		reversed = false;
	}

	// ------------------------------------------------------- getting off a rock

	/** Cycles left spinning in place. The first and cheapest thing a grounded raft does. */
	private int eddyCycles;

	/** Whether this golem has already tried backing out of where it is. */
	private boolean reversed;

	/** Cycles a stuck raft turns on the spot before trying something with a cost. */
	private static final int EDDY_CYCLES = 100;

	/** True while the golem is turning on the spot rather than going anywhere. */
	boolean isDrifting()
	{
		return eddyCycles > 0;
	}

	/**
	 * Works a grounded raft free, cheapest first: spin on the spot; reverse along the stored
	 * waypoints; re-plan from where the boat is; snap to valid water. Only the snap is a
	 * cheat, and a grounded golem is unwatched almost by definition, since a watched one
	 * would be on live collision, not the shipped mesh.
	 *
	 * @return true if this handled it and nothing further should be done
	 */
	boolean workFree(RoamContext context, RoamPlanner planner)
	{
		int tick = context.getTick();

		if (eddyCycles > 0)
		{
			// Rung one is still running.
			eddyCycles = Math.max(0, eddyCycles - 1);
			targetOrientation = (orientation + 512) & 2047;
			return true;
		}

		// Not a route already through its transport: reversed, the walk back starts on the
		// far side of the ladder while the golem is at the top, and it would be put back.
		if (!reversed && itinerary != null && !(itinerary.transport() != null && itinerary.isFinished(tick)))
		{
			Itinerary back = itinerary.reversed(tick, tick);
			if (back != null)
			{
				reversed = true;
				itinerary = back;
				eddyCycles = EDDY_CYCLES;
				return true;
			}
		}

		// Rung three: a fresh plan from here. Only a golem nobody can see may be given a
		// route, because a roaming route is a straight line that ignores the map; handing a
		// visible golem one sent them sliding across the water. In view, a path search.
		if (tier == GolemTier.FAR)
		{
			Itinerary replanned = planner.plan(currentTile(), tick, random, transportMemory,
				context);
			if (replanned != null)
			{
				itinerary = replanned;
				noteUnstuck(tick);
				return true;
			}
		}
		else
		{
			chooseDestination(context);
			if (!path.isEmpty())
			{
				noteUnstuck(tick);
				return true;
			}
		}

		// Nothing left but rung four, which the caller owns because only it has the mesh.
		return false;
	}

	/**
	 * Cycles left of the crumble, or -1 if this golem is not dying. A retired golem plays
	 * the game's own death animation; vanishing on the spot would look like a bug.
	 */
	private int dyingCycles = -1;

	/** True once the crumble has been started. The golem stops walking and cannot path. */
	boolean isDying()
	{
		return dyingCycles >= 0;
	}

	/** True when the crumble has played out and the golem should be dropped. */
	boolean isCrumbled()
	{
		return dyingCycles == 0;
	}

	/**
	 * Begins the crumble. Idempotent, so asking twice does not restart it.
	 */
	void startDying()
	{
		if (dyingCycles < 0)
		{
			dyingCycles = GolemContent.GOLEM_DEATH_CYCLES;
			path.clear();
			stepping = false;
			walking = false;
		}
	}

	/** True while the golem is moving, which selects the walk animation over the idle. */
	@Getter
	private boolean walking;

	/** Set when the golem is inside the loaded scene and should be drawn. */
	@Getter
	@Setter
	private FakeGolem renderer;

	/**
	 * A name the player has given this golem, or null for none.
	 *
	 * <p>Bookkeeping for the side panel: the world calls every one of them "Golem", so a
	 * nickname on right-click gives the copy away.
	 */
	@Getter
	@Setter
	private String nickname;

	/**
	 * True while the golem is inside an instance — through the pew, in the Mad Angel's room.
	 * Golems are simulated in the instance's template, ordinary world coordinates, so
	 * coordinates alone cannot say who is inside; without this, golems near the cathedral
	 * were drawn inside the player's instance.
	 */
	@Getter
	@Setter
	private boolean inInstance;

	/** What a transport will make {@link #inInstance} on landing: 1, 0, or -1 for no change. */
	private int landingInstance = -1;

	private void landInInstance()
	{
		if (landingInstance >= 0)
		{
			inInstance = landingInstance == 1;
			landingInstance = -1;
		}
	}

	/** The same, for a golem out of view that has already arrived through a transport. */
	private void noteInstance(GolemTransport transport)
	{
		if (transport.entersInstance())
		{
			inInstance = true;
		}
		else if (transport.leavesInstance())
		{
			inInstance = false;
		}
	}

	/** Stable identity for the side panel and the save file, assigned on creation. */
	@Getter
	private final long id;

	Golem(GolemSnapshot snapshot, WorldPoint home, long seed, int startFineX, int startFineY)
	{
		this.snapshot = snapshot;
		this.home = home;
		this.plane = home.getPlane();
		this.random = new Random(seed);
		this.id = seed;

		this.fineX = startFineX;
		this.fineY = startFineY;
		this.orientation = snapshot.getOrientation() & 2047;
		this.targetOrientation = this.orientation;
		this.dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
	}

	/**
	 * Creates a golem on the centre of a tile, for restoring a save where only the tile was
	 * written down. Taking over from a live golem uses the other constructor with its exact
	 * sub-tile position; snapping to a tile centre there made the copy look teleported.
	 */
	static Golem onTile(GolemSnapshot snapshot, WorldPoint home, long seed, WorldPoint at)
	{
		return new Golem(snapshot, home, seed,
			at.getX() * TILE + TILE / 2,
			at.getY() * TILE + TILE / 2);
	}

	/**
	 * True if a scene-local position is inside the loaded scene. Replaces
	 * {@link net.runelite.api.coords.LocalPoint#isInScene()}, deprecated for assuming every
	 * scene is 104 tiles square; the world view's own size is correct for instances too.
	 */
	static boolean isInScene(WorldView wv, int localX, int localY)
	{
		return localX >= 0 && localY >= 0
			&& localX < wv.getSizeX() * TILE
			&& localY < wv.getSizeY() * TILE;
	}

	/** The tile the golem is standing on or walking out of. */
	WorldPoint currentTile()
	{
		return new WorldPoint(fineX / TILE, fineY / TILE, plane);
	}

	/**
	 * Moves the golem between tiers, doing the one-off work each crossing needs.
	 *
	 * <p>Called every frame; most frames the tier is unchanged. Inward, the route resolves to
	 * a tile snapped onto real walkable ground — which is what makes the straight-line far
	 * routes safe, correcting them exactly when the error would show. Outward, the renderer
	 * is dropped and a route is planned.
	 *
	 * @return true if the golem changed tier
	 */
	/** The tick this golem is next looked at while it is out of view. See {@link #scheduleFarCheck}. */
	private int nextFarCheck = Integer.MIN_VALUE;

	boolean farCheckDue(int tick)
	{
		return tick >= nextFarCheck;
	}

	/**
	 * Decides when a golem out of view is next looked at. Its position is a function of
	 * time, so nothing need happen between the moments something could change: the route
	 * running out, or the player coming near. Each golem takes its own tick in the cycle,
	 * spread by its id, so a few thousand share the work.
	 */
	void scheduleFarCheck(int tick, int interval)
	{
		if (itinerary == null || itinerary.isFinished(tick))
		{
			nextFarCheck = tick;
			return;
		}
		int slot = (int) ((id ^ (id >>> 32)) & 0x7fffffff) % interval;
		int next = tick + interval - (tick + slot) % interval;
		nextFarCheck = Math.min(next, itinerary.getStartTick() + itinerary.getDuration());
	}

	/**
	 * Puts a golem out of view where its route says it is now, before its tier is judged.
	 * Looked at only every few ticks, its last position can be a few ticks old.
	 */
	void catchUpFar(int tick)
	{
		if (itinerary != null && !itinerary.isFinished(tick))
		{
			this.fineX = itinerary.fineXAt(tick);
			this.fineY = itinerary.fineYAt(tick);
			this.plane = itinerary.planeAt(tick);
		}
	}

	boolean setTier(GolemTier now, RoamContext context, RoamPlanner planner)
	{
		if (now == tier)
		{
			return false;
		}

		boolean wasFar = tier == GolemTier.FAR;
		tier = now;
		// Out of view a crossing is not drawn, so there is nothing to trace.
		if (now != GolemTier.SCENE)
		{
			tracing = null;
		}

		if (now == GolemTier.FAR)
		{
			// Walking to a shortcut or a dock is something only a golem in view does.
			queuedTransport = null;
			queuedDock = null;
			// A crossing keeps going, out of view as into it. Planning afresh from the open
			// sea found nowhere to walk, so the golem idled on the water for good.
			if (itinerary != null && itinerary.isVoyage() && !itinerary.isFinished(context.getTick()))
			{
				return true;
			}
			itinerary = planner.plan(currentTile(), context.getTick(), random, transportMemory, context);
			return true;
		}

		if (wasFar)
		{
			// A crossing keeps going: it was searched over the ocean mesh, so a player who
			// sails out to meet one finds it where the route says, still sailing.
			if (itinerary != null && itinerary.isVoyage()
				&& !itinerary.isFinished(context.getTick()))
			{
				return true;
			}

			if (itinerary != null && itinerary.isFinished(context.getTick()) && itinerary.transport() != null)
			{
				noteInstance(itinerary.transport());
			}
			WorldPoint resolved = itinerary != null
				? itinerary.positionAt(context.getTick())
				: currentTile();
			relocate(planner.snapToMesh(resolved));
			itinerary = null;
		}
		return true;
	}

	/**
	 * Advances a golem nobody can see, almost always nothing at all: the only work is
	 * replanning when a route runs out, once a minute or so per golem.
	 */
	/**
	 * Moves the golem along its route, and tidies up when the route runs out. Position comes
	 * from the route rather than being stepped toward it, so the mechanism is the same
	 * watched or not; only the ending differs.
	 */
	private void followItinerary(int cycles, RoamContext context)
	{
		int tick = context.getTick();

		// Sub-tile, interpolated along the route by distance. Reading the waypoint index
		// instead made a golem jump a whole straightened leg at a time.
		int[] at = itinerary.fineAt(tick, context.getTickFraction());

		// Face along the leg being travelled: the route's own answer, not dependent on
		// having moved since last frame.
		int facing = itinerary.facingAt(tick, context.getTickFraction());
		if (facing >= 0)
		{
			// At sea the raft's own heading, which already turns at a raft's pace. The
			// walking turn on top of it lagged the raft round every bend.
			orientation = facing;
			targetOrientation = facing;
		}
		else
		{
			int[] heading = itinerary.headingAt(tick);
			if (heading[0] != 0 || heading[1] != 0)
			{
				targetOrientation = headingFor(heading[0], heading[1]);
			}
			turnToward(cycles);
		}

		this.fineX = at[0];
		this.fineY = at[1];
		this.plane = itinerary.planeAt(tick);

		// At sea the golem holds the helm: it played its walk the whole crossing, which read
		// as a golem running on the spot in a boat. A passage from the cave dock is not sea.
		walking = false;
		afloat = itinerary.isSailed() && !itinerary.isFinished(tick);

		if (itinerary.isFinished(tick) && tier != GolemTier.FAR)
		{
			boolean wasVoyage = itinerary.isVoyage();
			itinerary = null;
			walking = false;
			afloat = false;
			dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);

			// A voyage ends at a mooring, which is water: left there the golem would stand
				// on the sea with nowhere to walk, so it is put ashore.
			if (wasVoyage)
			{
				transportMemory.beginShoreLeaveOnArrival(tick, tick, random);
				RoamPlanner planner = context.getPlanner();
				if (planner != null)
				{
					relocate(planner.snapToMesh(currentTile()));
				}
			}
		}
	}

	/**
	 * @param mayPlan false once this frame's planning is spent, so a golem whose route ran
	 *                out stands where it arrived and plans on a later frame rather than a
	 *                thousand of them searching in the same one.
	 * @return true if a route was planned
	 */
	boolean advanceFar(RoamContext context, RoamPlanner planner, boolean mayPlan)
	{
		// Nobody sees a golem out of view crumble, so it is simply done. The crumble only
		// counted down in view, and a golem told to go while out of it stayed in the roster,
		// still walking, for the rest of the session.
		if (isDying())
		{
			dyingCycles = 0;
			return false;
		}

		int tick = context.getTick();

		if (itinerary != null && !itinerary.isFinished(tick))
		{
			// Read the route's position rather than stepping toward it: a binary search and
			// a lerp, so "costs nothing" means no search, no allocation and no drift. Live
			// position lets the tier check notice a golem sailing toward the player, and
			// stops one mid-ocean saving the port it left. Cached per tick.
			this.fineX = itinerary.fineXAt(tick);
			this.fineY = itinerary.fineYAt(tick);
			this.plane = itinerary.planeAt(tick);
			return false;
		}

		if (itinerary != null && itinerary.transport() != null)
		{
			noteInstance(itinerary.transport());
		}
		WorldPoint at = itinerary == null ? currentTile() : itinerary.destination();
		this.fineX = at.getX() * TILE + TILE / 2;
		this.fineY = at.getY() * TILE + TILE / 2;
		this.plane = at.getPlane();
		if (!mayPlan)
		{
			return false;
		}

		itinerary = planner.plan(at, tick, random, transportMemory, context);
		if (itinerary == null)
		{
			// Nowhere found: stand a moment before looking again. See RoamPlanner.idle.
			itinerary = RoamPlanner.idle(at, tick, random, farFailures++);
		}
		else
		{
			farFailures = 0;
		}
		return true;
	}

	/** Plans in a row that found nowhere to go; lengthens the pause before the next. */
	private int farFailures;

	/**
	 * Puts the golem down somewhere else entirely — the far end of a ladder, a dock it has
	 * just sailed to, or a valid tile after it was found somewhere it cannot stand.
	 *
	 * <p>Everything mid-flight has to go: a queued path found on the old plane would walk
	 * the golem through the new floor, and a half-finished step would interpolate it across
	 * the map. Identity is untouched.
	 */
	void relocate(WorldPoint to)
	{
		this.plane = to.getPlane();
		this.fineX = to.getX() * TILE + TILE / 2;
		this.fineY = to.getY() * TILE + TILE / 2;

		path.clear();
		gaitWalk = -1;
		gaitIdle = -1;
		gaitFinish = -1;
		motion = null;
		stepping = false;
		stepElapsed = 0;
		walking = false;
		afloat = false;

		// The route goes too: a kept itinerary would resolve against the new position next
		// frame and drag the golem straight back, making a rescue look like a rubber band.
		itinerary = null;
		queuedTransport = null;
		queuedDock = null;
		transportMemory.clearPending();
		// A crossing interrupted by being put somewhere else is not one worth recording.
		tracing = null;

		// Arriving somewhere new is a moment to stand and look around, and it keeps a golem
		// from immediately pathing back out of a doorway it just used.
		dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
	}

	/**
	 * Advances the simulation.
	 *
	 * @param cycles client cycles (20ms each) since the last advance
	 * @param bounds where it may walk, re-derived each time so flipping the free roam
	 *               setting takes effect on the golem's next decision
	 */
	boolean advance(int cycles, RoamContext context)
	{
		if (cycles <= 0)
		{
			return false;
		}
		this.searched = false;

		if (isDying())
		{
			// Stands where it is and crumbles. No turning, no walking, no pathing.
			dyingCycles = Math.max(0, dyingCycles - cycles);
			return false;
		}

		sampleTrace(cycles);

		// Mid-obstacle: playing a climb or a squeeze, so it must not walk, turn or path
		// until it has finished and landed.
		if (advanceTransition(cycles))
		{
			return false;
		}

		// A route carries the golem only if it is a crossing. Roaming routes are straight
		// lines drawn without consulting the map, safe only while nobody can see: following
		// one in view put golems sliding through the sea and the cliffs, so one found here
		// is discarded.
		if (itinerary != null)
		{
			if (itinerary.isVoyage())
			{
				followItinerary(cycles, context);
				return false;
			}
			itinerary = null;
		}

		turnToward(cycles);

		// Movement is resolved a step at a time rather than by advancing a distance, so a
		// large `cycles` — after a stutter or a tab-out — carries the golem through several
		// whole tiles instead of teleporting it past a wall.
		int remaining = cycles;
		while (remaining > 0)
		{
			if (!stepping)
			{
				if (path.isEmpty())
				{
					walking = false;
					dwellRemaining -= remaining;
					if (dwellRemaining > 0)
					{
						return searched;
					}
					// Hopping off a stepping stone is not a search and must not wait on the
					// budget: a golem mid-crossing has nowhere to walk, so being told to
					// try next frame left it in a river until the watchdog came.
					if (takeQueuedTransport(context) || takeQueuedDock(context) || considerTransport(context))
					{
						return searched;
					}
					// Standing where it cannot walk off, nothing fresh to take: go back the
					// way it came rather than wait for the watchdog.
					if (!context.getMemory().isKnownWalkable(fineX / TILE, fineY / TILE, plane)
						&& takeWayOut(context, true))
					{
						return searched;
					}

					if (!context.isMayPath())
					{
						// This frame's search budget is spent: stand still rather than join
						// a stampede of path searches.
						return searched;
					}
					// Overshoot is discarded rather than carried forward.
					remaining = 0;
					searched = true;
					// Somewhere it knows no way out of: back the way it came in, now and then.
					if (headHome(context))
					{
						return searched;
					}
					// Sometimes the dock nearby, otherwise anywhere. One search a frame is
					// the budget, so a dock it could not reach is left for a pause.
					boolean toDock = headForDock(context);
					if (toDock && path.isEmpty())
					{
						dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
						return searched;
					}
					if (!toDock)
					{
						chooseDestination(context);
					}
					if (path.isEmpty())
					{
						// Nowhere to go — usually a golem boxed in by scenery. Counted,
						// because the difference between briefly hemmed in and
						// permanently trapped is only how often this happens.
						failedSearches++;
						// Twice in a row with nowhere to walk is a dead end, not bad luck —
						// but on ground it can stand on, only a fresh way out is taken.
						// Going back is how golems ping-ponged up and down the tower ladder
						// a hundred and sixty times, each shut-in floor sending them back.
						if (failedSearches >= 2 && takeWayOut(context, false))
						{
							failedSearches = 0;
							return searched;
						}
						dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
						return searched;
					}
					failedSearches = 0;
					continue;
				}

				// Checked again at the moment of stepping, not only when the path was planned:
				// a door open when the golem chose its route can be shut by the time it gets
				// there. A climb is exempt, walking up a cliff never walkable to begin with.
				int[] next = path.peek();
				int fromX = fineX / TILE;
				int fromY = fineY / TILE;
				int stepX = next[0] - fromX;
				int stepY = next[1] - fromY;
				if (gaitWalk == -1 && Math.abs(stepX) <= 1 && Math.abs(stepY) <= 1
					&& (stepX != 0 || stepY != 0)
					&& !context.getMemory().canStep(fromX, fromY, plane, stepX, stepY))
				{
					path.clear();
					walking = false;
					dwellRemaining = DWELL_MIN;
					return searched;
				}
				beginStep(path.poll());
			}

			int left = CYCLES_PER_TILE - stepElapsed;
			if (remaining < left)
			{
				stepElapsed += remaining;
				remaining = 0;
			}
			else
			{
				remaining -= left;
				stepElapsed = CYCLES_PER_TILE;
			}

			interpolateStep();

			if (stepElapsed >= CYCLES_PER_TILE)
			{
				stepping = false;

				// A climb ends the moment its last tile is reached, before anything else
				// looks at this golem: leaving the gait on would walk it around the world
				// in a climbing pose, and rolling again would abandon the obstacle.
				if (gaitWalk != -1 && path.isEmpty())
				{
					finishTrace();
					endClimb();
					// Walked across, it has landed like any other crossing, instance change
					// included. Only animated crossings applied that, so a golem that
					// climbed the pew was drawn on the wrong side of it.
					landInInstance();
					walking = false;
					dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
					return searched;
				}

				// A tile has just been entered, the one moment a transport roll may happen:
				// rolling per frame would tie the behaviour to framerate, and a golem
				// loitering near a ladder would eventually always take it. A shortcut it
				// walked here to use comes first, having already decided.
				if (takeQueuedTransport(context) || takeQueuedDock(context) || considerBoarding(context)
					|| considerTransport(context))
				{
					return searched;
				}

				if (path.isEmpty())
				{
					walking = false;
					dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
					return searched;
				}
			}
		}
		return searched;
	}

	/**
	 * How far from a transport's origin a golem will consider using it, in tiles. Three, not
	 * one: only 3.2% of walkable ground is within three tiles of a transport origin at all,
	 * so insisting on an exact hit makes the network effectively invisible.
	 */
	private static final int TRANSPORT_REACH = 3;

	/**
	 * Chance of taking a transport the golem is standing on, falling off with distance.
	 * Deliberately well under certainty: a forced "use what you are next to" rule turns a
	 * ladder in a corridor into a wall. A failed roll just means it carries on.
	 */
	private static final float TRANSPORT_CHANCE = 0.3f;

	/**
	 * Rolls for a voyage, for a golem standing at a dock where the player can see it.
	 * Sailing was once planned only out of range, so boats appeared and vanished at the edge
	 * of what was loaded; with crossings cached per pair of ports and searches rationed to
	 * one a frame, a golem in view goes if the route is known and otherwise stays put.
	 *
	 * @return true if the golem set off, stopping this frame's movement
	 */
	private boolean considerBoarding(RoamContext context)
	{
		RoamPlanner planner = context.getPlanner();
		if (planner == null)
		{
			return false;
		}

		Itinerary crossing = planner.planVoyage(currentTile(), context.getTick(),
			random, transportMemory, context);
		if (crossing == null)
		{
			return false;
		}

		path.clear();
		stepping = false;
		itinerary = crossing;
		return true;
	}

	/**
	 * Rolls for a transport near the tile just entered, and takes one if it wins.
	 *
	 * @return true if it used something, stopping this frame's movement
	 */
	private boolean considerTransport(RoamContext context)
	{
		TransportNetwork network = context.getTransports();
		if (network == null || network.size() == 0)
		{
			return false;
		}

		int tileX = fineX / TILE;
		int tileY = fineY / TILE;

		// True when the golem cannot walk out of where it is but the network can: halfway
		// across a river, on a stone. The next hop then happens without a roll.
		boolean stranded = !context.getMemory().isKnownWalkable(tileX, tileY, plane)
			&& (network.isStone(tileX, tileY, plane) || !walkableBeside(tileX, tileY, context));

		// Mid-crossing, the hop back is a last resort. A stone mid-river starts a hop both
		// ways, and taking whichever was found first had golems turn round on the middle
		// stone and hop back where they began.
		GolemTransport wayBack = null;

		// Scanned as a box rather than by asking for neighbours, because the index is by
		// exact origin tile and most tiles have nothing on them: 49 cheap lookups that
		// almost always all miss.
		for (int dx = -TRANSPORT_REACH; dx <= TRANSPORT_REACH; dx++)
		{
			for (int dy = -TRANSPORT_REACH; dy <= TRANSPORT_REACH; dy++)
			{
				int x = tileX + dx;
				int y = tileY + dy;
				if (!network.hasOrigin(x, y))
				{
					continue;
				}

				int distance = Math.abs(dx) + Math.abs(dy);
				if (distance > TRANSPORT_REACH)
				{
					continue;
				}

				for (GolemTransport transport : network.from(x, y))
				{
					if (transport.getFromPlane() != plane
						|| transportMemory.onCooldown(transport, context.getTick())
						|| context.crowded(transport.getToX(), transport.getToY(), transport.getToPlane())
						|| !arrivesSomewhereKnown(transport, context)
						|| !context.getAbilities().canUse(transport))
					{
						continue;
					}

					// Somewhere that cannot be walked off — mid-crossing, on a stepping
					// stone — the next hop is not a choice: rolling for it would strand
					// the golem on a rock until the watchdog came.
					if (!stranded)
					{
						// Not straight after the last one, unless looking for a way out of a
						// crowd. See TransportMemory.TRANSPORT_REST_TICKS.
						if (transportMemory.restingFromTransports(context.getTick())
							&& !context.crowdedRegion(tileX, tileY, plane))
						{
							continue;
						}
						// Adjacent is the full chance, three tiles away a quarter of it, and
						// more or less again by where it leads. See RoamContext.appeal.
						float chance = TRANSPORT_CHANCE
							* (TRANSPORT_REACH + 1 - distance) / (TRANSPORT_REACH + 1)
							* context.appeal(tileX, tileY, plane,
								transport.getToX(), transport.getToY(), transport.getToPlane());
						if (random.nextFloat() >= chance)
						{
							continue;
						}
					}

					// Only ever taken from the tile it actually starts on: the radius exists
					// so a golem notices a shortcut it walks past, not so it can use one
					// from across the clearing. Letting a stranded golem take any row in
					// range had golems on the extra slippery stone hop nowhere, the row
					// having started on the far bank.
					if (tileX != transport.getFromX() || tileY != transport.getFromY())
					{
						if (stranded)
						{
							// Mid-crossing there is nowhere to walk to, so a row starting
							// elsewhere is no use: wait for one that starts here.
							continue;
						}
						if (walkTo(transport.getFromX(), transport.getFromY(), context))
						{
							queuedTransport = transport;
							return true;
						}
						continue;
					}

					if (stranded && reversesLastHop(transport, context.getTick()))
					{
						if (wayBack == null)
						{
							wayBack = transport;
						}
						continue;
					}

					take(transport, context);
					return true;
				}
			}
		}
		if (wayBack != null)
		{
			// Nothing onward from this stone: back is still better than standing in the river.
			take(wayBack, context);
			return true;
		}
		return false;
	}

	/**
	 * True if a tile beside this one is ground the golem knows it can walk. A golem on a
	 * fairy ring is not stranded the way one on a stone is. See RoamPlanner.plan.
	 */
	private boolean walkableBeside(int tileX, int tileY, RoamContext context)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if ((dx != 0 || dy != 0) && context.getMemory().isKnownWalkable(tileX + dx, tileY + dy, plane))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Shortest wait before going back, however small the space beyond: about 15 seconds. */
	private static final int MIN_COOLDOWN_TICKS = 25;

	/**
	 * How long before a golem may go back the way a transport just took it, scaled by the
	 * room on the far side. The full wait suits open ground; behind the stile is a pen of a
	 * few dozen tiles, where two minutes let arrivals outnumber departures until it could
	 * not be drawn. Unwalkable landings keep the full wait, being crossings rather than
	 * small spaces.
	 */
	private int cooldownFor(GolemTransport transport, RoamContext context)
	{
		int x = transport.getToX();
		int y = transport.getToY();
		int toPlane = transport.getToPlane();
		if (!context.getMemory().isKnownWalkable(x, y, toPlane))
		{
			return TransportMemory.COOLDOWN_TICKS;
		}
		float share = Math.min(1f, context.enclosedArea(x, y, toPlane) / (float) RoamContext.OPEN_AREA);
		return Math.max(MIN_COOLDOWN_TICKS, Math.round(TransportMemory.COOLDOWN_TICKS * share));
	}

	/**
	 * Leaves a dead end by whatever starts here, even the way the golem just came. The
	 * reverse cooldown stops a golem pacing through a door, but at the top of a ladder with
	 * no floor to walk on it was the only thing keeping the golem there, re-planning until
	 * the watchdog lifted it. A fresh way out is preferred; the way back is the fallback.
	 *
	 * @return true if a transport was taken
	 */
	private boolean takeWayOut(RoamContext context, boolean evenBack)
	{
		TransportNetwork network = context.getTransports();
		if (network == null)
		{
			return false;
		}
		GolemTransport back = null;
		for (GolemTransport transport : network.from(fineX / TILE, fineY / TILE))
		{
			if (transport.getFromPlane() != plane
				|| !arrivesSomewhereKnown(transport, context)
				|| !context.getAbilities().canUse(transport))
			{
				continue;
			}
			if (!transportMemory.onCooldown(transport, context.getTick()))
			{
				take(transport, context);
				return true;
			}
			if (back == null)
			{
				back = transport;
			}
		}
		if (back == null || !evenBack)
		{
			return false;
		}
		note(context, "dead end: taking the way back");
		take(back, context);
		return true;
	}

	/**
	 * True if the far end of a transport is ground the golem could actually walk on.
	 *
	 * <p>The transport table covers the whole game; the passability map, for now, covers
	 * Wyrmscraig. A row leading somewhere unmapped would land a golem on ground the
	 * pathfinder cannot route out of. The network is allowed to be larger than the map, and
	 * this is the seam: as the mesh grows, more of the table becomes reachable.
	 */
	private boolean arrivesSomewhereKnown(GolemTransport transport, RoamContext context)
	{
		if (context.getMemory().isKnownWalkable(
			transport.getToX(), transport.getToY(), transport.getToPlane()))
		{
			return true;
		}

		// A stepping stone is blocked ground — that is why crossing it is a transport — but
		// it is somewhere you can stand, the proof being that another transport starts
		// there. So a transport origin is accepted as a destination, but only if it goes on
		// somewhere: golems hopped back and forth across the extra-slippery crossing forty
		// times each. "Goes on" means eventually reaches ground, followed hop by hop, since
		// one hop ahead passed every stone of a crossing that never reached a bank.
		return context.getTransports().leadsToGround(transport.getToX(), transport.getToY(), transport.getToPlane(),
			transport.getFromX(), transport.getFromY(), transport.getFromPlane(), TransportNetwork.CHAIN_HOPS,
			context.getAbilities()::canUse, context.getMemory()::isKnownWalkable);
	}

	/**
	 * A transport the golem is walking toward and will use on arrival. Held rather than
	 * taken at once so the golem uses it from the tile it starts on, as a player does.
	 */
	private GolemTransport queuedTransport;

	/** A dock the golem is walking up to, to consider sailing from. See dockToVisit. */
	private SailingDocks.Dock queuedDock;

	/** How long it stands between asking whether the crossing is ready, in client cycles. */
	private static final int DOCK_WAIT_CYCLES = 20;

	/**
	 * Sets off for a dock nearby, if the golem chooses to.
	 *
	 * @return true if it is on its way, with a path to the quayside
	 */
	private boolean headForDock(RoamContext context)
	{
		RoamPlanner planner = context.getPlanner();
		if (planner == null)
		{
			return false;
		}
		SailingDocks.Dock dock = planner.dockToVisit(currentTile(), transportMemory, context, random);
		if (dock == null)
		{
			return false;
		}
		// True once it has searched, found or not. See the caller.
		if (walkTo(dock.getShore().getX(), dock.getShore().getY(), context))
		{
			queuedDock = dock;
		}
		return true;
	}

	/**
	 * Rolls to sail once the golem has walked up to the dock it chose.
	 *
	 * @return true if it set sail, stopping this frame's movement
	 */
	private boolean takeQueuedDock(RoamContext context)
	{
		if (queuedDock == null)
		{
			return false;
		}
		RoamPlanner planner = context.getPlanner();
		WorldPoint here = currentTile();
		if (planner == null || !planner.atDock(here, queuedDock))
		{
			// Still on the way; or the path ran out short of it, and the plan is stale.
			if (planner == null || path.isEmpty() && !stepping)
			{
				queuedDock = null;
			}
			return false;
		}
		queuedDock = null;

		Itinerary crossing = planner.planVoyageAtDock(here, context.getTick(), random, transportMemory, context);
		if (crossing == null)
		{
			if (transportMemory.getPendingPort() >= 0)
			{
				// Decided to go and the crossing is still being worked out: wait at the dock
				// rather than walk away. How long is TransportMemory's business.
				queuedDock = planner.dockAt(here);
				dwellRemaining = DOCK_WAIT_CYCLES;
				return queuedDock != null;
			}
			// Thought better of it, or no crossing to be had: it wanders off, and may
			// come back.
			return false;
		}
		path.clear();
		stepping = false;
		itinerary = crossing;
		return true;
	}

	/**
	 * Paths the golem to a nearby tile.
	 *
	 * @return true if a route was found
	 */
	private boolean walkTo(int goalX, int goalY, RoamContext context)
	{
		int tileX = fineX / TILE;
		int tileY = fineY / TILE;

		path.clear();
		path.addAll(context.getPathfinder().findPath(tileX, tileY, plane, goalX, goalY,
			new RoamBounds(context.getMemory(), plane, tileX, tileY)));
		return !path.isEmpty();
	}

	/**
	 * Heads back out the way it came in, if it is somewhere it knows no other way out of.
	 * See RoamPlanner.wayHome.
	 *
	 * @return true if it set off, or went
	 */
	private boolean headHome(RoamContext context)
	{
		RoamPlanner planner = context.getPlanner();
		if (planner == null || random.nextFloat() >= RoamPlanner.HOMEWARD_CHANCE)
		{
			return false;
		}
		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		GolemTransport home = planner.wayHome(tileX, tileY, plane, context.getTick(), transportMemory, random);
		if (home == null)
		{
			return false;
		}
		note(context, "no known way out: back the way it came");
		if (tileX == home.getFromX() && tileY == home.getFromY())
		{
			take(home, context);
			return true;
		}
		if (walkTo(home.getFromX(), home.getFromY(), context))
		{
			queuedTransport = home;
		}
		else
		{
			// Searched and found no way: that was this frame's search. Look again after a pause.
			dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
		}
		return true;
	}

	/**
	 * Takes the queued transport once the golem has arrived at its starting tile.
	 *
	 * @return true if it was used, stopping this frame's movement
	 */
	private boolean takeQueuedTransport(RoamContext context)
	{
		if (queuedTransport == null)
		{
			return false;
		}

		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		if (tileX != queuedTransport.getFromX() || tileY != queuedTransport.getFromY())
		{
			// Still on the way. If the path ran out without arriving, the plan is stale:
			// drop it rather than hold out for a tile the golem is no longer heading to.
			if (path.isEmpty() && !stepping)
			{
				queuedTransport = null;
			}
			return false;
		}

		GolemTransport transport = queuedTransport;
		queuedTransport = null;

		if (transportMemory.onCooldown(transport, context.getTick())
			|| !context.getAbilities().canUse(transport))
		{
			return false;
		}

		take(transport, context);
		return true;
	}

	/** Which way, and when, the golem last used a transport on one plane. See reversesLastHop. */
	private int lastHopX;
	private int lastHopY;
	private int lastHopTick = Integer.MIN_VALUE;

	/** How long after a hop the next one is still part of the same crossing, in ticks. */
	private static final int CROSSING_TICKS = 20;

	/** True if this transport would take the golem back against the hop it has just made. */
	private boolean reversesLastHop(GolemTransport transport, int tick)
	{
		if (tick - lastHopTick > CROSSING_TICKS || transport.getFromPlane() != transport.getToPlane())
		{
			return false;
		}
		int dx = transport.getToX() - transport.getFromX();
		int dy = transport.getToY() - transport.getFromY();
		return dx * lastHopX + dy * lastHopY < 0;
	}

	/**
	 * Uses a transport.
	 *
	 * <p>Anything with an animation is played before the golem arrives, since arriving
	 * instantly would look like a teleport. Doors and teleport-like rows have no animation
	 * and land immediately, which is correct rather than a shortcut: a door animates itself.
	 */
	private void take(GolemTransport transport, RoamContext context)
	{
		if (transport.getFromPlane() == transport.getToPlane())
		{
			lastHopX = transport.getToX() - transport.getFromX();
			lastHopY = transport.getToY() - transport.getFromY();
			lastHopTick = context.getTick();
		}
		transportMemory.used(transport, context.getTick(), cooldownFor(transport, context));
		// On landing, not now: a golem climbing into the pew is still in the cathedral.
		landingInstance = transport.entersInstance() ? 1 : transport.leavesInstance() ? 0 : -1;

		// Logged before anything else can return: a row with no animation used to relocate
		// the golem above this line, so staircases left no trace in the log.
		note(context, "transport obj=" + transport.getObjectId()
			+ " to=" + transport.getToX() + "," + transport.getToY() + ","
			+ transport.getToPlane()
			+ " arch=" + transport.getArchetype()
			+ " dur=" + transport.getDuration());

		// A recording beats anything reconstructed, the silent case included: a staircase
		// plays nothing but still has a shape. A plane change may be performed from one
		// only if it barely moves, since a travelling recording would slide the golem
		// across a floor it has left.
		MotionCurve recorded = context.getKnowledge() == null ? null
			: context.getKnowledge().curveFor(transport);
		boolean samePlane = transport.getFromPlane() == transport.getToPlane();
		if (recorded != null && !recorded.isEmpty() && (samePlane || recorded.reach() < TILE))
		{
			beginTrace(transport, context);
			beginRecordedMotion(transport, recorded);
			note(context, "performing " + recorded);
			return;
		}

		int animation = transport.animation();
		if (animation < 0 || animation == snapshot.getWalkAnimation())
		{
			note(context, "relocated without animation");
			relocate(transport.destination());
			landInInstance();
			return;
		}

		beginTrace(transport, context);

		// Stop where it is and play the clip. The path is dropped now rather than on
		// landing so the golem does not keep walking under its own animation.
		path.clear();
		stepping = false;
		walking = false;
		transitionAnimation = animation;
		// The whole clip set, in order — mount, cross, dismount — each phase running exactly
		// as long as its clip does; a fixed length made a cliff take the same two thirds of
		// a second as a doorway. What the player was seen doing beats what was shipped,
		// which beats the archetype's guess from menu text.
		int[] clips = context.getKnowledge() == null
			? transport.animations()
			: context.getKnowledge().clipsFor(transport);
		phaseClips = clips;
		phaseCycles = new int[clips.length];

		int total = 0;
		for (int i = 0; i < clips.length; i++)
		{
			int length = context.getModels() == null ? 0
				: context.getModels().animationCycles(clips[i]);
			phaseCycles[i] = Math.max(1, length);
			total += phaseCycles[i];
		}

		// How long the obstacle takes, in order of how much the answer is worth: a measured
		// tick count, then this row's authored duration, then the clip's own length. The
		// middle term used to be last, and it matters: a clip length is per obstacle *type*
		// — every rock climb plays 4435 — so ranking it above the row gave them all one
		// duration, where the tables author eight to fifteen ticks across the climbing-rock
		// rows and three to six across the stiles.
		int measuredTicks = context.getKnowledge() == null
			? MeasuredShortcuts.ticksFor(transport.getObjectId())
			: context.getKnowledge().ticksFor(transport);
		int authored = transport.getDuration() * CYCLES_PER_TICK;
		// Whether this is walked or performed follows from how long it takes and how far it
		// goes, not whether its clip loops: human_climbing (737) is a one-shot and yet is
		// the walk animation of a climb, while hole_squeeze (3835) loops and is not walked.
		// Duration does separate them — stepping stones read one or two ticks, log balances
		// and slopes six to eight.
		int obstacleTicks = measuredTicks > 0 ? measuredTicks
			: context.getObstacles() != null
				&& context.getObstacles().ticksFor(transport.getObjectId()) > 0
				? context.getObstacles().ticksFor(transport.getObjectId())
				: transport.getDuration();

		// Whether a clip may be stretched is still the clip's own business — a one-shot
		// restarted halfway through looks broken however long the obstacle takes.
		int stretchIndex = phaseCycles.length > 2 ? 1 : phaseCycles.length - 1;
		boolean stretchable = total == 0 || stretchIndex < 0
			|| context.getModels() == null
			|| context.getModels().loops(clips[stretchIndex]);

		int wanted;
		if (!stretchable)
		{
			wanted = total;
		}
		else
		{
			wanted = measuredTicks > 0 ? measuredTicks * CYCLES_PER_TICK
				: authored > 0 ? authored
				: total;
		}
		wanted = Math.max(TRANSITION_MIN_CYCLES, wanted);

		note(context, "clips=" + java.util.Arrays.toString(clips) + " total=" + total
			+ " wanted=" + wanted + " measured=" + measuredTicks + " authored=" + authored
			+ " obstacleTicks=" + obstacleTicks + " stretchable=" + stretchable
			+ " delay=" + (context.getKnowledge() == null ? -1
				: context.getKnowledge().moveDelayFor(transport))
			+ " span=" + (context.getKnowledge() == null ? -1
				: context.getKnowledge().moveSpanFor(transport))
			+ " at=" + (fineX / TILE) + "," + (fineY / TILE));

		// Several ticks over several tiles is a walk, whatever the clip does.
		if (obstacleTicks >= WALKED_TICKS && total > 0)
		{
			if (beginClimb(transport, clips, context))
			{
				note(context, "climbing as a walk");
				return;
			}
			note(context, "walk refused: plane or span");
		}

		// Nothing to play, as on a ladder down: the golem stands for the obstacle's time. With no
		// cycles the transition never finished, and the golem stayed at the top of the ladder.
		if (clips.length == 0)
		{
			clips = new int[]{snapshot.getIdlePoseAnimation()};
			phaseClips = clips;
			phaseCycles = new int[]{wanted};
			total = wanted;
		}

		if (phaseCycles.length > 0 && total != wanted)
		{
			int loop = phaseCycles.length > 2 ? 1 : phaseCycles.length - 1;
			phaseCycles[loop] = Math.max(1, phaseCycles[loop] + (wanted - total));

			total = 0;
			for (int length : phaseCycles)
			{
				total += length;
			}
		}

		phase = 0;
		transitionAnimation = clips.length > 0 ? clips[0] : animation;
		transitionTotal = total;
		transitionCycles = total;
		phaseRemaining = phaseCycles.length > 0 ? phaseCycles[0] : total;
		transitionDestination = transport.destination();

		// A hop or a vault carries the golem across and is drawn doing so. A ladder or cave
		// mouth ends up elsewhere, often another plane thousands of tiles away, where
		// interpolating would slide the golem across the world.
		int span = Math.abs(transport.getToX() - transport.getFromX())
			+ Math.abs(transport.getToY() - transport.getFromY());
		transitionGlide = transport.getFromPlane() == transport.getToPlane() && span <= 8;

		// Movement is whole game ticks while the clip is whatever length it was drawn at:
		// the measured hop covers its gap in one tick under a clip of nearly one and a
		// third. The measured window wins — how long it stands still, then how long it
		// moves — which a single duration cannot express.
		int learnedDelay = context.getKnowledge() == null ? 0
			: context.getKnowledge().moveDelayFor(transport);
		int learnedSpan = context.getKnowledge() == null ? 0
			: context.getKnowledge().moveSpanFor(transport);

		if (learnedSpan > 0)
		{
			// Never longer than the clip. A chained crossing recorded a 72-cycle span for a
			// 38-cycle hop, and a window wider than the transition left the golem partway
			// through its glide when it was dropped at the far side — the
			// jump-in-place-then-teleport.
			int moveCycles = Math.max(1, Math.min(learnedSpan, total));

			// The movement has to finish with the animation; the observed delay is otherwise
			// taken as given. Clamping it to the first half of the clip broke the cathedral
			// door, which measures a 30-cycle delay against a 30-cycle clip because the
			// player plays the whole animation and *then* teleports. The double jump came
			// from the tail instead: a one-shot clip completing inside a longer transition
			// is nulled by the animation controller and set again by the renderer.
			int latest = Math.max(0, total - moveCycles);
			transitionGlideDelay = Math.min(learnedDelay, latest);
			transitionGlideCycles = moveCycles;
			transitionCycles = total;
			transitionTotal = transitionCycles;
		}
		else
		{
			int movementTicks = Math.max(1, measuredTicks > 0 ? measuredTicks
				: transport.getDuration() > 0 ? transport.getDuration() : 1);
			transitionGlideDelay = 0;
			transitionGlideCycles = Math.min(total, movementTicks * CYCLES_PER_TICK);
		}

		if (transitionGlide)
		{
			transitionFromX = fineX;
			transitionFromY = fineY;
			transitionToX = transport.getToX() * TILE + TILE / 2;
			transitionToY = transport.getToY() * TILE + TILE / 2;

			// Face the way it is going, instantly: a golem that jumps sideways because it
			// had not finished turning looks worse than one that snaps round first.
			orientation = headingFor(transitionToX - transitionFromX,
				transitionToY - transitionFromY);
			targetOrientation = orientation;
		}

		if (transport.wantsPropAnimation())
		{
			pendingProp = transport;
		}
	}

	/**
	 * A transport whose scenery should be animated, claimed once by the plugin. The golem
	 * knows nothing about models or the scene: it decides a plank should lower, and the
	 * plugin decides whether anyone can see it.
	 */
	private GolemTransport pendingProp;

	/** Takes the pending prop request, if any. Returns null once it has been claimed. */
	GolemTransport claimPendingProp()
	{
		GolemTransport claimed = pendingProp;
		pendingProp = null;
		return claimed;
	}

	/**
	 * Walks the golem through an obstacle wearing the obstacle's gait, as the game does:
	 * tile-by-tile movement with the walk and idle animations swapped for climbing ones.
	 * The loop clip is the walk cycle, so a three-tile scramble takes three ticks with
	 * nobody choosing a duration. Only for obstacles on one plane over ground the golem can
	 * be drawn crossing.
	 *
	 * @return true if the golem is now climbing, false to fall back to a played clip
	 */
	private boolean beginClimb(GolemTransport transport, int[] clips, RoamContext context)
	{
		if (transport.getFromPlane() != transport.getToPlane())
		{
			return false;
		}

		int span = Math.max(Math.abs(transport.getToX() - fineX / TILE),
			Math.abs(transport.getToY() - fineY / TILE));
		if (span < 1 || span > CLIMB_MAX_TILES)
		{
			return false;
		}

		path.clear();
		int x = fineX / TILE;
		int y = fineY / TILE;
		while (x != transport.getToX() || y != transport.getToY())
		{
			x += Integer.signum(transport.getToX() - x);
			y += Integer.signum(transport.getToY() - y);
			path.add(new int[]{x, y});
		}

		// Three clips is ready, loop, merge — the idle, the walk, and a one-shot on
		// arrival. Fewer than three and the one clip is the walk.
		gaitWalk = clips.length > 2 ? clips[1] : clips[clips.length - 1];
		gaitIdle = clips.length > 2 ? clips[0] : gaitWalk;
		gaitFinish = clips.length > 2 ? clips[2] : -1;
		gaitFinishCycles = gaitFinish == -1 || context.getModels() == null ? 0
			: context.getModels().animationCycles(gaitFinish);

		transitionCycles = 0;
		transitionAnimation = -1;
		beginStep(path.poll());
		return true;
	}

	/** Clears the climbing gait, playing the step-off if the obstacle had one. */
	private void endClimb()
	{
		gaitWalk = -1;
		gaitIdle = -1;

		if (gaitFinish != -1)
		{
			transitionAnimation = gaitFinish;
			transitionTotal = Math.max(TRANSITION_MIN_CYCLES, gaitFinishCycles);
			transitionCycles = transitionTotal;
			phaseClips = new int[0];
			phaseCycles = new int[0];
			phaseRemaining = transitionTotal;
			transitionGlide = false;
			transitionDestination = null;
			gaitFinish = -1;
		}
	}

	/** Tiles a golem will climb across rather than be carried over. */
	private static final int CLIMB_MAX_TILES = 12;

	/**
	 * Ticks above which a traversal is walked rather than performed. Four: the cache's own
	 * durations cluster either side — one or two for stepping stones and broken walls, six
	 * to eight for log balances and slopes — with nothing on it.
	 */
	private static final int WALKED_TICKS = 4;

	/**
	 * Where to draw the golem relative to where it is, in fine units, and on which plane.
	 * Zero everywhere but an instance, where the golem is simulated at the room's template —
	 * the only address it keeps between visits — and the player inside sees it elsewhere.
	 */
	private int drawOffsetX;
	private int drawOffsetY;
	private int drawPlane = -1;

	void setDrawOffset(int x, int y, int plane)
	{
		drawOffsetX = x;
		drawOffsetY = y;
		drawPlane = plane;
	}

	int getDrawFineX()
	{
		return fineX + drawOffsetX;
	}

	int getDrawFineY()
	{
		return fineY + drawOffsetY;
	}

	int getDrawPlane()
	{
		return drawPlane >= 0 ? drawPlane : plane;
	}

	/** Steps begun so far, so each can be checked exactly once from outside. */
	private int stepSerial;
	private boolean stepClimbing;

	int getStepSerial()
	{
		return stepSerial;
	}

	/** The most recent step as {fromX, fromY, toX, toY} in tiles. */
	int[] lastStep()
	{
		return new int[]{stepFromX / TILE, stepFromY / TILE, stepToX / TILE, stepToY / TILE};
	}

	/** True if the most recent step was part of a climb, which crosses unwalkable ground. */
	boolean lastStepClimbing()
	{
		return stepClimbing;
	}

	private void beginStep(int[] tile)
	{
		stepSerial++;
		stepClimbing = gaitWalk != -1;
		stepFromX = fineX;
		stepFromY = fineY;
		stepToX = tile[0] * TILE + TILE / 2;
		stepToY = tile[1] * TILE + TILE / 2;
		stepElapsed = 0;
		stepping = true;
		walking = true;
		targetOrientation = headingFor(stepToX - stepFromX, stepToY - stepFromY);
	}

	private void interpolateStep()
	{
		fineX = stepFromX + (stepToX - stepFromX) * stepElapsed / CYCLES_PER_TILE;
		fineY = stepFromY + (stepToY - stepFromY) * stepElapsed / CYCLES_PER_TILE;
	}

	/**
	 * Picks somewhere new to walk. The roam bounds are built here rather than passed in:
	 * they describe a window around where the golem is, so building one per golem per frame
	 * meant hundreds of throwaway objects for the few golems actually choosing anything.
	 */
	private void chooseDestination(RoamContext context)
	{
		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		path.clear();
		path.addAll(context.getPathfinder().wanderPath(tileX, tileY, plane,
			new RoamBounds(context.getMemory(), plane, tileX, tileY,
				(x, y) -> context.crowded(x, y, plane)), random));
	}

	/** Eases the heading toward where the golem is walking, the short way round. */
	private void turnToward(int cycles)
	{
		if (orientation == targetOrientation)
		{
			return;
		}
		int delta = ((targetOrientation - orientation + 1024) & 2047) - 1024;
		int maxTurn = TURN_PER_CYCLE * cycles;
		if (Math.abs(delta) <= maxTurn)
		{
			orientation = targetOrientation;
		}
		else
		{
			orientation = (orientation + Integer.signum(delta) * maxTurn) & 2047;
		}
	}

	/**
	 * The orientation for a direction of travel, to the nearest angle rather than the
	 * nearest cardinal. Picking the nearest cardinal was exact while the pathfinder only
	 * stepped north, south, east and west; once diagonals were added a golem walking
	 * north-east faced north and crabbed sideways.
	 *
	 * <p>Angles run 0 south, 512 west, 1024 north, 1536 east, so north is the zero of the
	 * arc-tangent and east a quarter turn on.
	 */
	private static int headingFor(int dx, int dy)
	{
		if (dx == 0 && dy == 0)
		{
			return NORTH;
		}
		return (int) (1024 + Math.round(Math.atan2(dx, dy) / Math.PI * 1024)) & 2047;
	}

	/**
	 * Performs a traversal exactly as it was observed. No delay, span, stretch or
	 * walked-versus-glided decision is taken: the recording holds the position at every
	 * other cycle and the animation at every change, and both are read back.
	 */
	private void beginRecordedMotion(GolemTransport transport, MotionCurve recorded)
	{
		path.clear();
		stepping = false;
		walking = false;
		gaitWalk = -1;
		gaitIdle = -1;
		gaitFinish = -1;

		motion = recorded;
		transitionTotal = Math.max(1, recorded.cycles());
		transitionCycles = transitionTotal;
		transitionGlide = false;
		transitionGlideDelay = 0;
		transitionGlideCycles = 0;
		phaseClips = new int[0];
		phaseCycles = new int[0];
		phase = 0;
		transitionDestination = transport.destination();
		int opening = recorded.animationAt(0);
		transitionAnimation = opening != -1 ? opening : snapshot.getIdlePoseAnimation();

		// The axis and the distance, both in fine units from exactly where the golem is.
		// These used to come from its *tile* while the offsets were added to its exact
		// position, so the fraction of a tile it stood off centre was added to the distance
		// and the golem slid past the far side before the arrival snapped it back.
		motionFrame = recorded.frameAt(0);
		motionFromX = fineX;
		motionFromY = fineY;

		float dx = transport.getToX() * TILE + TILE / 2f - fineX;
		float dy = transport.getToY() * TILE + TILE / 2f - fineY;
		float needed = (float) Math.sqrt(dx * dx + dy * dy);
		motionAxisX = needed < 1f ? 0f : dx / needed;
		motionAxisY = needed < 1f ? 1f : dy / needed;

		// The recording covered the player's distance; this golem may have a different one.
		// Scale the forward part so it arrives exactly.
		int reach = recorded.reach();
		motionScale = reach <= TILE / 2 || needed < 1f ? 1f : needed / reach;

		// Face the way it is about to go, immediately: a golem still turning as a recording
		// starts performs the whole thing at the wrong angle. Turned by the player's facing
		// relative to their travel — on the rockslide they face the rock and move away from
		// it, and a golem facing its travel climbed off the cliff. Only where the traversal
		// goes somewhere; a ladder has no direction to be relative to.
		int heading = headingFor(Math.round(dx), Math.round(dy));
		targetOrientation = recorded.hasFacing() && needed >= TILE / 2f
			? (heading + recorded.facing()) & 2047
			: heading;
		orientation = targetOrientation;
	}

	/** Where the recording started from, in fine units. */
	private int motionFromX;
	private int motionFromY;

	/** Forward scaling, so a recording made from one tile away still lands correctly. */
	private float motionScale = 1f;

	/**
	 * Which frame the recording says the animation should be on, or -1. Read by the renderer
	 * so animation and movement share one clock; without it the clip advances at the draw
	 * rate while the position advances on cycle count, and the drift looks like skipping.
	 */
	@Getter
	private int motionFrame = -1;

	/** Reports a decision to the debug log, if one is listening. */
	private void note(RoamContext context, String what)
	{
		if (context != null && context.getDecisions() != null)
		{
			context.getDecisions().accept(this, what);
		}
	}

	/**
	 * Everything about this golem's current state, for the debug log. One flat line
	 * per golem per tick: working out why a golem did something means reading its position,
	 * animation, path and intention together.
	 */
	String debugState()
	{
		return "tile=" + (fineX / TILE) + "," + (fineY / TILE) + "," + plane
			+ " fine=" + fineX + "," + fineY
			+ " orient=" + orientation + "/" + targetOrientation
			+ " anim=" + currentPoseAnimation()
			+ " tier=" + tier
			+ (walking ? " walking" : "")
			+ (stepping ? " stepping" : "")
			+ (transitionCycles > 0 ? " transit=" + transitionCycles + "/" + transitionTotal
				+ (transitionGlide ? " glide=" + transitionGlideCycles : "") : "")
			+ (gaitWalk != -1 ? " climbing gait=" + gaitWalk + "/" + gaitIdle : "")
			+ (motion != null ? " performing" : "")
			+ " path=" + path.size()
			+ (itinerary != null ? " itinerary" : "")
			+ (dwellRemaining > 0 ? " dwell=" + dwellRemaining : "");
	}

	/** The animation this golem should be playing right now. -1 if it has none. */
	int currentPoseAnimation()
	{
		if (isDying())
		{
			return GolemContent.GOLEM_DEATH_ANIMATION;
		}
		if (transitionCycles > 0)
		{
			return transitionAnimation;
		}
		if (afloat)
		{
			return GolemContent.ANIM_GOLEM_HELM;
		}
		if (gaitWalk != -1)
		{
			return walking ? gaitWalk : gaitIdle;
		}
		return walking ? snapshot.getWalkAnimation() : snapshot.getIdlePoseAnimation();
	}

	/**
	 * The gait a golem climbs with, replacing its own for the length of the obstacle; -1
	 * when it uses its own, which is nearly always. A long climb is not a long animation:
	 * the game swaps the base animation set and walks the player up the cliff a tile at a
	 * time, which is why {@code human_climbing_loop} loops — it is a walk animation, and
	 * walk animations repeat once per tile.
	 */
	private int gaitWalk = -1;
	private int gaitIdle = -1;

	/** Played once on arrival, or -1. The step-off at the top of a climb. */
	private int gaitFinish = -1;

	/** Its length, measured when the climb began while the models were to hand. */
	private int gaitFinishCycles;

	// ------------------------------------------------------- using a transport

	/**
	 * The clip playing while the golem climbs, jumps or squeezes through something. All are
	 * the game's own human animations, playable because the golem shares the human rig —
	 * see {@link GolemContent#GOLEM_FRAMEMAP}. Nothing is authored or deformed.
	 */
	private int transitionAnimation = -1;

	/**
	 * Cycles of the transition the golem is actually moving for. Movement and animation do
	 * not last the same time: a stepping-stone hop covers the gap in <b>30 cycles, one game
	 * tick, while the clip runs for 38</b>. Gliding across the whole clip leaves the golem
	 * drifting when it should have landed.
	 */
	private int transitionGlideCycles;

	/**
	 * Cycles the golem holds still at the start of a traversal before moving. Measured, not
	 * assumed: four consecutive basalt hops each held 33 cycles and then crossed in 12, and
	 * the game's own script uses a 12-cycle window inside a longer action. Without it the
	 * golem slides on the animation's first frame.
	 */
	private int transitionGlideDelay;

	/**
	 * The recorded motion being performed, or null when none was available. While it is set
	 * nothing is calculated: position and animation both come from the recording, so a hop's
	 * wind-up, a climb's rise and a door's animate-then-teleport are all just recordings.
	 */
	private MotionCurve motion;

	/** The unit vector toward this traversal's destination, for orienting the recording. */
	private float motionAxisX;
	private float motionAxisY;

	/** Scratch for the curve's offset, to avoid allocating one every cycle per golem. */
	private final int[] motionOffset = new int[2];

	/** Cycles left of the transition, after which the golem arrives at the far end. */
	private int transitionCycles;

	/** Where the golem lands once the transition finishes. */
	private WorldPoint transitionDestination;

	/**
	 * Shortest a transport may take, in client cycles. A floor rather than the duration
	 * itself: every transport runs for as long as its own table row says, where a fixed
	 * length made a rock climb take the same two thirds of a second as a doorway.
	 */
	private static final int TRANSITION_MIN_CYCLES = 20;

	/** Client cycles in one game tick, which is the unit the tables give durations in. */
	private static final int CYCLES_PER_TICK = 30;

	/** How long the transition in progress runs for, so the glide and arc can be paced. */
	private int transitionTotal = TRANSITION_MIN_CYCLES;

	/** The clip set being played, its per-phase lengths, and where in it the golem is. */
	private int[] phaseClips = new int[0];
	private int[] phaseCycles = new int[0];
	private int phase;
	private int phaseRemaining;

	/** True while the golem is mid-obstacle and should not be walking or pathing. */
	boolean inTransition()
	{
		// A climb is walked rather than played, so it has no transition cycles, but it is as
		// much mid-obstacle as a hop: without this the watchdog called a golem on a cliff
		// face unwalkable ground and relocated it halfway up.
		return transitionCycles > 0 || gaitWalk != -1;
	}

	/**
	 * Advances an in-progress transition, landing the golem when it completes.
	 *
	 * @return true while still mid-transition, when the golem must not move
	 */
	private boolean advanceTransition(int cycles)
	{
		if (transitionCycles <= 0)
		{
			return false;
		}

		transitionCycles -= cycles;

		if (motion != null)
		{
			int elapsed = transitionTotal - transitionCycles;
			int beforeX = fineX;
			int beforeY = fineY;
			motion.offsetAt(elapsed, motionAxisX, motionAxisY, motionScale, motionOffset);
			fineX = motionFromX + motionOffset[0];
			fineY = motionFromY + motionOffset[1];

			// Between clips — before the first starts, or after the last ends — the golem is
			// itself: idle, or walking if the recording is moving it. Keeping the last value
			// left golems in their bare model waiting to hop, and frozen after the stile.
			int playing = motion.animationAt(elapsed);
			transitionAnimation = playing != -1 ? playing
				: fineX != beforeX || fineY != beforeY ? snapshot.getWalkAnimation()
				: snapshot.getIdlePoseAnimation();
			motionFrame = motion.frameAt(elapsed);

			if (transitionCycles > 0)
			{
				return true;
			}
			motion = null;
			motionFrame = -1;
		}

		// Step through the clip set as each phase runs out, so the golem takes hold, hauls
		// itself up and steps off rather than looping one clip for the whole obstacle.
		phaseRemaining -= cycles;
		while (phaseRemaining <= 0 && phase + 1 < phaseClips.length)
		{
			phase++;
			phaseRemaining += phaseCycles[phase];
			transitionAnimation = phaseClips[phase];
		}

		if (transitionCycles > 0)
		{
			// Carry the golem across while the clip plays: a jump with the golem in two
			// places and nothing in between reads as a teleport with an animation on it.
			if (transitionGlide)
			{
				// Against the movement window, not the whole transition, so the golem
				// arrives when it should and holds still for the rest of the clip.
				int window = transitionGlideCycles > 0 ? transitionGlideCycles : transitionTotal;
				int elapsed = transitionTotal - transitionCycles - transitionGlideDelay;
				float done = elapsed <= 0 ? 0f : Math.min(1f, elapsed / (float) window);
				fineX = transitionFromX + Math.round((transitionToX - transitionFromX) * done);
				fineY = transitionFromY + Math.round((transitionToY - transitionFromY) * done);
			}
			return true;
		}

		transitionCycles = 0;
		transitionAnimation = -1;
		transitionGlide = false;
		motion = null;
		phaseClips = new int[0];
		phaseCycles = new int[0];
		phase = 0;
		if (transitionDestination != null)
		{
			finishTrace();
			relocate(transitionDestination);
			transitionDestination = null;
			landInInstance();
		}
		return false;
	}

	/** Frames kept of one traced crossing: ten seconds of them at fifty a second. */
	private static final int TRACE_SAMPLES = 500;

	/** Longest crossing traced, in tiles. Further is a teleport, with no path to get wrong. */
	private static final int TRACE_REACH = 8;

	/** The crossing being traced, or null. See GolemTraversal. */
	private GolemTransport tracing;
	private java.util.function.Consumer<GolemTraversal> traceSink;
	private int traceStartX;
	private int traceStartY;
	private int traceElapsed;
	private java.util.List<int[]> traceSamples;

	/** Starts tracing a crossing, if it is one worth tracing and somebody keeps the record. */
	private void beginTrace(GolemTransport transport, RoamContext context)
	{
		tracing = null;
		if (tier != GolemTier.SCENE || context.getTraversals() == null
			|| transport.getFromPlane() != transport.getToPlane()
			|| Math.max(Math.abs(transport.getToX() - transport.getFromX()),
				Math.abs(transport.getToY() - transport.getFromY())) > TRACE_REACH)
		{
			return;
		}
		tracing = transport;
		traceSink = context.getTraversals();
		traceStartX = fineX;
		traceStartY = fineY;
		traceElapsed = 0;
		traceSamples = new java.util.ArrayList<>();
		traceSamples.add(new int[]{0, fineX, fineY});
	}

	private void sampleTrace(int cycles)
	{
		if (tracing == null)
		{
			return;
		}
		traceElapsed += cycles;
		if (traceSamples.size() < TRACE_SAMPLES)
		{
			traceSamples.add(new int[]{traceElapsed, fineX, fineY});
		}
	}

	/** Hands the finished crossing over, from where the golem is before it lands on the tile. */
	private void finishTrace()
	{
		if (tracing == null)
		{
			return;
		}
		if (traceSamples.size() < TRACE_SAMPLES)
		{
			traceSamples.add(new int[]{traceElapsed, fineX, fineY});
		}
		GolemTraversal done = new GolemTraversal(tracing, traceStartX, traceStartY, fineX, fineY, traceSamples);
		tracing = null;
		traceSamples = null;
		traceSink.accept(done);
	}

	/** Where the glide started and ends, in the same 128ths of a tile as everything else. */
	private int transitionFromX;
	private int transitionFromY;
	private int transitionToX;
	private int transitionToY;

	/** Whether this transition moves the golem, or is played on the spot. */
	private boolean transitionGlide;

	/**
	 * How high the golem is lifted mid-jump, in client units at the peak. A stepping-stone
	 * hop is an arc, not a slide: without this the golem crosses the water at ground level
	 * looking dragged.
	 */
	private static final int JUMP_ARC_HEIGHT = 26;

	/**
	 * Extra height for the drawn model this frame, or zero. Read by {@link FakeGolem} and
	 * added to the terrain height: a parabola across the transition, so the golem leaves
	 * the ground, peaks halfway and lands.
	 */
	int jumpArc()
	{
		if (!transitionGlide || transitionCycles <= 0)
		{
			return 0;
		}

		// You can only be in the air while you are moving. Arcing across the whole
		// transition made the golem rise and hang there for the cathedral door, which holds
		// still for thirty cycles and then teleports.
		int window = transitionGlideCycles > 0 ? transitionGlideCycles : transitionTotal;
		int elapsed = transitionTotal - transitionCycles - transitionGlideDelay;
		if (elapsed <= 0 || elapsed >= window)
		{
			return 0;
		}

		// And only for a leap. A door's single tile is a step through a doorway; lifting the
		// golem off the ground for it is a hover, not a jump.
		if (Math.abs(transitionToX - transitionFromX)
			+ Math.abs(transitionToY - transitionFromY) <= TILE)
		{
			return 0;
		}

		float done = elapsed / (float) window;
		// 4t(1-t) peaks at 1 when t is a half, and is zero at both ends.
		return Math.round(JUMP_ARC_HEIGHT * 4f * done * (1f - done));
	}
}

package com.golemsdontdie;

import com.golemsdontdie.telemetry.GolemCrossing;
import com.golemsdontdie.telemetry.ObstacleDataFile;
import com.golemsdontdie.telemetry.PlayerCrossing;
import java.io.BufferedReader;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;

/**
 * The one place the plugin hands anything to the obstacle data file.
 *
 * <p>Copies numbers out of the plugin's own objects into the plain records of the
 * {@code telemetry} package, and nothing else: no decisions about what to keep are made here beyond
 * which fields to copy. See that package for what is kept and why.
 */
@Singleton
class ObstacleDataBridge
{
	@Inject
	private TransportNetwork transports;

	private ObstacleDataFile file;

	/**
	 * @param folder the plugin's own folder, or null if RuneLite could not give it one: then nothing
	 *               is kept, and play goes on without it
	 */
	void startUp(Filepath folder)
	{
		if (folder == null)
		{
			file = null;
			return;
		}
		Filepath path = folder.join(ObstacleDataFile.FILE_NAME);
		file = new ObstacleDataFile(new ObstacleDataFile.Store()
		{
			@Override
			public boolean exists()
			{
				return path.exists();
			}

			@Override
			public BufferedReader reader() throws IOException
			{
				return path.openBufferedReader();
			}

			@Override
			public void write(String text) throws IOException
			{
				folder.createDirectories();
				path.write(text);
			}
		}, GolemsDontDiePlugin.VERSION);
		file.load();
	}

	void save()
	{
		if (file != null)
		{
			file.save();
		}
	}

	/** A crossing the player made, already judged to be an obstacle. */
	void playerCrossed(ObstacleSighting s)
	{
		if (file == null)
		{
			return;
		}
		MotionCurve curve = s.curve;
		file.add(new PlayerCrossing(s.objectId, s.name, s.menu, s.clips, s.ticks, s.moveDelay, s.moveSpan,
			s.fromX, s.fromY, s.fromPlane, s.toX, s.toY, s.toPlane, s.lineX, s.lineY, s.instance,
			curve == null ? new int[0][] : curve.samples(),
			curve == null ? new int[0][] : curve.animationChanges(),
			curve == null ? -1 : curve.facing()));
	}

	/** A crossing a golem made in view. See GolemTraversal. */
	void golemCrossed(GolemTraversal t)
	{
		if (file == null)
		{
			return;
		}
		GolemTransport route = t.route;
		file.add(new GolemCrossing(route.getObjectId(),
			route.getFromX(), route.getFromY(), route.getFromPlane(),
			route.getToX(), route.getToY(), route.getToPlane(),
			t.samples.toArray(new int[0][]), passesOverStone(route)));
	}

	/**
	 * True if a route passes over a tile another short hop starts on, between its two ends: a
	 * stepping stone the golem did not land on.
	 */
	private boolean passesOverStone(GolemTransport route)
	{
		int dx = Integer.signum(route.getToX() - route.getFromX());
		int dy = Integer.signum(route.getToY() - route.getFromY());
		int x = route.getFromX() + dx;
		int y = route.getFromY() + dy;
		for (int step = 0; step < 16 && (x != route.getToX() || y != route.getToY()); step++)
		{
			if (transports.isStone(x, y, route.getFromPlane()))
			{
				return true;
			}
			x += dx;
			y += dy;
		}
		return false;
	}
}

package com.golemsdontdie;

import net.runelite.api.WorldView;

/**
 * How much of a golem needs simulating, decided by how close the player is to it.
 *
 * <p>A golem nobody can see costs <em>no tick</em> at all. The gate used to be whether the
 * player was near Wyrmscraig; once golems can be anywhere it is asked per golem. Tiers are
 * spatial, not scheduled: a golem is in whichever tier its distance puts it in each frame,
 * so crossing a boundary costs one action, not an ongoing one.
 */
enum GolemTier
{
	/** Inside the loaded scene, on the player's plane. Drawn, clickable, stepped each frame. */
	SCENE,

	/**
	 * Outside the scene but close enough to walk into view shortly. Simulated in full like
	 * {@link #SCENE}, just not drawn.
	 *
	 * <p>A coarse once-a-second step here was dropped: the previous version stepped every
	 * golem in full near Wyrmscraig and handled hundreds, so the saving is not needed, and
	 * a throttled golem would enter the scene up to a second out of place — precisely the
	 * boundary where that shows.
	 */
	NEAR,

	/** Everywhere else, land or sea. A route and a start time, resolved only when asked. */
	FAR;

	/**
	 * Tiles beyond the scene edge that still count as near: roughly two regions. Wide enough
	 * that a golem has somewhere to be as the player approaches, narrow enough to stay cheap.
	 */
	private static final int NEAR_RANGE = 128;

	/**
	 * Which tier a golem at these world coordinates falls into. Plane is part of the scene
	 * test: a golem two floors up is not in the player's scene, even though its tile is.
	 */
	static GolemTier of(WorldView wv, int worldX, int worldY, int plane,
		int playerX, int playerY, int playerPlane)
	{
		if (wv == null)
		{
			return FAR;
		}

		int localX = worldX - wv.getBaseX();
		int localY = worldY - wv.getBaseY();
		boolean inScene = localX >= 0 && localY >= 0
			&& localX < wv.getSizeX() && localY < wv.getSizeY();

		if (inScene && plane == playerPlane)
		{
			return SCENE;
		}

		// Chebyshev, not Euclidean: the scene and the ring around it are squares.
		int distance = Math.max(Math.abs(worldX - playerX), Math.abs(worldY - playerY));
		return distance <= NEAR_RANGE ? NEAR : FAR;
	}
}

package com.golemsdontdie;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.MenuOptionClicked;

/**
 * Watches the player use obstacles, and teaches the plugin what it sees.
 *
 * <p>Which animation a shortcut plays, and how long it takes, is <b>not in the cache</b>:
 * agility obstacles are resolved server-side, object definitions carry the object's own
 * animation but not the person's, and of three open server reimplementations none is current
 * enough to trust. So it watches: every obstacle used becomes an {@link ObstacleSighting} for
 * {@link ObstacleKnowledge}, and two consistent sightings unlock it for golems permanently.
 */
@Slf4j
@Singleton
class ObstacleObserver
{
	/**
	 * Ticks after a click within which an animation is taken to belong to it. Generous because an
	 * earlier three-tick window expired during the walk to the obstacle, easily ten seconds.
	 */
	private static final int CLAIM_WINDOW = 60;

	/** Ticks to keep watching before giving up on a traversal ever finishing. */
	private static final int PATIENCE = 40;

	/**
	 * Tiles the player can cover in one tick before it must have been a transport. Running covers
	 * two a tick and a staircase several thousand, so the test is nowhere near the margin.
	 */
	private static final int TELEPORT_TILES = 3;

	@Inject
	private Client client;

	@Inject
	private ObstacleKnowledge knowledge;

	@Inject
	private ObstacleIndex index;

	@Inject
	private TransportNetwork transports;

	/** What golems can walk on, which decides where a traversal is learned to start and end. */
	@Inject
	private IslandMemory memory;

	/** Whether to report the plugin's verdict on each obstacle clicked. */
	@Setter
	private boolean explaining;

	/** Called when a sighting completes, so the plugin can persist and announce it. */
	@Setter
	private java.util.function.Consumer<ObstacleSighting> onSighting;

	// ------------------------------------------------------------- what was clicked

	private int clickedObject = -1;
	private String clickedName = "";
	private String clickedMenu = "";
	private int clickedTick = -1;

	/** An object clicked while another was still animating; see onMenuOptionClicked. */
	private int queuedObject = -1;
	private String queuedName = "";
	private String queuedMenu = "";
	private int queuedTick = -1;

	/** A golem walks a tile a tick, and so do the steps added on and off an obstacle. */
	private static final int WALK_CYCLES = 30;

	// --------------------------------------------------------- the traversal so far

	private final List<Integer> clips = new ArrayList<>();
	private WorldPoint startedAt;
	private int startedTick = -1;
	private int lastAnimTick = -1;

	/** Where the player was last tick, for spotting a move no walk could explain. */
	private WorldPoint previousTile;

	/**
	 * The client cycle the traversal's first clip began on, or -1. The movement window is measured
	 * from here: a golem's own transition starts there, so it is the only origin the two share.
	 */
	private int clipStartCycle = -1;

	/** Cycles from the first clip to the player first moving, and to them stopping. */
	private int moveDelay = -1;
	private int moveEnd = -1;

	/**
	 * When the last animation of the traversal ended, and where the player's tile was then. The
	 * traversal is over when the obstacle has finished with the player, not when the player next
	 * stands still: as one, that recorded the cathedral door plus the walk after it, two tiles off
	 * and three ticks instead of two.
	 */
	private int animEndCycle = -1;
	private WorldPoint animEndTile;

	/**
	 * Cycles of complete stillness on a tile centre that mark the end of one step: a crossing is
	 * one click, and basalt hops rest about fifteen cycles, where a climb's stalls last two.
	 */
	private static final int REST_CYCLES = 6;

	private static final int CYCLES_PER_TICK = 30;

	/**
	 * The traversal being recorded: {cycle, worldFineX, worldFineY} per client tick. World fine
	 * units, because a scene can shift underneath a recording and take local coordinates with it.
	 */
	private final List<int[]> samples = new ArrayList<>();

	/** {cycle, animationId} for each change during the traversal. */
	private final List<int[]> animTimeline = new ArrayList<>();

	/** Where the player was on the previous client tick, for spotting movement at all. */
	private LocalPoint previousFine;

	/**
	 * A move that looked like a silent traversal, held back one tick because the two events race:
	 * a ladder playing 828 can move first, so it was called animated sometimes and silent others,
	 * and every disagreement voided the count.
	 */
	private WorldPoint silentFrom;
	private WorldPoint silentTo;
	private int silentObject = -1;
	private String silentName = "";
	private String silentMenu = "";

	// ------------------------------------------------------------------ lifecycle

	void startUp()
	{
		resetSession();
	}

	void shutDown()
	{
		resetSession();
	}

	// --------------------------------------------------------------------- capture

	/** Remembers the object the player just clicked, so an animation can be attributed. */
	void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (option == null || option.isEmpty())
		{
			return;
		}


		if (!isObjectAction(event.getMenuAction()))
		{
			// Only scene objects are obstacles: a definition looked up for a walk target returns
			// whatever object shares that number. A click on anything else drops the object being
			// walked to, as the game does — a door clicked and then a teleport cast was learned as a
			// door to the teleport's destination — but a traversal already started is left to finish.
			if (startedAt == null && clips.isEmpty() && posing == -1)
			{
				clickedObject = -1;
				clickedTick = -1;
				clearSilent();
			}
			return;
		}

		Player local = client.getLocalPlayer();
		WorldPoint at = local == null ? null : local.getWorldLocation();

		// A click while an obstacle is still animating is held, not acted on: players click ahead as
		// a matter of course, and ending the recording there cut it off mid-animation.
		if (startedAt != null && !clips.isEmpty() && local != null && local.getAnimation() != -1)
		{
			queuedObject = event.getId();
			queuedMenu = (option + " " + stripTags(event.getMenuTarget())).trim();
			queuedName = objectName(queuedObject);
			queuedTick = client.getTickCount();
			return;
		}

		// A traversal already under way is finished by the next click, not thrown away: chained
		// obstacles are one action per step, and discarding the one in flight merged both hops into
		// a four-tile route a golem cleared in a single jump.
		if (startedAt != null && !clips.isEmpty() && at != null && !at.equals(startedAt))
		{
			// The next stone of the same crossing ends the hop on the stone it landed on, and the
			// next starts there. Any other click is somewhere new, and the hop ends as usual.
			boolean sameObstacle = event.getId() == clickedObject
				|| objectName(event.getId()).equals(clickedName) && !clickedName.isEmpty();
			complete(at, client.getTickCount(), sameObstacle);
			if (sameObstacle)
			{
				chainTile = at;
			}
		}

		clickedObject = event.getId();
		clickedMenu = (option + " " + stripTags(event.getMenuTarget())).trim();
		clickedName = objectName(clickedObject);
		clickedTick = client.getTickCount();
		hurt = false;
		ordinaryPoses = local == null ? null : ordinaryPosesOf(local);

		clips.clear();
		startedAt = null;


		if (explaining)
		{
			explain(clickedObject);
		}
	}

	/**
	 * Says what the plugin currently believes about the obstacle just clicked. Tied to the
	 * highlight setting: it answers which of the four things the colour depends on is missing.
	 */
	private void explain(int objectId)
	{
		int sizeX = 1;
		int sizeY = 1;
		int x = -1;
		int y = -1;
		int plane = 0;

		Player local = client.getLocalPlayer();
		WorldPoint at = local == null ? null : local.getWorldLocation();
		if (at != null)
		{
			// The index entry nearest the player, so the footprint and position match the overlay's.
			for (ObstacleIndex.Obstacle o : index.near(at.getX(), at.getY(), at.getPlane(), 12))
			{
				if (o.objectId == objectId)
				{
					x = o.x;
					y = o.y;
					plane = o.plane;
					sizeX = o.sizeX;
					sizeY = o.sizeY;
					break;
				}
			}
		}

		if (x < 0)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"[golem] " + objectId + " is not in the obstacle index", null);
			return;
		}

		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[golem] " + objectId + " "
			+ knowledge.explain(objectId, x, y, plane, sizeX, sizeY,
				transports.archetypeFor(objectId)), null);
	}

	/**
	 * Notes each clip the player begins, and the moment the traversal starts. Every clip is kept:
	 * OSRS builds a traversal in parts, and only the first would be a mount and then stillness.
	 */
	void onAnimationChanged(AnimationChanged event)
	{
		Player local = client.getLocalPlayer();
		if (local == null || event.getActor() != local)
		{
			return;
		}

		int playing = local.getAnimation();
		int tick = client.getTickCount();


		if (playing == -1 && startedAt != null)
		{
			animEndCycle = client.getGameCycle();
			animEndTile = local.getWorldLocation();
			animEndTileTemplate = templateOf(animEndTile);
			// Kept so a golem stops animating when the player did; without it the golem stepped
			// off a stile frozen in the last frame of the climb.
			animTimeline.add(new int[]{client.getGameCycle(), -1});
		}

		if (playing == -1 || clickedTick < 0 || tick - clickedTick > CLAIM_WINDOW)
		{
			// An emote, combat, a skill: not attributable to a click, so nothing to learn.
			return;
		}

		// An animation turned up after all, so the move was not silent.
		clearSilent();

		// The next step of a chained crossing, not more of the same one: one click crosses a whole
		// line of stones, and storing that as one traversal let golems cross without touching the
		// middle stone. The same clip again, while the player rests on a tile they did not start
		// from, is a new step; a multi-part obstacle pauses between *different* clips.
		WorldPoint splitAt = null;
		List<int[]> restRun = null;
		if (startedAt != null && !clips.isEmpty() && clips.get(clips.size() - 1) == playing)
		{
			restRun = restingRun();
			WorldPoint resting = restRun == null ? null : tileOf(restRun.get(restRun.size() - 1));
			if (resting != null && !resting.equals(startedAt))
			{
				int object = clickedObject;
				String name = clickedName;
				String menu = clickedMenu;
				int clicked = clickedTick;

				complete(resting, tick, true);
				chainTile = resting;

				clickedObject = object;
				clickedName = name;
				clickedMenu = menu;
				clickedTick = clicked;
				splitAt = resting;
			}
			else
			{
				restRun = null;
			}
		}

		beginClip(playing, splitAt, restRun, local, tick);
	}

	/**
	 * Notes a clip starting: the first of a traversal, which anchors it, or another part of the one
	 * under way. Played animations come here, and so does a pose that moves the player silently.
	 */
	private void beginClip(int playing, WorldPoint splitAt, List<int[]> restRun, Player local, int tick)
	{
		if (startedAt == null)
		{
			// Where the traversal began is where the player was a tick ago: movement and animation
			// arrive in either order, and a rock climb moves you first, so anchoring on the current
			// position recorded a traversal that never left its own tile.
			startedAt = splitAt != null ? splitAt
				: previousTile != null ? previousTile : local.getWorldLocation();
			startedAtTemplate = splitAt != null ? templateOf(splitAt)
				: previousTile != null ? previousTileTemplate : templateOf(local.getWorldLocation());
			startedTick = tick;
			clipStartCycle = client.getGameCycle();
			moveDelay = -1;
			moveEnd = -1;
			samples.clear();
			if (restRun != null)
			{
				// The rest before this step belongs to it: it is where the step starts from.
				samples.addAll(restRun);
			}
			animTimeline.clear();
			animEndCycle = -1;
			animEndTile = null;
		}


		clips.add(playing);
		animTimeline.add(new int[]{client.getGameCycle(), playing});
		lastAnimTick = tick;
	}

	/**
	 * Finishes a traversal once the player has stopped moving somewhere new. A looping clip hides
	 * its own length — a rock climb loops silently — so only the arrival gives it.
	 */
	void onGameTick()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		int tick = client.getTickCount();
		WorldPoint at = local.getWorldLocation();

		WorldPoint was = previousTile;
		previousTile = at;
		WorldPoint wasTemplate = previousTileTemplate;
		previousTileTemplate = templateOf(at);

		// A pose the obstacle put the player in, playing nothing. See posedTraversal.
		if (posedTraversal(local, at, was, wasTemplate, tick))
		{
			return;
		}

		if (startedAt == null && clips.isEmpty())
		{
			// Nothing is animating, so watch for the traversal that plays no animation at all.
			// Staircases are the large case and were invisible here, capture having only ever begun
			// on an animation; "plays nothing" is itself a fact worth knowing.
			silentTraversal(was, at, tick, wasTemplate, previousTileTemplate);
			return;
		}

		if (startedAt == null || clips.isEmpty())
		{
			return;
		}

		// Finished means stopped, not merely between animations: a looping clip reports -1 between
		// repeats, and a rock climb was declared over on its first tile, recording 2550,2209 ->
		// 2550,2208. Or two ticks after the animation ended, moving or not, since a player who
		// clicks away the moment an obstacle lets go never stands still.
		boolean stillMoving = was == null || !was.equals(at);
		boolean released = animEndCycle >= 0
			&& client.getGameCycle() - animEndCycle >= 2 * CYCLES_PER_TICK;
		if (local.getAnimation() == -1 && at != null && (!stillMoving || released)
			&& !at.equals(startedAt))
		{
			complete(at, tick);
			return;
		}

		if (tick - lastAnimTick > PATIENCE)
		{
			// Whatever that was, it was not a traversal that finished.
			reset();
		}
	}

	private void complete(WorldPoint at, int tick)
	{
		complete(at, tick, false);
	}

	/**
	 * Turns the watched traversal into a sighting and hands it on.
	 *
	 * @param continues true if the same obstacle carries straight on, as the next hop of a line of
	 *                  stepping stones does, so the part ends on the stone it landed on.
	 */
	private void complete(WorldPoint at, int tick, boolean continues)
	{
		// A fall is not the way across: washed downstream off a stepping stone the player still
		// moves, and learned, that teaches golems to cross by swimming. So hurt means failed.
		if (hurt)
		{
			hurt = false;
			chainTile = null;
			reset();
			return;
		}

		// Started on the stone a previous hop of the same crossing landed on.
		boolean fromChain = chainTile != null && chainTile.equals(startedAt);
		chainTile = null;

		int[] played = new int[clips.size()];
		for (int i = 0; i < played.length; i++)
		{
			played[i] = clips.get(i);
		}

		// Where the obstacle put the player, not always where they came to rest; see animEndTile.
		// A tile equal to the start is a clip that ended before its own teleport — a ladder.
		WorldPoint to = at;
		if (animEndTile != null && !animEndTile.equals(startedAt) && !animEndTile.equals(at))
		{
			to = animEndTile;
		}

		// Where a golem gets on and off, which for some obstacles is not where the obstacle begins
		// and ends: the stile puts the player on its own blocked tile first. See wayIn, wayOut.
		WorldPoint landing = to;
		// The direction and line in lasting coordinates. Across an instance edge the raw tiles are
		// thousands apart — the pew to the Mad Angel's room recorded a line of 11486,5792.
		WorldPoint landingTemplate = landing.equals(animEndTile) ? animEndTileTemplate : templateOf(landing);
		WorldPoint lineFrom = startedAtTemplate != null ? startedAtTemplate : startedAt;
		WorldPoint lineTo = landingTemplate != null ? landingTemplate : landing;
		int dirX = Integer.signum(lineTo.getX() - lineFrom.getX());
		int dirY = Integer.signum(lineTo.getY() - lineFrom.getY());
		boolean level = landing.getPlane() == startedAt.getPlane();
		// Not in the middle of a crossing. Stepping back to walkable ground is right for a stile but
		// wrong for a stone mid-river, which was learned as a jump over the stone beside it.
		WorldPoint origin = level && !fromChain ? wayIn(startedAt, dirX, dirY) : startedAt;
		to = level && !continues ? wayOut(landing, dirX, dirY) : landing;

		// The recording is the obstacle and nothing else: from the player standing on the tile it
		// starts them from to the moment it puts them down. Everything either side is the player,
		// and was being replayed by golems. Where the route's ends lie a tile outside, the steps
		// between are added as ordinary walking.
		List<int[]> track = flattenTeleports(cutAtArrival(trimToStart(samples, startedAt), landing));
		if (level && !track.isEmpty())
		{
			track = withWalk(track, origin, startedAt, landing, to);
		}
		MotionCurve curve = MotionCurve.record(track, animTimeline,
			origin.getX() * Golem.TILE + Golem.TILE / 2,
			origin.getY() * Golem.TILE + Golem.TILE / 2,
			to.getX() * Golem.TILE + Golem.TILE / 2,
			to.getY() * Golem.TILE + Golem.TILE / 2);

		// Timings read off the recording, which is exactly one step long. Counted live they came back
		// as one cycle for nearly every obstacle, the position stalling every other cycle.
		int ticks = tick - startedTick;
		int delay = Math.max(0, moveDelay);
		int span = 0;
		if (curve != null)
		{
			ticks = Math.max(1, Math.round(curve.cycles() / (float) CYCLES_PER_TICK));
			if (curve.firstMoveCycle() >= 0)
			{
				delay = Math.max(0, curve.firstMoveCycle() - curve.firstAnimationCycle());
				span = Math.max(0, curve.lastMoveCycle() - curve.firstMoveCycle());
			}
		}

		// The route's ends in lasting coordinates: inside an instance that is its template, captured
		// when seen, since the instance may be gone by now. The same offset carries over.
		WorldPoint fromTemplate = shift(startedAtTemplate, origin, startedAt);
		WorldPoint toTemplate = shift(landingTemplate, to, landing);
		boolean placed = fromTemplate != null && toTemplate != null;
		WorldPoint from = placed ? fromTemplate : origin;
		WorldPoint end = placed ? toTemplate : to;

		ObstacleSighting sighting = new ObstacleSighting(
			clickedObject, clickedName, clickedMenu, played, ticks,
			from.getX(), from.getY(), from.getPlane(),
			end.getX(), end.getY(), end.getPlane(), !placed,
			delay, span, curve,
			level ? lineTo.getX() - lineFrom.getX() : 0,
			level ? lineTo.getY() - lineFrom.getY() : 0,
			// A tile inside an instance is not its own template; outside one it is.
			startedAtTemplate != null && !startedAtTemplate.equals(startedAt),
			landingTemplate != null && !landingTemplate.equals(landing));


		reset();

		// A traversal that did not move the player is not a traversal: the main guard against being
		// attacked between clicking a ladder and reaching it.
		if (!sighting.moved())
		{
			return;
		}

		if (onSighting != null)
		{
			onSighting.accept(sighting);
		}
	}

	/**
	 * Records a traversal that moved the player without animating them, judged by the move rather
	 * than the click: a plane change, or a jump no running could cover in one tick.
	 */
	private void silentTraversal(WorldPoint was, WorldPoint now, int tick, WorldPoint wasTemplate,
		WorldPoint nowTemplate)
	{
		// Last tick's candidate, now that an animation has had its chance to turn up.
		if (silentFrom != null)
		{
			WorldPoint from = silentFrom;
			WorldPoint to = silentTo;
			WorldPoint fromTemplate = silentFromTemplate;
			WorldPoint toTemplate = silentToTemplate;
			boolean placed = fromTemplate != null && toTemplate != null;
			int object = silentObject;
			String name = silentName;
			String menu = silentMenu;
			clearSilent();

			// A silent traversal has no clip to measure a window against but still has a shape:
			// without one a staircase appeared at the far end the tick the golem arrived. A silent
			// exit is reported a tick after the overworld loads, so its template is a tick older.
			MotionCurve curve = silentCurve(from, to);
			WorldPoint start = placed ? fromTemplate : from;
			WorldPoint end = placed ? toTemplate : to;
			ObstacleSighting sighting = new ObstacleSighting(object, name, menu,
				new int[0], 1, start.getX(), start.getY(), start.getPlane(),
				end.getX(), end.getY(), end.getPlane(), !placed, 0, 0,
				curve, 0, 0,
				fromTemplate != null && !fromTemplate.equals(from),
				toTemplate != null && !toTemplate.equals(to));

			reset();

			if (onSighting != null)
			{
				onSighting.accept(sighting);
			}
			return;
		}

		if (clickedObject < 0 || was == null || now == null
			|| clickedTick < 0 || tick - clickedTick > CLAIM_WINDOW)
		{
			return;
		}

		boolean jumped = was.getPlane() != now.getPlane()
			|| Math.abs(was.getX() - now.getX()) > TELEPORT_TILES
			|| Math.abs(was.getY() - now.getY()) > TELEPORT_TILES;
		if (!jumped)
		{
			return;
		}

		// Boarding or leaving a boat is not an obstacle: aboard, the player stands in the boat's own
		// world thousands of tiles off the map, and a gangplank was learned as a way there.
		boolean aboard = onBoat();
		if (aboard || boatChanged)
		{
			return;
		}

		// Held, not emitted. Next tick decides.
		silentFrom = was;
		silentTo = now;
		silentFromTemplate = wasTemplate;
		silentToTemplate = nowTemplate;
		silentObject = clickedObject;
		silentName = clickedName;
		silentMenu = clickedMenu;
	}

	/**
	 * Drops the walk up to the obstacle, keeping the traversal itself, which starts at the last
	 * moment the player stood on its origin tile. Recording begins at the click, well before.
	 */
	private List<int[]> trimToStart(List<int[]> all, WorldPoint from)
	{
		int start = startOfTraversal(all, from);
		if (start >= 0)
		{
			return all.subList(start, all.size());
		}
		// Never seen standing there: start at the animation rather than keep the approach,
		// which is the player's walk and not the obstacle.
		for (int i = 0; i < all.size(); i++)
		{
			if (all.get(i)[0] >= clipStartCycle)
			{
				return all.subList(i, all.size());
			}
		}
		return all;
	}

	/**
	 * The walk onto and off an obstacle, added where a route starts or ends a tile outside it:
	 * straight lines at walking pace playing no animation, so the golem's own walk shows.
	 */
	private static List<int[]> withWalk(List<int[]> track, WorldPoint origin, WorldPoint start,
		WorldPoint landing, WorldPoint dest)
	{
		List<int[]> out = new ArrayList<>();
		int[] first = track.get(0);
		if (!origin.equals(start))
		{
			for (int i = 0; i < WALK_CYCLES; i++)
			{
				out.add(walkSample(first[0] - WALK_CYCLES + i, origin, start, i / (float) WALK_CYCLES, first[3]));
			}
		}
		out.addAll(track);
		if (!dest.equals(landing))
		{
			int[] last = track.get(track.size() - 1);
			for (int i = 0; i < WALK_CYCLES; i++)
			{
				out.add(walkSample(last[0] + 1 + i, landing, dest, (i + 1) / (float) WALK_CYCLES, last[3]));
			}
		}
		return out;
	}

	private static int[] walkSample(int cycle, WorldPoint from, WorldPoint to, float t, int plane)
	{
		float fromX = from.getX() * Golem.TILE + Golem.TILE / 2f;
		float fromY = from.getY() * Golem.TILE + Golem.TILE / 2f;
		float toX = to.getX() * Golem.TILE + Golem.TILE / 2f;
		float toY = to.getY() * Golem.TILE + Golem.TILE / 2f;
		return new int[]{cycle, Math.round(fromX + (toX - fromX) * t), Math.round(fromY + (toY - fromY) * t),
			plane, -1, -1};
	}

	/** The index of the traversal's first sample, or -1 if the player never stood on its origin. */
	private static int startOfTraversal(List<int[]> all, WorldPoint from)
	{
		if (from == null || all.isEmpty())
		{
			return -1;
		}

		// Tile centres, because the samples are rendered and a player is drawn at a tile's middle.
		int originX = from.getX() * Golem.TILE + Golem.TILE / 2;
		int originY = from.getY() * Golem.TILE + Golem.TILE / 2;

		// The moment the player arrived on the origin tile, not the moment they left it: a door
		// stands still for thirty cycles and then teleports, all of it "at the origin", so taking the
		// last sample there began the recording at the teleport. Hence the walk back to the run.
		int last = -1;
		for (int i = 0; i < all.size(); i++)
		{
			int[] sample = all.get(i);
			if (Math.abs(sample[1] - originX) <= Golem.TILE / 4
				&& Math.abs(sample[2] - originY) <= Golem.TILE / 4)
			{
				last = i;
			}
		}

		if (last < 0)
		{
			return -1;
		}

		int start = last;
		while (start > 0)
		{
			int[] before = all.get(start - 1);
			if (Math.abs(before[1] - originX) > Golem.TILE / 4
				|| Math.abs(before[2] - originY) > Golem.TILE / 4)
			{
				break;
			}
			start--;
		}

		return start;
	}

	/**
	 * Drops whatever the player did after the obstacle finished: the first moment, at or after the
	 * last animation ended, that they are drawn on the destination. A door keeps its whole clip.
	 */
	private List<int[]> cutAtArrival(List<int[]> track, WorldPoint to)
	{
		// Without an end to the animation, the first arrival after it began will do.
		int after = animEndCycle >= 0 ? animEndCycle : clipStartCycle;
		if (after < 0)
		{
			return track;
		}
		int centreX = to.getX() * Golem.TILE + Golem.TILE / 2;
		int centreY = to.getY() * Golem.TILE + Golem.TILE / 2;
		for (int i = 0; i < track.size(); i++)
		{
			int[] sample = track.get(i);
			if (sample[0] >= after && sample[3] == to.getPlane()
				&& Math.abs(sample[1] - centreX) <= Golem.TILE / 4
				&& Math.abs(sample[2] - centreY) <= Golem.TILE / 4)
			{
				return track.subList(0, i + 1);
			}
		}
		return track;
	}

	/**
	 * Holds the recording still from the first teleport onward. A cave mouth puts the player six
	 * thousand tiles away while still animating, which a golem would glide across the world.
	 */
	private static List<int[]> flattenTeleports(List<int[]> track)
	{
		for (int i = 1; i < track.size(); i++)
		{
			int[] before = track.get(i - 1);
			int[] after = track.get(i);
			if (before[3] != after[3]
				|| Math.abs(after[1] - before[1]) > TELEPORT_TILES * Golem.TILE
				|| Math.abs(after[2] - before[2]) > TELEPORT_TILES * Golem.TILE)
			{
				List<int[]> held = new ArrayList<>(track.subList(0, i));
				for (int j = i; j < track.size(); j++)
				{
					int[] sample = track.get(j);
					held.add(new int[]{sample[0], before[1], before[2], before[3],
						sample.length > 4 ? sample[4] : -1, sample.length > 5 ? sample[5] : -1});
				}
				return held;
			}
		}
		return track;
	}

	/**
	 * The stillness on a silent obstacle before the player vanishes, as a recording. Only the part
	 * on the origin tile: the approach is not the obstacle, and the far side is elsewhere.
	 */
	private MotionCurve silentCurve(WorldPoint from, WorldPoint to)
	{
		int start = startOfTraversal(samples, from);
		if (start < 0)
		{
			return null;
		}
		int originX = from.getX() * Golem.TILE + Golem.TILE / 2;
		int originY = from.getY() * Golem.TILE + Golem.TILE / 2;
		int end = samples.size();
		for (int i = start; i < samples.size(); i++)
		{
			int[] sample = samples.get(i);
			if (sample[3] != from.getPlane()
				|| Math.abs(sample[1] - originX) > Golem.TILE / 4
				|| Math.abs(sample[2] - originY) > Golem.TILE / 4)
			{
				end = i;
				break;
			}
		}
		return MotionCurve.record(samples.subList(start, end), new ArrayList<>(),
			originX, originY,
			to.getX() * Golem.TILE + Golem.TILE / 2, to.getY() * Golem.TILE + Golem.TILE / 2);
	}

	/** The rest ending the recording, if long enough on a tile centre to end a step; else null. */
	private List<int[]> restingRun()
	{
		if (samples.isEmpty())
		{
			return null;
		}
		int[] last = samples.get(samples.size() - 1);
		int first = samples.size() - 1;
		while (first > 0)
		{
			int[] before = samples.get(first - 1);
			if (before[1] != last[1] || before[2] != last[2] || before[3] != last[3])
			{
				break;
			}
			first--;
		}
		if (last[0] - samples.get(first)[0] < REST_CYCLES)
		{
			return null;
		}
		int offX = Math.floorMod(last[1], Golem.TILE) - Golem.TILE / 2;
		int offY = Math.floorMod(last[2], Golem.TILE) - Golem.TILE / 2;
		if (Math.abs(offX) > Golem.TILE / 4 || Math.abs(offY) > Golem.TILE / 4)
		{
			return null;
		}
		return new ArrayList<>(samples.subList(first, samples.size()));
	}

	/**
	 * Where a traversal really starts, for a golem.
	 *
	 * <p>Some obstacles start the player on a tile no golem can walk onto: clicking the stile walks
	 * you onto its blocked tile, so a route learned from there started where no golem could stand
	 * and the stile went unused. The way in is the walkable tile behind the obstacle, along its
	 * line — from the obstacle alone, never from where the player was, since players come at a
	 * stile from the side. A stepping stone is blocked too, but behind it is water.
	 */
	private WorldPoint wayIn(WorldPoint origin, int dirX, int dirY)
	{
		if (origin == null || walkable(origin) || (dirX == 0 && dirY == 0))
		{
			return origin;
		}
		WorldPoint behind = new WorldPoint(origin.getX() - dirX, origin.getY() - dirY, origin.getPlane());
		return walkable(behind) ? behind : origin;
	}

	/** Where a traversal really ends: the landing, else the walkable tile past it, else itself. */
	private WorldPoint wayOut(WorldPoint landing, int dirX, int dirY)
	{
		if (walkable(landing) || (dirX == 0 && dirY == 0))
		{
			return landing;
		}
		WorldPoint beyond = new WorldPoint(landing.getX() + dirX, landing.getY() + dirY, landing.getPlane());
		return walkable(beyond) ? beyond : landing;
	}

	private boolean walkable(WorldPoint tile)
	{
		return tile != null && memory.isKnownWalkable(tile.getX(), tile.getY(), tile.getPlane());
	}

	private static boolean adjacent(WorldPoint a, WorldPoint b)
	{
		return a != null && b != null && a.getPlane() == b.getPlane() && !a.equals(b)
			&& Math.abs(a.getX() - b.getX()) <= 1 && Math.abs(a.getY() - b.getY()) <= 1;
	}

	private static WorldPoint tileOf(int[] sample)
	{
		return new WorldPoint(Math.floorDiv(sample[1], Golem.TILE),
			Math.floorDiv(sample[2], Golem.TILE), sample[3]);
	}

	/** The stone a hop of a crossing just landed on, where the crossing's next hop starts. */
	private WorldPoint chainTile;

	/** True if the player took damage since clicking the obstacle: they failed it. */
	private boolean hurt;

	/** The player's own standing, walking, running and turning poses, as they were at the click. */
	private java.util.Set<Integer> ordinaryPoses;

	/** A pose being recorded as the traversal's clip, or -1. */
	private int posing = -1;

	/** True if the player was aboard a boat last tick. */
	private boolean wasOnBoat;

	/**
	 * True if the player got on or off a boat this tick, kept apart from {@link #wasOnBoat} because
	 * {@link #posedTraversal} has moved that on before {@link #silentTraversal} looks: read there,
	 * stepping off a boat could be learned as a route.
	 */
	private boolean boatChanged;

	/**
	 * Forgets the player's last position and click for a new session — the plugin starting, a
	 * logout, a world hop — since otherwise a jump that never happened could be learned.
	 */
	void resetSession()
	{
		queuedObject = -1;
		reset();
		previousTile = null;
		previousTileTemplate = null;
		wasOnBoat = false;
		boatChanged = false;
		hurt = false;
		ordinaryPoses = null;
		clickedName = "";
		clickedMenu = "";
	}

	/** Marks the obstacle under way as failed. Called when the player takes a hit. */
	void onPlayerHurt()
	{
		if (clickedTick >= 0 || startedAt != null)
		{
			hurt = true;
		}
	}

	private boolean onBoat()
	{
		Player local = client.getLocalPlayer();
		return local != null && local.getWorldView() != null && !local.getWorldView().isTopLevel();
	}

	private static java.util.Set<Integer> ordinaryPosesOf(Player local)
	{
		java.util.Set<Integer> poses = new java.util.HashSet<>();
		poses.add(-1);
		poses.add(local.getIdlePoseAnimation());
		poses.add(local.getIdleRotateLeft());
		poses.add(local.getIdleRotateRight());
		poses.add(local.getWalkAnimation());
		poses.add(local.getWalkRotateLeft());
		poses.add(local.getWalkRotateRight());
		poses.add(local.getWalkRotate180());
		poses.add(local.getRunAnimation());
		return poses;
	}

	/**
	 * Watches for an obstacle that moves the player in a pose of its own, playing nothing.
	 *
	 * <p>Climbing down a vine is one: the game swaps the player's walk for a climbing pose and
	 * moves them a tile a tick with no animation, so this class, recording only on an animation or
	 * a jump, saw nothing and the vine could only be learned going up. A pose none of the player's
	 * own, soon after a click, is that obstacle's clip.
	 *
	 * @return true if this tick belonged to such a traversal
	 */
	private boolean posedTraversal(Player local, WorldPoint at, WorldPoint was, WorldPoint wasTemplate, int tick)
	{
		boolean aboard = onBoat();
		boatChanged = aboard != wasOnBoat;
		wasOnBoat = aboard;
		if (boatChanged || aboard)
		{
			return false;
		}

		int pose = local.getPoseAnimation();
		boolean special = ordinaryPoses != null && !ordinaryPoses.contains(pose) && local.getAnimation() == -1;

		if (posing != -1)
		{
			if (special && pose == posing)
			{
				return false;
			}
			// Back to the player's own poses: the obstacle has let go.
			posing = -1;
			if (startedAt != null)
			{
				animEndCycle = client.getGameCycle();
				animEndTile = at;
				animEndTileTemplate = templateOf(at);
				animTimeline.add(new int[]{client.getGameCycle(), -1});
			}
			return false;
		}

		if (!special || startedAt != null || !clips.isEmpty()
			|| clickedObject < 0 || clickedTick < 0 || tick - clickedTick > CLAIM_WINDOW)
		{
			return false;
		}

		clearSilent();
		posing = pose;
		beginClip(pose, null, null, local, tick);
		// From where the player was when the pose took them, a tick ago: by now they have
		// already been moved a tile.
		if (was != null)
		{
			startedAt = was;
			startedAtTemplate = wasTemplate;
		}
		return true;
	}

	private void clearSilent()
	{
		silentFrom = null;
		silentTo = null;
		silentFromTemplate = null;
		silentToTemplate = null;
		silentObject = -1;
	}

	private void reset()
	{
		clearSilent();
		posing = -1;
		chainTile = null;
		clipStartCycle = -1;
		moveDelay = -1;
		moveEnd = -1;
		animEndCycle = -1;
		animEndTile = null;
		animEndTileTemplate = null;
		startedAtTemplate = null;
		samples.clear();
		animTimeline.clear();
		clips.clear();
		startedAt = null;
		startedTick = -1;
		clickedTick = -1;
		clickedObject = -1;

		// A click held back while the obstacle finished is the one the next traversal belongs to.
		if (queuedObject >= 0)
		{
			clickedObject = queuedObject;
			clickedName = queuedName;
			clickedMenu = queuedMenu;
			clickedTick = queuedTick;
			queuedObject = -1;
		}
	}

	// ------------------------------------------------------------------- motion

	/**
	 * Samples the player's exact position while a traversal is in progress. A game tick is 600ms and
	 * movement is interpolated thirty times inside it, so tick resolution cannot tell a walk from a
	 * glide from a teleport. Local coordinates: 128ths of a tile, the golems' unit.
	 */
	void onClientTick()
	{
		// The samples below are the motion curves golems learn from, and a curve is what splits a
		// line of stepping stones into its hops.
		Player local = client.getLocalPlayer();
		LocalPoint fine = local == null ? null : local.getLocalLocation();

		// The motion itself, sample by sample: what a golem performs, the window below being a summary
		// for obstacles no curve was captured for. Sampled from the click onward, not the animation,
		// because the movement can happen *before* the clip — a rock climb puts you at the far side
		// first — so the approach is trimmed at the end. A rolling window; a cap left it unsampled.
		if (clickedTick >= 0 && local != null)
		{
			net.runelite.api.WorldView view = client.getTopLevelWorldView();
			LocalPoint fineNow = local.getLocalLocation();
			if (view != null && fineNow != null)
			{
				// The *rendered* position, and only that. A traversal moves the logical tile to the
				// destination at once and then slides the drawn position across, which is why
				// getWorldLocation() already reads the top of a rock climb; combining the two gave
				// the destination tile with the departure's sub-tile offset.
				if (samples.size() >= MotionCurve.MAX_CYCLES)
				{
					samples.remove(0);
				}
				samples.add(new int[]{
					client.getGameCycle(),
					view.getBaseX() * Golem.TILE + fineNow.getX(),
					view.getBaseY() * Golem.TILE + fineNow.getY(),
					local.getWorldLocation().getPlane(),
					local.getOrientation(),
					local.getAnimation() == -1 ? -1 : local.getAnimationFrame(),
				});
			}
		}

		// The movement window, measured against the clip rather than the tick. A traversal holds the
		// player still for part of its animation and then moves them quickly — 33 cycles of stillness
		// then 12 of movement, on the stones — and only the total made golems drift.
		if (clipStartCycle >= 0 && fine != null && previousFine != null)
		{
			boolean moving = fine.getX() != previousFine.getX()
				|| fine.getY() != previousFine.getY();
			if (moving)
			{
				int since = client.getGameCycle() - clipStartCycle;
				if (moveDelay < 0)
				{
					moveDelay = Math.max(0, since);
				}
			}
		}
		previousFine = fine;

	}

	private String objectName(int id)
	{
		try
		{
			ObjectComposition def = client.getObjectDefinition(id);
			return def == null || def.getName() == null ? "" : def.getName();
		}
		catch (RuntimeException e)
		{
			return "";
		}
	}

	private static boolean isObjectAction(MenuAction action)
	{
		switch (action)
		{
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	/**
	 * The sampled positions' templates, captured while that instance is still the loaded scene.
	 */
	private WorldPoint previousTileTemplate;
	private WorldPoint startedAtTemplate;
	private WorldPoint animEndTileTemplate;
	private WorldPoint silentFromTemplate;
	private WorldPoint silentToTemplate;

	private WorldPoint templateOf(WorldPoint tile)
	{
		return InstanceMap.templateOf(client.getTopLevelWorldView(), tile);
	}

	/** {@code base} moved by however far {@code moved} is from {@code reference}; null if base is. */
	private static WorldPoint shift(WorldPoint base, WorldPoint moved, WorldPoint reference)
	{
		if (base == null)
		{
			return null;
		}
		return new WorldPoint(base.getX() + moved.getX() - reference.getX(),
			base.getY() + moved.getY() - reference.getY(),
			base.getPlane() + moved.getPlane() - reference.getPlane());
	}

	private static String stripTags(String text)
	{
		return text == null ? "" : text.replaceAll("<[^>]*>", "");
	}
}

package com.golemsdontdie;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * How many golems the player has ever crafted, read from the game's own count.
 *
 * <p>The plugin's roster is not the player's history: golems made before it was installed were
 * never taken over, and ones culled or dismissed are gone. The gap is what the revive button
 * offers to close. The total only ever goes up, a lower figure being treated as a misread line,
 * because reading some other line as a smaller total would silently offer too few golems.
 *
 * <p>{@link GolemContent#GOLEM_COUNT_VARBIT} arrives with the player's variables at login, so
 * golems crafted on mobile or before the plugin was installed are counted by the next login
 * rather than staying wrong until the next craft. The chat line on every craft reports the same
 * number and is a backstop: it does not depend on the varbit meaning what it appears to, and is
 * not capped at 65,535. Counting golem spawns was dropped — on a shared island it would tally
 * other players' golems.
 */
@Slf4j
@Singleton
class GolemTally
{
	/** Config key for the running total. Plugin-written, so not a config item. */
	static final String TOTAL_KEY = "totalGolemsCrafted";

	/**
	 * The game's own tally line, sent each time a golem is finished:
	 * <pre>You have crafted 374 golems on Wyrmscraig.</pre>
	 *
	 * <p>Matched precisely, not by keywords: a loose test would read "You need 5 stone chunks to
	 * build a golem" as a total of five. The trailing "on Wyrmscraig" is not required.
	 */
	private static final Pattern TOTAL_MESSAGE =
		Pattern.compile("(?i)\\byou have crafted\\s+([\\d,]+)\\s+golems?\\b");

	@Inject
	private ConfigManager configManager;

	/** Golems crafted, ever. Zero until a message says otherwise. */
	@Getter
	private int total;

	void load()
	{
		total = 0;
		String stored = configManager.getConfiguration(GolemsDontDieConfig.GROUP, TOTAL_KEY);
		if (stored == null || stored.trim().isEmpty())
		{
			return;
		}
		try
		{
			total = Math.max(0, Integer.parseInt(stored.trim()));
		}
		catch (NumberFormatException e)
		{
			log.debug("Stored golem total '{}' unreadable", stored);
		}
	}

	/**
	 * Offers a chat line to the tally.
	 *
	 * @return true if the total changed, so the panel can be redrawn
	 */
	boolean observe(String message)
	{
		if (message == null || message.isEmpty())
		{
			return false;
		}

		Matcher matcher = TOTAL_MESSAGE.matcher(message);
		if (!matcher.find())
		{
			return false;
		}

		int found;
		try
		{
			found = Integer.parseInt(matcher.group(1).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			// A number too large for an int is not a golem count.
			return false;
		}

		return setTotal(found);
	}

	/**
	 * Offers the game's own count, read from {@link GolemContent#GOLEM_COUNT_VARBIT}. Refusing
	 * to go backwards covers every awkward case: a varbit read before the server sends it is 0,
	 * and a count past sixteen bits pins at 65,535 or wraps small, by which point the chat line
	 * carries the real figure.
	 *
	 * @return true if the total changed, so the panel can be redrawn
	 */
	boolean observeCount(int count)
	{
		return setTotal(count);
	}

	/**
	 * Raises the total. Ignores anything that would lower it.
	 *
	 * @return true if the total changed
	 */
	boolean setTotal(int candidate)
	{
		if (candidate <= total)
		{
			return false;
		}
		total = candidate;
		configManager.setConfiguration(GolemsDontDieConfig.GROUP, TOTAL_KEY, total);
		log.debug("Golems crafted total is now {}", total);
		return true;
	}

}

package com.golemsdontdie;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;

/**
 * Reads and writes the saved golem roster.
 *
 * <p>Only what the cache cannot supply is written: the NPC ID, position, home tile, and the
 * three animation IDs no composition exposes. Everything visual is re-fetched on load, so the
 * save stays about ten numbers per golem. A flat delimited string rather than JSON: the record
 * is all numbers, and a save the player can read and edit is worth more than a schema.
 */
@Slf4j
@Singleton
class GolemStore
{
	private static final String GOLEM_SEPARATOR = ";";
	private static final String FIELD_SEPARATOR = ",";

	/**
	 * Ten numbers plus the nickname. Two more are optional: whether the golem is in an
	 * instance, and when it may next sail.
	 */
	private static final int FIELD_COUNT = 11;

	/** Characters a nickname may not contain, because they are the separators. */
	private static final String ILLEGAL_IN_NICKNAME = "[;,]";

	@Inject
	private Client client;

	/** A golem as it sits in the save file, before the cache fills in its appearance. */
	static class SavedGolem
	{
		int npcId;
		int worldX;
		int worldY;
		int plane;
		int orientation;
		int homeX;
		int homeY;
		int idlePose;
		int walk;
		int run;
		String nickname;
		boolean inInstance;
		long shoreLeaveUntil;
	}

	/** Encodes a live roster for the config store. */
	String serialise(List<Golem> golems)
	{
		StringBuilder out = new StringBuilder();
		for (Golem golem : golems)
		{
			GolemSnapshot snapshot = golem.getSnapshot();
			WorldPoint at = golem.saveTile();
			if (out.length() > 0)
			{
				out.append(GOLEM_SEPARATOR);
			}
			out.append(snapshot.getNpcId()).append(FIELD_SEPARATOR)
				.append(at.getX()).append(FIELD_SEPARATOR)
				.append(at.getY()).append(FIELD_SEPARATOR)
				.append(at.getPlane()).append(FIELD_SEPARATOR)
				.append(golem.getOrientation()).append(FIELD_SEPARATOR)
				.append(golem.getHome().getX()).append(FIELD_SEPARATOR)
				.append(golem.getHome().getY()).append(FIELD_SEPARATOR)
				.append(snapshot.getIdlePoseAnimation()).append(FIELD_SEPARATOR)
				.append(snapshot.getWalkAnimation()).append(FIELD_SEPARATOR)
				.append(snapshot.getRunAnimation()).append(FIELD_SEPARATOR)
				// Separators are stripped rather than escaped: losing a stray comma from
				// free text beats a save file that will not parse.
				.append(golem.getNickname() == null
					? ""
					: golem.getNickname().replaceAll(ILLEGAL_IN_NICKNAME, ""))
				.append(FIELD_SEPARATOR).append(golem.isInInstance() ? 1 : 0)
				// Real time, so a golem that landed just before logout is still ashore after it.
				.append(FIELD_SEPARATOR).append(golem.getShoreLeaveUntil());
		}
		return out.toString();
	}

	/** Decodes a roster. Malformed entries are dropped rather than failing the load. */
	List<SavedGolem> deserialise(String encoded)
	{
		List<SavedGolem> result = new ArrayList<>();
		if (encoded == null || encoded.trim().isEmpty())
		{
			return result;
		}

		for (String entry : encoded.split(GOLEM_SEPARATOR))
		{
			if (entry.trim().isEmpty())
			{
				continue;
			}
			// -1 keeps a trailing empty nickname as a field rather than dropping it.
			String[] fields = entry.split(FIELD_SEPARATOR, -1);
			if (fields.length < FIELD_COUNT || fields.length > FIELD_COUNT + 2)
			{
				log.debug("Dropping malformed saved golem '{}'", entry);
				continue;
			}
			try
			{
				SavedGolem saved = new SavedGolem();
				saved.npcId = Integer.parseInt(fields[0].trim());
				saved.worldX = Integer.parseInt(fields[1].trim());
				saved.worldY = Integer.parseInt(fields[2].trim());
				saved.plane = Integer.parseInt(fields[3].trim());
				saved.orientation = Integer.parseInt(fields[4].trim());
				saved.homeX = Integer.parseInt(fields[5].trim());
				saved.homeY = Integer.parseInt(fields[6].trim());
				saved.idlePose = Integer.parseInt(fields[7].trim());
				saved.walk = Integer.parseInt(fields[8].trim());
				saved.run = Integer.parseInt(fields[9].trim());
				String nickname = fields[10].trim();
				saved.nickname = nickname.isEmpty() ? null : nickname;
				saved.inInstance = fields.length > FIELD_COUNT && "1".equals(fields[FIELD_COUNT].trim());
				saved.shoreLeaveUntil = fields.length > FIELD_COUNT + 1 ? Long.parseLong(fields[FIELD_COUNT + 1].trim()) : 0;
				result.add(saved);
			}
			catch (NumberFormatException e)
			{
				log.debug("Dropping unparseable saved golem '{}'", entry, e);
			}
		}
		return result;
	}

	/**
	 * Turns a saved record back into a golem, pulling its appearance from the cache.
	 *
	 * @param index position in the save file, which keeps each golem's seed distinct
	 * @return the golem, or null if the cache no longer knows that NPC ID
	 */
	Golem revive(SavedGolem saved, int index)
	{
		WorldPoint at = new WorldPoint(saved.worldX, saved.worldY, saved.plane);
		GolemSnapshot snapshot = GolemSnapshot.restore(
			client, saved.npcId, saved.idlePose, saved.walk, saved.run, at, saved.orientation);
		if (snapshot == null)
		{
			log.debug("Saved golem npc {} is no longer in the cache", saved.npcId);
			return null;
		}

		WorldPoint home = new WorldPoint(saved.homeX, saved.homeY, saved.plane);

		// The index is what makes the seed unique. Position alone is not enough: two golems
		// saved on the same tile — what happens on a spawn tile — would share a seed, and a
		// Golem's entire gait comes out of that one number. Position still contributes, so a
		// golem keeps a stable character across reloads.
		long seed = ((long) saved.worldX << 32) ^ ((long) saved.worldY << 8) ^ saved.npcId ^ (index * 0x9E3779B9L);
		Golem golem = Golem.onTile(snapshot, home, seed, at);
		golem.setNickname(saved.nickname);
		golem.setInInstance(saved.inInstance);
		golem.setShoreLeaveUntil(saved.shoreLeaveUntil);
		return golem;
	}
}

package com.golemsdontdie;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Where the player is in the world, including when they are aboard a boat.
 *
 * <p>A boat is a world of its own: aboard one, {@link Player#getWorldLocation()} answers in the
 * boat's coordinates, far off the map, which put every golem out of range the moment the player
 * boarded. So the deck position is carried out to the main world through the boat, found by world
 * view id as RuneLite's own overlays do.
 */
final class PlayerPosition
{
	private PlayerPosition()
	{
	}

	/** The player's tile in the main world, or null if there is no player. */
	static WorldPoint of(Client client)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		WorldView view = me.getWorldView();
		WorldView top = client.getTopLevelWorldView();
		if (view == null || top == null || view.isTopLevel())
		{
			return me.getWorldLocation();
		}

		WorldEntity boat = top.worldEntities().byIndex(view.getId());
		LocalPoint onDeck = me.getLocalLocation();
		if (boat == null || onDeck == null)
		{
			return me.getWorldLocation();
		}
		LocalPoint atSea = boat.transformToMainWorld(onDeck);
		if (atSea == null)
		{
			return me.getWorldLocation();
		}
		return WorldPoint.fromLocal(top, atSea.getX(), atSea.getY(), top.getPlane());
	}
}

package com.golemsdontdie;

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Where every obstacle in the game is, read from the cache and shipped.
 *
 * <p>Separate from {@link TransportNetwork} because only one of the two questions is easy. Where
 * the obstacles are is a fact out of the map index; where each one leads is derived from collision
 * components, and was wrong by one to three tiles on every Wyrmscraig shortcut until somebody
 * measured them. So this index, claiming nothing about destinations, is what the overlay draws.
 *
 * <p>Doors and gates are not here, excluded on the game's own wall-versus-scenery split: a golem
 * cannot open a door, because that changes an object every other player can see.
 */
@Slf4j
@Singleton
class ObstacleIndex
{
	private static final String RESOURCE = "/obstacles.gz";

	/** Bumped when the format changes; an old file is refused rather than misread. */
	private static final int VERSION = 4;

	/**
	 * Obstacles by the region they stand in, because the overlay asks "what is near me" every time
	 * the player moves and all but a handful are hundreds of tiles off.
	 */
	private final Map<Integer, List<Obstacle> > byRegion = new HashMap<>();

	/** Cache traversal time per object id: asked for on the hot path, so kept apart from places. */
	private final Map<Integer, Integer> ticksByObject = new HashMap<>();

	/**
	 * One obstacle, at one place. {@code x, y} is the south-west corner, as the cache records a
	 * placement; marking only that lit one half of every two-tile object.
	 */
	static final class Obstacle
	{
		final int objectId;
		final int x;
		final int y;
		final int plane;
		final int sizeX;
		final int sizeY;

		/**
		 * True if this is mounted in a wall — a door or a gate. Kept rather than dropped, because a
		 * handful are not doors at all: the Wyrmscraig cathedral door does not swing open, it puts you
		 * on the other side. Drawn only once something is known about it.
		 */
		final boolean wall;

		/**
		 * How many game ticks this obstacle takes, from the cache, or 0 if it does not say. Neither
		 * measured nor guessed: only about fifty obstacles carry it, and it lines up with Shortest
		 * Path's hand-measured table.
		 */
		final int ticks;

		Obstacle(int objectId, int x, int y, int plane, int sizeX, int sizeY, boolean wall,
			int ticks)
		{
			this.ticks = ticks;
			this.objectId = objectId;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.sizeX = sizeX;
			this.sizeY = sizeY;
			this.wall = wall;
		}
	}

	void load()
	{
		byRegion.clear();
		ticksByObject.clear();
		known.clear();

		try (InputStream raw = ObstacleIndex.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.warn("No obstacle index on the classpath; highlighting will be empty");
				return;
			}

			try (DataInputStream in = new DataInputStream(new GZIPInputStream(raw)))
			{
				int version = in.readInt();
				if (version != VERSION)
				{
					log.warn("Obstacle index is version {}, expected {} — ignoring it",
						version, VERSION);
					return;
				}

				int count = in.readInt();
				for (int i = 0; i < count; i++)
				{
					int objectId = in.readInt();
					int x = in.readShort() & 0xffff;
					int y = in.readShort() & 0xffff;
					int plane = in.readByte();
					int sizeX = in.readByte() & 0xff;
					int sizeY = in.readByte() & 0xff;
					boolean wall = in.readByte() != 0;
					int ticks = in.readByte() & 0xff;

					// Bucketed by the anchor's region. An object straddling a boundary is still found,
					// because the search below widens by the largest footprint any object has.
					byRegion.computeIfAbsent(region(x, y), k -> new ArrayList<>())
						.add(new Obstacle(objectId, x, y, plane, sizeX, sizeY, wall, ticks));
					known.add(objectId);
					if (ticks > 0)
					{
						ticksByObject.put(objectId, ticks);
					}
				}

				log.debug("Loaded obstacle index: {} obstacles across {} regions",
					count, byRegion.size());
			}
		}
		catch (IOException e)
		{
			// Cosmetic data: a failure here costs the highlight overlay and nothing else.
			log.warn("Could not read the obstacle index", e);
		}
	}

	/**
	 * Every obstacle within {@code radius} tiles, on the given plane. Searches only the regions the
	 * box touches: a radius of a hundred spans nine of the index's two and a half thousand.
	 */
	List<Obstacle> near(int x, int y, int plane, int radius)
	{
		List<Obstacle> found = new ArrayList<>();

		for (int rx = (x - radius) >> 6; rx <= (x + radius) >> 6; rx++)
		{
			for (int ry = (y - radius) >> 6; ry <= (y + radius) >> 6; ry++)
			{
				List<Obstacle> here = byRegion.get((rx << 8) | ry);
				if (here == null)
				{
					continue;
				}
				for (Obstacle o : here)
				{
					// Measured to the nearest part of the object rather than its corner,
					// so a long object half inside the radius is not dropped.
					if (o.plane == plane
						&& Math.abs(o.x + o.sizeX / 2 - x) <= radius + o.sizeX
						&& Math.abs(o.y + o.sizeY / 2 - y) <= radius + o.sizeY)
					{
						found.add(o);
					}
				}
			}
		}
		return found;
	}

	/** The cache's traversal time for an object, in ticks, or 0: the same wherever it stands. */
	/**
	 * True if the cache lists this object as something you traverse: the first question asked of
	 * anything the player is seen using, watching alone not telling an obstacle from a tree. The
	 * index holds objects whose menu offers a way across — climb, cross, squeeze, jump.
	 */
	boolean knows(int objectId)
	{
		return known.contains(objectId);
	}

	private final java.util.Set<Integer> known = new java.util.HashSet<>();

	int ticksFor(int objectId)
	{
		Integer found = ticksByObject.get(objectId);
		return found == null ? 0 : found;
	}

	int size()
	{
		int n = 0;
		for (List<Obstacle> bucket : byRegion.values())
		{
			n += bucket.size();
		}
		return n;
	}

	private static int region(int x, int y)
	{
		return ((x >> 6) << 8) | (y >> 6);
	}
}

package com.golemsdontdie;

/**
 * One obstacle, watched being used, reduced to the facts worth keeping.
 *
 * <p>What {@link ObstacleObserver} produces once a traversal is judged real, and what telemetry
 * would send, so it deliberately holds nothing identifying who saw it.
 */
final class ObstacleSighting
{
	final int objectId;

	/** The object's name from the cache, for a human to read. */
	final String name;

	/** The menu text, e.g. "Climb-down Ladder". */
	final String menu;

	/** Every animation the player played, in order. */
	final int[] clips;

	/** Game ticks from the first clip to standing still somewhere new. */
	final int ticks;

	/**
	 * Client cycles from the first clip until the player actually moves: the wind-up, during which
	 * they hold still. Measured on the basalt stones at <b>33 cycles of stillness then 12 of
	 * movement</b>, identical across four hops. Without it a golem drifts from the first frame.
	 */
	final int moveDelay;

	/** Client cycles the movement lasts, once it starts. */
	final int moveSpan;

	/**
	 * The traversal as it happened, or null if it could not be recorded. Delay and span above
	 * remain for obstacles no curve was captured for.
	 */
	final MotionCurve curve;

	final int fromX;
	final int fromY;
	final int fromPlane;
	final int toX;
	final int toY;
	final int toPlane;

	/**
	 * True if this happened inside an instanced region: the animation is worth keeping, the
	 * destination is not. One church pew recorded three exits, (12105,4551) among them.
	 */
	final boolean instance;

	/**
	 * The way the obstacle itself moved the player, in tiles: from the tile they began on to where
	 * they finished. (0, 0) for no local movement — a ladder or a teleport. The route, where a golem
	 * gets on and off, may be a tile either side but must lie along this. See {@link RouteGeometry}.
	 */
	final int lineX;
	final int lineY;

	/**
	 * True if the traversal began inside an instance, and if it ended inside one: the route's ends
	 * are in template coordinates either way, so only these say which side is an instance.
	 */
	final boolean fromInstance;
	final boolean toInstance;

	ObstacleSighting(int objectId, String name, String menu, int[] clips, int ticks,
		int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane, boolean instance,
		int moveDelay, int moveSpan, MotionCurve curve, int lineX, int lineY)
	{
		this(objectId, name, menu, clips, ticks, fromX, fromY, fromPlane, toX, toY, toPlane, instance,
			moveDelay, moveSpan, curve, lineX, lineY, false, false);
	}

	ObstacleSighting(int objectId, String name, String menu, int[] clips, int ticks,
		int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane, boolean instance,
		int moveDelay, int moveSpan, MotionCurve curve, int lineX, int lineY,
		boolean fromInstance, boolean toInstance)
	{
		this.fromInstance = fromInstance;
		this.toInstance = toInstance;
		this.lineX = lineX;
		this.lineY = lineY;
		this.curve = curve;
		this.instance = instance;
		this.moveDelay = moveDelay;
		this.moveSpan = moveSpan;
		this.objectId = objectId;
		this.name = name;
		this.menu = menu;
		this.clips = clips;
		this.ticks = ticks;
		this.fromX = fromX;
		this.fromY = fromY;
		this.fromPlane = fromPlane;
		this.toX = toX;
		this.toY = toY;
		this.toPlane = toPlane;
	}

	/** True if the player went somewhere, which is what makes this a traversal. */
	boolean moved()
	{
		return fromX != toX || fromY != toY || fromPlane != toPlane;
	}

	@Override
	public String toString()
	{
		StringBuilder sb = new StringBuilder();
		sb.append(objectId).append(" \"").append(menu).append("\" clips=");
		for (int i = 0; i < clips.length; i++)
		{
			sb.append(i == 0 ? "" : ",").append(clips[i]);
		}
		return sb.append(" ticks=").append(ticks)
			.append(" delay=").append(moveDelay).append(" span=").append(moveSpan)
			.append(curve == null ? "" : " [" + curve + "]")
			.append(" ").append(fromX).append(",").append(fromY).append(",").append(fromPlane)
			.append(" -> ").append(toX).append(",").append(toY).append(",").append(toPlane)
			.append(" line=").append(lineX).append(",").append(lineY)
			.append(toInstance && !fromInstance ? " into-instance" : fromInstance && !toInstance ? " out-of-instance" : "")
			.toString();
	}
}

package com.golemsdontdie;

import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.coords.WorldPoint;

/**
 * Everything about a live golem that a copy will need, recorded while the real one
 * is still standing.
 *
 * <p>None of it survives the NPC, so a snapshot is kept refreshed for every watched golem
 * and the copy built from the last one before the death animation. Models, recolours, scale
 * and size come from {@link NPCComposition} given only an NPC ID; the animation IDs do not,
 * only the live {@link net.runelite.api.Actor} having them, so those three go to disk.
 */
@Value
class GolemSnapshot
{
	int npcId;
	String name;

	/** Model IDs from the composition, merged and recoloured into the base model. */
	int[] modelIds;
	short[] recolourFrom;
	short[] recolourTo;

	/** Composition scaling, in 128ths. 128 = as authored. */
	int widthScale;
	int heightScale;

	/** Footprint in tiles; sizes the drawn object's tile-sorting radius. */
	int size;

	/** Pose animations from the actor. -1 where the golem has none. */
	int idlePoseAnimation;
	int walkAnimation;
	int runAnimation;

	/** Where it stood and which way it faced when taken. */
	WorldPoint worldLocation;
	int orientation;

	GolemSnapshot facing(int newOrientation)
	{
		return new GolemSnapshot(npcId, name, modelIds, recolourFrom, recolourTo,
			widthScale, heightScale, size, idlePoseAnimation, walkAnimation, runAnimation,
			worldLocation, newOrientation & 2047);
	}

	/** Reads the current state of a live golem; null if the NPC has no usable composition. */
	static GolemSnapshot of(NPC npc)
	{
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			comp = npc.getComposition();
		}
		if (comp == null)
		{
			return null;
		}

		return build(
			comp,
			npc.getName() == null ? comp.getName() : npc.getName(),
			npc.getIdlePoseAnimation(),
			npc.getWalkAnimation(),
			npc.getRunAnimation(),
			npc.getWorldLocation(),
			npc.getCurrentOrientation());
	}

	/**
	 * Rebuilds a snapshot for a saved golem: appearance from the cache, the rest from the save.
	 *
	 * @return the snapshot, or null if the NPC ID is no longer in the cache
	 */
	static GolemSnapshot restore(Client client, int npcId, int idlePose, int walk, int run,
		WorldPoint where, int orientation)
	{
		NPCComposition comp = client.getNpcDefinition(npcId);
		if (comp == null)
		{
			return null;
		}

		// A golem with no animation stands frozen, which is worse than one moving
		// slightly wrong; saves predating the recording, or catching a transition, carry -1.
		if (walk == -1)
		{
			walk = GolemContent.GOLEM_WALK_ANIMATION;
		}
		if (idlePose == -1)
		{
			idlePose = GolemContent.GOLEM_IDLE_ANIMATION;
		}

		return build(comp, comp.getName(), idlePose, walk, run, where, orientation);
	}

	private static GolemSnapshot build(NPCComposition comp, String name, int idlePose, int walk, int run,
		WorldPoint where, int orientation)
	{
		int[] models = comp.getModels();
		if (models == null || models.length == 0)
		{
			return null;
		}

		return new GolemSnapshot(
			comp.getId(),
			name == null ? "Golem" : name,
			models.clone(),
			comp.getColorToReplace() == null ? new short[0] : comp.getColorToReplace().clone(),
			comp.getColorToReplaceWith() == null ? new short[0] : comp.getColorToReplaceWith().clone(),
			comp.getWidthScale(),
			comp.getHeightScale(),
			Math.max(1, comp.getSize()),
			idlePose,
			walk,
			run,
			where,
			orientation & 2047);
	}
}

package com.golemsdontdie;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Colours the shortcuts around the player by how well the plugin knows them.
 *
 * <p>Golems only perform animations that have been measured, and the set grows as the
 * player is seen using obstacles. Nothing announces that, so this is the only way to tell
 * which would benefit from being used once. Green is confirmed here; orange is inferred
 * from similar objects elsewhere, and using it once turns it green, so those are the ones
 * worth a detour; red has no usable animation and golems route around it.
 *
 * <p>Off by default: a diagnostic, not decoration.
 */
class ObstacleHighlightOverlay extends Overlay
{
	/**
	 * How far out obstacles are gathered, in tiles. Deliberately larger than anything
	 * drawable: the scene is 104 tiles square, so {@link Perspective} declines to project
	 * beyond about fifty. Gathering further costs nothing and has highlights ready the
	 * moment a tile scrolls in.
	 */
	private static final int RADIUS = 100;

	/**
	 * Tiles the player may move before the gathered set is rebuilt. A rebuild sweeps the
	 * whole transport table, thirteen thousand rows — far too much at fifty frames a second.
	 * Ten tiles is about one rebuild a second at a run, and the radius is a hundred, so
	 * nothing scrolls into view between them.
	 */
	private static final int REBUILD_DISTANCE = 10;

	private static final Color CONFIRMED = new Color(0, 200, 60, 180);
	private static final Color INFERRED = new Color(255, 150, 0, 180);
	private static final Color UNUSABLE = new Color(220, 40, 40, 180);

	/** Fill is much fainter than the outline; a solid tile hides the obstacle under it. */
	private static final int FILL_ALPHA = 40;

	@Inject
	private Client client;

	@Inject
	private TransportNetwork transports;

	@Inject
	private ObstacleIndex obstacles;

	@Inject
	private ObstacleKnowledge knowledge;

	@Inject
	private GolemsDontDieConfig config;

	/** One tile to outline, and the colour it earned. */
	private static final class Marked
	{
		final int x;
		final int y;
		final int plane;
		final Color colour;

		/** The same colour at the fill's alpha, made once rather than every frame. */
		final Color fill;

		Marked(int x, int y, int plane, Color colour)
		{
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.colour = colour;
			this.fill = new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), FILL_ALPHA);
		}
	}

	private final List<Marked> marked = new ArrayList<>();

	private int builtX = Integer.MIN_VALUE;
	private int builtY = Integer.MIN_VALUE;
	private int builtPlane = -1;

	/** The knowledge version this set was built from, so a change to it forces a rebuild. */
	private int builtVersion = -1;

	@Inject
	ObstacleHighlightOverlay()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!DevOptions.HIGHLIGHT_OBSTACLES)
		{
			// Dropped, so turning the overlay off does not leave a hundred tiles
			// of stale highlights waiting to be drawn again.
			marked.clear();
			builtPlane = -1;
			builtVersion = -1;
			return null;
		}

		// In the main world, aboard a boat too; see PlayerPosition.
		WorldPoint at = PlayerPosition.of(client);
		if (at == null)
		{
			return null;
		}

		// Inside an instance, obstacle knowledge is keyed by where it was copied from;
		// looking up its own coordinates left the Mad Angel's room uncoloured. See
		// InstanceMap.
		WorldView wv = client.getTopLevelWorldView();
		WorldView instance = wv != null && wv.isInstance() ? wv : null;
		WorldPoint centre = instance != null ? InstanceMap.templateOf(instance, at) : at;
		if (centre == null)
		{
			return null;
		}

		if (needsRebuild(centre, instance))
		{
			rebuild(centre, instance);
		}

		// Once for every tile rather than once per tile: there can be thousands.
		WorldView top = client.getTopLevelWorldView();
		for (Marked mark : marked)
		{
			if (top == null)
			{
				break;
			}
			draw(graphics, top, mark);
		}

		return null;
	}

	/** Where the instance the set was built for was loaded, or MIN_VALUE outside one. */
	private int builtBaseX = Integer.MIN_VALUE;
	private int builtBaseY = Integer.MIN_VALUE;

	private boolean needsRebuild(WorldPoint at, WorldView instance)
	{
		// Using an obstacle changes its colour while the player stands still beside it,
		// which a distance-keyed cache would miss; and a new instance of the same room is
		// somewhere else each visit.
		int baseX = instance == null ? Integer.MIN_VALUE : instance.getBaseX();
		int baseY = instance == null ? Integer.MIN_VALUE : instance.getBaseY();
		return knowledge.getVersion() != builtVersion
			|| baseX != builtBaseX || baseY != builtBaseY
			|| at.getPlane() != builtPlane
			|| Math.abs(at.getX() - builtX) >= REBUILD_DISTANCE
			|| Math.abs(at.getY() - builtY) >= REBUILD_DISTANCE;
	}

	/**
	 * Gathers every obstacle within range, one colour per tile. Drawn from the obstacle
	 * index, not the transport table, which is why the index exists: the table holds only
	 * obstacles with a worked-out destination. One in neither comes out red, which is
	 * accurate and is precisely the obstacle worth using once.
	 */
	private void rebuild(WorldPoint at, WorldView instance)
	{
		builtX = at.getX();
		builtY = at.getY();
		builtPlane = at.getPlane();
		builtVersion = knowledge.getVersion();
		builtBaseX = instance == null ? Integer.MIN_VALUE : instance.getBaseX();
		builtBaseY = instance == null ? Integer.MIN_VALUE : instance.getBaseY();
		marked.clear();

		// A tile can start several transports — a ladder that is also a door — so the most
		// confident wins rather than stacking outlines: only a tile where nothing at all
		// is usable comes out red.
		Map<Long, ObstacleKnowledge.Status> best = new HashMap<>();

		for (ObstacleIndex.Obstacle obstacle : obstacles.near(builtX, builtY, builtPlane, RADIUS))
		{
			ObstacleKnowledge.Status status = knowledge.statusAt(obstacle.objectId,
				obstacle.x, obstacle.y, obstacle.plane, obstacle.sizeX, obstacle.sizeY,
				transports.archetypeFor(obstacle.objectId));

			// Ordinary doors are not obstacles a golem can perform and there are three and a
			// half thousand of them; outlining the lot would bury everything else in red.
			if (obstacle.wall && status == ObstacleKnowledge.Status.UNUSABLE)
			{
				continue;
			}

			// Every tile the object stands on, not just the corner the cache records. A church
			// pew is two tiles and a cave mouth can be three.
			for (int dx = 0; dx < obstacle.sizeX; dx++)
			{
				for (int dy = 0; dy < obstacle.sizeY; dy++)
				{
					long tile = ((long) (obstacle.x + dx) << 32)
						| ((obstacle.y + dy) & 0xffffffffL);
					ObstacleKnowledge.Status current = best.get(tile);

					// The enum is ordered most confident first, so the lowest wins.
					if (current == null || status.ordinal() < current.ordinal())
					{
						best.put(tile, status);
					}
				}
			}
		}

		// Obstacles the player has used that the index has never heard of: it is read from
		// the world's fixed placements, and some exist only in an instance — the Mad
		// Angel's exit pew — so the player's use is the only record.
		for (int[] place : knowledge.confirmedPlaces())
		{
			if (obstacles.knows(place[0]) || place[3] != builtPlane
				|| Math.abs(place[1] - builtX) > RADIUS || Math.abs(place[2] - builtY) > RADIUS)
			{
				continue;
			}
			ObstacleKnowledge.Status status = knowledge.statusAt(place[0], place[1], place[2], place[3], 1, 1,
				transports.archetypeFor(place[0]));
			long tile = ((long) place[1] << 32) | (place[2] & 0xffffffffL);
			ObstacleKnowledge.Status current = best.get(tile);
			if (current == null || status.ordinal() < current.ordinal())
			{
				best.put(tile, status);
			}
		}

		Map<Long, int[]> sceneChunks = instance == null ? null : InstanceMap.sceneChunks(instance);
		for (Map.Entry<Long, ObstacleKnowledge.Status> e : best.entrySet())
		{
			int x = (int) (e.getKey() >> 32);
			int y = (int) (e.getKey() & 0xffffffffL);
			// Gathered in template coordinates; drawn where the instance put that tile.
			WorldPoint drawAt = sceneChunks == null ? new WorldPoint(x, y, builtPlane)
				: InstanceMap.instanceTileOf(instance, sceneChunks, x, y, builtPlane);
			if (drawAt != null)
			{
				marked.add(new Marked(drawAt.getX(), drawAt.getY(), drawAt.getPlane(), colourOf(e.getValue())));
			}
		}
	}

	/** Outlines one tile, or silently skips it if the client cannot place it on screen. */
	private void draw(Graphics2D graphics, WorldView top, Marked mark)
	{
		// LocalPoint.fromWorld without making the point: a tile on another plane is not in
		// this scene.
		LocalPoint localPoint = top.getPlane() != mark.plane ? null : LocalPoint.fromWorld(top, mark.x, mark.y);
		if (localPoint == null)
		{
			// Outside the loaded scene. Most of a hundred-tile radius is, most of the time.
			return;
		}

		Polygon tile = Perspective.getCanvasTilePoly(client, localPoint);
		if (tile == null)
		{
			// On screen in principle, but the client has no height for it.
			return;
		}

		graphics.setColor(mark.colour);
		graphics.drawPolygon(tile);
		graphics.setColor(mark.fill);
		graphics.fillPolygon(tile);
	}

	private static Color colourOf(ObstacleKnowledge.Status status)
	{
		switch (status)
		{
			case CONFIRMED:
				return CONFIRMED;
			case INFERRED:
				return INFERRED;
			default:
				return UNUSABLE;
		}
	}
}

package com.golemsdontdie;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Setter;

/**
 * The world as one golem sees it while deciding what to do next: passability, pathfinder,
 * transports, unlocks and the current tick, rather than five collaborators in a signature
 * called once per golem per frame. One instance, reused for every golem in the frame; it holds
 * no per-golem state.
 */
@Getter
@RequiredArgsConstructor
final class RoamContext
{
	private final IslandMemory memory;
	private final GolemPathfinder pathfinder;
	private final TransportNetwork transports;
	private final GolemAbilities abilities;

	/** How each obstacle is traversed. Set, not injected, so a golem sees the latest unlocks. */
	@Setter
	private ObstacleKnowledge knowledge;

	/** Where every obstacle is; wanted here for its duration, the only per-obstacle traversal
	 * time neither measured nor inferred from a median. */
	@Setter
	private ObstacleIndex obstacles;

	/**
	 * Where a golem reports what it just decided, or null. Logged only with the developer option
	 * on: the outcome alone does not say which of the transport roll, the knowledge lookup and the
	 * pacing went wrong.
	 */
	@Setter
	private java.util.function.BiConsumer<Golem, String> decisions;

	/** Where every golem is, by region, so golems spread out. Null in tools that do not count. */
	@Setter
	private GolemCensus census;

	/** Where a golem in view reports each crossing, for the obstacle record; null if none. */
	@Setter
	private java.util.function.Consumer<GolemTraversal> traversals;

	/** How willing a golem is to enter this tile's region: 1 unless crowded. */
	float roominess(int x, int y, int plane)
	{
		return census == null ? 1f : census.roominess(x, y, plane);
	}

	/** How little a shortcut that keeps a crowded golem in place appeals. */
	private static final float STAYING_PUT = 0.1f;

	/**
	 * How much a shortcut from one tile to another appeals, from 0 to 1, given where golems are.
	 *
	 * <p>With room, this is the room at the far end; crowded, a way out is wanted and staying in
	 * the same region hardly appeals, which a walled place needs: Meiyerditch's ladders all land
	 * inside its own walls, leaving golems nowhere roomier to prefer.
	 */
	float appeal(int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane)
	{
		if (census == null)
		{
			return 1f;
		}
		float here = census.roominess(fromX, fromY, fromPlane);
		float there = census.roominess(toX, toY, toPlane);
		if (here >= 1f)
		{
			return there;
		}
		if (fromPlane == toPlane && fromX >> 6 == toX >> 6 && fromY >> 6 == toY >> 6)
		{
			return STAYING_PUT;
		}
		return Math.min(1f, there / here);
	}

	boolean crowdedRegion(int x, int y, int plane)
	{
		return census != null && census.roominess(x, y, plane) < 1f;
	}

	/**
	 * The route planner, so a golem in view can consider sailing. Set after construction: it
	 * needs the same singletons this context holds, so injecting both ways would be a cycle.
	 */
	@Setter
	private RoamPlanner planner;

	/** The shared model and animation cache, for clip lengths. Set after construction. */
	@Setter
	private GolemModelFactory models;

	/**
	 * The client's tick counter, used for cooldowns; set once per frame, and ticks rather than
	 * wall clock so cooldowns pause with the game.
	 */
	@Setter
	private int tick;

	/** How far through the tick this frame is, 0 to 1, so a golem in view glides along a route. */
	@Setter
	private float tickFraction;

	/** Whether this golem may spend one of the frame's path searches; set per golem as the plugin
	 * works down the roster, so the budget is shared rather than first-come. */
	@Setter
	private boolean mayPath;

	/**
	 * Whether an ocean search may still be run this frame. Crossings are cached per pair of ports,
	 * so almost every voyage is a lookup; the first golem to sail a route pays for an A* across a
	 * 2.4-million-tile sea.
	 */
	@Setter
	private boolean maySearchSea;

	/** "Restrict Golem ambition": golems stay on Wyrmscraig and never sail. Set each frame. */
	@Setter
	private boolean ambitionRestricted;

	void spendSeaSearch()
	{
		maySearchSea = false;
	}

	/** Golems standing on each tile this frame, keyed by {@link #tileKey}; null until filled. */
	@Setter
	private TileMap occupancy;

	/**
	 * Golems on a tile beyond which another should not go there: the game draws only so many
	 * things on one tile, and a pen of three hundred had them flashing in and out.
	 */
	static final int CROWD = 3;

	boolean crowded(int x, int y, int plane)
	{
		return occupancy != null && occupancy.getOrDefault(tileKey(x, y, plane), 0L) >= CROWD;
	}

	static long tileKey(int x, int y, int plane)
	{
		return ((long) plane << 40) | ((long) (x & 0xFFFFF) << 20) | (y & 0xFFFFF);
	}

	/** A space this many walkable tiles or larger is open ground. */
	static final int OPEN_AREA = 400;

	/** How long a measured area is trusted, in ticks, before doors may have changed it. */
	private static final int AREA_REFRESH_TICKS = 500;

	private final java.util.Map<Long, int[]> areas = new java.util.HashMap<>();

	/** Walkable tiles reachable from here, capped at {@link #OPEN_AREA}, cached for a while. */
	int enclosedArea(int x, int y, int plane)
	{
		long key = tileKey(x, y, plane);
		int[] cached = areas.get(key);
		if (cached != null && tick - cached[1] < AREA_REFRESH_TICKS)
		{
			return cached[0];
		}
		int size = pathfinder.areaSize(x, y, plane, OPEN_AREA);
		areas.put(key, new int[]{size, tick});
		return size;
	}
}
